#[cfg(feature = "parallel")]
fn mace_serial_fused_hidden2_chunk_edges_f32(num_edges: usize) -> usize {
    static CHUNK_EDGES: OnceLock<usize> = OnceLock::new();
    (*CHUNK_EDGES.get_or_init(|| {
        std::env::var("LLMLIP_MACE_SERIAL_FUSED_HIDDEN2_CHUNK_EDGES_F32")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|&value| value > 0)
            .unwrap_or(2048)
    }))
    .min(num_edges)
    .max(1)
}

fn mace_prepared_tp_cache_max_edges() -> usize {
    static MAX_EDGES: OnceLock<usize> = OnceLock::new();
    *MAX_EDGES.get_or_init(|| {
        std::env::var("LLMLIP_MACE_PREPARED_TP_CACHE_MAX_EDGES")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .unwrap_or(MACE_PREPARED_TP_CACHE_MAX_EDGES_DEFAULT)
    })
}

