#[cfg(target_arch = "x86_64")]
#[inline(always)]
fn mace_x86_avx2_enabled_from_flags(
    disable_simd: bool,
    disable_avx2: bool,
    disable_avx: bool,
    has_avx2: bool,
) -> bool {
    !disable_simd && !disable_avx2 && !disable_avx && has_avx2
}

#[cfg(all(feature = "parallel", target_arch = "x86_64"))]
#[inline(always)]
fn mace_x86_avx512_enabled_from_flags(
    disable_simd: bool,
    enable_avx512: bool,
    disable_avx512: bool,
    disable_avx: bool,
    has_avx512f: bool,
) -> bool {
    !disable_simd && enable_avx512 && !disable_avx512 && !disable_avx && has_avx512f
}

#[cfg(target_arch = "x86_64")]
#[inline(always)]
fn mace_f32_avx2_fma_enabled() -> bool {
    static ENABLED: OnceLock<bool> = OnceLock::new();
    *ENABLED.get_or_init(|| {
        mace_x86_avx2_enabled_from_flags(
            mace_simd_disabled(),
            std::env::var_os("LLMLIP_DISABLE_AVX2").is_some(),
            std::env::var_os("LLMLIP_DISABLE_AVX").is_some(),
            std::is_x86_feature_detected!("avx2"),
        ) && std::is_x86_feature_detected!("fma")
    })
}

