#[inline(always)]
fn mace_trace_elapsed_ms(start: Instant) -> f64 {
    start.elapsed().as_secs_f64() * 1.0e3
}

#[cfg(all(
    feature = "openblas",
    target_os = "linux",
    any(target_arch = "x86_64", target_arch = "aarch64")
))]
fn mace_openblas_threads_is_one() -> bool {
    std::env::var_os("OPENBLAS_NUM_THREADS")
        .and_then(|value| value.into_string().ok())
        .is_some_and(|value| value.trim() == "1")
}

#[cfg(all(
    feature = "parallel",
    any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    )
))]
fn mace_outer_parallel_blas_threads_is_one() -> bool {
    #[cfg(all(feature = "accelerate-blas", target_os = "macos"))]
    {
        return std::env::var_os("VECLIB_MAXIMUM_THREADS")
            .and_then(|value| value.into_string().ok())
            .is_some_and(|value| value.trim() == "1");
    }
    #[cfg(all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"))]
    {
        return std::env::var_os("MKL_NUM_THREADS")
            .and_then(|value| value.into_string().ok())
            .is_some_and(|value| value.trim() == "1");
    }
    #[cfg(all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ))]
    {
        return mace_openblas_threads_is_one();
    }
    #[allow(unreachable_code)]
    false
}

#[cfg(all(
    feature = "parallel",
    feature = "openblas",
    target_os = "linux",
    any(target_arch = "x86_64", target_arch = "aarch64")
))]
fn mace_parallel_dense_chunk_rows(rows: usize) -> usize {
    let threads = rayon::current_num_threads().max(1);
    let chunks_per_thread = if rows < 20_000 {
        1
    } else {
        mace_dense_chunks_per_thread()
    };
    rows.div_ceil(threads * chunks_per_thread).max(1)
}

#[cfg(all(
    feature = "parallel",
    feature = "openblas",
    target_os = "linux",
    any(target_arch = "x86_64", target_arch = "aarch64")
))]
fn mace_dense_chunks_per_thread() -> usize {
    static CHUNKS_PER_THREAD: OnceLock<usize> = OnceLock::new();
    *CHUNKS_PER_THREAD.get_or_init(|| {
        std::env::var("LLMLIP_MACE_DENSE_CHUNKS_PER_THREAD")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|&value| value > 0)
            .unwrap_or(16)
    })
}

#[cfg(feature = "parallel")]
fn mace_contraction_node_min_len() -> usize {
    static MIN_LEN: OnceLock<usize> = OnceLock::new();
    *MIN_LEN.get_or_init(|| {
        std::env::var("LLMLIP_MACE_CONTRACTION_NODE_MIN_LEN")
            .ok()
            .and_then(|value| value.parse::<usize>().ok())
            .filter(|&value| value > 0)
            .unwrap_or(2)
    })
}

// Used only by the BLAS-backend-gated combined-hidden-linear callers; under
// `--features parallel` without a BLAS backend those callers are cfg'd out, leaving this
// helper unused. Allow dead_code so `clippy -p llmlip --features parallel -D warnings` stays clean.
#[cfg(feature = "parallel")]
#[allow(dead_code)]
fn mp0b_layer1_hidden_chunk_nodes_f32(num_nodes: usize) -> usize {
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 {
        static CHUNK_NODES: OnceLock<usize> = OnceLock::new();
        return (*CHUNK_NODES.get_or_init(|| {
            std::env::var("LLMLIP_MACE_LAYER1_HIDDEN_CHUNK_NODES_F32")
                .ok()
                .and_then(|value| value.parse::<usize>().ok())
                .filter(|&value| value > 0)
                .unwrap_or(6000)
        }))
        .min(num_nodes)
        .max(1);
    }
    num_nodes.max(1)
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
fn mace_dense_forward_f64(
    input: &[f64],
    rows: usize,
    in_dim: usize,
    weight: &[f64],
    out: &mut [f64],
    alpha: f64,
) {
    #[cfg(all(
        feature = "parallel",
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ))]
    if rows >= 16
        && weight.len() / in_dim >= 64
        && rayon::current_num_threads() > 1
        && mace_openblas_threads_is_one()
    {
        let out_dim = weight.len() / in_dim;
        let chunk_rows = mace_parallel_dense_chunk_rows(rows);
        input
            .par_chunks(chunk_rows * in_dim)
            .zip(out.par_chunks_mut(chunk_rows * out_dim))
            .for_each(|(input_chunk, out_chunk)| {
                let chunk_rows = input_chunk.len() / in_dim;
                blas_backend::dense_forward(
                    input_chunk,
                    chunk_rows,
                    in_dim,
                    weight,
                    out_chunk,
                    alpha,
                );
            });
        return;
    }
    blas_backend::dense_forward(input, rows, in_dim, weight, out, alpha);
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
fn mace_dense_vjp_input_f64(
    rows: usize,
    in_dim: usize,
    weight: &[f64],
    bar_out: &[f64],
    bar_input: &mut [f64],
    alpha: f64,
) {
    // This VJP always accumulates into `bar_input` (BLAS beta=1 semantics).
    // Callers that need overwrite behavior must zero the buffer first.
    #[cfg(all(
        feature = "parallel",
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ))]
    if rows >= 16
        && weight.len() / in_dim >= 64
        && rayon::current_num_threads() > 1
        && mace_openblas_threads_is_one()
    {
        let out_dim = weight.len() / in_dim;
        let chunk_rows = mace_parallel_dense_chunk_rows(rows);
        bar_out
            .par_chunks(chunk_rows * out_dim)
            .zip(bar_input.par_chunks_mut(chunk_rows * in_dim))
            .for_each(|(bar_out_chunk, bar_input_chunk)| {
                let chunk_rows = bar_out_chunk.len() / out_dim;
                blas_backend::dense_vjp_input(
                    chunk_rows,
                    in_dim,
                    weight,
                    bar_out_chunk,
                    bar_input_chunk,
                    alpha,
                );
            });
        return;
    }
    blas_backend::dense_vjp_input(rows, in_dim, weight, bar_out, bar_input, alpha);
}

