#[derive(Debug, Error)]
pub enum MaceLiteError {
    #[error(transparent)]
    Core(#[from] CoreError),

    #[error(transparent)]
    NeighborList(#[from] NeighborListError),

    #[error(transparent)]
    ExternalGraph(#[from] ExternalGraphError),

    #[error(transparent)]
    ForceAccum(#[from] ForceAccumError),

    #[error("invalid MACE-lite model: {0}")]
    InvalidModel(String),

    #[error("MACE-lite runtime inference is not implemented yet")]
    UnsupportedRuntime,

    #[cfg(all(feature = "apple-metal", target_os = "macos"))]
    #[error("MACE-MP0b Metal backend failed: {0}")]
    Metal(String),

    #[error("MACE-lite force runtime inference is not implemented yet")]
    UnsupportedForces,

    #[error("MACE-lite stress prediction requires a finite periodic cell")]
    StressRequiresCell,

    #[error("MACE-lite stress prediction is not supported for this model architecture with partial periodic boundary conditions")]
    PartialPbcStressUnsupported,

    #[error("MACE-lite currently requires non-periodic structures")]
    PeriodicUnsupported,

    #[error("unknown species {0:?} for MACE-lite model")]
    UnknownSpecies(String),

    #[error("unsupported prediction head {head:?} for MACE-lite model; supported heads: {supported_heads:?}")]
    UnsupportedHead {
        head: String,
        supported_heads: Vec<String>,
    },

    #[error("invalid MACE-lite descriptor request: {0}")]
    InvalidDescriptorRequest(String),

    #[error("MACE-lite model is missing required state tensor {0:?}")]
    MissingStateTensor(String),

    #[error("MACE-lite state tensor {name:?} has shape {actual:?}, expected {expected:?}")]
    StateTensorShape {
        name: String,
        actual: Vec<usize>,
        expected: Vec<usize>,
    },
}

