#[cfg(feature = "parallel")]
fn build_receiver_edge_index(receivers: &[usize], num_nodes: usize) -> ReceiverEdgeIndex {
    let mut offsets = vec![0usize; num_nodes + 1];
    for &receiver in receivers {
        offsets[receiver + 1] += 1;
    }
    for node in 1..=num_nodes {
        offsets[node] += offsets[node - 1];
    }
    let mut next_offsets = offsets[..num_nodes].to_vec();
    let mut edges = vec![0usize; receivers.len()];
    for (edge, &receiver) in receivers.iter().enumerate() {
        let target = next_offsets[receiver];
        edges[target] = edge;
        next_offsets[receiver] += 1;
    }
    ReceiverEdgeIndex { offsets, edges }
}

