    #[cfg(all(feature = "apple-metal", target_os = "macos"))]
    fn mp0b_layer1_conv_tp_vjp_fixed_metal_cache(
        &self,
        num_nodes: usize,
        edge_attrs_f32: &[f32],
    ) -> Result<Option<metal::Mp0bLayer1ConvTpVjpFixedCacheMetal>, MaceLiteError> {
        let conv_plan = self
            .conv_tp_plan(1)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let layer_plan = self.mp0b_layer_plan_spec(1)?;
        if conv_plan.input1_dim() != MP0B_PRODUCT0_ROW_LEN
            || conv_plan.input2_dim() != MP0B_SH_DIM
            || conv_plan.output_dim() != 10 * MP0B_PRODUCT0_ROW_LEN
            || conv_plan.weight_numel != 10 * MP0B_NUM_FEATURES
            || layer_plan.conv_tp_weight_mlp_hidden_dim != 64
            || layer_plan.conv_tp_weight_numel != 10 * MP0B_NUM_FEATURES
            || !edge_attrs_f32.len().is_multiple_of(MP0B_SH_DIM)
        {
            return Ok(None);
        }
        metal::mp0b_layer1_conv_tp_vjp_fixed_cache_f32(
            num_nodes,
            edge_attrs_f32,
            self.float_tensor_f32(
                "interactions.1.conv_tp_weights.layer3.weight",
                &[
                    layer_plan.conv_tp_weight_mlp_hidden_dim,
                    layer_plan.conv_tp_weight_numel,
                ],
            )?,
            self.float_tensor_f32(
                "interactions.1.linear_up.weight",
                &[2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor_f32(
                "interactions.1.linear_up.output_mask",
                &[MP0B_PRODUCT0_ROW_LEN],
            )?,
        )
        .map(Some)
        .map_err(MaceLiteError::Metal)
    }

