    fn mp0b_prepared_edge_features(
        &self,
        type_ids: &[usize],
        neighbor_list: &NeighborList,
        sh_dim: usize,
    ) -> Result<(Vec<f64>, Vec<f64>, RadialEmbeddingEdgeCache), MaceLiteError> {
        let num_edges = neighbor_list.edges.len();
        let mut edge_attrs = vec![0.0; num_edges * sh_dim];
        let mut edge_feats = vec![0.0; num_edges * self.num_bessel];
        let mut radial_cache = RadialEmbeddingEdgeCache {
            bessel_basis: vec![0.0; num_edges * self.num_bessel],
            radial_distance: vec![0.0; num_edges],
            radial_distance_derivative: vec![0.0; num_edges],
        };
        let mut bessel_basis = vec![0.0; self.num_bessel];
        let mut radial = vec![0.0; self.num_bessel];
        for (edge_index, edge) in neighbor_list.edges.iter().enumerate() {
            self.sh_plan.forward(
                edge.vector,
                &mut edge_attrs[edge_index * sh_dim..(edge_index + 1) * sh_dim],
            )?;
            let radial_distance = self.radial_embedding_forward(
                edge.distance,
                type_ids[edge.src],
                type_ids[edge.dst],
                &mut bessel_basis,
                &mut radial,
            )?;
            radial_cache.bessel_basis
                [edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel]
                .copy_from_slice(&bessel_basis);
            radial_cache.radial_distance[edge_index] = radial_distance.value;
            radial_cache.radial_distance_derivative[edge_index] = radial_distance.derivative;
            edge_feats[edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel]
                .copy_from_slice(&radial);
        }
        Ok((edge_attrs, edge_feats, radial_cache))
    }

    fn mp0b_prepared_edge_features_f32(
        &self,
        neighbor_list: &NeighborList,
        sh_dim: usize,
        edge_feats_f64: &[f64],
    ) -> (Vec<f32>, Vec<f32>) {
        let num_edges = neighbor_list.edges.len();
        let mut edge_attrs = vec![0.0_f32; num_edges * sh_dim];
        let edge_feats = edge_feats_f64
            .iter()
            .map(|&value| value as f32)
            .collect::<Vec<_>>();
        let mut sh = vec![0.0_f32; sh_dim];
        for (edge_index, edge) in neighbor_list.edges.iter().enumerate() {
            self.sh_plan.forward_f32_unchecked(edge.vector, &mut sh);
            edge_attrs[edge_index * sh_dim..(edge_index + 1) * sh_dim].copy_from_slice(&sh);
        }
        (edge_attrs, edge_feats)
    }

    fn prepare_mace_edge_features_f32(
        &self,
        type_ids: &[usize],
        neighbor_list: &NeighborList,
        sh_dim: usize,
    ) -> Result<MacePreparedEdgeFeaturesF32, MaceLiteError> {
        let num_edges = neighbor_list.edges.len();
        let mut edge_attrs = vec![0.0_f32; num_edges * sh_dim];
        let mut edge_feats = vec![0.0_f32; num_edges * self.num_bessel];
        let mut radial_cache = RadialEmbeddingEdgeCache {
            bessel_basis: vec![0.0; num_edges * self.num_bessel],
            radial_distance: vec![0.0; num_edges],
            radial_distance_derivative: vec![0.0; num_edges],
        };
        let mut sh = vec![0.0_f32; sh_dim];
        let mut bessel_basis = vec![0.0; self.num_bessel];
        let mut radial = vec![0.0; self.num_bessel];
        for (edge_index, edge) in neighbor_list.edges.iter().enumerate() {
            self.sh_plan.forward_f32_unchecked(edge.vector, &mut sh);
            edge_attrs[edge_index * sh_dim..(edge_index + 1) * sh_dim].copy_from_slice(&sh);
            let radial_distance = self.radial_embedding_forward(
                edge.distance,
                type_ids[edge.src],
                type_ids[edge.dst],
                &mut bessel_basis,
                &mut radial,
            )?;
            radial_cache.bessel_basis
                [edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel]
                .copy_from_slice(&bessel_basis);
            radial_cache.radial_distance[edge_index] = radial_distance.value;
            radial_cache.radial_distance_derivative[edge_index] = radial_distance.derivative;
            for (target, &value) in edge_feats
                [edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel]
                .iter_mut()
                .zip(&radial)
            {
                *target = value as f32;
            }
        }
        Ok(MacePreparedEdgeFeaturesF32 {
            sh_dim,
            num_bessel: self.num_bessel,
            edge_attrs,
            edge_feats,
            radial_cache,
        })
    }

    fn prepare_mace_conv_tp_weights_f32(
        &self,
        num_nodes: usize,
        edge_feats: &[f32],
    ) -> Result<Option<Box<MacePreparedConvTpWeightsF32>>, MaceLiteError> {
        if !matches!(
            self.active_runtime_plan_kind(),
            Some(
                MaceRuntimePlanKind::Osaka24
                    | MaceRuntimePlanKind::Osaka26
                    | MaceRuntimePlanKind::Oam
            )
        ) || !edge_feats.len().is_multiple_of(self.num_bessel)
        {
            return Ok(None);
        }
        let runtime_plan = match self.active_runtime_plan_kind() {
            Some(MaceRuntimePlanKind::Osaka24 | MaceRuntimePlanKind::Osaka26) => {
                self.active_osaka_plan_spec()?
            }
            Some(MaceRuntimePlanKind::Oam) => self.active_oam_plan_spec()?,
            _ => return Ok(None),
        };
        let num_edges = edge_feats.len() / self.num_bessel;
        if num_edges > mace_prepared_tp_cache_max_edges() {
            return Ok(None);
        }
        let mut layers = Vec::with_capacity(runtime_plan.layers.len());
        for (layer, layer_plan) in runtime_plan.layers.iter().enumerate() {
            let allow_output_readback_skip = self
                .can_skip_generic_conv_tp_weight_output_readback_f32(
                    layer, num_nodes, layer_plan,
                )?;
            layers.push(Some(self.large_conv_tp_weights_with_plan_f32(
                layer,
                layer_plan,
                edge_feats,
                true,
                allow_output_readback_skip,
            )?));
        }
        Ok(Some(Box::new(MacePreparedConvTpWeightsF32 {
            num_edges,
            num_bessel: self.num_bessel,
            layers,
        })))
    }

    fn can_skip_generic_conv_tp_weight_output_readback_f32(
        &self,
        _layer: usize,
        _num_nodes: usize,
        _layer_plan: &PinnedMaceRuntimeLayerPlanSpec,
    ) -> Result<bool, MaceLiteError> {
        #[cfg(all(feature = "apple-metal", target_os = "macos"))]
        {
            if self.active_runtime_plan_kind() == Some(MaceRuntimePlanKind::Oam)
                && _layer == 1
                && metal::mace_metal_enabled()
                && _num_nodes >= OAM_NODE_EMBEDDING_METAL_MIN_NODES
            {
                let conv_plan = self
                    .conv_tp_plan(_layer)
                    .ok_or(MaceLiteError::UnsupportedRuntime)?;
                let conv_output_mask = self.float_tensor_f32(
                    &format!("interactions.{_layer}.conv_tp.output_mask"),
                    &[_layer_plan.conv_tp_output_dim],
                )?;
                Ok(conv_output_mask.iter().all(|&mask| mask == 1.0)
                    && conv_plan.input1_dim() == MP0B_PRODUCT0_ROW_LEN
                    && conv_plan.input2_dim() == MP0B_SH_DIM
                    && conv_plan.output_dim() == 10 * MP0B_PRODUCT0_ROW_LEN
                    && conv_plan.weight_numel == 10 * MP0B_NUM_FEATURES)
            } else {
                Ok(false)
            }
        }
        #[cfg(not(all(feature = "apple-metal", target_os = "macos")))]
        {
            Ok(false)
        }
    }

    pub fn predict_prepared_with_compute_dtype(
        &self,
        prepared: &MaceLitePreparedInput,
        options: &PredictionOptions,
        dtype: PredictionComputeDtype,
    ) -> Result<Prediction, MaceLiteError> {
        match dtype {
            PredictionComputeDtype::Float64 => self.predict_internal(
                &prepared.structure,
                options,
                Some(&prepared.neighbor_list),
                Some(prepared),
                None,
            ),
            PredictionComputeDtype::Float32 => match self.active_runtime_plan_kind() {
                Some(MaceRuntimePlanKind::Mp0b) => self.predict_mp0b_f32_with_neighbor_list(
                    &prepared.structure,
                    options,
                    Some(&prepared.neighbor_list),
                    Some(prepared),
                    None,
                ),
                Some(MaceRuntimePlanKind::Osaka26 | MaceRuntimePlanKind::Osaka24) => self
                    .predict_osaka26_f32_with_neighbor_list(
                        &prepared.structure,
                        options,
                        Some(&prepared.neighbor_list),
                        Some(prepared),
                        None,
                    ),
                Some(MaceRuntimePlanKind::Oam) => self.predict_oam_f32_with_neighbor_list(
                    &prepared.structure,
                    options,
                    Some(&prepared.neighbor_list),
                    Some(prepared),
                    None,
                ),
                _ => Err(MaceLiteError::UnsupportedRuntime),
            },
        }
    }

    #[must_use]
    pub fn name(&self) -> &str {
        &self.name
    }

    #[must_use]
    pub fn type_names(&self) -> &[String] {
        &self.type_names
    }

    #[must_use]
    pub fn atomic_numbers(&self) -> &[usize] {
        &self.atomic_numbers
    }

    #[must_use]
    pub fn cutoff(&self) -> f64 {
        self.cutoff
    }

    #[must_use]
    pub fn l_max(&self) -> usize {
        self.l_max
    }

    #[must_use]
    pub fn heads(&self) -> &[String] {
        &self.heads
    }

    pub(crate) fn validate_head(&self, selected_head: Option<&str>) -> Result<(), MaceLiteError> {
        if let Some(selected_head) = selected_head {
            if !self.heads.iter().any(|head| head == selected_head) {
                return Err(MaceLiteError::UnsupportedHead {
                    head: selected_head.to_owned(),
                    supported_heads: self.heads.clone(),
                });
            }
        }
        Ok(())
    }

    #[must_use]
    pub fn state_dict_len(&self) -> usize {
        self.state_dict_tensor_names.len()
    }

    #[must_use]
    pub fn num_layers(&self) -> usize {
        self.num_layers
    }

    #[must_use]
    pub fn has_state_tensor(&self, name: &str) -> bool {
        self.state_dict_tensor_names
            .iter()
            .any(|candidate| candidate == name)
    }

    #[must_use]
    pub fn state_float_tensor_shape(&self, name: &str) -> Option<&[usize]> {
        self.state_float_tensors
            .get(name)
            .map(|tensor| tensor.shape.as_slice())
    }

    #[must_use]
    pub fn state_float_tensor_len(&self, name: &str) -> Option<usize> {
        self.state_float_tensors
            .get(name)
            .map(|tensor| tensor.values.len())
    }

    #[must_use]
    pub fn active_runtime_plan_kind(&self) -> Option<MaceRuntimePlanKind> {
        self.runtime_plan.as_ref().map(|(kind, _)| *kind)
    }

    #[must_use]
    pub fn has_pinned_mace_runtime_plan(&self) -> bool {
        self.active_runtime_plan_kind().is_some()
    }

    #[must_use]
    pub fn has_mp0b_runtime_plan(&self) -> bool {
        self.active_runtime_plan_kind() == Some(MaceRuntimePlanKind::Mp0b)
    }

    #[must_use]
    pub fn has_osaka26_runtime_plan(&self) -> bool {
        self.active_runtime_plan_kind() == Some(MaceRuntimePlanKind::Osaka26)
    }

    #[must_use]
    pub fn has_osaka_runtime_plan(&self) -> bool {
        self.active_runtime_plan_kind() == Some(MaceRuntimePlanKind::Osaka24)
    }

    #[must_use]
    pub fn has_oam_runtime_plan(&self) -> bool {
        self.active_runtime_plan_kind() == Some(MaceRuntimePlanKind::Oam)
    }

    fn from_spec(
        spec: ModelSpec,
        external_tensors: HashMap<String, MaceLiteExternalTensor>,
    ) -> Result<Self, MaceLiteError> {
        if spec.schema_version != MODEL_SCHEMA_VERSION {
            return Err(invalid_model(format!(
                "schema_version must be {MODEL_SCHEMA_VERSION:?}, got {:?}",
                spec.schema_version
            )));
        }
        if spec.name.trim().is_empty() {
            return Err(invalid_model("name must not be empty"));
        }
        validate_type_names(&spec.type_names)?;
        validate_atomic_numbers(&spec.atomic_numbers)?;
        if spec.atomic_numbers.len() != spec.type_names.len() {
            return Err(invalid_model(
                "atomic_numbers length must match type_names length",
            ));
        }
        if !spec.cutoff.is_finite() || spec.cutoff <= 0.0 {
            return Err(invalid_model(format!(
                "cutoff must be finite and positive, got {}",
                spec.cutoff
            )));
        }
        if spec.l_max > MAX_INITIAL_L {
            return Err(invalid_model(format!(
                "l_max={} is unsupported by the initial MACE-lite loader; supported l_max <= {MAX_INITIAL_L}",
                spec.l_max
            )));
        }
        if spec.heads.as_slice() != [DEFAULT_HEAD] {
            return Err(invalid_model(format!(
                "heads must be exactly [{DEFAULT_HEAD:?}]"
            )));
        }
        if !spec.unsupported_features.is_empty() {
            return Err(invalid_model(format!(
                "unsupported upstream MACE features are present: {}",
                spec.unsupported_features.join(", ")
            )));
        }
        let distance_transform = validate_radial(&spec.radial, spec.cutoff)?;
        let pair_repulsion = validate_pair_repulsion(&spec.pair_repulsion)?;
        let pair_repulsion_cutoff_p = spec
            .pair_repulsion
            .as_ref()
            .map_or(spec.radial.polynomial_cutoff_p, |pair| {
                pair.polynomial_cutoff_p
            });
        validate_layers(&spec.layers, spec.l_max, spec.atomic_numbers.len())?;
        validate_readouts(&spec.readouts, spec.layers.len())?;
        let readout_kinds = spec
            .readouts
            .iter()
            .map(|readout| readout.kind.clone())
            .collect();
        let layer_interactions = spec
            .layers
            .iter()
            .map(|layer| layer.interaction.clone())
            .collect();
        let layer_avg_num_neighbors_norm = spec
            .layers
            .iter()
            .map(|layer| layer.avg_num_neighbors_norm)
            .collect();
        let layer_products = spec
            .layers
            .iter()
            .map(|layer| layer.product.clone())
            .collect();
        let (state_dict_tensor_names, state_float_tensors) = validate_state_dict(
            spec.state_dict_format.as_deref(),
            &spec.state_dict,
            external_tensors,
        )?;
        validate_radial_state_tensors(distance_transform, &state_float_tensors)?;
        validate_pair_repulsion_state_tensors(pair_repulsion, &state_float_tensors)?;
        validate_referenced_state_tensors(&spec.layers, &state_dict_tensor_names)?;
        let conv_tp_plans = parse_tensor_product_plans(&spec.conv_tp_plans, spec.layers.len())?;
        let mp0b_runtime_plan = validate_mp0b_runtime_plan(
            spec.mp0b_runtime_plan.as_ref(),
            &spec,
            &conv_tp_plans,
            &state_float_tensors,
        )?;
        let osaka26_runtime_plan = validate_osaka26_runtime_plan(
            spec.osaka26_runtime_plan.as_ref(),
            &spec,
            &conv_tp_plans,
            &state_float_tensors,
        )?;
        let osaka_runtime_plan = validate_osaka_runtime_plan(
            spec.osaka_runtime_plan.as_ref(),
            &spec,
            &conv_tp_plans,
            &state_float_tensors,
        )?;
        let oam_runtime_plan = validate_oam_runtime_plan(
            spec.oam_runtime_plan.as_ref(),
            &spec,
            &conv_tp_plans,
            &state_float_tensors,
        )?;
        validate_mace_provenance(
            spec.provenance.as_ref(),
            mp0b_runtime_plan.is_some(),
            osaka26_runtime_plan.is_some(),
            osaka_runtime_plan.is_some(),
            oam_runtime_plan.is_some(),
            spec.state_dict_format.as_deref(),
            state_dict_tensor_names.len(),
        )?;
        let runtime_plan = select_mace_runtime_plan(
            mp0b_runtime_plan,
            osaka26_runtime_plan,
            osaka_runtime_plan,
            oam_runtime_plan,
        );
        let sh_plan = SphericalHarmonicsPlan::new(spec.l_max, true, ShNormalization::Component)?;
        let state_float_tensors_f32 = state_float_tensors
            .iter()
            .map(|(name, tensor)| {
                (
                    name.clone(),
                    StateFloatTensorF32 {
                        shape: tensor.shape.clone(),
                        values: tensor.values.iter().map(|&value| value as f32).collect(),
                    },
                )
            })
            .collect();

        let mut model = Self {
            name: spec.name,
            type_names: spec.type_names,
            atomic_numbers: spec.atomic_numbers,
            cutoff: spec.cutoff,
            l_max: spec.l_max,
            heads: spec.heads,
            num_layers: spec.layers.len(),
            layer_interactions,
            layer_avg_num_neighbors_norm,
            distance_transform,
            pair_repulsion,
            pair_repulsion_cutoff_p,
            num_bessel: spec.radial.num_bessel,
            polynomial_cutoff_p: spec.radial.polynomial_cutoff_p,
            readout_kinds,
            layer_products,
            conv_tp_plans,
            runtime_plan,
            sh_plan,
            state_dict_tensor_names,
            state_float_tensors,
            state_float_tensors_f32,
            scalar_contraction_entries: HashMap::new(),
            vector_contraction_entries: HashMap::new(),
            scalar_contraction_entries_f32: HashMap::new(),
            vector_contraction_entries_f32: HashMap::new(),
        };
        model.prescale_mp0b_blas_weights();
        model.scalar_contraction_entries = model.build_scalar_contraction_entry_cache()?;
        model.vector_contraction_entries = model.build_vector_contraction_entry_cache()?;
        model.scalar_contraction_entries_f32 = model.build_scalar_contraction_entry_cache_f32()?;
        model.vector_contraction_entries_f32 = model.build_vector_contraction_entry_cache_f32()?;
        Ok(model)
    }

    fn build_scalar_contraction_entry_cache(
        &self,
    ) -> Result<HashMap<String, MaceScalarSymmetricContractionEntries>, MaceLiteError> {
        let mut cache = HashMap::new();
        for product in &self.layer_products {
            let contraction = &product.symmetric_contraction;
            if contraction.contractions.is_empty() {
                let view = ContractionComponentView {
                    u_tensors: &contraction.u_tensors,
                    weight_tensors: &contraction.weight_tensors,
                    num_equivariance: None,
                };
                let scalar = match self.scalar_contraction_from_component_uncached(view) {
                    Ok(scalar) => scalar,
                    Err(MaceLiteError::MissingStateTensor(_)) => continue,
                    Err(err) => return Err(err),
                };
                cache.insert(contraction_entry_cache_key(view), scalar.entries()?);
                continue;
            }
            for component in &contraction.contractions {
                if component.kind != "scalar" {
                    continue;
                }
                let view = contraction_component_view(component);
                let scalar = match self.scalar_contraction_from_component_uncached(view) {
                    Ok(scalar) => scalar,
                    Err(MaceLiteError::MissingStateTensor(_)) => continue,
                    Err(err) => return Err(err),
                };
                cache.insert(contraction_entry_cache_key(view), scalar.entries()?);
            }
        }
        Ok(cache)
    }

    fn build_vector_contraction_entry_cache(
        &self,
    ) -> Result<HashMap<String, MaceVectorSymmetricContractionEntries>, MaceLiteError> {
        let mut cache = HashMap::new();
        for product in &self.layer_products {
            let contraction = &product.symmetric_contraction;
            for component in &contraction.contractions {
                if component.kind != "vector" {
                    continue;
                }
                let view = contraction_component_view(component);
                let vector = match self.vector_contraction_from_component_uncached(view) {
                    Ok(vector) => vector,
                    Err(MaceLiteError::MissingStateTensor(_)) => continue,
                    Err(err) => return Err(err),
                };
                cache.insert(contraction_entry_cache_key(view), vector.entries()?);
            }
        }
        Ok(cache)
    }

    fn build_scalar_contraction_entry_cache_f32(
        &self,
    ) -> Result<HashMap<String, ScalarContractionEntriesF32>, MaceLiteError> {
        let mut cache = HashMap::new();
        for product in &self.layer_products {
            let contraction = &product.symmetric_contraction;
            if contraction.contractions.is_empty() {
                let view = ContractionComponentView {
                    u_tensors: &contraction.u_tensors,
                    weight_tensors: &contraction.weight_tensors,
                    num_equivariance: None,
                };
                let shape = match self.scalar_contraction_shape_f32(view) {
                    Ok(shape) => shape,
                    Err(MaceLiteError::MissingStateTensor(_)) => continue,
                    Err(err) => return Err(err),
                };
                cache.insert(
                    contraction_entry_cache_key(view),
                    ScalarContractionEntriesF32::from_shape(shape),
                );
                continue;
            }
            for component in &contraction.contractions {
                if component.kind != "scalar" {
                    continue;
                }
                let view = contraction_component_view(component);
                let shape = match self.scalar_contraction_shape_f32(view) {
                    Ok(shape) => shape,
                    Err(MaceLiteError::MissingStateTensor(_)) => continue,
                    Err(err) => return Err(err),
                };
                cache.insert(
                    contraction_entry_cache_key(view),
                    ScalarContractionEntriesF32::from_shape(shape),
                );
            }
        }
        Ok(cache)
    }

    fn build_vector_contraction_entry_cache_f32(
        &self,
    ) -> Result<HashMap<String, VectorContractionEntriesF32>, MaceLiteError> {
        let mut cache = HashMap::new();
        for product in &self.layer_products {
            let contraction = &product.symmetric_contraction;
            for component in &contraction.contractions {
                if component.kind != "vector" {
                    continue;
                }
                let view = contraction_component_view(component);
                let shape = match self.vector_contraction_shape_f32(view) {
                    Ok(shape) => shape,
                    Err(MaceLiteError::MissingStateTensor(_)) => continue,
                    Err(err) => return Err(err),
                };
                cache.insert(
                    contraction_entry_cache_key(view),
                    VectorContractionEntriesF32::from_shape(shape),
                );
            }
        }
        Ok(cache)
    }

    /// Pre-multiply MP0B weight tensors by their constant path weights, so the
    /// forward/backward GEMM calls can use `alpha = 1.0`. This eliminates the
    /// libxsmm alpha workaround (post-scale or scratch-buffer combine) on the
    /// hottest BLAS dispatch sites and removes one multiply per output
    /// element on the non-BLAS fallback.
    ///
    /// Only weight tensors whose alpha is a single load-time constant across
    /// every consumer are touched. Tensors that mix different alphas (e.g.
    /// runtime-dependent factors like `density + 1`) are left alone. The
    /// transformation is idempotent on the resulting struct because
    /// `from_spec` is the only entry point that constructs `state_float_tensors`.
    fn prescale_mp0b_blas_weights(&mut self) {
        if !matches!(
            self.active_runtime_plan_kind(),
            Some(MaceRuntimePlanKind::Mp0b)
        ) {
            return;
        }
        let inv_sqrt_features = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
        let inv_sqrt_features_f32 = 1.0 / (MP0B_NUM_FEATURES as f32).sqrt();
        const UNIFORM_INV_SQRT_FEATURES_TENSORS: [&str; 4] = [
            "interactions.0.linear_up.weight",
            "interactions.1.linear_up.weight",
            "products.0.linear.weight",
            "products.1.linear.weight",
        ];
        for name in UNIFORM_INV_SQRT_FEATURES_TENSORS {
            if let Some(tensor) = self.state_float_tensors.get_mut(name) {
                for value in &mut tensor.values {
                    *value *= inv_sqrt_features;
                }
            }
            if let Some(tensor) = self.state_float_tensors_f32.get_mut(name) {
                for value in &mut tensor.values {
                    *value *= inv_sqrt_features_f32;
                }
            }
        }
        if let Some(tensor) = self
            .state_float_tensors
            .get_mut("interactions.1.linear.weight")
        {
            let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
            if tensor.values.len() == block_weights * MP0B_LAYER1_HIDDEN_PATH_WEIGHTS.len() {
                for (block, &path_weight) in MP0B_LAYER1_HIDDEN_PATH_WEIGHTS.iter().enumerate() {
                    let start = block * block_weights;
                    let end = start + block_weights;
                    for value in &mut tensor.values[start..end] {
                        *value *= path_weight;
                    }
                }
            }
        }
        if let Some(tensor) = self
            .state_float_tensors_f32
            .get_mut("interactions.1.linear.weight")
        {
            let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
            if tensor.values.len() == block_weights * MP0B_LAYER1_HIDDEN_PATH_WEIGHTS.len() {
                for (block, &path_weight) in MP0B_LAYER1_HIDDEN_PATH_WEIGHTS.iter().enumerate() {
                    let start = block * block_weights;
                    let end = start + block_weights;
                    for value in &mut tensor.values[start..end] {
                        *value *= path_weight as f32;
                    }
                }
            }
        }
    }

    fn evaluate_energy_only_with_neighbor_list(
        &self,
        structure: &Structure,
        shared_neighbor_list: Option<&NeighborList>,
        selected_nodes: Option<&[bool]>,
    ) -> Result<f64, MaceLiteError> {
        if self.state_float_tensors.is_empty() {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        if self.supports_mp0b_energy_only() {
            return self.evaluate_mp0b_energy_only(structure, shared_neighbor_list, selected_nodes);
        }
        if self.supports_osaka_runtime_energy_only() {
            return Ok(self
                .evaluate_osaka26(
                    structure,
                    false,
                    &PredictionOptions::default(),
                    shared_neighbor_list,
                    None,
                    selected_nodes,
                    MaceLiteExtraOutputRequest::default(),
                )?
                .energy);
        }
        if self.supports_oam_runtime_energy_only() {
            return Ok(self
                .evaluate_oam(
                    structure,
                    false,
                    &PredictionOptions::default(),
                    shared_neighbor_list,
                    None,
                    selected_nodes,
                    MaceLiteExtraOutputRequest::default(),
                )?
                .energy);
        }
        if !(1..=2).contains(&self.num_layers) || self.l_max > MAX_INITIAL_L || self.num_bessel != 1
        {
            return Err(MaceLiteError::UnsupportedRuntime);
        }

        let type_ids = self.type_ids(structure)?;
        let node_attrs = one_hot(&type_ids, self.type_names.len());
        let neighbor_list_storage;
        let neighbor_list = if let Some(neighbor_list) = shared_neighbor_list {
            neighbor_list_storage = neighbor_list.filtered_by_cutoff(self.cutoff)?;
            &neighbor_list_storage
        } else {
            neighbor_list_storage = all_pairs_neighbor_list(structure, self.cutoff)?;
            &neighbor_list_storage
        };
        let pair_node_energy = self.pair_repulsion_node_energy(&type_ids, neighbor_list)?;
        let mut node_feats = self.node_embedding(&type_ids)?;
        let mut readout_sum = vec![0.0; structure.len()];

        for layer in 0..self.num_layers {
            node_feats = self.evaluate_layer_product(
                layer,
                structure.len(),
                &type_ids,
                &node_attrs,
                &node_feats,
                neighbor_list,
            )?;
            self.accumulate_readout(layer, &node_feats, &mut readout_sum)?;
        }

        let atomic_energies = self.atomic_energies_tensor()?;
        let scale = self.scale_shift_scale()?;
        let shift = self.scale_shift_shift()?;
        let energy = mace_final_energy_sum_f64(
            &type_ids,
            atomic_energies,
            scale,
            shift,
            &pair_node_energy,
            selected_nodes,
            |node| readout_sum[node],
        );
        Ok(energy)
    }

    fn supports_mp0b_energy_only(&self) -> bool {
        self.has_mp0b_runtime_plan()
            && self.num_layers == 2
            && self.l_max == 3
            && self.num_bessel == 10
            && self.type_names.len() == MP0B_NUM_ELEMENTS
            && self.distance_transform == MaceDistanceTransform::Agnesi
            && self.pair_repulsion == MacePairRepulsion::Zbl
            && self.has_state_tensor("interactions.0.conv_tp.output_mask")
            && self.has_state_tensor("interactions.1.conv_tp.output_mask")
            && self.conv_tp_plan(0).is_some()
            && self.conv_tp_plan(1).is_some()
    }

    fn supports_osaka_runtime_energy_only(&self) -> bool {
        let Some(plan) = self.active_osaka_plan() else {
            return false;
        };
        let Some(layer0) = plan.layers.first() else {
            return false;
        };
        let Some(layer1) = plan.layers.get(1) else {
            return false;
        };
        matches!(
            self.active_runtime_plan_kind(),
            Some(MaceRuntimePlanKind::Osaka26 | MaceRuntimePlanKind::Osaka24)
        ) && self.num_layers == 2
            && self.l_max == 3
            && self.num_bessel == 10
            && self.type_names.len() == plan.num_elements
            && plan.num_features == MP0B_NUM_FEATURES
            && plan.sh_dim == MP0B_SH_DIM
            && layer0.product_output_dim == plan.product0_row_len
            && layer1.product_output_dim == plan.product1_row_len
            && self.has_state_tensor("interactions.0.conv_tp.output_mask")
            && self.has_state_tensor("interactions.1.conv_tp.output_mask")
            && self.conv_tp_plan(0).is_some()
            && self.conv_tp_plan(1).is_some()
    }

    fn supports_oam_runtime_energy_only(&self) -> bool {
        let Some(plan) = self.active_oam_plan() else {
            return false;
        };
        let Some(layer0) = plan.layers.first() else {
            return false;
        };
        let Some(layer1) = plan.layers.get(1) else {
            return false;
        };
        self.active_runtime_plan_kind() == Some(MaceRuntimePlanKind::Oam)
            && self.num_layers == 2
            && self.l_max == 3
            && self.num_bessel == 10
            && self.type_names.len() == plan.num_elements
            && self.distance_transform == MaceDistanceTransform::Agnesi
            && self.pair_repulsion == MacePairRepulsion::Zbl
            && plan.num_features == MP0B_NUM_FEATURES
            && plan.sh_dim == MP0B_SH_DIM
            && plan.product1_row_len == MP0B_PRODUCT1_ROW_LEN
            && layer0.product_output_dim == plan.product0_row_len
            && layer1.product_output_dim == plan.product1_row_len
            && self.has_state_tensor("interactions.0.conv_tp.output_mask")
            && self.has_state_tensor("interactions.1.conv_tp.output_mask")
            && self.has_state_tensor("interactions.0.density_fn.layer0.weight")
            && self.has_state_tensor("interactions.1.density_fn.layer0.weight")
            && self.conv_tp_plan(0).is_some()
            && self.conv_tp_plan(1).is_some()
    }

    #[allow(dead_code)]
    fn supports_osaka24_runtime_energy_only(&self) -> bool {
        matches!(
            self.active_runtime_plan_kind(),
            Some(MaceRuntimePlanKind::Osaka24)
        ) && self.supports_osaka_runtime_energy_only()
    }

    fn evaluate_mp0b_energy_only(
        &self,
        structure: &Structure,
        shared_neighbor_list: Option<&NeighborList>,
        selected_nodes: Option<&[bool]>,
    ) -> Result<f64, MaceLiteError> {
        Ok(self
            .evaluate_mp0b(
                structure,
                false,
                &PredictionOptions::default(),
                shared_neighbor_list,
                None,
                selected_nodes,
                MaceLiteExtraOutputRequest::default(),
            )?
            .energy)
    }

    #[allow(clippy::too_many_arguments)]
    fn evaluate_mp0b(
        &self,
        structure: &Structure,
        compute_forces: bool,
        options: &PredictionOptions,
        shared_neighbor_list: Option<&NeighborList>,
        prepared: Option<&MaceLitePreparedInput>,
        selected_nodes: Option<&[bool]>,
        extra: MaceLiteExtraOutputRequest,
    ) -> Result<MaceLiteOutput, MaceLiteError> {
        let trace_timings = mace_trace_timings_enabled();
        let eval_start = trace_timings.then(Instant::now);
        let runtime_plan = self.mp0b_plan_spec()?;
        let type_ids_storage;
        let type_ids = if let Some(prepared) = prepared {
            prepared.type_ids.as_slice()
        } else {
            type_ids_storage = self.type_ids(structure)?;
            &type_ids_storage
        };
        let node_attrs_storage;
        let node_attrs = if let Some(prepared) = prepared {
            prepared.node_attrs_f64.as_slice()
        } else {
            node_attrs_storage = one_hot(type_ids, self.type_names.len());
            &node_attrs_storage
        };
        let neighbor_list_storage;
        let neighbor_list = if let Some(prepared) = prepared {
            &prepared.neighbor_list
        } else if let Some(neighbor_list) = shared_neighbor_list {
            neighbor_list_storage = neighbor_list.filtered_by_cutoff(self.cutoff)?;
            &neighbor_list_storage
        } else {
            neighbor_list_storage = cell_list_multi_image_neighbor_list(structure, self.cutoff)?;
            &neighbor_list_storage
        };
        let num_nodes = structure.len();
        let num_edges = neighbor_list.edges.len();
        let prepared_mp0b_cache = prepared
            .and_then(|prepared| prepared.mp0b_cache.as_deref())
            .filter(|cache| {
                cache.matches_f64(num_nodes, num_edges, runtime_plan.sh_dim, self.num_bessel)
            });
        let pair_node_energy = if let Some(cache) = prepared_mp0b_cache {
            cache.pair_node_energy.clone()
        } else if let Some(cached) =
            prepared.and_then(|prepared| prepared.cached_pair_node_energy(num_nodes, num_edges))
        {
            cached.to_vec()
        } else {
            self.pair_repulsion_node_energy(type_ids, neighbor_list)?
        };
        let senders_storage;
        let receivers_storage;
        let prepared_edge_data = prepared
            .filter(|prepared| prepared.neighbor_list.edges.len() == neighbor_list.edges.len());
        let (senders, receivers): (&[usize], &[usize]) = if let Some(prepared) = prepared_edge_data
        {
            (&prepared.senders, &prepared.receivers)
        } else {
            senders_storage = neighbor_list
                .edges
                .iter()
                .map(|edge| edge.src)
                .collect::<Vec<_>>();
            receivers_storage = neighbor_list
                .edges
                .iter()
                .map(|edge| edge.dst)
                .collect::<Vec<_>>();
            (&senders_storage, &receivers_storage)
        };

        let mut section_start = trace_timings.then(Instant::now);
        let mut edge_attrs = if let Some(cache) = prepared_mp0b_cache {
            cache.edge_attrs_f64.clone()
        } else {
            vec![0.0; num_edges * runtime_plan.sh_dim]
        };
        let mut edge_feats = if let Some(cache) = prepared_mp0b_cache {
            cache.edge_feats_f64.clone()
        } else {
            vec![0.0; num_edges * self.num_bessel]
        };
        let mut radial_cache = compute_forces.then(|| {
            prepared_mp0b_cache.map_or_else(
                || RadialEmbeddingEdgeCache {
                    bessel_basis: vec![0.0; num_edges * self.num_bessel],
                    radial_distance: vec![0.0; num_edges],
                    radial_distance_derivative: vec![0.0; num_edges],
                },
                |cache| cache.radial_cache.clone(),
            )
        });
        let edge_features_done = prepared_mp0b_cache.is_some();
        #[cfg(feature = "parallel")]
        let edge_features_done = edge_features_done
            || if rayon::current_num_threads() > 1
                && num_edges >= 512
                && runtime_plan.sh_dim == MP0B_SH_DIM
                && self.num_bessel == 10
            {
                if let Some(cache) = radial_cache.as_mut() {
                    edge_attrs
                        .par_chunks_mut(runtime_plan.sh_dim)
                        .zip(edge_feats.par_chunks_mut(self.num_bessel))
                        .zip(cache.bessel_basis.par_chunks_mut(self.num_bessel))
                        .zip(cache.radial_distance.par_iter_mut())
                        .zip(cache.radial_distance_derivative.par_iter_mut())
                        .enumerate()
                        .map_init(
                            || (vec![0.0; self.num_bessel], vec![0.0; self.num_bessel]),
                            |(bessel_basis, radial),
                             (
                                edge_index,
                                (
                                    (
                                        ((edge_attr_row, edge_feat_row), cache_basis_row),
                                        cache_distance,
                                    ),
                                    cache_derivative,
                                ),
                            )|
                             -> Result<(), MaceLiteError> {
                                let edge = &neighbor_list.edges[edge_index];
                                self.sh_plan.forward(edge.vector, edge_attr_row)?;
                                let radial_distance = self.radial_embedding_forward(
                                    edge.distance,
                                    type_ids[edge.src],
                                    type_ids[edge.dst],
                                    bessel_basis,
                                    radial,
                                )?;
                                cache_basis_row.copy_from_slice(bessel_basis);
                                *cache_distance = radial_distance.value;
                                *cache_derivative = radial_distance.derivative;
                                edge_feat_row.copy_from_slice(radial);
                                Ok(())
                            },
                        )
                        .try_for_each(|result| result)?;
                } else {
                    edge_attrs
                        .par_chunks_mut(runtime_plan.sh_dim)
                        .zip(edge_feats.par_chunks_mut(self.num_bessel))
                        .enumerate()
                        .map_init(
                            || (vec![0.0; self.num_bessel], vec![0.0; self.num_bessel]),
                            |(bessel_basis, radial),
                             (edge_index, (edge_attr_row, edge_feat_row))|
                             -> Result<(), MaceLiteError> {
                                let edge = &neighbor_list.edges[edge_index];
                                self.sh_plan.forward(edge.vector, edge_attr_row)?;
                                self.radial_embedding_forward(
                                    edge.distance,
                                    type_ids[edge.src],
                                    type_ids[edge.dst],
                                    bessel_basis,
                                    radial,
                                )?;
                                edge_feat_row.copy_from_slice(radial);
                                Ok(())
                            },
                        )
                        .try_for_each(|result| result)?;
                }
                true
            } else {
                false
            };
        if !edge_features_done {
            let mut bessel_basis = vec![0.0; self.num_bessel];
            let mut radial = vec![0.0; self.num_bessel];
            for (edge_index, edge) in neighbor_list.edges.iter().enumerate() {
                self.sh_plan.forward(
                    edge.vector,
                    &mut edge_attrs
                        [edge_index * runtime_plan.sh_dim..(edge_index + 1) * runtime_plan.sh_dim],
                )?;
                let radial_distance = self.radial_embedding_forward(
                    edge.distance,
                    type_ids[edge.src],
                    type_ids[edge.dst],
                    &mut bessel_basis,
                    &mut radial,
                )?;
                if let Some(cache) = radial_cache.as_mut() {
                    cache.bessel_basis
                        [edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel]
                        .copy_from_slice(&bessel_basis);
                    cache.radial_distance[edge_index] = radial_distance.value;
                    cache.radial_distance_derivative[edge_index] = radial_distance.derivative;
                }
                edge_feats[edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel]
                    .copy_from_slice(&radial);
            }
        }
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 edge_features_ms={:.3} edges={num_edges}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let node_plan = &runtime_plan.node_embedding;
        let mut node_feats = vec![0.0; num_nodes * node_plan.out_features];
        osaka_node_embedding(
            type_ids,
            self.float_tensor(
                "node_embedding.linear.weight",
                &[node_plan.in_features * node_plan.out_features],
            )?,
            self.float_tensor(
                "node_embedding.linear.output_mask",
                &[node_plan.out_features],
            )?,
            Mp0bMaskedLinearSpec {
                input_row_len: node_plan.input_row_len,
                in_features: node_plan.in_features,
                out_features: node_plan.out_features,
                path_weight: node_plan.path_weight,
            },
            &mut node_feats,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 node_embedding_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let layer0 = self.mp0b_layer0_forward_cached(
            num_nodes,
            node_attrs,
            &node_feats,
            &edge_attrs,
            &edge_feats,
            senders,
            receivers,
            compute_forces,
            prepared_mp0b_cache.and_then(|cache| cache.layer0_tp_f64.as_ref()),
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer0_forward_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let readout0 = self.mp0b_readout0(&layer0.product_out)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 readout0_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let layer1 = self.mp0b_layer1_forward_cached(
            num_nodes,
            node_attrs,
            &layer0.product_out,
            &edge_attrs,
            &edge_feats,
            senders,
            receivers,
            compute_forces,
            prepared_mp0b_cache.and_then(|cache| cache.layer1_tp_f64.as_ref()),
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer1_forward_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let readout1 = self.mp0b_readout1(&layer1.product_out)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 readout1_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        let atomic_energies = self.float_tensor(
            "atomic_energies_fn.atomic_energies",
            &[self.type_names.len()],
        )?;
        let scale = self.float_scalar("scale_shift.scale")?;
        let shift = self.float_scalar("scale_shift.shift")?;
        let (energy, atomic_energies_out) = mace_node_energy_sum_and_optional_values_f64(
            type_ids,
            atomic_energies,
            &pair_node_energy,
            scale,
            shift,
            selected_nodes,
            extra.atomic_energies,
            |node| readout0[node] + readout1[node],
        );

        let (forces, stress, virial) = if compute_forces {
            section_start = trace_timings.then(Instant::now);
            let mut vjp = self.mp0b_vjp(
                type_ids,
                node_attrs,
                neighbor_list,
                &edge_attrs,
                &edge_feats,
                senders,
                receivers,
                &layer0,
                &layer1,
                scale,
                selected_nodes,
                options.compute_stress || options.compute_virial,
                radial_cache.as_ref(),
                prepared_mp0b_cache.and_then(|cache| cache.layer0_tp_f64.as_ref()),
                prepared_mp0b_cache.and_then(|cache| cache.layer1_tp_f64.as_ref()),
            )?;
            self.add_pair_repulsion_vjp(
                type_ids,
                neighbor_list,
                scale,
                selected_nodes,
                options.compute_stress || options.compute_virial,
                &mut vjp,
            )?;
            if let Some(start) = section_start.take() {
                eprintln!(
                    "mace_mp0b_f64 vjp_total_ms={:.3}",
                    mace_trace_elapsed_ms(start)
                );
            }
            vjp.into_output_tensors(structure, options, self.cutoff, selected_nodes.is_none())?
        } else {
            (Vec::new(), None, None)
        };
        if let Some(start) = eval_start {
            eprintln!(
                "mace_mp0b_f64 eval_total_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        let descriptors = if extra.descriptors {
            Some(self.descriptors_from_layer_outputs(
                &[layer0.product_out.as_slice(), layer1.product_out.as_slice()],
                num_nodes,
                extra.descriptor_invariants_only,
                extra.descriptor_num_layers,
            )?)
        } else {
            None
        };
        Ok(MaceLiteOutput {
            energy,
            forces,
            stress,
            virial,
            atomic_energies: atomic_energies_out,
            descriptors,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn mp0b_layer0_forward_cached(
        &self,
        num_nodes: usize,
        node_attrs: &[f64],
        node_feats: &[f64],
        edge_attrs: &[f64],
        edge_feats: &[f64],
        senders: &[usize],
        receivers: &[usize],
        cache_tp_weights: bool,
        cached_tp_weights: Option<&Mp0bConvTpWeightsForward>,
    ) -> Result<Mp0bLayerForward, MaceLiteError> {
        let trace_timings = mace_trace_timings_enabled();
        let mut section_start = trace_timings.then(Instant::now);
        let layer_plan = self.mp0b_layer_plan_spec(0)?;
        let mut linear_up = vec![0.0; num_nodes * layer_plan.linear_up_output_dim];
        mp0b_scalar_product_linear(
            node_feats,
            self.float_tensor(
                "interactions.0.linear_up.weight",
                &[MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "interactions.0.linear_up.output_mask",
                &[layer_plan.linear_up_output_dim],
            )?,
            1.0,
            &mut linear_up,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer0_linear_up_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let (tp_weights, tp_weight_cache, cached_tp_weights_ref) = if cache_tp_weights {
            if let Some(cached) = cached_tp_weights {
                (Vec::new(), None, Some(cached.output.as_slice()))
            } else {
                let forward = self.mp0b_conv_tp_weights_with_cache(0, edge_feats)?;
                (forward.output, Some(forward.cache), None)
            }
        } else if let Some(cached) = cached_tp_weights {
            (Vec::new(), None, Some(cached.output.as_slice()))
        } else {
            (self.mp0b_conv_tp_weights(0, edge_feats)?, None, None)
        };
        let tp_weights_ref = cached_tp_weights_ref.unwrap_or(&tp_weights);
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer0_tp_weights_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let density = self.mp0b_density(0, edge_feats, receivers, num_nodes)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer0_density_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let conv_plan = self
            .conv_tp_plan(0)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let mut scatter_message = vec![0.0; num_nodes * conv_plan.output_dim()];
        mp0b_apply_conv_tp(
            Mp0bConvTpInput {
                plan: conv_plan,
                linear_up: &linear_up,
                edge_attrs,
                tp_weights: tp_weights_ref,
                output_mask: self.float_tensor(
                    "interactions.0.conv_tp.output_mask",
                    &[layer_plan.conv_tp_output_dim],
                )?,
                senders,
                receivers,
            },
            &mut scatter_message,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer0_conv_tp_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let mut linear_message = vec![0.0; num_nodes * layer_plan.linear_message_output_dim];
        mp0b_layer0_hidden_linear(
            &scatter_message,
            &density,
            self.float_tensor(
                "interactions.0.linear.weight",
                &[4 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "interactions.0.linear.output_mask",
                &[layer_plan.linear_message_output_dim],
            )?,
            &mut linear_message,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer0_hidden_linear_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let mut selected_message = vec![0.0; num_nodes * layer_plan.skip_output_dim];
        mp0b_hidden_message_selector(
            &linear_message,
            node_attrs,
            self.float_tensor(
                "interactions.0.skip_tp.weight",
                &[4 * MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "interactions.0.skip_tp.output_mask",
                &[layer_plan.skip_output_dim],
            )?,
            &mut selected_message,
        );
        let mut interaction_out = vec![0.0; num_nodes * layer_plan.linear_message_output_dim];
        mp0b_reshape_hidden_irreps_to_feature_major(&selected_message, &mut interaction_out);
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer0_selector_reshape_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let contraction = self.layer_scalar_vector_contraction(0)?;
        let mut product_symmetric = vec![0.0; num_nodes * layer_plan.product_output_dim];
        contraction.forward(&interaction_out, node_attrs, &mut product_symmetric)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer0_product_contraction_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let mut product_out = vec![0.0; num_nodes * layer_plan.product_output_dim];
        mp0b_scalar_vector_product_linear(
            &product_symmetric,
            self.float_tensor(
                "products.0.linear.weight",
                &[2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "products.0.linear.output_mask",
                &[layer_plan.product_output_dim],
            )?,
            1.0,
            &mut product_out,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer0_product_linear_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        Ok(Mp0bLayerForward {
            linear_up,
            tp_weights,
            tp_weight_cache,
            density,
            scatter_message,
            linear_message,
            interaction_out,
            product_out,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn mp0b_layer1_forward_cached(
        &self,
        num_nodes: usize,
        node_attrs: &[f64],
        node_feats: &[f64],
        edge_attrs: &[f64],
        edge_feats: &[f64],
        senders: &[usize],
        receivers: &[usize],
        cache_tp_weights: bool,
        cached_tp_weights: Option<&Mp0bConvTpWeightsForward>,
    ) -> Result<Mp0bLayerForward, MaceLiteError> {
        let trace_timings = mace_trace_timings_enabled();
        let mut section_start = trace_timings.then(Instant::now);
        let layer_plan = self.mp0b_layer_plan_spec(1)?;
        let mut linear_up = vec![0.0; num_nodes * layer_plan.linear_up_output_dim];
        mp0b_scalar_vector_product_linear(
            node_feats,
            self.float_tensor(
                "interactions.1.linear_up.weight",
                &[2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "interactions.1.linear_up.output_mask",
                &[layer_plan.linear_up_output_dim],
            )?,
            1.0,
            &mut linear_up,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer1_linear_up_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let (tp_weights, tp_weight_cache, cached_tp_weights_ref) = if cache_tp_weights {
            if let Some(cached) = cached_tp_weights {
                (Vec::new(), None, Some(cached.output.as_slice()))
            } else {
                let forward = self.mp0b_conv_tp_weights_with_cache(1, edge_feats)?;
                (forward.output, Some(forward.cache), None)
            }
        } else if let Some(cached) = cached_tp_weights {
            (Vec::new(), None, Some(cached.output.as_slice()))
        } else {
            (self.mp0b_conv_tp_weights(1, edge_feats)?, None, None)
        };
        let tp_weights_ref = cached_tp_weights_ref.unwrap_or(&tp_weights);
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer1_tp_weights_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let density = self.mp0b_density(1, edge_feats, receivers, num_nodes)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer1_density_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let conv_plan = self
            .conv_tp_plan(1)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let mut scatter_message = vec![0.0; num_nodes * conv_plan.output_dim()];
        mp0b_apply_conv_tp(
            Mp0bConvTpInput {
                plan: conv_plan,
                linear_up: &linear_up,
                edge_attrs,
                tp_weights: tp_weights_ref,
                output_mask: self.float_tensor(
                    "interactions.1.conv_tp.output_mask",
                    &[layer_plan.conv_tp_output_dim],
                )?,
                senders,
                receivers,
            },
            &mut scatter_message,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer1_conv_tp_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let mut linear_message = vec![0.0; num_nodes * layer_plan.linear_message_output_dim];
        mp0b_layer1_hidden_linear(
            &scatter_message,
            &density,
            self.float_tensor(
                "interactions.1.linear.weight",
                &[10 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "interactions.1.linear.output_mask",
                &[layer_plan.linear_message_output_dim],
            )?,
            &mut linear_message,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer1_hidden_linear_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let mut interaction_out = vec![0.0; num_nodes * layer_plan.linear_message_output_dim];
        mp0b_reshape_hidden_irreps_to_feature_major(&linear_message, &mut interaction_out);
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer1_reshape_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let contraction = self.layer_contraction(1)?;
        let mut product_symmetric = vec![0.0; num_nodes * layer_plan.product_output_dim];
        contraction.forward(&interaction_out, node_attrs, &mut product_symmetric)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer1_product_contraction_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let mut product_linear = vec![0.0; num_nodes * layer_plan.product_output_dim];
        mp0b_scalar_product_linear(
            &product_symmetric,
            self.float_tensor(
                "products.1.linear.weight",
                &[MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "products.1.linear.output_mask",
                &[layer_plan.product_output_dim],
            )?,
            1.0,
            &mut product_linear,
        );
        let mut skip = vec![0.0; num_nodes * layer_plan.skip_output_dim];
        mp0b_scalar_residual_skip(
            node_feats,
            node_attrs,
            self.float_tensor(
                "interactions.1.skip_tp.weight",
                &[MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "interactions.1.skip_tp.output_mask",
                &[layer_plan.skip_output_dim],
            )?,
            &mut skip,
        );
        for (value, skip_value) in product_linear.iter_mut().zip(skip) {
            *value += skip_value;
        }
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer1_product_skip_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        Ok(Mp0bLayerForward {
            linear_up,
            tp_weights,
            tp_weight_cache,
            density,
            scatter_message,
            linear_message,
            interaction_out,
            product_out: product_linear,
        })
    }

    fn mp0b_conv_tp_weights(
        &self,
        layer: usize,
        edge_feats: &[f64],
    ) -> Result<Vec<f64>, MaceLiteError> {
        let layer_plan = self.mp0b_layer_plan_spec(layer)?;
        let hidden_dim = layer_plan.conv_tp_weight_mlp_hidden_dim;
        let output_dim = layer_plan.conv_tp_weight_numel;
        let num_edges = edge_feats.len() / self.num_bessel;
        let mut hidden0 = vec![0.0; num_edges * hidden_dim];
        mp0b_dense_input_major(
            edge_feats,
            num_edges,
            self.num_bessel,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer0.weight"),
                &[self.num_bessel, hidden_dim],
            )?,
            &mut hidden0,
        );
        mp0b_apply_scaled_silu(&mut hidden0);
        let mut hidden1 = vec![0.0; num_edges * hidden_dim];
        mp0b_dense_input_major(
            &hidden0,
            num_edges,
            hidden_dim,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer1.weight"),
                &[hidden_dim, hidden_dim],
            )?,
            &mut hidden1,
        );
        mp0b_apply_scaled_silu(&mut hidden1);
        let mut hidden2 = vec![0.0; num_edges * hidden_dim];
        mp0b_dense_input_major(
            &hidden1,
            num_edges,
            hidden_dim,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer2.weight"),
                &[hidden_dim, hidden_dim],
            )?,
            &mut hidden2,
        );
        mp0b_apply_scaled_silu(&mut hidden2);
        let mut output = vec![0.0; num_edges * output_dim];
        mp0b_dense_input_major(
            &hidden2,
            num_edges,
            hidden_dim,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer3.weight"),
                &[hidden_dim, output_dim],
            )?,
            &mut output,
        );
        Ok(output)
    }

    fn mp0b_conv_tp_weights_with_cache(
        &self,
        layer: usize,
        edge_feats: &[f64],
    ) -> Result<Mp0bConvTpWeightsForward, MaceLiteError> {
        let layer_plan = self.mp0b_layer_plan_spec(layer)?;
        self.large_conv_tp_weights_with_plan(layer, layer_plan, edge_feats)
    }

    fn large_conv_tp_weights_with_plan(
        &self,
        layer: usize,
        layer_plan: &PinnedMaceRuntimeLayerPlanSpec,
        edge_feats: &[f64],
    ) -> Result<Mp0bConvTpWeightsForward, MaceLiteError> {
        let trace_timings = mace_trace_timings_enabled();
        let hidden_dim = layer_plan.conv_tp_weight_mlp_hidden_dim;
        let output_dim = layer_plan.conv_tp_weight_numel;
        let num_edges = edge_feats.len() / self.num_bessel;

        let mut section_start = trace_timings.then(Instant::now);
        let mut hidden0 = vec![0.0; num_edges * hidden_dim];
        mp0b_dense_input_major(
            edge_feats,
            num_edges,
            self.num_bessel,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer0.weight"),
                &[self.num_bessel, hidden_dim],
            )?,
            &mut hidden0,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer{layer}_tp_mlp_layer0_dense_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let hidden0_raw = hidden0.clone();
        let mut hidden0_derivative = vec![0.0; hidden0.len()];
        mp0b_apply_scaled_silu_in_place_with_derivative(&mut hidden0, &mut hidden0_derivative);
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer{layer}_tp_mlp_layer0_silu_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let mut hidden1 = vec![0.0; num_edges * hidden_dim];
        mp0b_dense_input_major(
            &hidden0,
            num_edges,
            hidden_dim,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer1.weight"),
                &[hidden_dim, hidden_dim],
            )?,
            &mut hidden1,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer{layer}_tp_mlp_layer1_dense_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let hidden1_raw = hidden1.clone();
        let mut hidden1_derivative = vec![0.0; hidden1.len()];
        mp0b_apply_scaled_silu_in_place_with_derivative(&mut hidden1, &mut hidden1_derivative);
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer{layer}_tp_mlp_layer1_silu_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let mut hidden2 = vec![0.0; num_edges * hidden_dim];
        mp0b_dense_input_major(
            &hidden1,
            num_edges,
            hidden_dim,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer2.weight"),
                &[hidden_dim, hidden_dim],
            )?,
            &mut hidden2,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer{layer}_tp_mlp_layer2_dense_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let hidden2_raw = hidden2.clone();
        let mut hidden2_derivative = vec![0.0; hidden2.len()];
        mp0b_apply_scaled_silu_in_place_with_derivative(&mut hidden2, &mut hidden2_derivative);
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer{layer}_tp_mlp_layer2_silu_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let mut output = vec![0.0; num_edges * output_dim];
        mp0b_dense_input_major(
            &hidden2,
            num_edges,
            hidden_dim,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer3.weight"),
                &[hidden_dim, output_dim],
            )?,
            &mut output,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 layer{layer}_tp_mlp_layer3_dense_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        Ok(Mp0bConvTpWeightsForward {
            output,
            cache: Mp0bConvTpWeightCache {
                hidden0_raw,
                hidden1_raw,
                hidden2_raw,
                hidden0_derivative,
                hidden1_derivative,
                hidden2_derivative,
            },
        })
    }

    fn mp0b_density(
        &self,
        layer: usize,
        edge_feats: &[f64],
        receivers: &[usize],
        num_nodes: usize,
    ) -> Result<Vec<f64>, MaceLiteError> {
        let num_edges = receivers.len();
        let mut density_linear = vec![0.0; num_edges];
        mp0b_dense_input_major(
            edge_feats,
            num_edges,
            self.num_bessel,
            self.float_tensor(
                &format!("interactions.{layer}.density_fn.layer0.weight"),
                &[self.num_bessel, 1],
            )?,
            &mut density_linear,
        );
        let mut density = vec![0.0; num_nodes];
        for (edge, &receiver) in receivers.iter().enumerate() {
            density[receiver] += (density_linear[edge] * density_linear[edge]).tanh();
        }
        Ok(density)
    }

    fn mp0b_readout0(&self, node_feats: &[f64]) -> Result<Vec<f64>, MaceLiteError> {
        let mut output = vec![0.0; node_feats.len() / MP0B_PRODUCT0_ROW_LEN];
        mp0b_masked_linear(
            node_feats,
            self.float_tensor("readouts.0.linear.weight", &[MP0B_NUM_FEATURES])?,
            self.float_tensor("readouts.0.linear.output_mask", &[1])?,
            Mp0bMaskedLinearSpec {
                input_row_len: MP0B_PRODUCT0_ROW_LEN,
                in_features: MP0B_NUM_FEATURES,
                out_features: 1,
                path_weight: 1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
            },
            &mut output,
        );
        Ok(output)
    }

    fn mp0b_readout1(&self, node_feats: &[f64]) -> Result<Vec<f64>, MaceLiteError> {
        let num_nodes = node_feats.len() / MP0B_PRODUCT1_ROW_LEN;
        let mut hidden = vec![0.0; num_nodes * 16];
        mp0b_masked_linear(
            node_feats,
            self.float_tensor("readouts.1.linear_1.weight", &[MP0B_NUM_FEATURES * 16])?,
            self.float_tensor("readouts.1.linear_1.output_mask", &[16])?,
            Mp0bMaskedLinearSpec {
                input_row_len: MP0B_PRODUCT1_ROW_LEN,
                in_features: MP0B_NUM_FEATURES,
                out_features: 16,
                path_weight: 1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
            },
            &mut hidden,
        );
        mp0b_apply_scaled_silu(&mut hidden);
        let mut output = vec![0.0; num_nodes];
        mp0b_masked_linear(
            &hidden,
            self.float_tensor("readouts.1.linear_2.weight", &[16])?,
            self.float_tensor("readouts.1.linear_2.output_mask", &[1])?,
            Mp0bMaskedLinearSpec {
                input_row_len: 16,
                in_features: 16,
                out_features: 1,
                path_weight: 1.0 / (16.0_f64).sqrt(),
            },
            &mut output,
        );
        Ok(output)
    }

    fn mp0b_readout0_vjp(
        &self,
        bar_readout: &[f64],
        bar_product_out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        mp0b_masked_linear_vjp_input(
            self.float_tensor("readouts.0.linear.weight", &[MP0B_NUM_FEATURES])?,
            self.float_tensor("readouts.0.linear.output_mask", &[1])?,
            Mp0bMaskedLinearSpec {
                input_row_len: MP0B_PRODUCT0_ROW_LEN,
                in_features: MP0B_NUM_FEATURES,
                out_features: 1,
                path_weight: 1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
            },
            bar_readout,
            bar_product_out,
        );
        Ok(())
    }

    fn mp0b_readout1_vjp(
        &self,
        product_out: &[f64],
        bar_readout: &[f64],
        bar_product_out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let num_nodes = product_out.len() / MP0B_PRODUCT1_ROW_LEN;
        let mut hidden_raw = vec![0.0; num_nodes * 16];
        mp0b_masked_linear(
            product_out,
            self.float_tensor("readouts.1.linear_1.weight", &[MP0B_NUM_FEATURES * 16])?,
            self.float_tensor("readouts.1.linear_1.output_mask", &[16])?,
            Mp0bMaskedLinearSpec {
                input_row_len: MP0B_PRODUCT1_ROW_LEN,
                in_features: MP0B_NUM_FEATURES,
                out_features: 16,
                path_weight: 1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
            },
            &mut hidden_raw,
        );
        let mut bar_hidden = vec![0.0; hidden_raw.len()];
        mp0b_masked_linear_vjp_input(
            self.float_tensor("readouts.1.linear_2.weight", &[16])?,
            self.float_tensor("readouts.1.linear_2.output_mask", &[1])?,
            Mp0bMaskedLinearSpec {
                input_row_len: 16,
                in_features: 16,
                out_features: 1,
                path_weight: 1.0 / (16.0_f64).sqrt(),
            },
            bar_readout,
            &mut bar_hidden,
        );
        for (bar, &raw) in bar_hidden.iter_mut().zip(&hidden_raw) {
            *bar *= MACE_SILU_SCALE * silu_derivative(raw);
        }
        mp0b_masked_linear_vjp_input(
            self.float_tensor("readouts.1.linear_1.weight", &[MP0B_NUM_FEATURES * 16])?,
            self.float_tensor("readouts.1.linear_1.output_mask", &[16])?,
            Mp0bMaskedLinearSpec {
                input_row_len: MP0B_PRODUCT1_ROW_LEN,
                in_features: MP0B_NUM_FEATURES,
                out_features: 16,
                path_weight: 1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
            },
            &bar_hidden,
            bar_product_out,
        );
        Ok(())
    }

    fn mp0b_product0_vjp_to_interaction_out(
        &self,
        node_attrs: &[f64],
        interaction_out: &[f64],
        bar_product_out: &[f64],
        bar_interaction_out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let mut bar_product_symmetric = vec![0.0; bar_product_out.len()];
        mp0b_scalar_vector_product_linear_vjp_input(
            self.float_tensor(
                "products.0.linear.weight",
                &[2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor("products.0.linear.output_mask", &[MP0B_PRODUCT0_ROW_LEN])?,
            bar_product_out,
            1.0,
            &mut bar_product_symmetric,
        );
        self.layer_scalar_vector_contraction(0)?.vjp_x(
            interaction_out,
            node_attrs,
            &bar_product_symmetric,
            bar_interaction_out,
        )?;
        Ok(())
    }

    fn mp0b_product1_vjp_to_interaction_out(
        &self,
        node_attrs: &[f64],
        interaction_out: &[f64],
        bar_product_out: &[f64],
        bar_interaction_out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let mut bar_product_symmetric = vec![0.0; bar_product_out.len()];
        mp0b_scalar_product_linear_vjp_input(
            self.float_tensor(
                "products.1.linear.weight",
                &[MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor("products.1.linear.output_mask", &[MP0B_PRODUCT1_ROW_LEN])?,
            bar_product_out,
            1.0,
            &mut bar_product_symmetric,
        );
        self.layer_contraction(1)?.vjp_x(
            interaction_out,
            node_attrs,
            &bar_product_symmetric,
            bar_interaction_out,
        )?;
        Ok(())
    }

