    fn mp0b_layer0_message_vjp_to_scatter_density(
        &self,
        node_attrs: &[f64],
        scatter_message: &[f64],
        density: &[f64],
        linear_message: &[f64],
        bar_interaction_out: &[f64],
    ) -> Result<Mp0bMessageVjp, MaceLiteError> {
        let mut bar_linear_message = vec![0.0; bar_interaction_out.len()];
        mp0b_hidden_message_selector_vjp_input_from_feature_major(
            node_attrs,
            self.float_tensor(
                "interactions.0.skip_tp.weight",
                &[4 * MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor("interactions.0.skip_tp.output_mask", &[MP0B_HIDDEN_ROW_LEN])?,
            bar_interaction_out,
            &mut bar_linear_message,
        );
        let mut bar_scatter_message = vec![0.0; scatter_message.len()];
        let mut bar_density = vec![0.0; density.len()];
        mp0b_layer0_hidden_linear_vjp_input_density(
            scatter_message,
            density,
            linear_message,
            self.float_tensor(
                "interactions.0.linear.weight",
                &[4 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor("interactions.0.linear.output_mask", &[MP0B_HIDDEN_ROW_LEN])?,
            &bar_linear_message,
            &mut bar_scatter_message,
            &mut bar_density,
        );
        Ok(Mp0bMessageVjp {
            bar_scatter_message,
            bar_density,
        })
    }

    fn mp0b_layer1_message_vjp_to_scatter_density(
        &self,
        scatter_message: &[f64],
        density: &[f64],
        linear_message: &[f64],
        bar_interaction_out: &[f64],
    ) -> Result<Mp0bMessageVjp, MaceLiteError> {
        let mut bar_linear_message = vec![0.0; bar_interaction_out.len()];
        mp0b_reshape_hidden_irreps_to_feature_major_vjp(
            bar_interaction_out,
            &mut bar_linear_message,
        );
        let mut bar_scatter_message = vec![0.0; scatter_message.len()];
        let mut bar_density = vec![0.0; density.len()];
        mp0b_layer1_hidden_linear_vjp_input_density(
            scatter_message,
            density,
            linear_message,
            self.float_tensor(
                "interactions.1.linear.weight",
                &[10 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor("interactions.1.linear.output_mask", &[MP0B_HIDDEN_ROW_LEN])?,
            &bar_linear_message,
            &mut bar_scatter_message,
            &mut bar_density,
        );
        Ok(Mp0bMessageVjp {
            bar_scatter_message,
            bar_density,
        })
    }

    fn conv_tp_plan(&self, layer: usize) -> Option<&TensorProductPlan> {
        self.conv_tp_plans
            .iter()
            .find(|entry| entry.layer == layer)
            .map(|entry| &entry.plan)
    }

    fn mp0b_plan_spec(&self) -> Result<&PinnedMaceRuntimePlanSpec, MaceLiteError> {
        match self.runtime_plan.as_ref() {
            Some((MaceRuntimePlanKind::Mp0b, plan)) => Ok(plan),
            _ => Err(MaceLiteError::UnsupportedRuntime),
        }
    }

    fn mp0b_layer_plan_spec(
        &self,
        layer: usize,
    ) -> Result<&PinnedMaceRuntimeLayerPlanSpec, MaceLiteError> {
        self.mp0b_plan_spec()?
            .layers
            .get(layer)
            .ok_or(MaceLiteError::UnsupportedRuntime)
    }

    fn active_osaka_plan(&self) -> Option<&PinnedMaceRuntimePlanSpec> {
        match self.runtime_plan.as_ref() {
            Some((MaceRuntimePlanKind::Osaka26 | MaceRuntimePlanKind::Osaka24, plan)) => Some(plan),
            _ => None,
        }
    }

    fn active_osaka_plan_spec(&self) -> Result<&PinnedMaceRuntimePlanSpec, MaceLiteError> {
        // The Osaka24/26 conv-TP / readout helpers are shared by the
        // plan. Route plan-spec lookups to the active plan family so the OAM path resolves
        // its own (structurally identical) runtime spec instead of failing with
        // `UnsupportedRuntime`. Osaka24/26 models are unaffected.
        if self.active_runtime_plan_kind() == Some(MaceRuntimePlanKind::Oam) {
            return self.active_oam_plan_spec();
        }
        self.active_osaka_plan()
            .ok_or(MaceLiteError::UnsupportedRuntime)
    }

    fn osaka26_layer_plan_spec(
        &self,
        layer: usize,
    ) -> Result<&PinnedMaceRuntimeLayerPlanSpec, MaceLiteError> {
        self.active_osaka_plan_spec()?
            .layers
            .get(layer)
            .ok_or(MaceLiteError::UnsupportedRuntime)
    }

    fn active_oam_plan(&self) -> Option<&PinnedMaceRuntimePlanSpec> {
        match self.runtime_plan.as_ref() {
            Some((MaceRuntimePlanKind::Oam, plan)) => Some(plan),
            _ => None,
        }
    }

    fn active_oam_plan_spec(&self) -> Result<&PinnedMaceRuntimePlanSpec, MaceLiteError> {
        self.active_oam_plan()
            .ok_or(MaceLiteError::UnsupportedRuntime)
    }

    fn oam_layer_plan_spec(
        &self,
        layer: usize,
    ) -> Result<&PinnedMaceRuntimeLayerPlanSpec, MaceLiteError> {
        self.active_oam_plan_spec()?
            .layers
            .get(layer)
            .ok_or(MaceLiteError::UnsupportedRuntime)
    }

