    fn large_conv_tp_weights_vjp_edge_feats_with_plan(
        &self,
        layer: usize,
        layer_plan: &PinnedMaceRuntimeLayerPlanSpec,
        edge_feats: &[f64],
        cache: &Mp0bConvTpWeightCache,
        bar_output: &[f64],
        bar_edge_feats: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let hidden_dim = layer_plan.conv_tp_weight_mlp_hidden_dim;
        let output_dim = layer_plan.conv_tp_weight_numel;
        let num_edges = edge_feats.len() / self.num_bessel;
        debug_assert_eq!(bar_output.len(), num_edges * output_dim);
        debug_assert_eq!(bar_edge_feats.len(), edge_feats.len());
        debug_assert_eq!(cache.hidden0_derivative.len(), num_edges * hidden_dim);
        debug_assert_eq!(cache.hidden1_derivative.len(), num_edges * hidden_dim);
        debug_assert_eq!(cache.hidden2_derivative.len(), num_edges * hidden_dim);

        let mut bar_hidden2 = vec![0.0; cache.hidden2_derivative.len()];
        mp0b_dense_input_major_vjp_input(
            num_edges,
            hidden_dim,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer3.weight"),
                &[hidden_dim, output_dim],
            )?,
            bar_output,
            &mut bar_hidden2,
        );
        self.large_conv_tp_weights_vjp_edge_feats_from_bar_hidden2_with_plan(
            layer,
            layer_plan,
            edge_feats,
            cache,
            &mut bar_hidden2,
            bar_edge_feats,
        )
    }

    fn large_conv_tp_weights_vjp_edge_feats_from_bar_hidden2_with_plan(
        &self,
        layer: usize,
        layer_plan: &PinnedMaceRuntimeLayerPlanSpec,
        edge_feats: &[f64],
        cache: &Mp0bConvTpWeightCache,
        bar_hidden2: &mut [f64],
        bar_edge_feats: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let hidden_dim = layer_plan.conv_tp_weight_mlp_hidden_dim;
        let num_edges = edge_feats.len() / self.num_bessel;
        debug_assert_eq!(bar_edge_feats.len(), edge_feats.len());
        debug_assert_eq!(bar_hidden2.len(), cache.hidden2_derivative.len());
        debug_assert_eq!(cache.hidden0_derivative.len(), num_edges * hidden_dim);
        debug_assert_eq!(cache.hidden1_derivative.len(), num_edges * hidden_dim);
        debug_assert_eq!(cache.hidden2_derivative.len(), num_edges * hidden_dim);

        mp0b_apply_cached_derivative_vjp(bar_hidden2, &cache.hidden2_derivative);
        let mut bar_hidden1 = vec![0.0; cache.hidden1_derivative.len()];
        mp0b_dense_input_major_vjp_input(
            num_edges,
            hidden_dim,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer2.weight"),
                &[hidden_dim, hidden_dim],
            )?,
            &bar_hidden2,
            &mut bar_hidden1,
        );
        mp0b_apply_cached_derivative_vjp(&mut bar_hidden1, &cache.hidden1_derivative);
        let mut bar_hidden0 = vec![0.0; cache.hidden0_derivative.len()];
        mp0b_dense_input_major_vjp_input(
            num_edges,
            hidden_dim,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer1.weight"),
                &[hidden_dim, hidden_dim],
            )?,
            &bar_hidden1,
            &mut bar_hidden0,
        );
        mp0b_apply_cached_derivative_vjp(&mut bar_hidden0, &cache.hidden0_derivative);
        mp0b_dense_input_major_vjp_input(
            num_edges,
            self.num_bessel,
            self.float_tensor(
                &format!("interactions.{layer}.conv_tp_weights.layer0.weight"),
                &[self.num_bessel, hidden_dim],
            )?,
            &bar_hidden0,
            bar_edge_feats,
        );
        Ok(())
    }

    fn mp0b_density_vjp_edge_feats(
        &self,
        layer: usize,
        edge_feats: &[f64],
        receivers: &[usize],
        bar_density: &[f64],
        bar_edge_feats: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let num_edges = receivers.len();
        debug_assert_eq!(edge_feats.len(), num_edges * self.num_bessel);
        debug_assert_eq!(bar_edge_feats.len(), edge_feats.len());
        let mut density_linear = vec![0.0; num_edges];
        mp0b_dense_input_major(
            edge_feats,
            num_edges,
            self.num_bessel,
            self.float_tensor(
                &format!("interactions.{layer}.density_fn.layer0.weight"),
                &[self.num_bessel, 1],
            )?,
            &mut density_linear,
        );
        let mut bar_density_linear = vec![0.0; num_edges];
        for (edge, &receiver) in receivers.iter().enumerate() {
            let raw = density_linear[edge];
            let edge_density = (raw * raw).tanh();
            bar_density_linear[edge] =
                bar_density[receiver] * (1.0 - edge_density * edge_density) * 2.0 * raw;
        }
        mp0b_dense_input_major_vjp_input(
            num_edges,
            self.num_bessel,
            self.float_tensor(
                &format!("interactions.{layer}.density_fn.layer0.weight"),
                &[self.num_bessel, 1],
            )?,
            &bar_density_linear,
            bar_edge_feats,
        );
        Ok(())
    }

    fn mp0b_radial_embedding_vjp_distance(
        &self,
        distance: f64,
        src_type_id: usize,
        dst_type_id: usize,
        bessel_basis: &[f64],
        bar_radial: &[f64],
    ) -> Result<f64, MaceLiteError> {
        if bessel_basis.len() != self.num_bessel || bar_radial.len() != self.num_bessel {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let radial_distance = self.radial_distance_forward(distance, src_type_id, dst_type_id)?;
        let cutoff =
            mace_polynomial_cutoff_forward(distance, self.cutoff, self.polynomial_cutoff_p)?;
        let bar_cutoff = bessel_basis
            .iter()
            .zip(bar_radial)
            .map(|(basis, bar)| basis * bar)
            .sum::<f64>();
        let bar_basis = bar_radial
            .iter()
            .map(|bar| bar * cutoff.value)
            .collect::<Vec<_>>();
        let bar_radial_distance =
            mace_bessel_basis_vjp(radial_distance.value, self.cutoff, bessel_basis, &bar_basis)?;
        Ok(cutoff.derivative * bar_cutoff + radial_distance.derivative * bar_radial_distance)
    }

    fn mp0b_radial_embedding_vjp_distance_cached_f64(
        &self,
        distance: f64,
        radial_distance_value: f64,
        radial_distance_derivative: f64,
        bessel_basis: &[f64],
        bar_radial: &[f64],
    ) -> Result<f64, MaceLiteError> {
        if bessel_basis.len() != self.num_bessel || bar_radial.len() != self.num_bessel {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let cutoff =
            mace_polynomial_cutoff_forward(distance, self.cutoff, self.polynomial_cutoff_p)?;
        let prefactor = (2.0 / self.cutoff).sqrt();
        let theta = std::f64::consts::PI * radial_distance_value / self.cutoff;
        let (sin_theta, cos_theta) = theta.sin_cos();
        let mut sin_n = sin_theta;
        let mut cos_n = cos_theta;
        let mut bar_cutoff = 0.0;
        let mut bar_radial_distance = 0.0;
        for (index, (&basis, &bar)) in bessel_basis.iter().zip(bar_radial).enumerate() {
            if index > 0 {
                let next_sin = sin_n * cos_theta + cos_n * sin_theta;
                let next_cos = cos_n * cos_theta - sin_n * sin_theta;
                sin_n = next_sin;
                cos_n = next_cos;
            }
            bar_cutoff += basis * bar;
            let weight = std::f64::consts::PI * (index + 1) as f64 / self.cutoff;
            let derivative = prefactor * (weight * cos_n * radial_distance_value - sin_n)
                / (radial_distance_value * radial_distance_value);
            bar_radial_distance += bar * cutoff.value * derivative;
        }
        Ok(cutoff.derivative * bar_cutoff + radial_distance_derivative * bar_radial_distance)
    }

    fn mp0b_radial_embedding_vjp_distance_cached_f32(
        &self,
        distance: f64,
        radial_distance_value: f64,
        radial_distance_derivative: f64,
        bessel_basis: &[f64],
        bar_radial: &[f32],
    ) -> Result<f64, MaceLiteError> {
        if bessel_basis.len() != self.num_bessel || bar_radial.len() != self.num_bessel {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let cutoff =
            mace_polynomial_cutoff_forward(distance, self.cutoff, self.polynomial_cutoff_p)?;
        let prefactor = (2.0 / self.cutoff).sqrt();
        let theta = std::f64::consts::PI * radial_distance_value / self.cutoff;
        let (sin_theta, cos_theta) = theta.sin_cos();
        let mut sin_n = sin_theta;
        let mut cos_n = cos_theta;
        let mut bar_cutoff = 0.0;
        let mut bar_radial_distance = 0.0;
        for (index, (&basis, &bar_value)) in bessel_basis.iter().zip(bar_radial).enumerate() {
            if index > 0 {
                let next_sin = sin_n * cos_theta + cos_n * sin_theta;
                let next_cos = cos_n * cos_theta - sin_n * sin_theta;
                sin_n = next_sin;
                cos_n = next_cos;
            }
            let bar = f64::from(bar_value);
            bar_cutoff += basis * bar;
            let weight = std::f64::consts::PI * (index + 1) as f64 / self.cutoff;
            let derivative = prefactor * (weight * cos_n * radial_distance_value - sin_n)
                / (radial_distance_value * radial_distance_value);
            bar_radial_distance += bar * cutoff.value * derivative;
        }
        Ok(cutoff.derivative * bar_cutoff + radial_distance_derivative * bar_radial_distance)
    }

    fn mp0b_edge_feature_vjp_to_edge_vectors(
        &self,
        type_ids: &[usize],
        neighbor_list: &NeighborList,
        bar_edge_attrs: &[f64],
        bar_edge_feats: &[f64],
        radial_cache: Option<&RadialEmbeddingEdgeCache>,
    ) -> Result<Vec<Vec3>, MaceLiteError> {
        let num_edges = neighbor_list.edges.len();
        let sh_dim = self.sh_dim();
        if bar_edge_attrs.len() != num_edges * sh_dim
            || bar_edge_feats.len() != num_edges * self.num_bessel
        {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        if let Some(cache) = radial_cache {
            check_len(
                "mace_edge_feature_vjp_f64 cached bessel_basis",
                num_edges * self.num_bessel,
                cache.bessel_basis.len(),
            )?;
            check_len(
                "mace_edge_feature_vjp_f64 cached radial_distance",
                num_edges,
                cache.radial_distance.len(),
            )?;
            check_len(
                "mace_edge_feature_vjp_f64 cached radial_distance_derivative",
                num_edges,
                cache.radial_distance_derivative.len(),
            )?;
        }
        if neighbor_list
            .edges
            .iter()
            .any(|edge| edge.src >= type_ids.len() || edge.dst >= type_ids.len())
        {
            return Err(MaceLiteError::UnsupportedRuntime);
        }

        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && (128..2048).contains(&num_edges) {
            let results = neighbor_list
                .edges
                .par_iter()
                .enumerate()
                .map_init(
                    || {
                        (
                            vec![0.0; self.num_bessel],
                            vec![0.0; self.num_bessel],
                            vec![0.0; sh_dim],
                        )
                    },
                    |(bessel_basis, radial, bar_sh), (edge_index, edge)| {
                        let mut bar_r = [0.0; 3];
                        for (target, &value) in bar_sh
                            .iter_mut()
                            .zip(&bar_edge_attrs[edge_index * sh_dim..(edge_index + 1) * sh_dim])
                        {
                            *target = value;
                        }
                        self.sh_plan
                            .vjp_edge_vector(edge.vector, bar_sh, &mut bar_r)?;
                        let radial_distance = if let Some(cache) = radial_cache {
                            bessel_basis.copy_from_slice(
                                &cache.bessel_basis[edge_index * self.num_bessel
                                    ..(edge_index + 1) * self.num_bessel],
                            );
                            Some((
                                cache.radial_distance[edge_index],
                                cache.radial_distance_derivative[edge_index],
                            ))
                        } else {
                            self.radial_embedding_forward(
                                edge.distance,
                                type_ids[edge.src],
                                type_ids[edge.dst],
                                bessel_basis,
                                radial,
                            )?;
                            None
                        };
                        let bar_radial = &bar_edge_feats
                            [edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel];
                        let bar_distance = if let Some((value, derivative)) = radial_distance {
                            self.mp0b_radial_embedding_vjp_distance_cached_f64(
                                edge.distance,
                                value,
                                derivative,
                                bessel_basis,
                                bar_radial,
                            )?
                        } else {
                            self.mp0b_radial_embedding_vjp_distance(
                                edge.distance,
                                type_ids[edge.src],
                                type_ids[edge.dst],
                                bessel_basis,
                                bar_radial,
                            )?
                        };
                        distance_vjp_accumulate(
                            edge.vector,
                            bar_distance,
                            DISTANCE_EPS,
                            &mut bar_r,
                        )?;
                        Ok(bar_r)
                    },
                )
                .collect::<Vec<Result<Vec3, MaceLiteError>>>();
            return results.into_iter().collect();
        }

        let mut bar_edge_vectors = vec![[0.0; 3]; num_edges];
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && num_edges >= 2048 {
            let target_chunks = rayon::current_num_threads() * 2;
            let edge_chunk_len = num_edges.div_ceil(target_chunks).max(1);
            bar_edge_vectors
                .par_chunks_mut(edge_chunk_len)
                .enumerate()
                .try_for_each(|(chunk_index, bar_chunk)| -> Result<(), MaceLiteError> {
                    let start = chunk_index * edge_chunk_len;
                    let mut bessel_basis = vec![0.0; self.num_bessel];
                    let mut radial = vec![0.0; self.num_bessel];
                    for (offset, bar_out) in bar_chunk.iter_mut().enumerate() {
                        let edge_index = start + offset;
                        let edge = &neighbor_list.edges[edge_index];
                        let mut bar_r = [0.0; 3];
                        self.sh_plan.vjp_edge_vector_unchecked(
                            edge.vector,
                            &bar_edge_attrs[edge_index * sh_dim..(edge_index + 1) * sh_dim],
                            &mut bar_r,
                        );
                        let (radial_distance_value, radial_distance_derivative) =
                            if let Some(cache) = radial_cache {
                                bessel_basis.copy_from_slice(
                                    &cache.bessel_basis[edge_index * self.num_bessel
                                        ..(edge_index + 1) * self.num_bessel],
                                );
                                (
                                    cache.radial_distance[edge_index],
                                    cache.radial_distance_derivative[edge_index],
                                )
                            } else {
                                let radial_distance = self.radial_embedding_forward(
                                    edge.distance,
                                    type_ids[edge.src],
                                    type_ids[edge.dst],
                                    &mut bessel_basis,
                                    &mut radial,
                                )?;
                                (radial_distance.value, radial_distance.derivative)
                            };
                        let bar_distance = self.mp0b_radial_embedding_vjp_distance_cached_f64(
                            edge.distance,
                            radial_distance_value,
                            radial_distance_derivative,
                            &bessel_basis,
                            &bar_edge_feats
                                [edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel],
                        )?;
                        distance_vjp_accumulate(
                            edge.vector,
                            bar_distance,
                            DISTANCE_EPS,
                            &mut bar_r,
                        )?;
                        *bar_out = bar_r;
                    }
                    Ok(())
                })?;
            return Ok(bar_edge_vectors);
        }
        let mut bessel_basis = vec![0.0; self.num_bessel];
        let mut radial = vec![0.0; self.num_bessel];
        for (edge_index, edge) in neighbor_list.edges.iter().enumerate() {
            let mut bar_r = [0.0; 3];
            self.sh_plan.vjp_edge_vector_unchecked(
                edge.vector,
                &bar_edge_attrs[edge_index * sh_dim..(edge_index + 1) * sh_dim],
                &mut bar_r,
            );
            let (radial_distance_value, radial_distance_derivative) =
                if let Some(cache) = radial_cache {
                    bessel_basis.copy_from_slice(
                        &cache.bessel_basis
                            [edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel],
                    );
                    (
                        cache.radial_distance[edge_index],
                        cache.radial_distance_derivative[edge_index],
                    )
                } else {
                    let radial_distance = self.radial_embedding_forward(
                        edge.distance,
                        type_ids[edge.src],
                        type_ids[edge.dst],
                        &mut bessel_basis,
                        &mut radial,
                    )?;
                    (radial_distance.value, radial_distance.derivative)
                };
            let bar_distance = self.mp0b_radial_embedding_vjp_distance_cached_f64(
                edge.distance,
                radial_distance_value,
                radial_distance_derivative,
                &bessel_basis,
                &bar_edge_feats[edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel],
            )?;
            distance_vjp_accumulate(edge.vector, bar_distance, DISTANCE_EPS, &mut bar_r)?;
            bar_edge_vectors[edge_index] = bar_r;
        }
        Ok(bar_edge_vectors)
    }

    #[allow(clippy::too_many_arguments)]
    fn mp0b_vjp(
        &self,
        type_ids: &[usize],
        node_attrs: &[f64],
        neighbor_list: &NeighborList,
        edge_attrs: &[f64],
        edge_feats: &[f64],
        senders: &[usize],
        receivers: &[usize],
        layer0: &Mp0bLayerForward,
        layer1: &Mp0bLayerForward,
        scale: f64,
        selected_nodes: Option<&[bool]>,
        compute_displacement_gradient: bool,
        radial_cache: Option<&RadialEmbeddingEdgeCache>,
        cached_layer0_tp: Option<&Mp0bConvTpWeightsForward>,
        cached_layer1_tp: Option<&Mp0bConvTpWeightsForward>,
    ) -> Result<MaceLiteVjp, MaceLiteError> {
        let trace_timings = mace_trace_timings_enabled();
        let mut section_start = trace_timings.then(Instant::now);
        let num_nodes = type_ids.len();
        let bar_readout = readout_seed(scale, num_nodes, selected_nodes);
        let mut bar_layer0_product_out = vec![0.0; layer0.product_out.len()];
        let mut bar_layer1_product_out = vec![0.0; layer1.product_out.len()];
        self.mp0b_readout0_vjp(&bar_readout, &mut bar_layer0_product_out)?;
        self.mp0b_readout1_vjp(
            &layer1.product_out,
            &bar_readout,
            &mut bar_layer1_product_out,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_readout_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let mut bar_layer1_interaction_out = vec![0.0; layer1.interaction_out.len()];
        self.mp0b_product1_vjp_to_interaction_out(
            node_attrs,
            &layer1.interaction_out,
            &bar_layer1_product_out,
            &mut bar_layer1_interaction_out,
        )?;
        mp0b_scalar_residual_skip_vjp_input(
            node_attrs,
            self.float_tensor(
                "interactions.1.skip_tp.weight",
                &[MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "interactions.1.skip_tp.output_mask",
                &[MP0B_PRODUCT1_ROW_LEN],
            )?,
            &bar_layer1_product_out,
            &mut bar_layer0_product_out,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_layer1_product_skip_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let layer1_message_vjp = self.mp0b_layer1_message_vjp_to_scatter_density(
            &layer1.scatter_message,
            &layer1.density,
            &layer1.linear_message,
            &bar_layer1_interaction_out,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_layer1_message_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let conv_plan = self
            .conv_tp_plan(1)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let layer1_output_mask = self.float_tensor(
            "interactions.1.conv_tp.output_mask",
            &[conv_plan.output_dim()],
        )?;
        let layer1_tp_weights = cached_layer1_tp
            .and_then(|cached| (!cached.output.is_empty()).then_some(cached.output.as_slice()))
            .unwrap_or(layer1.tp_weights.as_slice());
        let mut layer1_fused_bar_hidden2: Option<Vec<f64>> = None;
        #[cfg_attr(not(feature = "parallel"), allow(unused_mut))]
        let mut layer1_conv_vjp: Option<Mp0bConvTpVjp> = None;
        #[cfg(feature = "parallel")]
        if layer1_output_mask.iter().all(|&mask| mask == 1.0)
            && conv_plan.input2_dim() == MP0B_SH_DIM
            && conv_plan.input1_dim().is_multiple_of(MP0B_NUM_FEATURES)
            && conv_plan.output_dim().is_multiple_of(MP0B_NUM_FEATURES)
            && conv_plan.weight_numel.is_multiple_of(MP0B_NUM_FEATURES)
            && mp0b_layer1_dynamic_templates(conv_plan).is_some()
        {
            if let Some(edge_chunk_len) = mp0b_conv_tp_vjp_parallel_edge_chunk_len(senders.len()) {
                let layer_plan = self.mp0b_layer_plan_spec(1)?;
                let hidden_dim = layer_plan.conv_tp_weight_mlp_hidden_dim;
                let weight_numel = layer_plan.conv_tp_weight_numel;
                let layer3_weight = self.float_tensor(
                    "interactions.1.conv_tp_weights.layer3.weight",
                    &[hidden_dim, weight_numel],
                )?;
                let fused = mp0b_apply_conv_tp_layer1_scalar_vector_fast_vjp_hidden2_parallel(
                    &Mp0bConvTpInput {
                        plan: conv_plan,
                        linear_up: &layer1.linear_up,
                        edge_attrs,
                        tp_weights: layer1_tp_weights,
                        output_mask: layer1_output_mask,
                        senders,
                        receivers,
                    },
                    &layer1_message_vjp.bar_scatter_message,
                    edge_chunk_len,
                    hidden_dim,
                    layer3_weight,
                );
                layer1_fused_bar_hidden2 = Some(fused.bar_hidden2);
                layer1_conv_vjp = Some(Mp0bConvTpVjp {
                    bar_linear_up: fused.bar_linear_up,
                    bar_edge_attrs: fused.bar_edge_attrs,
                    bar_tp_weights: Vec::new(),
                });
            }
        }
        let layer1_conv_vjp = match layer1_conv_vjp {
            Some(vjp) => vjp,
            None => mp0b_apply_conv_tp_vjp(
                Mp0bConvTpInput {
                    plan: conv_plan,
                    linear_up: &layer1.linear_up,
                    edge_attrs,
                    tp_weights: layer1_tp_weights,
                    output_mask: layer1_output_mask,
                    senders,
                    receivers,
                },
                &layer1_message_vjp.bar_scatter_message,
            )?,
        };
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_layer1_conv_tp_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        mp0b_scalar_vector_product_linear_vjp_input(
            self.float_tensor(
                "interactions.1.linear_up.weight",
                &[2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "interactions.1.linear_up.output_mask",
                &[MP0B_PRODUCT0_ROW_LEN],
            )?,
            &layer1_conv_vjp.bar_linear_up,
            1.0,
            &mut bar_layer0_product_out,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_layer1_linear_up_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let mut bar_edge_attrs = layer1_conv_vjp.bar_edge_attrs;
        let mut bar_edge_feats = vec![0.0; edge_feats.len()];
        let layer1_tp_weight_cache = if let Some(cached) = cached_layer1_tp {
            &cached.cache
        } else {
            layer1
                .tp_weight_cache
                .as_ref()
                .ok_or(MaceLiteError::UnsupportedRuntime)?
        };
        if let Some(mut bar_hidden2) = layer1_fused_bar_hidden2.take() {
            let layer_plan = self.mp0b_layer_plan_spec(1)?;
            self.large_conv_tp_weights_vjp_edge_feats_from_bar_hidden2_with_plan(
                1,
                layer_plan,
                edge_feats,
                layer1_tp_weight_cache,
                &mut bar_hidden2,
                &mut bar_edge_feats,
            )?;
        } else {
            self.mp0b_conv_tp_weights_vjp_edge_feats_with_cache(
                1,
                edge_feats,
                layer1_tp_weight_cache,
                &layer1_conv_vjp.bar_tp_weights,
                &mut bar_edge_feats,
            )?;
        }
        self.mp0b_density_vjp_edge_feats(
            1,
            edge_feats,
            receivers,
            &layer1_message_vjp.bar_density,
            &mut bar_edge_feats,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_layer1_tp_weights_density_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let mut bar_layer0_interaction_out = vec![0.0; layer0.interaction_out.len()];
        self.mp0b_product0_vjp_to_interaction_out(
            node_attrs,
            &layer0.interaction_out,
            &bar_layer0_product_out,
            &mut bar_layer0_interaction_out,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_layer0_product_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let layer0_message_vjp = self.mp0b_layer0_message_vjp_to_scatter_density(
            node_attrs,
            &layer0.scatter_message,
            &layer0.density,
            &layer0.linear_message,
            &bar_layer0_interaction_out,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_layer0_message_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let conv_plan = self
            .conv_tp_plan(0)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let layer0_tp_weights = cached_layer0_tp.map_or(layer0.tp_weights.as_slice(), |cached| {
            cached.output.as_slice()
        });
        let layer0_conv_vjp = mp0b_apply_conv_tp_vjp(
            Mp0bConvTpInput {
                plan: conv_plan,
                linear_up: &layer0.linear_up,
                edge_attrs,
                tp_weights: layer0_tp_weights,
                output_mask: self.float_tensor(
                    "interactions.0.conv_tp.output_mask",
                    &[conv_plan.output_dim()],
                )?,
                senders,
                receivers,
            },
            &layer0_message_vjp.bar_scatter_message,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_layer0_conv_tp_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        for (target, value) in bar_edge_attrs
            .iter_mut()
            .zip(&layer0_conv_vjp.bar_edge_attrs)
        {
            *target += value;
        }
        section_start = trace_timings.then(Instant::now);
        let layer0_tp_weight_cache = if let Some(cached) = cached_layer0_tp {
            &cached.cache
        } else {
            layer0
                .tp_weight_cache
                .as_ref()
                .ok_or(MaceLiteError::UnsupportedRuntime)?
        };
        self.mp0b_conv_tp_weights_vjp_edge_feats_with_cache(
            0,
            edge_feats,
            layer0_tp_weight_cache,
            &layer0_conv_vjp.bar_tp_weights,
            &mut bar_edge_feats,
        )?;
        self.mp0b_density_vjp_edge_feats(
            0,
            edge_feats,
            receivers,
            &layer0_message_vjp.bar_density,
            &mut bar_edge_feats,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_layer0_tp_weights_density_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let bar_edge_vectors = self.mp0b_edge_feature_vjp_to_edge_vectors(
            type_ids,
            neighbor_list,
            &bar_edge_attrs,
            &bar_edge_feats,
            radial_cache,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_edge_vectors_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let mut forces = vec![[0.0; 3]; num_nodes];
        let mut displacement_gradient = [[0.0; 3]; 3];
        for (edge, bar_r) in neighbor_list.edges.iter().zip(bar_edge_vectors) {
            scatter_edge_vector_vjp(edge.src, edge.dst, bar_r, &mut forces)?;
            if compute_displacement_gradient {
                accumulate_edge_displacement_gradient(
                    edge.vector,
                    bar_r,
                    &mut displacement_gradient,
                );
            }
        }
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_mp0b_f64 vjp_force_scatter_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        Ok(MaceLiteVjp {
            forces,
            displacement_gradient,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn evaluate_osaka26(
        &self,
        structure: &Structure,
        compute_forces: bool,
        options: &PredictionOptions,
        shared_neighbor_list: Option<&NeighborList>,
        prepared: Option<&MaceLitePreparedInput>,
        selected_nodes: Option<&[bool]>,
        extra: MaceLiteExtraOutputRequest,
    ) -> Result<MaceLiteOutput, MaceLiteError> {
        let trace_timings = mace_trace_timings_enabled();
        let _eval_start = trace_timings.then(Instant::now);
        let runtime_plan = self.active_osaka_plan_spec()?;
        let type_ids_storage;
        let type_ids = if let Some(prepared) = prepared {
            prepared.type_ids.as_slice()
        } else {
            type_ids_storage = self.type_ids(structure)?;
            &type_ids_storage
        };
        let node_attrs_storage;
        let node_attrs = if let Some(prepared) = prepared {
            prepared.node_attrs_f64.as_slice()
        } else {
            node_attrs_storage = one_hot(type_ids, self.type_names.len());
            &node_attrs_storage
        };
        let neighbor_list_storage;
        let neighbor_list = if let Some(prepared) = prepared {
            &prepared.neighbor_list
        } else if let Some(neighbor_list) = shared_neighbor_list {
            neighbor_list_storage = neighbor_list.filtered_by_cutoff(self.cutoff)?;
            &neighbor_list_storage
        } else {
            neighbor_list_storage = cell_list_multi_image_neighbor_list(structure, self.cutoff)?;
            &neighbor_list_storage
        };
        let num_nodes = structure.len();
        let num_edges = neighbor_list.edges.len();
        let prepared_mp0b_cache = prepared
            .and_then(|prepared| prepared.mp0b_cache.as_deref())
            .filter(|cache| {
                cache.matches_f32(num_nodes, num_edges, runtime_plan.sh_dim, self.num_bessel)
            });
        let pair_node_energy = if let Some(cache) = prepared_mp0b_cache {
            cache.pair_node_energy.clone()
        } else {
            self.pair_repulsion_node_energy(type_ids, neighbor_list)?
        };
        let senders_storage;
        let receivers_storage;
        let prepared_edge_data = prepared
            .filter(|prepared| prepared.neighbor_list.edges.len() == neighbor_list.edges.len());
        let (senders, receivers): (&[usize], &[usize]) = if let Some(prepared) = prepared_edge_data
        {
            (&prepared.senders, &prepared.receivers)
        } else {
            senders_storage = neighbor_list
                .edges
                .iter()
                .map(|edge| edge.src)
                .collect::<Vec<_>>();
            receivers_storage = neighbor_list
                .edges
                .iter()
                .map(|edge| edge.dst)
                .collect::<Vec<_>>();
            (&senders_storage, &receivers_storage)
        };

        let mut edge_attrs = vec![0.0; num_edges * runtime_plan.sh_dim];
        let mut edge_feats = vec![0.0; num_edges * self.num_bessel];
        // Per-edge spherical-harmonics + radial precompute. Each edge writes only
        // its own disjoint `sh_dim` slice of `edge_attrs` and `num_bessel` slice of
        // `edge_feats`, so the parallel path is bit-identical to the serial one (no
        // shared accumulator, no reduction reorder). Mirrors the f32 sibling
        // (`evaluate_osaka26_f32`) gating and per-iteration scratch buffers.
        #[cfg(feature = "parallel")]
        let edge_features_done = if rayon::current_num_threads() > 1
            && num_edges >= 512
            && runtime_plan.sh_dim == MP0B_SH_DIM
            && self.num_bessel == 10
        {
            edge_attrs
                .par_chunks_mut(runtime_plan.sh_dim)
                .zip(edge_feats.par_chunks_mut(self.num_bessel))
                .enumerate()
                .try_for_each(
                    |(edge_index, (edge_attr_row, edge_feat_row))| -> Result<(), MaceLiteError> {
                        let edge = &neighbor_list.edges[edge_index];
                        let mut bessel_basis = vec![0.0; self.num_bessel];
                        let mut radial = vec![0.0; self.num_bessel];
                        self.sh_plan.forward(edge.vector, edge_attr_row)?;
                        self.radial_embedding_forward(
                            edge.distance,
                            type_ids[edge.src],
                            type_ids[edge.dst],
                            &mut bessel_basis,
                            &mut radial,
                        )?;
                        edge_feat_row.copy_from_slice(&radial);
                        Ok(())
                    },
                )?;
            true
        } else {
            false
        };
        #[cfg(not(feature = "parallel"))]
        let edge_features_done = false;
        if !edge_features_done {
            let mut bessel_basis = vec![0.0; self.num_bessel];
            let mut radial = vec![0.0; self.num_bessel];
            for (edge_index, edge) in neighbor_list.edges.iter().enumerate() {
                self.sh_plan.forward(
                    edge.vector,
                    &mut edge_attrs
                        [edge_index * runtime_plan.sh_dim..(edge_index + 1) * runtime_plan.sh_dim],
                )?;
                self.radial_embedding_forward(
                    edge.distance,
                    type_ids[edge.src],
                    type_ids[edge.dst],
                    &mut bessel_basis,
                    &mut radial,
                )?;
                edge_feats[edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel]
                    .copy_from_slice(&radial);
            }
        }

        let node_plan = &runtime_plan.node_embedding;
        let mut node_feats = vec![0.0; num_nodes * node_plan.out_features];
        mp0b_masked_linear(
            node_attrs,
            self.float_tensor(
                "node_embedding.linear.weight",
                &[node_plan.in_features * node_plan.out_features],
            )?,
            self.float_tensor(
                "node_embedding.linear.output_mask",
                &[node_plan.out_features],
            )?,
            Mp0bMaskedLinearSpec {
                input_row_len: node_plan.input_row_len,
                in_features: node_plan.in_features,
                out_features: node_plan.out_features,
                path_weight: node_plan.path_weight,
            },
            &mut node_feats,
        );

        let layer0 = self.osaka26_layer_forward_cached(
            0,
            num_nodes,
            node_attrs,
            &node_feats,
            &edge_attrs,
            &edge_feats,
            senders,
            receivers,
            compute_forces,
        )?;
        let readout0 = self.osaka26_readout0(&layer0.product_out)?;
        let layer1 = self.osaka26_layer_forward_cached(
            1,
            num_nodes,
            node_attrs,
            &layer0.product_out,
            &edge_attrs,
            &edge_feats,
            senders,
            receivers,
            compute_forces,
        )?;
        let readout1 = self.mp0b_readout1(&layer1.product_out)?;

        let atomic_energies = self.atomic_energies_tensor()?;
        let scale = self.scale_shift_scale()?;
        let shift = self.scale_shift_shift()?;
        let (energy, atomic_energies_out) = mace_node_energy_sum_and_optional_values_f64(
            type_ids,
            atomic_energies,
            &pair_node_energy,
            scale,
            shift,
            selected_nodes,
            extra.atomic_energies,
            |node| readout0[node] + readout1[node],
        );

        let (forces, stress, virial) = if compute_forces {
            let mut vjp = self.osaka26_vjp(
                type_ids,
                node_attrs,
                neighbor_list,
                &edge_attrs,
                &edge_feats,
                senders,
                receivers,
                &layer0,
                &layer1,
                scale,
                selected_nodes,
                options.compute_stress || options.compute_virial,
            )?;
            self.add_pair_repulsion_vjp(
                type_ids,
                neighbor_list,
                scale,
                selected_nodes,
                options.compute_stress || options.compute_virial,
                &mut vjp,
            )?;
            vjp.into_output_tensors(structure, options, self.cutoff, selected_nodes.is_none())?
        } else {
            (Vec::new(), None, None)
        };
        let descriptors = if extra.descriptors {
            Some(self.descriptors_from_layer_outputs(
                &[layer0.product_out.as_slice(), layer1.product_out.as_slice()],
                num_nodes,
                extra.descriptor_invariants_only,
                extra.descriptor_num_layers,
            )?)
        } else {
            None
        };
        Ok(MaceLiteOutput {
            energy,
            forces,
            stress,
            virial,
            atomic_energies: atomic_energies_out,
            descriptors,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn osaka26_layer_forward_cached(
        &self,
        layer: usize,
        num_nodes: usize,
        node_attrs: &[f64],
        node_feats: &[f64],
        edge_attrs: &[f64],
        edge_feats: &[f64],
        senders: &[usize],
        receivers: &[usize],
        cache_tp_weights: bool,
    ) -> Result<Mp0bLayerForward, MaceLiteError> {
        let layer_plan = self.osaka26_layer_plan_spec(layer)?;
        let mut linear_up = vec![0.0; num_nodes * layer_plan.linear_up_output_dim];
        let linear_up_groups =
            product_linear_groups(layer_plan.linear_up_output_dim, MP0B_NUM_FEATURES)?;
        let linear_up_weight = self.float_tensor(
            &format!("interactions.{layer}.linear_up.weight"),
            &[equivariant_linear_weight_len(&linear_up_groups)],
        )?;
        let linear_up_output_mask = self.float_tensor(
            &format!("interactions.{layer}.linear_up.output_mask"),
            &[layer_plan.linear_up_output_dim],
        )?;
        if layer_plan.linear_up_input_dim == MP0B_NUM_FEATURES
            && layer_plan.linear_up_output_dim == MP0B_NUM_FEATURES
            && linear_up_weight.len() == MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && linear_up_output_mask.len() == MP0B_NUM_FEATURES
        {
            mp0b_scalar_product_linear(
                node_feats,
                linear_up_weight,
                linear_up_output_mask,
                1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
                &mut linear_up,
            );
        } else if layer_plan.linear_up_input_dim == MP0B_PRODUCT0_ROW_LEN
            && layer_plan.linear_up_output_dim == MP0B_PRODUCT0_ROW_LEN
            && linear_up_weight.len() == 2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && linear_up_output_mask.len() == MP0B_PRODUCT0_ROW_LEN
        {
            mp0b_scalar_vector_product_linear(
                node_feats,
                linear_up_weight,
                linear_up_output_mask,
                1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
                &mut linear_up,
            );
        } else {
            mace_equivariant_linear(
                node_feats,
                linear_up_weight,
                linear_up_output_mask,
                &linear_up_groups,
                &mut linear_up,
            )?;
        }
        let (tp_weights, tp_weight_cache) = if cache_tp_weights {
            let forward = self.large_conv_tp_weights_with_plan(layer, layer_plan, edge_feats)?;
            (forward.output, Some(forward.cache))
        } else {
            let forward = self.large_conv_tp_weights_with_plan(layer, layer_plan, edge_feats)?;
            (forward.output, None)
        };
        let conv_plan = self
            .conv_tp_plan(layer)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let mut scatter_message = vec![0.0; num_nodes * conv_plan.output_dim()];
        mp0b_apply_conv_tp(
            Mp0bConvTpInput {
                plan: conv_plan,
                linear_up: &linear_up,
                edge_attrs,
                tp_weights: &tp_weights,
                output_mask: self.float_tensor(
                    &format!("interactions.{layer}.conv_tp.output_mask"),
                    &[layer_plan.conv_tp_output_dim],
                )?,
                senders,
                receivers,
            },
            &mut scatter_message,
        )?;

        let mut linear_message = vec![0.0; num_nodes * layer_plan.linear_message_output_dim];
        let hidden_groups =
            grouped_input_to_hidden_linear_groups(&conv_plan.irreps_out, MP0B_NUM_FEATURES);
        let linear_weight = self.float_tensor(
            &format!("interactions.{layer}.linear.weight"),
            &[equivariant_linear_weight_len(&hidden_groups)],
        )?;
        let linear_output_mask = self.float_tensor(
            &format!("interactions.{layer}.linear.output_mask"),
            &[layer_plan.linear_message_output_dim],
        )?;
        if layer_plan.linear_message_output_dim == MP0B_HIDDEN_ROW_LEN
            && scatter_message.len() == num_nodes * MP0B_HIDDEN_ROW_LEN
            && linear_weight.len() == 4 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && linear_output_mask.len() == MP0B_HIDDEN_ROW_LEN
        {
            large_hidden_linear_avg(
                &scatter_message,
                self.layer_avg_num_neighbors_norm[layer],
                linear_weight,
                linear_output_mask,
                &mut linear_message,
            );
        } else {
            mace_equivariant_linear(
                &scatter_message,
                linear_weight,
                linear_output_mask,
                &hidden_groups,
                &mut linear_message,
            )?;
            for value in &mut linear_message {
                *value /= self.layer_avg_num_neighbors_norm[layer];
            }
        }
        let mut interaction_out = vec![0.0; num_nodes * layer_plan.linear_message_output_dim];
        mp0b_reshape_hidden_irreps_to_feature_major(&linear_message, &mut interaction_out);

        let mut product_symmetric = vec![0.0; num_nodes * layer_plan.product_output_dim];
        self.product_contraction_forward(
            layer,
            &interaction_out,
            node_attrs,
            &mut product_symmetric,
        )?;
        let mut product_linear = vec![0.0; num_nodes * layer_plan.product_output_dim];
        let product_groups =
            product_linear_groups(layer_plan.product_output_dim, MP0B_NUM_FEATURES)?;
        mace_equivariant_linear(
            &product_symmetric,
            self.float_tensor(
                &format!("products.{layer}.linear.weight"),
                &[equivariant_linear_weight_len(&product_groups)],
            )?,
            self.float_tensor(
                &format!("products.{layer}.linear.output_mask"),
                &[layer_plan.product_output_dim],
            )?,
            &product_groups,
            &mut product_linear,
        )?;
        let mut skip = vec![0.0; num_nodes * layer_plan.skip_output_dim];
        osaka_scalar_residual_skip(
            node_feats,
            node_attrs,
            self.float_tensor(
                &format!("interactions.{layer}.skip_tp.weight"),
                &[MP0B_NUM_FEATURES * self.type_names.len() * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                &format!("interactions.{layer}.skip_tp.output_mask"),
                &[layer_plan.skip_output_dim],
            )?,
            OsakaScalarSkipConfig {
                input_row_len: layer_plan.linear_up_input_dim,
                num_features: MP0B_NUM_FEATURES,
                num_elements: self.type_names.len(),
            },
            &mut skip,
        )?;
        for (value, skip_value) in product_linear.iter_mut().zip(skip) {
            *value += skip_value;
        }
        Ok(Mp0bLayerForward {
            linear_up,
            tp_weights,
            tp_weight_cache,
            density: Vec::new(),
            scatter_message,
            linear_message,
            interaction_out,
            product_out: product_linear,
        })
    }

    fn osaka26_readout0(&self, node_feats: &[f64]) -> Result<Vec<f64>, MaceLiteError> {
        let input_row_len = self.active_osaka_plan_spec()?.product0_row_len;
        let mut output = vec![0.0; node_feats.len() / input_row_len];
        mp0b_masked_linear(
            node_feats,
            self.float_tensor("readouts.0.linear.weight", &[MP0B_NUM_FEATURES])?,
            self.float_tensor("readouts.0.linear.output_mask", &[1])?,
            Mp0bMaskedLinearSpec {
                input_row_len,
                in_features: MP0B_NUM_FEATURES,
                out_features: 1,
                path_weight: 1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
            },
            &mut output,
        );
        Ok(output)
    }

    fn osaka26_readout0_vjp(
        &self,
        bar_readout: &[f64],
        bar_product_out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let input_row_len = self.active_osaka_plan_spec()?.product0_row_len;
        mp0b_masked_linear_vjp_input(
            self.float_tensor("readouts.0.linear.weight", &[MP0B_NUM_FEATURES])?,
            self.float_tensor("readouts.0.linear.output_mask", &[1])?,
            Mp0bMaskedLinearSpec {
                input_row_len,
                in_features: MP0B_NUM_FEATURES,
                out_features: 1,
                path_weight: 1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
            },
            bar_readout,
            bar_product_out,
        );
        Ok(())
    }

    fn osaka26_product_vjp_to_interaction_out(
        &self,
        layer: usize,
        node_attrs: &[f64],
        interaction_out: &[f64],
        bar_product_out: &[f64],
        bar_interaction_out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let mut bar_product_symmetric = vec![0.0; bar_product_out.len()];
        let layer_plan = self.osaka26_layer_plan_spec(layer)?;
        let product_groups =
            product_linear_groups(layer_plan.product_output_dim, MP0B_NUM_FEATURES)?;
        mace_equivariant_linear_vjp_input(
            self.float_tensor(
                &format!("products.{layer}.linear.weight"),
                &[equivariant_linear_weight_len(&product_groups)],
            )?,
            self.float_tensor(
                &format!("products.{layer}.linear.output_mask"),
                &[layer_plan.product_output_dim],
            )?,
            &product_groups,
            bar_product_out,
            &mut bar_product_symmetric,
        )?;
        self.product_contraction_vjp_x(
            layer,
            interaction_out,
            node_attrs,
            &bar_product_symmetric,
            bar_interaction_out,
        )?;
        Ok(())
    }

    fn osaka26_message_vjp_to_scatter(
        &self,
        layer: usize,
        scatter_message: &[f64],
        bar_interaction_out: &[f64],
    ) -> Result<Vec<f64>, MaceLiteError> {
        let mut bar_scatter_message = vec![0.0; scatter_message.len()];
        self.osaka26_message_vjp_to_scatter_into(
            layer,
            scatter_message,
            bar_interaction_out,
            &mut bar_scatter_message,
        )?;
        Ok(bar_scatter_message)
    }

    fn osaka26_message_vjp_to_scatter_into(
        &self,
        layer: usize,
        scatter_message: &[f64],
        bar_interaction_out: &[f64],
        bar_scatter_message: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let mut bar_linear_message = vec![0.0; bar_interaction_out.len()];
        self.osaka26_message_vjp_to_scatter_into_with_scratch(
            layer,
            scatter_message,
            bar_interaction_out,
            &mut bar_linear_message,
            bar_scatter_message,
        )
    }

    fn osaka26_message_vjp_to_scatter_into_with_scratch(
        &self,
        layer: usize,
        scatter_message: &[f64],
        bar_interaction_out: &[f64],
        bar_linear_message: &mut [f64],
        bar_scatter_message: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let layer_plan = self.osaka26_layer_plan_spec(layer)?;
        let conv_plan = self
            .conv_tp_plan(layer)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        if bar_linear_message.len() != bar_interaction_out.len()
            || bar_scatter_message.len() != scatter_message.len()
        {
            return Err(MaceLiteError::InvalidModel(format!(
                "Osaka26 message VJP output shape mismatch: layer {layer}, interaction {}, linear scratch {}, scatter {}, output {}",
                bar_interaction_out.len(),
                bar_linear_message.len(),
                scatter_message.len(),
                bar_scatter_message.len()
            )));
        }
        bar_scatter_message.fill(0.0);
        if bar_interaction_out.iter().all(|value| *value == 0.0) {
            return Ok(());
        }
        bar_linear_message.fill(0.0);
        mp0b_reshape_hidden_irreps_to_feature_major_vjp(bar_interaction_out, bar_linear_message);
        let hidden_groups =
            grouped_input_to_hidden_linear_groups(&conv_plan.irreps_out, MP0B_NUM_FEATURES);
        let linear_weight = self.float_tensor(
            &format!("interactions.{layer}.linear.weight"),
            &[equivariant_linear_weight_len(&hidden_groups)],
        )?;
        let linear_output_mask = self.float_tensor(
            &format!("interactions.{layer}.linear.output_mask"),
            &[layer_plan.linear_message_output_dim],
        )?;
        if layer_plan.linear_message_output_dim == MP0B_HIDDEN_ROW_LEN
            && scatter_message.len() == bar_linear_message.len()
            && linear_weight.len() == 4 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && linear_output_mask.len() == MP0B_HIDDEN_ROW_LEN
        {
            large_hidden_linear_avg_vjp_input(
                self.layer_avg_num_neighbors_norm[layer],
                linear_weight,
                linear_output_mask,
                bar_linear_message,
                bar_scatter_message,
            );
        } else {
            for value in bar_linear_message.iter_mut() {
                *value /= self.layer_avg_num_neighbors_norm[layer];
            }
            mace_equivariant_linear_vjp_input(
                linear_weight,
                linear_output_mask,
                &hidden_groups,
                bar_linear_message,
                bar_scatter_message,
            )?;
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments, clippy::type_complexity)]
    fn osaka26_layer1_conv_vjp_outputs(
        &self,
        edge_attrs: &[f64],
        edge_feats: &[f64],
        senders: &[usize],
        receivers: &[usize],
        layer1: &Mp0bLayerForward,
        layer1_bar_scatter: &[f64],
    ) -> Result<(Vec<f64>, Vec<f64>, Vec<f64>), MaceLiteError> {
        let layer_plan = self.osaka26_layer_plan_spec(1)?;
        let conv_plan = self
            .conv_tp_plan(1)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let output_mask = self.float_tensor(
            "interactions.1.conv_tp.output_mask",
            &[conv_plan.output_dim()],
        )?;
        let layer1_tp_weight_cache = layer1
            .tp_weight_cache
            .as_ref()
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let mut bar_edge_feats = vec![0.0; edge_feats.len()];

        #[cfg(feature = "parallel")]
        if output_mask.iter().all(|&mask| mask == 1.0)
            && conv_plan.input2_dim() == MP0B_SH_DIM
            && conv_plan.input1_dim().is_multiple_of(MP0B_NUM_FEATURES)
            && conv_plan.output_dim().is_multiple_of(MP0B_NUM_FEATURES)
            && conv_plan.weight_numel.is_multiple_of(MP0B_NUM_FEATURES)
            && mp0b_layer1_dynamic_templates(conv_plan).is_some()
        {
            if let Some(edge_chunk_len) = mp0b_conv_tp_vjp_parallel_edge_chunk_len(senders.len()) {
                let hidden_dim = layer_plan.conv_tp_weight_mlp_hidden_dim;
                let weight_numel = layer_plan.conv_tp_weight_numel;
                let layer3_weight = self.float_tensor(
                    "interactions.1.conv_tp_weights.layer3.weight",
                    &[hidden_dim, weight_numel],
                )?;
                let mut fused = mp0b_apply_conv_tp_layer1_scalar_vector_fast_vjp_hidden2_parallel(
                    &Mp0bConvTpInput {
                        plan: conv_plan,
                        linear_up: &layer1.linear_up,
                        edge_attrs,
                        tp_weights: &layer1.tp_weights,
                        output_mask,
                        senders,
                        receivers,
                    },
                    layer1_bar_scatter,
                    edge_chunk_len,
                    hidden_dim,
                    layer3_weight,
                );
                self.large_conv_tp_weights_vjp_edge_feats_from_bar_hidden2_with_plan(
                    1,
                    layer_plan,
                    edge_feats,
                    layer1_tp_weight_cache,
                    &mut fused.bar_hidden2,
                    &mut bar_edge_feats,
                )?;
                return Ok((fused.bar_linear_up, fused.bar_edge_attrs, bar_edge_feats));
            }
        }

        let layer1_conv_vjp = mp0b_apply_conv_tp_vjp(
            Mp0bConvTpInput {
                plan: conv_plan,
                linear_up: &layer1.linear_up,
                edge_attrs,
                tp_weights: &layer1.tp_weights,
                output_mask,
                senders,
                receivers,
            },
            layer1_bar_scatter,
        )?;
        self.large_conv_tp_weights_vjp_edge_feats_with_plan(
            1,
            layer_plan,
            edge_feats,
            layer1_tp_weight_cache,
            &layer1_conv_vjp.bar_tp_weights,
            &mut bar_edge_feats,
        )?;
        Ok((
            layer1_conv_vjp.bar_linear_up,
            layer1_conv_vjp.bar_edge_attrs,
            bar_edge_feats,
        ))
    }

    #[allow(clippy::too_many_arguments)]
    fn osaka26_vjp(
        &self,
        type_ids: &[usize],
        node_attrs: &[f64],
        neighbor_list: &NeighborList,
        edge_attrs: &[f64],
        edge_feats: &[f64],
        senders: &[usize],
        receivers: &[usize],
        layer0: &Mp0bLayerForward,
        layer1: &Mp0bLayerForward,
        scale: f64,
        selected_nodes: Option<&[bool]>,
        compute_displacement_gradient: bool,
    ) -> Result<MaceLiteVjp, MaceLiteError> {
        let num_nodes = type_ids.len();
        let bar_readout = readout_seed(scale, num_nodes, selected_nodes);
        let mut bar_layer0_product_out = vec![0.0; layer0.product_out.len()];
        let mut bar_layer1_product_out = vec![0.0; layer1.product_out.len()];
        self.osaka26_readout0_vjp(&bar_readout, &mut bar_layer0_product_out)?;
        self.mp0b_readout1_vjp(
            &layer1.product_out,
            &bar_readout,
            &mut bar_layer1_product_out,
        )?;

        let mut bar_layer1_interaction_out = vec![0.0; layer1.interaction_out.len()];
        self.osaka26_product_vjp_to_interaction_out(
            1,
            node_attrs,
            &layer1.interaction_out,
            &bar_layer1_product_out,
            &mut bar_layer1_interaction_out,
        )?;
        let layer1_plan = self.osaka26_layer_plan_spec(1)?;
        osaka_scalar_residual_skip_vjp_input(
            node_attrs,
            self.float_tensor(
                "interactions.1.skip_tp.weight",
                &[MP0B_NUM_FEATURES * self.type_names.len() * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "interactions.1.skip_tp.output_mask",
                &[layer1_plan.skip_output_dim],
            )?,
            &bar_layer1_product_out,
            MP0B_NUM_FEATURES,
            self.type_names.len(),
            &mut bar_layer0_product_out,
        )?;

        let layer1_bar_scatter = self.osaka26_message_vjp_to_scatter(
            1,
            &layer1.scatter_message,
            &bar_layer1_interaction_out,
        )?;
        let (layer1_bar_linear_up, mut bar_edge_attrs, mut bar_edge_feats) = self
            .osaka26_layer1_conv_vjp_outputs(
                edge_attrs,
                edge_feats,
                senders,
                receivers,
                layer1,
                &layer1_bar_scatter,
            )?;
        let layer1_linear_up_groups =
            product_linear_groups(layer1_plan.linear_up_output_dim, MP0B_NUM_FEATURES)?;
        let layer1_linear_up_weight = self.float_tensor(
            "interactions.1.linear_up.weight",
            &[equivariant_linear_weight_len(&layer1_linear_up_groups)],
        )?;
        let layer1_linear_up_output_mask = self.float_tensor(
            "interactions.1.linear_up.output_mask",
            &[layer1_plan.linear_up_output_dim],
        )?;
        if layer1_plan.linear_up_input_dim == MP0B_NUM_FEATURES
            && layer1_plan.linear_up_output_dim == MP0B_NUM_FEATURES
            && layer1_linear_up_weight.len() == MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && layer1_linear_up_output_mask.len() == MP0B_NUM_FEATURES
        {
            mp0b_scalar_product_linear_vjp_input(
                layer1_linear_up_weight,
                layer1_linear_up_output_mask,
                &layer1_bar_linear_up,
                1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
                &mut bar_layer0_product_out,
            );
        } else if layer1_plan.linear_up_input_dim == MP0B_PRODUCT0_ROW_LEN
            && layer1_plan.linear_up_output_dim == MP0B_PRODUCT0_ROW_LEN
            && layer1_linear_up_weight.len() == 2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && layer1_linear_up_output_mask.len() == MP0B_PRODUCT0_ROW_LEN
        {
            mp0b_scalar_vector_product_linear_vjp_input(
                layer1_linear_up_weight,
                layer1_linear_up_output_mask,
                &layer1_bar_linear_up,
                1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
                &mut bar_layer0_product_out,
            );
        } else {
            mace_equivariant_linear_vjp_input(
                layer1_linear_up_weight,
                layer1_linear_up_output_mask,
                &layer1_linear_up_groups,
                &layer1_bar_linear_up,
                &mut bar_layer0_product_out,
            )?;
        }

        let mut bar_layer0_interaction_out = vec![0.0; layer0.interaction_out.len()];
        self.osaka26_product_vjp_to_interaction_out(
            0,
            node_attrs,
            &layer0.interaction_out,
            &bar_layer0_product_out,
            &mut bar_layer0_interaction_out,
        )?;
        let layer0_bar_scatter = self.osaka26_message_vjp_to_scatter(
            0,
            &layer0.scatter_message,
            &bar_layer0_interaction_out,
        )?;
        let conv_plan = self
            .conv_tp_plan(0)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let layer0_conv_vjp = mp0b_apply_conv_tp_vjp(
            Mp0bConvTpInput {
                plan: conv_plan,
                linear_up: &layer0.linear_up,
                edge_attrs,
                tp_weights: &layer0.tp_weights,
                output_mask: self.float_tensor(
                    "interactions.0.conv_tp.output_mask",
                    &[conv_plan.output_dim()],
                )?,
                senders,
                receivers,
            },
            &layer0_bar_scatter,
        )?;
        for (target, value) in bar_edge_attrs
            .iter_mut()
            .zip(&layer0_conv_vjp.bar_edge_attrs)
        {
            *target += value;
        }
        let layer0_tp_weight_cache = layer0
            .tp_weight_cache
            .as_ref()
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        self.large_conv_tp_weights_vjp_edge_feats_with_plan(
            0,
            self.osaka26_layer_plan_spec(0)?,
            edge_feats,
            layer0_tp_weight_cache,
            &layer0_conv_vjp.bar_tp_weights,
            &mut bar_edge_feats,
        )?;

        let bar_edge_vectors = self.mp0b_edge_feature_vjp_to_edge_vectors(
            type_ids,
            neighbor_list,
            &bar_edge_attrs,
            &bar_edge_feats,
            None,
        )?;
        let mut forces = vec![[0.0; 3]; num_nodes];
        let mut displacement_gradient = [[0.0; 3]; 3];
        for (edge, bar_r) in neighbor_list.edges.iter().zip(bar_edge_vectors) {
            scatter_edge_vector_vjp(edge.src, edge.dst, bar_r, &mut forces)?;
            if compute_displacement_gradient {
                accumulate_edge_displacement_gradient(
                    edge.vector,
                    bar_r,
                    &mut displacement_gradient,
                );
            }
        }
        Ok(MaceLiteVjp {
            forces,
            displacement_gradient,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn evaluate_oam(
        &self,
        structure: &Structure,
        compute_forces: bool,
        options: &PredictionOptions,
        shared_neighbor_list: Option<&NeighborList>,
        prepared: Option<&MaceLitePreparedInput>,
        selected_nodes: Option<&[bool]>,
        extra: MaceLiteExtraOutputRequest,
    ) -> Result<MaceLiteOutput, MaceLiteError> {
        let trace_timings = mace_trace_timings_enabled();
        let runtime_plan = self.active_oam_plan_spec()?;
        let type_ids_storage;
        let type_ids = if let Some(prepared) = prepared {
            prepared.type_ids.as_slice()
        } else {
            type_ids_storage = self.type_ids(structure)?;
            &type_ids_storage
        };
        let node_attrs_storage;
        let node_attrs = if let Some(prepared) = prepared {
            prepared.node_attrs_f64.as_slice()
        } else {
            node_attrs_storage = one_hot(type_ids, self.type_names.len());
            &node_attrs_storage
        };
        let neighbor_list_storage;
        let neighbor_list = if let Some(prepared) = prepared {
            &prepared.neighbor_list
        } else if let Some(neighbor_list) = shared_neighbor_list {
            neighbor_list_storage = neighbor_list.filtered_by_cutoff(self.cutoff)?;
            &neighbor_list_storage
        } else {
            neighbor_list_storage = cell_list_multi_image_neighbor_list(structure, self.cutoff)?;
            &neighbor_list_storage
        };
        let num_nodes = structure.len();
        let num_edges = neighbor_list.edges.len();
        let pair_node_energy = if let Some(cached) =
            prepared.and_then(|prepared| prepared.cached_pair_node_energy(num_nodes, num_edges))
        {
            cached.to_vec()
        } else {
            self.pair_repulsion_node_energy(type_ids, neighbor_list)?
        };
        let senders_storage;
        let receivers_storage;
        let (senders, receivers): (&[usize], &[usize]) = if let Some(prepared) = prepared
            .filter(|prepared| prepared.neighbor_list.edges.len() == neighbor_list.edges.len())
        {
            (&prepared.senders, &prepared.receivers)
        } else {
            senders_storage = neighbor_list
                .edges
                .iter()
                .map(|edge| edge.src)
                .collect::<Vec<_>>();
            receivers_storage = neighbor_list
                .edges
                .iter()
                .map(|edge| edge.dst)
                .collect::<Vec<_>>();
            (&senders_storage, &receivers_storage)
        };

        let mut section_start = trace_timings.then(Instant::now);
        let mut edge_attrs = vec![0.0; num_edges * runtime_plan.sh_dim];
        let mut edge_feats = vec![0.0; num_edges * self.num_bessel];
        let mut radial_cache = compute_forces.then(|| RadialEmbeddingEdgeCache {
            bessel_basis: vec![0.0; num_edges * self.num_bessel],
            radial_distance: vec![0.0; num_edges],
            radial_distance_derivative: vec![0.0; num_edges],
        });
        #[cfg(feature = "parallel")]
        let edge_features_done = if rayon::current_num_threads() > 1
            && num_edges >= 512
            && runtime_plan.sh_dim == MP0B_SH_DIM
            && self.num_bessel == 10
        {
            if let Some(cache) = radial_cache.as_mut() {
                edge_attrs
                    .par_chunks_mut(runtime_plan.sh_dim)
                    .zip(edge_feats.par_chunks_mut(self.num_bessel))
                    .zip(cache.bessel_basis.par_chunks_mut(self.num_bessel))
                    .zip(cache.radial_distance.par_iter_mut())
                    .zip(cache.radial_distance_derivative.par_iter_mut())
                    .enumerate()
                    .try_for_each(
                        |(
                            edge_index,
                            (
                                (((edge_attr_row, edge_feat_row), cache_basis_row), cache_distance),
                                cache_derivative,
                            ),
                        )|
                         -> Result<(), MaceLiteError> {
                            let edge = &neighbor_list.edges[edge_index];
                            let mut bessel_basis = vec![0.0; self.num_bessel];
                            let mut radial = vec![0.0; self.num_bessel];
                            self.sh_plan.forward(edge.vector, edge_attr_row)?;
                            let radial_distance = self.radial_embedding_forward(
                                edge.distance,
                                type_ids[edge.src],
                                type_ids[edge.dst],
                                &mut bessel_basis,
                                &mut radial,
                            )?;
                            cache_basis_row.copy_from_slice(&bessel_basis);
                            *cache_distance = radial_distance.value;
                            *cache_derivative = radial_distance.derivative;
                            edge_feat_row.copy_from_slice(&radial);
                            Ok(())
                        },
                    )?;
            } else {
                edge_attrs
                    .par_chunks_mut(runtime_plan.sh_dim)
                    .zip(edge_feats.par_chunks_mut(self.num_bessel))
                    .enumerate()
                    .try_for_each(
                        |(edge_index, (edge_attr_row, edge_feat_row))| -> Result<(), MaceLiteError> {
                            let edge = &neighbor_list.edges[edge_index];
                            let mut bessel_basis = vec![0.0; self.num_bessel];
                            let mut radial = vec![0.0; self.num_bessel];
                            self.sh_plan.forward(edge.vector, edge_attr_row)?;
                            self.radial_embedding_forward(
                                edge.distance,
                                type_ids[edge.src],
                                type_ids[edge.dst],
                                &mut bessel_basis,
                                &mut radial,
                            )?;
                            edge_feat_row.copy_from_slice(&radial);
                            Ok(())
                        },
                    )?;
            }
            true
        } else {
            false
        };
        #[cfg(not(feature = "parallel"))]
        let edge_features_done = false;
        if !edge_features_done {
            let mut bessel_basis = vec![0.0; self.num_bessel];
            let mut radial = vec![0.0; self.num_bessel];
            for (edge_index, edge) in neighbor_list.edges.iter().enumerate() {
                self.sh_plan.forward(
                    edge.vector,
                    &mut edge_attrs
                        [edge_index * runtime_plan.sh_dim..(edge_index + 1) * runtime_plan.sh_dim],
                )?;
                let radial_distance = self.radial_embedding_forward(
                    edge.distance,
                    type_ids[edge.src],
                    type_ids[edge.dst],
                    &mut bessel_basis,
                    &mut radial,
                )?;
                if let Some(cache) = radial_cache.as_mut() {
                    cache.bessel_basis
                        [edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel]
                        .copy_from_slice(&bessel_basis);
                    cache.radial_distance[edge_index] = radial_distance.value;
                    cache.radial_distance_derivative[edge_index] = radial_distance.derivative;
                }
                edge_feats[edge_index * self.num_bessel..(edge_index + 1) * self.num_bessel]
                    .copy_from_slice(&radial);
            }
        }
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam edge_features_ms={:.3} edges={num_edges}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let node_plan = &runtime_plan.node_embedding;
        let mut node_feats = vec![0.0; num_nodes * node_plan.out_features];
        mp0b_masked_linear(
            node_attrs,
            self.float_tensor(
                "node_embedding.linear.weight",
                &[node_plan.in_features * node_plan.out_features],
            )?,
            self.float_tensor(
                "node_embedding.linear.output_mask",
                &[node_plan.out_features],
            )?,
            Mp0bMaskedLinearSpec {
                input_row_len: node_plan.input_row_len,
                in_features: node_plan.in_features,
                out_features: node_plan.out_features,
                path_weight: node_plan.path_weight,
            },
            &mut node_feats,
        );
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam node_embedding_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let layer0 = self.oam_layer_forward_cached(
            0,
            num_nodes,
            node_attrs,
            &node_feats,
            &edge_attrs,
            &edge_feats,
            senders,
            receivers,
            compute_forces,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer0_forward_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let readout0 = self.oam_readout0(&layer0.product_out)?;
        if let Some(start) = section_start.take() {
            eprintln!("mace_oam readout0_ms={:.3}", mace_trace_elapsed_ms(start));
        }
        section_start = trace_timings.then(Instant::now);
        let layer1 = self.oam_layer_forward_cached(
            1,
            num_nodes,
            node_attrs,
            &layer0.product_out,
            &edge_attrs,
            &edge_feats,
            senders,
            receivers,
            compute_forces,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer1_forward_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let readout1 = self.mp0b_readout1(&layer1.product_out)?;
        if let Some(start) = section_start.take() {
            eprintln!("mace_oam readout1_ms={:.3}", mace_trace_elapsed_ms(start));
        }

        section_start = trace_timings.then(Instant::now);
        let atomic_energies = self.atomic_energies_tensor()?;
        let scale = self.scale_shift_scale()?;
        let shift = self.scale_shift_shift()?;
        let (energy, atomic_energies_out) = mace_node_energy_sum_and_optional_values_f64(
            type_ids,
            atomic_energies,
            &pair_node_energy,
            scale,
            shift,
            selected_nodes,
            extra.atomic_energies,
            |node| readout0[node] + readout1[node],
        );
        if let Some(start) = section_start.take() {
            eprintln!("mace_oam energy_sum_ms={:.3}", mace_trace_elapsed_ms(start));
        }

        let (forces, stress, virial) = if compute_forces {
            section_start = trace_timings.then(Instant::now);
            let mut vjp = self.oam_vjp(
                type_ids,
                node_attrs,
                neighbor_list,
                &edge_attrs,
                &edge_feats,
                senders,
                receivers,
                &layer0,
                &layer1,
                scale,
                selected_nodes,
                options.compute_stress || options.compute_virial,
                radial_cache.as_ref(),
            )?;
            if let Some(start) = section_start.take() {
                eprintln!("mace_oam vjp_ms={:.3}", mace_trace_elapsed_ms(start));
            }
            section_start = trace_timings.then(Instant::now);
            self.add_pair_repulsion_vjp(
                type_ids,
                neighbor_list,
                scale,
                selected_nodes,
                options.compute_stress || options.compute_virial,
                &mut vjp,
            )?;
            let output =
                vjp.into_output_tensors(structure, options, self.cutoff, selected_nodes.is_none())?;
            if let Some(start) = section_start.take() {
                eprintln!(
                    "mace_oam output_tensors_ms={:.3}",
                    mace_trace_elapsed_ms(start)
                );
            }
            output
        } else {
            (Vec::new(), None, None)
        };
        let descriptors = if extra.descriptors {
            Some(self.descriptors_from_layer_outputs(
                &[layer0.product_out.as_slice(), layer1.product_out.as_slice()],
                num_nodes,
                extra.descriptor_invariants_only,
                extra.descriptor_num_layers,
            )?)
        } else {
            None
        };
        Ok(MaceLiteOutput {
            energy,
            forces,
            stress,
            virial,
            atomic_energies: atomic_energies_out,
            descriptors,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn oam_layer_forward_cached(
        &self,
        layer: usize,
        num_nodes: usize,
        node_attrs: &[f64],
        node_feats: &[f64],
        edge_attrs: &[f64],
        edge_feats: &[f64],
        senders: &[usize],
        receivers: &[usize],
        cache_tp_weights: bool,
    ) -> Result<Mp0bLayerForward, MaceLiteError> {
        let trace_timings = mace_trace_timings_enabled();
        let mut section_start = trace_timings.then(Instant::now);
        let layer_plan = self.oam_layer_plan_spec(layer)?;
        let mut linear_up = vec![0.0; num_nodes * layer_plan.linear_up_output_dim];
        self.oam_linear_up(layer, node_feats, &mut linear_up)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer{layer}_linear_up_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let forward = self.large_conv_tp_weights_with_plan(layer, layer_plan, edge_feats)?;
        let (tp_weights, tp_weight_cache) = if cache_tp_weights {
            (forward.output, Some(forward.cache))
        } else {
            (forward.output, None)
        };
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer{layer}_tp_weights_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let density = self.mp0b_density(layer, edge_feats, receivers, num_nodes)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer{layer}_density_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        let conv_plan = self
            .conv_tp_plan(layer)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let mut scatter_message = vec![0.0; num_nodes * conv_plan.output_dim()];
        section_start = trace_timings.then(Instant::now);
        mp0b_apply_conv_tp(
            Mp0bConvTpInput {
                plan: conv_plan,
                linear_up: &linear_up,
                edge_attrs,
                tp_weights: &tp_weights,
                output_mask: self.float_tensor(
                    &format!("interactions.{layer}.conv_tp.output_mask"),
                    &[layer_plan.conv_tp_output_dim],
                )?,
                senders,
                receivers,
            },
            &mut scatter_message,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer{layer}_conv_apply_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        let mut linear_message = vec![0.0; num_nodes * layer_plan.linear_message_output_dim];
        section_start = trace_timings.then(Instant::now);
        self.oam_density_hidden_linear(layer, &scatter_message, &density, &mut linear_message)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer{layer}_hidden_linear_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        let mut interaction_out = vec![0.0; num_nodes * layer_plan.linear_message_output_dim];
        section_start = trace_timings.then(Instant::now);
        if layer_plan.skip_kind == "message_selector" {
            let mut selected_message = vec![0.0; num_nodes * layer_plan.skip_output_dim];
            mp0b_hidden_message_selector(
                &linear_message,
                node_attrs,
                self.float_tensor(
                    &format!("interactions.{layer}.skip_tp.weight"),
                    &[4 * MP0B_NUM_FEATURES * self.type_names.len() * MP0B_NUM_FEATURES],
                )?,
                self.float_tensor(
                    &format!("interactions.{layer}.skip_tp.output_mask"),
                    &[layer_plan.skip_output_dim],
                )?,
                &mut selected_message,
            );
            mp0b_reshape_hidden_irreps_to_feature_major(&selected_message, &mut interaction_out);
        } else {
            mp0b_reshape_hidden_irreps_to_feature_major(&linear_message, &mut interaction_out);
        }
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer{layer}_message_select_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        let mut product_symmetric = vec![0.0; num_nodes * layer_plan.product_output_dim];
        section_start = trace_timings.then(Instant::now);
        self.product_contraction_forward(
            layer,
            &interaction_out,
            node_attrs,
            &mut product_symmetric,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer{layer}_product_contract_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        let mut product_out = vec![0.0; num_nodes * layer_plan.product_output_dim];
        section_start = trace_timings.then(Instant::now);
        self.oam_product_linear(layer, &product_symmetric, &mut product_out)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer{layer}_product_linear_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        if layer_plan.skip_kind == "residual_add" {
            section_start = trace_timings.then(Instant::now);
            let mut skip = vec![0.0; num_nodes * layer_plan.skip_output_dim];
            osaka_scalar_residual_skip(
                node_feats,
                node_attrs,
                self.float_tensor(
                    &format!("interactions.{layer}.skip_tp.weight"),
                    &[MP0B_NUM_FEATURES * self.type_names.len() * MP0B_NUM_FEATURES],
                )?,
                self.float_tensor(
                    &format!("interactions.{layer}.skip_tp.output_mask"),
                    &[layer_plan.skip_output_dim],
                )?,
                OsakaScalarSkipConfig {
                    input_row_len: layer_plan.linear_up_input_dim,
                    num_features: MP0B_NUM_FEATURES,
                    num_elements: self.type_names.len(),
                },
                &mut skip,
            )?;
            for (value, skip_value) in product_out.iter_mut().zip(skip) {
                *value += skip_value;
            }
            if let Some(start) = section_start.take() {
                eprintln!(
                    "mace_oam layer{layer}_residual_skip_ms={:.3}",
                    mace_trace_elapsed_ms(start)
                );
            }
        }

        Ok(Mp0bLayerForward {
            linear_up,
            tp_weights,
            tp_weight_cache,
            density,
            scatter_message,
            linear_message,
            interaction_out,
            product_out,
        })
    }

    fn oam_linear_up(
        &self,
        layer: usize,
        node_feats: &[f64],
        out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let layer_plan = self.oam_layer_plan_spec(layer)?;
        let linear_up_groups =
            product_linear_groups(layer_plan.linear_up_output_dim, MP0B_NUM_FEATURES)?;
        let linear_up_weight = self.float_tensor(
            &format!("interactions.{layer}.linear_up.weight"),
            &[equivariant_linear_weight_len(&linear_up_groups)],
        )?;
        let linear_up_output_mask = self.float_tensor(
            &format!("interactions.{layer}.linear_up.output_mask"),
            &[layer_plan.linear_up_output_dim],
        )?;
        let raw_path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
        if layer_plan.linear_up_input_dim == MP0B_NUM_FEATURES
            && layer_plan.linear_up_output_dim == MP0B_NUM_FEATURES
            && linear_up_weight.len() == MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && linear_up_output_mask.len() == MP0B_NUM_FEATURES
        {
            mp0b_scalar_product_linear(
                node_feats,
                linear_up_weight,
                linear_up_output_mask,
                raw_path_weight,
                out,
            );
            return Ok(());
        }
        if layer_plan.linear_up_input_dim == MP0B_PRODUCT0_ROW_LEN
            && layer_plan.linear_up_output_dim == MP0B_PRODUCT0_ROW_LEN
            && linear_up_weight.len() == 2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && linear_up_output_mask.len() == MP0B_PRODUCT0_ROW_LEN
        {
            mp0b_scalar_vector_product_linear(
                node_feats,
                linear_up_weight,
                linear_up_output_mask,
                raw_path_weight,
                out,
            );
            return Ok(());
        }
        mace_equivariant_linear(
            node_feats,
            linear_up_weight,
            linear_up_output_mask,
            &linear_up_groups,
            out,
        )
    }

    fn oam_linear_up_vjp_input(
        &self,
        layer: usize,
        bar_out: &[f64],
        bar_input: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let layer_plan = self.oam_layer_plan_spec(layer)?;
        let linear_up_groups =
            product_linear_groups(layer_plan.linear_up_output_dim, MP0B_NUM_FEATURES)?;
        let linear_up_weight = self.float_tensor(
            &format!("interactions.{layer}.linear_up.weight"),
            &[equivariant_linear_weight_len(&linear_up_groups)],
        )?;
        let linear_up_output_mask = self.float_tensor(
            &format!("interactions.{layer}.linear_up.output_mask"),
            &[layer_plan.linear_up_output_dim],
        )?;
        let raw_path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
        if layer_plan.linear_up_input_dim == MP0B_NUM_FEATURES
            && layer_plan.linear_up_output_dim == MP0B_NUM_FEATURES
            && linear_up_weight.len() == MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && linear_up_output_mask.len() == MP0B_NUM_FEATURES
        {
            mp0b_scalar_product_linear_vjp_input(
                linear_up_weight,
                linear_up_output_mask,
                bar_out,
                raw_path_weight,
                bar_input,
            );
            return Ok(());
        }
        if layer_plan.linear_up_input_dim == MP0B_PRODUCT0_ROW_LEN
            && layer_plan.linear_up_output_dim == MP0B_PRODUCT0_ROW_LEN
            && linear_up_weight.len() == 2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && linear_up_output_mask.len() == MP0B_PRODUCT0_ROW_LEN
        {
            mp0b_scalar_vector_product_linear_vjp_input(
                linear_up_weight,
                linear_up_output_mask,
                bar_out,
                raw_path_weight,
                bar_input,
            );
            return Ok(());
        }
        mace_equivariant_linear_vjp_input(
            linear_up_weight,
            linear_up_output_mask,
            &linear_up_groups,
            bar_out,
            bar_input,
        )
    }

    fn oam_density_hidden_linear(
        &self,
        layer: usize,
        scatter_message: &[f64],
        density: &[f64],
        out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let layer_plan = self.oam_layer_plan_spec(layer)?;
        let conv_plan = self
            .conv_tp_plan(layer)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let hidden_groups =
            grouped_input_to_hidden_linear_groups(&conv_plan.irreps_out, MP0B_NUM_FEATURES);
        let linear_weight = self.float_tensor(
            &format!("interactions.{layer}.linear.weight"),
            &[equivariant_linear_weight_len(&hidden_groups)],
        )?;
        let linear_output_mask = self.float_tensor(
            &format!("interactions.{layer}.linear.output_mask"),
            &[layer_plan.linear_message_output_dim],
        )?;
        mace_equivariant_linear(
            scatter_message,
            linear_weight,
            linear_output_mask,
            &hidden_groups,
            out,
        )?;
        if out.len() != density.len() * layer_plan.linear_message_output_dim {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        for (node, out_row) in out
            .chunks_mut(layer_plan.linear_message_output_dim)
            .enumerate()
        {
            let density_norm = density[node] + 1.0;
            for value in out_row {
                *value /= density_norm;
            }
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    fn oam_density_hidden_linear_vjp_input_density(
        &self,
        layer: usize,
        density: &[f64],
        linear_out: &[f64],
        bar_out: &[f64],
        bar_input: &mut [f64],
        bar_density: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let layer_plan = self.oam_layer_plan_spec(layer)?;
        if linear_out.len() != bar_out.len()
            || linear_out.len() != density.len() * layer_plan.linear_message_output_dim
            || bar_density.len() != density.len()
        {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let conv_plan = self
            .conv_tp_plan(layer)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let hidden_groups =
            grouped_input_to_hidden_linear_groups(&conv_plan.irreps_out, MP0B_NUM_FEATURES);
        let linear_weight = self.float_tensor(
            &format!("interactions.{layer}.linear.weight"),
            &[equivariant_linear_weight_len(&hidden_groups)],
        )?;
        let linear_output_mask = self.float_tensor(
            &format!("interactions.{layer}.linear.output_mask"),
            &[layer_plan.linear_message_output_dim],
        )?;
        let mut bar_linear = bar_out.to_vec();
        for node in 0..density.len() {
            let density_norm = density[node] + 1.0;
            let start = node * layer_plan.linear_message_output_dim;
            let end = start + layer_plan.linear_message_output_dim;
            for index in start..end {
                bar_density[node] -= bar_out[index] * linear_out[index] / density_norm;
                bar_linear[index] /= density_norm;
            }
        }
        mace_equivariant_linear_vjp_input(
            linear_weight,
            linear_output_mask,
            &hidden_groups,
            &bar_linear,
            bar_input,
        )
    }

    fn oam_product_linear(
        &self,
        layer: usize,
        product_symmetric: &[f64],
        out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let layer_plan = self.oam_layer_plan_spec(layer)?;
        let product_groups =
            product_linear_groups(layer_plan.product_output_dim, MP0B_NUM_FEATURES)?;
        let product_weight = self.float_tensor(
            &format!("products.{layer}.linear.weight"),
            &[equivariant_linear_weight_len(&product_groups)],
        )?;
        let product_output_mask = self.float_tensor(
            &format!("products.{layer}.linear.output_mask"),
            &[layer_plan.product_output_dim],
        )?;
        let raw_path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
        if layer_plan.product_output_dim == MP0B_NUM_FEATURES
            && product_weight.len() == MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && product_output_mask.len() == MP0B_NUM_FEATURES
        {
            mp0b_scalar_product_linear(
                product_symmetric,
                product_weight,
                product_output_mask,
                raw_path_weight,
                out,
            );
            return Ok(());
        }
        if layer_plan.product_output_dim == MP0B_PRODUCT0_ROW_LEN
            && product_weight.len() == 2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && product_output_mask.len() == MP0B_PRODUCT0_ROW_LEN
        {
            mp0b_scalar_vector_product_linear(
                product_symmetric,
                product_weight,
                product_output_mask,
                raw_path_weight,
                out,
            );
            return Ok(());
        }
        mace_equivariant_linear(
            product_symmetric,
            product_weight,
            product_output_mask,
            &product_groups,
            out,
        )
    }

    fn oam_readout0(&self, node_feats: &[f64]) -> Result<Vec<f64>, MaceLiteError> {
        let input_row_len = self.active_oam_plan_spec()?.product0_row_len;
        let mut output = vec![0.0; node_feats.len() / input_row_len];
        mp0b_masked_linear(
            node_feats,
            self.float_tensor("readouts.0.linear.weight", &[MP0B_NUM_FEATURES])?,
            self.float_tensor("readouts.0.linear.output_mask", &[1])?,
            Mp0bMaskedLinearSpec {
                input_row_len,
                in_features: MP0B_NUM_FEATURES,
                out_features: 1,
                path_weight: 1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
            },
            &mut output,
        );
        Ok(output)
    }

    fn oam_readout0_vjp(
        &self,
        bar_readout: &[f64],
        bar_product_out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let input_row_len = self.active_oam_plan_spec()?.product0_row_len;
        mp0b_masked_linear_vjp_input(
            self.float_tensor("readouts.0.linear.weight", &[MP0B_NUM_FEATURES])?,
            self.float_tensor("readouts.0.linear.output_mask", &[1])?,
            Mp0bMaskedLinearSpec {
                input_row_len,
                in_features: MP0B_NUM_FEATURES,
                out_features: 1,
                path_weight: 1.0 / (MP0B_NUM_FEATURES as f64).sqrt(),
            },
            bar_readout,
            bar_product_out,
        );
        Ok(())
    }

    fn oam_product_vjp_to_interaction_out(
        &self,
        layer: usize,
        node_attrs: &[f64],
        interaction_out: &[f64],
        bar_product_out: &[f64],
        bar_interaction_out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let mut bar_product_symmetric = vec![0.0; bar_product_out.len()];
        let layer_plan = self.oam_layer_plan_spec(layer)?;
        let product_groups =
            product_linear_groups(layer_plan.product_output_dim, MP0B_NUM_FEATURES)?;
        let product_weight = self.float_tensor(
            &format!("products.{layer}.linear.weight"),
            &[equivariant_linear_weight_len(&product_groups)],
        )?;
        let product_output_mask = self.float_tensor(
            &format!("products.{layer}.linear.output_mask"),
            &[layer_plan.product_output_dim],
        )?;
        let raw_path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
        if layer_plan.product_output_dim == MP0B_NUM_FEATURES
            && product_weight.len() == MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && product_output_mask.len() == MP0B_NUM_FEATURES
        {
            mp0b_scalar_product_linear_vjp_input(
                product_weight,
                product_output_mask,
                bar_product_out,
                raw_path_weight,
                &mut bar_product_symmetric,
            );
        } else if layer_plan.product_output_dim == MP0B_PRODUCT0_ROW_LEN
            && product_weight.len() == 2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES
            && product_output_mask.len() == MP0B_PRODUCT0_ROW_LEN
        {
            mp0b_scalar_vector_product_linear_vjp_input(
                product_weight,
                product_output_mask,
                bar_product_out,
                raw_path_weight,
                &mut bar_product_symmetric,
            );
        } else {
            mace_equivariant_linear_vjp_input(
                product_weight,
                product_output_mask,
                &product_groups,
                bar_product_out,
                &mut bar_product_symmetric,
            )?;
        }
        self.product_contraction_vjp_x(
            layer,
            interaction_out,
            node_attrs,
            &bar_product_symmetric,
            bar_interaction_out,
        )?;
        Ok(())
    }

    fn oam_message_vjp_to_scatter_density(
        &self,
        layer: usize,
        node_attrs: &[f64],
        scatter_message: &[f64],
        density: &[f64],
        linear_message: &[f64],
        bar_interaction_out: &[f64],
    ) -> Result<Mp0bMessageVjp, MaceLiteError> {
        let layer_plan = self.oam_layer_plan_spec(layer)?;
        let mut bar_linear_message = vec![0.0; linear_message.len()];
        if layer_plan.skip_kind == "message_selector" {
            mp0b_hidden_message_selector_vjp_input_from_feature_major(
                node_attrs,
                self.float_tensor(
                    &format!("interactions.{layer}.skip_tp.weight"),
                    &[4 * MP0B_NUM_FEATURES * self.type_names.len() * MP0B_NUM_FEATURES],
                )?,
                self.float_tensor(
                    &format!("interactions.{layer}.skip_tp.output_mask"),
                    &[layer_plan.skip_output_dim],
                )?,
                bar_interaction_out,
                &mut bar_linear_message,
            );
        } else {
            mp0b_reshape_hidden_irreps_to_feature_major_vjp(
                bar_interaction_out,
                &mut bar_linear_message,
            );
        }
        let mut bar_scatter_message = vec![0.0; scatter_message.len()];
        let mut bar_density = vec![0.0; density.len()];
        self.oam_density_hidden_linear_vjp_input_density(
            layer,
            density,
            linear_message,
            &bar_linear_message,
            &mut bar_scatter_message,
            &mut bar_density,
        )?;
        Ok(Mp0bMessageVjp {
            bar_scatter_message,
            bar_density,
        })
    }

    #[allow(clippy::too_many_arguments, clippy::type_complexity)]
    fn oam_layer_conv_vjp_outputs(
        &self,
        layer: usize,
        edge_attrs: &[f64],
        edge_feats: &[f64],
        senders: &[usize],
        receivers: &[usize],
        layer_forward: &Mp0bLayerForward,
        bar_scatter: &[f64],
    ) -> Result<(Vec<f64>, Vec<f64>, Vec<f64>), MaceLiteError> {
        let trace_timings = mace_trace_timings_enabled();
        let mut section_start = trace_timings.then(Instant::now);
        let layer_plan = self.oam_layer_plan_spec(layer)?;
        let conv_plan = self
            .conv_tp_plan(layer)
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let conv_vjp = mp0b_apply_conv_tp_vjp(
            Mp0bConvTpInput {
                plan: conv_plan,
                linear_up: &layer_forward.linear_up,
                edge_attrs,
                tp_weights: &layer_forward.tp_weights,
                output_mask: self.float_tensor(
                    &format!("interactions.{layer}.conv_tp.output_mask"),
                    &[conv_plan.output_dim()],
                )?,
                senders,
                receivers,
            },
            bar_scatter,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer{layer}_conv_vjp_apply_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        let tp_weight_cache = layer_forward
            .tp_weight_cache
            .as_ref()
            .ok_or(MaceLiteError::UnsupportedRuntime)?;
        let mut bar_edge_feats = vec![0.0; edge_feats.len()];
        section_start = trace_timings.then(Instant::now);
        self.large_conv_tp_weights_vjp_edge_feats_with_plan(
            layer,
            layer_plan,
            edge_feats,
            tp_weight_cache,
            &conv_vjp.bar_tp_weights,
            &mut bar_edge_feats,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam layer{layer}_conv_vjp_weights_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        Ok((
            conv_vjp.bar_linear_up,
            conv_vjp.bar_edge_attrs,
            bar_edge_feats,
        ))
    }

    #[allow(clippy::too_many_arguments)]
    fn oam_vjp(
        &self,
        type_ids: &[usize],
        node_attrs: &[f64],
        neighbor_list: &NeighborList,
        edge_attrs: &[f64],
        edge_feats: &[f64],
        senders: &[usize],
        receivers: &[usize],
        layer0: &Mp0bLayerForward,
        layer1: &Mp0bLayerForward,
        scale: f64,
        selected_nodes: Option<&[bool]>,
        compute_displacement_gradient: bool,
        radial_cache: Option<&RadialEmbeddingEdgeCache>,
    ) -> Result<MaceLiteVjp, MaceLiteError> {
        let trace_timings = mace_trace_timings_enabled();
        let mut section_start = trace_timings.then(Instant::now);
        let num_nodes = type_ids.len();
        let bar_readout = readout_seed(scale, num_nodes, selected_nodes);
        let mut bar_layer0_product_out = vec![0.0; layer0.product_out.len()];
        let mut bar_layer1_product_out = vec![0.0; layer1.product_out.len()];
        self.oam_readout0_vjp(&bar_readout, &mut bar_layer0_product_out)?;
        self.mp0b_readout1_vjp(
            &layer1.product_out,
            &bar_readout,
            &mut bar_layer1_product_out,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_readout_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let mut bar_layer1_interaction_out = vec![0.0; layer1.interaction_out.len()];
        self.oam_product_vjp_to_interaction_out(
            1,
            node_attrs,
            &layer1.interaction_out,
            &bar_layer1_product_out,
            &mut bar_layer1_interaction_out,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_layer1_product_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let layer1_plan = self.oam_layer_plan_spec(1)?;
        osaka_scalar_residual_skip_vjp_input(
            node_attrs,
            self.float_tensor(
                "interactions.1.skip_tp.weight",
                &[MP0B_NUM_FEATURES * self.type_names.len() * MP0B_NUM_FEATURES],
            )?,
            self.float_tensor(
                "interactions.1.skip_tp.output_mask",
                &[layer1_plan.skip_output_dim],
            )?,
            &bar_layer1_product_out,
            MP0B_NUM_FEATURES,
            self.type_names.len(),
            &mut bar_layer0_product_out,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_layer1_residual_skip_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let layer1_message_vjp = self.oam_message_vjp_to_scatter_density(
            1,
            node_attrs,
            &layer1.scatter_message,
            &layer1.density,
            &layer1.linear_message,
            &bar_layer1_interaction_out,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_layer1_message_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let (layer1_bar_linear_up, mut bar_edge_attrs, mut bar_edge_feats) = self
            .oam_layer_conv_vjp_outputs(
                1,
                edge_attrs,
                edge_feats,
                senders,
                receivers,
                layer1,
                &layer1_message_vjp.bar_scatter_message,
            )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_layer1_conv_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        self.mp0b_density_vjp_edge_feats(
            1,
            edge_feats,
            receivers,
            &layer1_message_vjp.bar_density,
            &mut bar_edge_feats,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_layer1_density_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        self.oam_linear_up_vjp_input(1, &layer1_bar_linear_up, &mut bar_layer0_product_out)?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_layer1_linear_up_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }

        section_start = trace_timings.then(Instant::now);
        let mut bar_layer0_interaction_out = vec![0.0; layer0.interaction_out.len()];
        self.oam_product_vjp_to_interaction_out(
            0,
            node_attrs,
            &layer0.interaction_out,
            &bar_layer0_product_out,
            &mut bar_layer0_interaction_out,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_layer0_product_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let layer0_message_vjp = self.oam_message_vjp_to_scatter_density(
            0,
            node_attrs,
            &layer0.scatter_message,
            &layer0.density,
            &layer0.linear_message,
            &bar_layer0_interaction_out,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_layer0_message_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let (_, layer0_bar_edge_attrs, mut layer0_bar_edge_feats) = self
            .oam_layer_conv_vjp_outputs(
                0,
                edge_attrs,
                edge_feats,
                senders,
                receivers,
                layer0,
                &layer0_message_vjp.bar_scatter_message,
            )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_layer0_conv_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        self.mp0b_density_vjp_edge_feats(
            0,
            edge_feats,
            receivers,
            &layer0_message_vjp.bar_density,
            &mut layer0_bar_edge_feats,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_layer0_density_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        for (target, value) in bar_edge_attrs.iter_mut().zip(layer0_bar_edge_attrs) {
            *target += value;
        }
        for (target, value) in bar_edge_feats.iter_mut().zip(layer0_bar_edge_feats) {
            *target += value;
        }

        section_start = trace_timings.then(Instant::now);
        let bar_edge_vectors = self.mp0b_edge_feature_vjp_to_edge_vectors(
            type_ids,
            neighbor_list,
            &bar_edge_attrs,
            &bar_edge_feats,
            radial_cache,
        )?;
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_edge_features_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        section_start = trace_timings.then(Instant::now);
        let mut forces = vec![[0.0; 3]; num_nodes];
        let mut displacement_gradient = [[0.0; 3]; 3];
        for (edge, bar_r) in neighbor_list.edges.iter().zip(bar_edge_vectors) {
            scatter_edge_vector_vjp(edge.src, edge.dst, bar_r, &mut forces)?;
            if compute_displacement_gradient {
                accumulate_edge_displacement_gradient(
                    edge.vector,
                    bar_r,
                    &mut displacement_gradient,
                );
            }
        }
        if let Some(start) = section_start.take() {
            eprintln!(
                "mace_oam vjp_force_scatter_ms={:.3}",
                mace_trace_elapsed_ms(start)
            );
        }
        Ok(MaceLiteVjp {
            forces,
            displacement_gradient,
        })
    }

    fn evaluate_two_layer(
        &self,
        structure: &Structure,
        compute_forces: bool,
        options: &PredictionOptions,
        shared_neighbor_list: Option<&NeighborList>,
        selected_nodes: Option<&[bool]>,
        extra: MaceLiteExtraOutputRequest,
    ) -> Result<MaceLiteOutput, MaceLiteError> {
        if self.state_float_tensors.is_empty() {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        if !(1..=2).contains(&self.num_layers) || self.l_max > MAX_INITIAL_L || self.num_bessel != 1
        {
            return Err(MaceLiteError::UnsupportedRuntime);
        }

        let type_ids = self.type_ids(structure)?;
        let node_attrs = one_hot(&type_ids, self.type_names.len());
        let neighbor_list_storage;
        let neighbor_list = if let Some(neighbor_list) = shared_neighbor_list {
            neighbor_list_storage = neighbor_list.filtered_by_cutoff(self.cutoff)?;
            &neighbor_list_storage
        } else {
            neighbor_list_storage = all_pairs_neighbor_list(structure, self.cutoff)?;
            &neighbor_list_storage
        };
        let mut node_feats = self.node_embedding(&type_ids)?;
        let mut readout_sum = vec![0.0; structure.len()];
        let pair_node_energy = self.pair_repulsion_node_energy(&type_ids, neighbor_list)?;
        let mut layer_outputs = Vec::with_capacity(self.num_layers);
        let mut layer_caches = Vec::with_capacity(self.num_layers);

        for layer in 0..self.num_layers {
            let (next_node_feats, cache) = self.evaluate_layer_product_cached(
                layer,
                structure.len(),
                &type_ids,
                &node_attrs,
                &node_feats,
                neighbor_list,
            )?;
            node_feats = next_node_feats;
            self.accumulate_readout(layer, &node_feats, &mut readout_sum)?;
            layer_outputs.push(node_feats.clone());
            layer_caches.push(cache);
        }

        let atomic_energies = self.float_tensor(
            "atomic_energies_fn.atomic_energies",
            &[self.type_names.len()],
        )?;
        let scale = self.float_scalar("scale_shift.scale")?;
        let shift = self.float_scalar("scale_shift.shift")?;
        let (energy, atomic_energies_out) = mace_node_energy_sum_and_optional_values_f64(
            &type_ids,
            atomic_energies,
            &pair_node_energy,
            scale,
            shift,
            selected_nodes,
            extra.atomic_energies,
            |node| readout_sum[node],
        );

        let (forces, stress, virial) = if compute_forces {
            let mut vjp = self.multi_layer_vjp(
                structure.len(),
                &type_ids,
                &node_attrs,
                &layer_outputs,
                &layer_caches,
                scale,
                selected_nodes,
                options.compute_stress || options.compute_virial,
            )?;
            self.add_pair_repulsion_vjp(
                &type_ids,
                neighbor_list,
                scale,
                selected_nodes,
                options.compute_stress || options.compute_virial,
                &mut vjp,
            )?;
            vjp.into_output_tensors(structure, options, self.cutoff, selected_nodes.is_none())?
        } else {
            (Vec::new(), None, None)
        };
        let descriptors = if extra.descriptors {
            let layer_slices = layer_outputs.iter().map(Vec::as_slice).collect::<Vec<_>>();
            Some(self.descriptors_from_layer_outputs(
                &layer_slices,
                structure.len(),
                extra.descriptor_invariants_only,
                extra.descriptor_num_layers,
            )?)
        } else {
            None
        };
        Ok(MaceLiteOutput {
            energy,
            forces,
            stress,
            virial,
            atomic_energies: atomic_energies_out,
            descriptors,
        })
    }

    fn evaluate_one_layer(
        &self,
        structure: &Structure,
        compute_forces: bool,
        options: &PredictionOptions,
        shared_neighbor_list: Option<&NeighborList>,
        selected_nodes: Option<&[bool]>,
        extra: MaceLiteExtraOutputRequest,
    ) -> Result<MaceLiteOutput, MaceLiteError> {
        if self.state_float_tensors.is_empty() {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        if self.num_layers != 1 || self.l_max != 2 || self.num_bessel != 1 {
            return Err(MaceLiteError::UnsupportedRuntime);
        }

        let type_ids = self.type_ids(structure)?;
        let node_attrs = one_hot(&type_ids, self.type_names.len());
        let neighbor_list_storage;
        let neighbor_list = if let Some(neighbor_list) = shared_neighbor_list {
            neighbor_list_storage = neighbor_list.filtered_by_cutoff(self.cutoff)?;
            &neighbor_list_storage
        } else {
            neighbor_list_storage = all_pairs_neighbor_list(structure, self.cutoff)?;
            &neighbor_list_storage
        };
        let pair_node_energy = self.pair_repulsion_node_energy(&type_ids, neighbor_list)?;

        let node_embedding = self.node_embedding(&type_ids)?;

        let linear_up_weight = self.float_tensor("interactions.0.linear_up.weight", &[1])?[0];
        let linear_up = node_embedding
            .iter()
            .map(|value| value * linear_up_weight)
            .collect::<Vec<_>>();

        let edge_mlp_w0 =
            self.float_tensor("interactions.0.conv_tp_weights.layer0.weight", &[1, 1])?[0];
        let edge_mlp_w1 =
            self.float_tensor("interactions.0.conv_tp_weights.layer1.weight", &[1, 3])?;
        let mut scatter_message = vec![[0.0; ONE_LAYER_SH_DIM]; structure.len()];
        let mut edge_caches = Vec::with_capacity(neighbor_list.edges.len());
        let mut sh = [0.0; ONE_LAYER_SH_DIM];
        let mut radial = [0.0; 1];
        let mut bessel_basis = [0.0; 1];
        for edge in &neighbor_list.edges {
            self.sh_plan.forward(edge.vector, &mut sh)?;
            let radial_distance = self.radial_embedding_forward(
                edge.distance,
                type_ids[edge.src],
                type_ids[edge.dst],
                &mut bessel_basis,
                &mut radial,
            )?;
            let hidden = silu(radial[0] * edge_mlp_w0) * MACE_SILU_SCALE;
            let weights = [
                hidden * edge_mlp_w1[0],
                hidden * edge_mlp_w1[1],
                hidden * edge_mlp_w1[2],
            ];
            for (component, sh_component) in sh.iter().enumerate().take(ONE_LAYER_SH_DIM) {
                let path = sh_component_path(component);
                scatter_message[edge.dst][component] +=
                    linear_up[edge.src] * *sh_component * weights[path];
            }
            if compute_forces {
                edge_caches.push(OneLayerEdgeCache {
                    src: edge.src,
                    dst: edge.dst,
                    vector: edge.vector,
                    distance: edge.distance,
                    radial_distance: radial_distance.value,
                    radial_distance_derivative: radial_distance.derivative,
                    sh,
                    bessel_basis: bessel_basis[0],
                    radial: radial[0],
                    weights,
                    linear_up_src: linear_up[edge.src],
                });
            }
        }

        let linear_weight = self.float_tensor("interactions.0.linear.weight", &[3])?;
        let mut message = vec![0.0; structure.len() * ONE_LAYER_SH_DIM];
        for (node, node_message) in scatter_message.iter().enumerate() {
            for component in 0..ONE_LAYER_SH_DIM {
                let path = sh_component_path(component);
                message[node * ONE_LAYER_SH_DIM + component] =
                    node_message[component] * linear_weight[path];
            }
        }

        let contraction = MaceScalarSymmetricContraction {
            num_elements: self.type_names.len(),
            num_features: 1,
            num_ell: ONE_LAYER_SH_DIM,
            u1_params: 1,
            u2_params: 3,
            u3_params: 11,
            u1: self.float_tensor(
                "products.0.symmetric_contractions.contractions.0.U_matrix_1",
                &[9, 1],
            )?,
            u2: self.float_tensor(
                "products.0.symmetric_contractions.contractions.0.U_matrix_2",
                &[9, 9, 3],
            )?,
            u3: self.float_tensor(
                "products.0.symmetric_contractions.contractions.0.U_matrix_3",
                &[9, 9, 9, 11],
            )?,
            weights_u2: self.float_tensor(
                "products.0.symmetric_contractions.contractions.0.weights.0",
                &[2, 3, 1],
            )?,
            weights_u1: self.float_tensor(
                "products.0.symmetric_contractions.contractions.0.weights.1",
                &[2, 1, 1],
            )?,
            weights_u3: self.float_tensor(
                "products.0.symmetric_contractions.contractions.0.weights_max",
                &[2, 11, 1],
            )?,
            entries: None,
        };
        let mut product_basis = vec![0.0; structure.len()];
        contraction.forward(&message, &node_attrs, &mut product_basis)?;

        let product_linear = self.float_tensor("products.0.linear.weight", &[1])?[0];
        let skip_weight = self.float_tensor("interactions.0.skip_tp.weight", &[2])?;
        let skip_norm = (self.type_names.len() as f64).sqrt();
        let readout_weight = self.float_tensor("readouts.0.linear.weight", &[1])?[0];
        let atomic_energies = self.float_tensor(
            "atomic_energies_fn.atomic_energies",
            &[self.type_names.len()],
        )?;
        let scale = self.float_scalar("scale_shift.scale")?;
        let shift = self.float_scalar("scale_shift.shift")?;

        let mut energy = 0.0;
        let mut bar_product_basis = vec![0.0; structure.len()];
        let mut atomic_energies_out = extra.atomic_energies.then(|| vec![0.0; structure.len()]);
        let mut descriptor_product_out = extra.descriptors.then(|| vec![0.0; structure.len()]);
        for (node, &type_id) in type_ids.iter().enumerate() {
            let skip = node_embedding[node] * skip_weight[type_id] / skip_norm;
            let product_out = product_basis[node] * product_linear + skip;
            if let Some(values) = descriptor_product_out.as_mut() {
                values[node] = product_out;
            }
            if !is_selected_node(selected_nodes, node) {
                continue;
            }
            let interaction_energy =
                scale * (product_out * readout_weight + pair_node_energy[node]) + shift;
            let node_energy = atomic_energies[type_id] + interaction_energy;
            if let Some(values) = atomic_energies_out.as_mut() {
                values[node] = node_energy;
            }
            energy += node_energy;
            if compute_forces {
                bar_product_basis[node] += scale * readout_weight * product_linear;
            }
        }
        let (forces, stress, virial) = if compute_forces {
            let mut vjp = self.one_layer_vjp(
                structure,
                &node_attrs,
                &message,
                &contraction,
                &bar_product_basis,
                &edge_caches,
                linear_weight,
                edge_mlp_w0,
                edge_mlp_w1,
                options.compute_stress || options.compute_virial,
            )?;
            self.add_pair_repulsion_vjp(
                &type_ids,
                neighbor_list,
                scale,
                selected_nodes,
                options.compute_stress || options.compute_virial,
                &mut vjp,
            )?;
            vjp.into_output_tensors(structure, options, self.cutoff, selected_nodes.is_none())?
        } else {
            (Vec::new(), None, None)
        };
        let descriptors = if extra.descriptors {
            let product_out = descriptor_product_out
                .as_deref()
                .ok_or(MaceLiteError::UnsupportedRuntime)?;
            Some(self.descriptors_from_layer_outputs(
                &[product_out],
                structure.len(),
                extra.descriptor_invariants_only,
                extra.descriptor_num_layers,
            )?)
        } else {
            None
        };
        Ok(MaceLiteOutput {
            energy,
            forces,
            stress,
            virial,
            atomic_energies: atomic_energies_out,
            descriptors,
        })
    }

    fn descriptors_from_layer_outputs(
        &self,
        layer_outputs: &[&[f64]],
        num_nodes: usize,
        invariants_only: bool,
        num_layers: isize,
    ) -> Result<Vec<Vec<f64>>, MaceLiteError> {
        let layer_count = resolve_descriptor_layer_count(layer_outputs.len(), num_layers)?;
        if num_nodes == 0 {
            return Ok(Vec::new());
        }
        let mut layer_widths = Vec::with_capacity(layer_count);
        for (layer, output) in layer_outputs.iter().take(layer_count).enumerate() {
            if output.len() % num_nodes != 0 {
                return Err(MaceLiteError::UnsupportedRuntime);
            }
            let row_len = output.len() / num_nodes;
            let width = if invariants_only {
                self.scalar_contraction_shape(self.scalar_contraction_component(layer)?)?
                    .num_features
            } else {
                row_len
            };
            if width > row_len {
                return Err(MaceLiteError::UnsupportedRuntime);
            }
            layer_widths.push((row_len, width));
        }
        let total_width = layer_widths.iter().map(|(_, width)| *width).sum::<usize>();
        let mut descriptors = (0..num_nodes)
            .map(|_| Vec::with_capacity(total_width))
            .collect::<Vec<_>>();
        for (layer_output, (row_len, width)) in
            layer_outputs.iter().take(layer_count).zip(layer_widths)
        {
            for (node, row) in layer_output.chunks(row_len).enumerate() {
                descriptors[node].extend_from_slice(&row[..width]);
            }
        }
        Ok(descriptors)
    }

    fn descriptors_from_f32_layer_outputs(
        &self,
        layer_outputs: &[&[f32]],
        num_nodes: usize,
        invariants_only: bool,
        num_layers: isize,
    ) -> Result<Vec<Vec<f64>>, MaceLiteError> {
        let converted = layer_outputs
            .iter()
            .map(|output| {
                output
                    .iter()
                    .map(|&value| f64::from(value))
                    .collect::<Vec<_>>()
            })
            .collect::<Vec<_>>();
        let refs = converted.iter().map(Vec::as_slice).collect::<Vec<&[f64]>>();
        self.descriptors_from_layer_outputs(&refs, num_nodes, invariants_only, num_layers)
    }

    fn node_embedding(&self, type_ids: &[usize]) -> Result<Vec<f64>, MaceLiteError> {
        let node_embedding_weight =
            self.float_tensor("node_embedding.linear.weight", &[self.type_names.len()])?;
        let node_embedding_norm = (self.type_names.len() as f64).sqrt();
        Ok(type_ids
            .iter()
            .map(|&type_id| node_embedding_weight[type_id] / node_embedding_norm)
            .collect())
    }

    fn evaluate_layer_product(
        &self,
        layer: usize,
        num_nodes: usize,
        type_ids: &[usize],
        node_attrs: &[f64],
        node_feats: &[f64],
        neighbor_list: &NeighborList,
    ) -> Result<Vec<f64>, MaceLiteError> {
        let linear_up_weight =
            self.float_tensor(&format!("interactions.{layer}.linear_up.weight"), &[1])?[0];
        let edge_mlp_w0 = self.float_tensor(
            &format!("interactions.{layer}.conv_tp_weights.layer0.weight"),
            &[1, 1],
        )?[0];
        let sh_dim = self.sh_dim();
        let num_paths = self.num_paths();
        let edge_mlp_w1 = self.float_tensor(
            &format!("interactions.{layer}.conv_tp_weights.layer1.weight"),
            &[1, num_paths],
        )?;
        let density_weight = self.layer_density_weight(layer)?;
        let message_selector_weight = self.layer_message_selector_weight(layer)?;
        let mut density_denominator = vec![1.0; num_nodes];
        // Contiguous per-node scatter buffer (node-major, sh_dim wide). Mirrors the
        // contiguous layout used by `evaluate_one_layer`; index as [node * sh_dim + k].
        let mut scatter_message = vec![0.0; num_nodes * sh_dim];
        let mut sh = vec![0.0; sh_dim];
        let mut radial = [0.0; 1];
        let mut bessel_basis = [0.0; 1];
        for edge in &neighbor_list.edges {
            self.sh_plan.forward(edge.vector, &mut sh)?;
            self.radial_embedding_forward(
                edge.distance,
                type_ids[edge.src],
                type_ids[edge.dst],
                &mut bessel_basis,
                &mut radial,
            )?;
            let linear_up_src = node_feats[edge.src] * linear_up_weight;
            let hidden = silu(radial[0] * edge_mlp_w0) * MACE_SILU_SCALE;
            let weights = edge_mlp_w1
                .iter()
                .map(|weight| hidden * weight)
                .collect::<Vec<_>>();
            if let Some(weight) = density_weight {
                let density_raw = radial[0] * weight;
                density_denominator[edge.dst] += (density_raw * density_raw).tanh();
            }
            let dst_base = edge.dst * sh_dim;
            for component in 0..sh_dim {
                let path = sh_component_path(component);
                scatter_message[dst_base + component] +=
                    linear_up_src * sh[component] * weights[path];
            }
        }

        let linear_weight =
            self.float_tensor(&format!("interactions.{layer}.linear.weight"), &[num_paths])?;
        let mut message = vec![0.0; num_nodes * sh_dim];
        for (node, &denominator) in density_denominator.iter().enumerate().take(num_nodes) {
            let node_base = node * sh_dim;
            for component in 0..sh_dim {
                let path = sh_component_path(component);
                message[node_base + component] =
                    scatter_message[node_base + component] * linear_weight[path] / denominator;
            }
        }
        if let Some(selector_weight) = message_selector_weight {
            apply_message_selector(
                &mut message,
                selector_weight,
                type_ids,
                self.type_names.len(),
            );
        }

        let contraction = self.layer_contraction(layer)?;
        let mut product_basis = vec![0.0; num_nodes];
        contraction.forward(&message, node_attrs, &mut product_basis)?;

        let product_linear =
            self.float_tensor(&format!("products.{layer}.linear.weight"), &[1])?[0];
        let residual_skip_weight = self.layer_residual_skip_weight(layer)?;
        let skip_norm = (self.type_names.len() as f64).sqrt();
        Ok(type_ids
            .iter()
            .enumerate()
            .map(|(node, &type_id)| {
                let skip = residual_skip_weight
                    .map(|skip_weight| node_feats[node] * skip_weight[type_id] / skip_norm)
                    .unwrap_or(0.0);
                product_basis[node] * product_linear + skip
            })
            .collect())
    }

    fn evaluate_layer_product_cached(
        &self,
        layer: usize,
        num_nodes: usize,
        type_ids: &[usize],
        node_attrs: &[f64],
        node_feats: &[f64],
        neighbor_list: &NeighborList,
    ) -> Result<(Vec<f64>, MaceLayerCache), MaceLiteError> {
        let linear_up_weight =
            self.float_tensor(&format!("interactions.{layer}.linear_up.weight"), &[1])?[0];
        let edge_mlp_w0 = self.float_tensor(
            &format!("interactions.{layer}.conv_tp_weights.layer0.weight"),
            &[1, 1],
        )?[0];
        let sh_dim = self.sh_dim();
        let num_paths = self.num_paths();
        let edge_mlp_w1_slice = self.float_tensor(
            &format!("interactions.{layer}.conv_tp_weights.layer1.weight"),
            &[1, num_paths],
        )?;
        let edge_mlp_w1 = edge_mlp_w1_slice.to_vec();
        let density_weight = self.layer_density_weight(layer)?;
        let message_selector_weight = self
            .layer_message_selector_weight(layer)?
            .map(<[f64]>::to_vec);
        let mut density_denominator = vec![1.0; num_nodes];
        // Contiguous per-node scatter buffer (node-major, sh_dim wide). Mirrors the
        // contiguous layout used by `evaluate_one_layer`; index as [node * sh_dim + k].
        let mut scatter_message = vec![0.0; num_nodes * sh_dim];
        let mut edge_caches = Vec::with_capacity(neighbor_list.edges.len());
        let mut sh = vec![0.0; sh_dim];
        let mut radial = [0.0; 1];
        let mut bessel_basis = [0.0; 1];
        for edge in &neighbor_list.edges {
            self.sh_plan.forward(edge.vector, &mut sh)?;
            let radial_distance = self.radial_embedding_forward(
                edge.distance,
                type_ids[edge.src],
                type_ids[edge.dst],
                &mut bessel_basis,
                &mut radial,
            )?;
            let linear_up_src = node_feats[edge.src] * linear_up_weight;
            let hidden = silu(radial[0] * edge_mlp_w0) * MACE_SILU_SCALE;
            let weights = edge_mlp_w1
                .iter()
                .map(|weight| hidden * weight)
                .collect::<Vec<_>>();
            let density_raw = density_weight.map(|weight| radial[0] * weight);
            if let Some(raw) = density_raw {
                density_denominator[edge.dst] += (raw * raw).tanh();
            }
            let dst_base = edge.dst * sh_dim;
            for component in 0..sh_dim {
                let path = sh_component_path(component);
                scatter_message[dst_base + component] +=
                    linear_up_src * sh[component] * weights[path];
            }
            edge_caches.push(MaceLayerEdgeCache {
                src: edge.src,
                dst: edge.dst,
                vector: edge.vector,
                distance: edge.distance,
                radial_distance: radial_distance.value,
                radial_distance_derivative: radial_distance.derivative,
                sh: sh.clone(),
                bessel_basis: bessel_basis[0],
                radial: radial[0],
                weights,
                linear_up_src,
                density_raw,
            });
        }

        let linear_weight_slice =
            self.float_tensor(&format!("interactions.{layer}.linear.weight"), &[num_paths])?;
        let linear_weight = linear_weight_slice.to_vec();
        let mut message = vec![0.0; num_nodes * sh_dim];
        for (node, &denominator) in density_denominator.iter().enumerate().take(num_nodes) {
            let node_base = node * sh_dim;
            for component in 0..sh_dim {
                let path = sh_component_path(component);
                message[node_base + component] =
                    scatter_message[node_base + component] * linear_weight[path] / denominator;
            }
        }
        let normalized_message = message.clone();
        if let Some(selector_weight) = message_selector_weight.as_deref() {
            apply_message_selector(
                &mut message,
                selector_weight,
                type_ids,
                self.type_names.len(),
            );
        }

        let contraction = self.layer_contraction(layer)?;
        let mut product_basis = vec![0.0; num_nodes];
        contraction.forward(&message, node_attrs, &mut product_basis)?;

        let product_linear =
            self.float_tensor(&format!("products.{layer}.linear.weight"), &[1])?[0];
        let residual_skip_weight = self.layer_residual_skip_weight(layer)?.map(<[f64]>::to_vec);
        let skip_norm = (self.type_names.len() as f64).sqrt();
        let output = type_ids
            .iter()
            .enumerate()
            .map(|(node, &type_id)| {
                let skip = residual_skip_weight
                    .as_deref()
                    .map(|skip_weight| node_feats[node] * skip_weight[type_id] / skip_norm)
                    .unwrap_or(0.0);
                product_basis[node] * product_linear + skip
            })
            .collect();
        Ok((
            output,
            MaceLayerCache {
                layer,
                linear_up_weight,
                edge_mlp_w0,
                edge_mlp_w1,
                linear_weight,
                product_linear,
                residual_skip_weight,
                message_selector_weight,
                message,
                normalized_message,
                density_weight,
                density_denominator,
                edge_caches,
            },
        ))
    }

    fn layer_contraction(
        &self,
        layer: usize,
    ) -> Result<MaceScalarSymmetricContraction<'_>, MaceLiteError> {
        let component = self.scalar_contraction_component(layer)?;
        self.scalar_contraction_from_component(component)
    }

    fn scalar_contraction_from_component<'a>(
        &'a self,
        component: ContractionComponentView<'a>,
    ) -> Result<MaceScalarSymmetricContraction<'a>, MaceLiteError> {
        let mut scalar = self.scalar_contraction_from_component_uncached(component)?;
        scalar.entries = self
            .scalar_contraction_entries
            .get(&contraction_entry_cache_key(component));
        Ok(scalar)
    }

    fn scalar_contraction_from_component_uncached<'a>(
        &'a self,
        component: ContractionComponentView<'a>,
    ) -> Result<MaceScalarSymmetricContraction<'a>, MaceLiteError> {
        let sh_dim = self.sh_dim();
        let shape = self.scalar_contraction_shape(component)?;
        if shape.num_ell != sh_dim {
            return Err(MaceLiteError::StateTensorShape {
                name: component.u_tensors[0].clone(),
                actual: vec![shape.num_ell],
                expected: vec![sh_dim],
            });
        }
        Ok(MaceScalarSymmetricContraction {
            num_elements: self.type_names.len(),
            num_features: shape.num_features,
            num_ell: shape.num_ell,
            u1_params: shape.u1_params,
            u2_params: shape.u2_params,
            u3_params: shape.u3_params,
            u1: &shape.u1.values,
            u2: &shape.u2.values,
            u3: &shape.u3.values,
            weights_u2: &shape.weights_u2.values,
            weights_u1: &shape.weights_u1.values,
            weights_u3: &shape.weights_u3.values,
            entries: None,
        })
    }

