    fn product_contraction_forward(
        &self,
        layer: usize,
        interaction_out: &[f64],
        node_attrs: &[f64],
        out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let contraction = self.layer_symmetric_contraction(layer)?;
        if contraction.contractions.is_empty() {
            self.layer_contraction(layer)?
                .forward(interaction_out, node_attrs, out)?;
            return Ok(());
        }
        if self.type_names.is_empty() || !node_attrs.len().is_multiple_of(self.type_names.len()) {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let num_nodes = node_attrs.len() / self.type_names.len();
        if num_nodes == 0 || !out.len().is_multiple_of(num_nodes) {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let output_row_len = out.len() / num_nodes;
        if let [component] = contraction.contractions.as_slice() {
            if component.kind == "scalar" {
                let view = contraction_component_view(component);
                let scalar = self.scalar_contraction_from_component(view)?;
                if scalar.num_features == output_row_len {
                    scalar.forward(interaction_out, node_attrs, out)?;
                    return Ok(());
                }
            }
        }
        out.fill(0.0);
        let mut row_offset = 0;
        for component in &contraction.contractions {
            match component.kind.as_str() {
                "scalar" => {
                    let view = contraction_component_view(component);
                    let scalar = self.scalar_contraction_from_component(view)?;
                    let component_len = scalar.num_features;
                    let mut component_out = vec![0.0; num_nodes * component_len];
                    scalar.forward(interaction_out, node_attrs, &mut component_out)?;
                    copy_component_rows_to_product(
                        &component_out,
                        component_len,
                        row_offset,
                        output_row_len,
                        out,
                    )?;
                    row_offset += component_len;
                }
                "vector" => {
                    let view = contraction_component_view(component);
                    let vector = self.vector_contraction_from_component(view)?;
                    let component_len = vector.num_features * vector.num_equivariance;
                    let mut component_out = vec![0.0; num_nodes * component_len];
                    vector.forward(interaction_out, node_attrs, &mut component_out)?;
                    copy_component_rows_to_product(
                        &component_out,
                        component_len,
                        row_offset,
                        output_row_len,
                        out,
                    )?;
                    row_offset += component_len;
                }
                _ => return Err(MaceLiteError::UnsupportedRuntime),
            }
        }
        if row_offset != output_row_len {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        Ok(())
    }

    fn product_contraction_vjp_x(
        &self,
        layer: usize,
        interaction_out: &[f64],
        node_attrs: &[f64],
        grad_out: &[f64],
        grad_interaction_out: &mut [f64],
    ) -> Result<(), MaceLiteError> {
        let contraction = self.layer_symmetric_contraction(layer)?;
        if contraction.contractions.is_empty() {
            self.layer_contraction(layer)?.vjp_x(
                interaction_out,
                node_attrs,
                grad_out,
                grad_interaction_out,
            )?;
            return Ok(());
        }
        if self.type_names.is_empty() || !node_attrs.len().is_multiple_of(self.type_names.len()) {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let num_nodes = node_attrs.len() / self.type_names.len();
        if num_nodes == 0 || !grad_out.len().is_multiple_of(num_nodes) {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let output_row_len = grad_out.len() / num_nodes;
        if let [component] = contraction.contractions.as_slice() {
            if component.kind == "scalar" {
                let view = contraction_component_view(component);
                let scalar = self.scalar_contraction_from_component(view)?;
                if scalar.num_features == output_row_len {
                    scalar.vjp_x(interaction_out, node_attrs, grad_out, grad_interaction_out)?;
                    return Ok(());
                }
            }
        }
        let mut row_offset = 0;
        for component in &contraction.contractions {
            match component.kind.as_str() {
                "scalar" => {
                    let view = contraction_component_view(component);
                    let scalar = self.scalar_contraction_from_component(view)?;
                    let component_len = scalar.num_features;
                    let mut component_grad = vec![0.0; num_nodes * component_len];
                    copy_product_rows_to_component(
                        grad_out,
                        output_row_len,
                        row_offset,
                        component_len,
                        &mut component_grad,
                    )?;
                    scalar.vjp_x(
                        interaction_out,
                        node_attrs,
                        &component_grad,
                        grad_interaction_out,
                    )?;
                    row_offset += component_len;
                }
                "vector" => {
                    let view = contraction_component_view(component);
                    let vector = self.vector_contraction_from_component(view)?;
                    let component_len = vector.num_features * vector.num_equivariance;
                    let mut component_grad = vec![0.0; num_nodes * component_len];
                    copy_product_rows_to_component(
                        grad_out,
                        output_row_len,
                        row_offset,
                        component_len,
                        &mut component_grad,
                    )?;
                    vector.vjp_x(
                        interaction_out,
                        node_attrs,
                        &component_grad,
                        grad_interaction_out,
                    )?;
                    row_offset += component_len;
                }
                _ => return Err(MaceLiteError::UnsupportedRuntime),
            }
        }
        if row_offset != output_row_len {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        Ok(())
    }

    fn product_contraction_forward_f32(
        &self,
        layer: usize,
        interaction_out: &[f32],
        node_attrs: &[f32],
        out: &mut [f32],
        cached_entries: Option<&ScalarContractionEntriesF32>,
    ) -> Result<Option<ScalarContractionCacheF32>, MaceLiteError> {
        let contraction = self.layer_symmetric_contraction(layer)?;
        if self.type_names.is_empty() || !node_attrs.len().is_multiple_of(self.type_names.len()) {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let num_nodes = node_attrs.len() / self.type_names.len();
        if num_nodes == 0 || !out.len().is_multiple_of(num_nodes) {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let output_row_len = out.len() / num_nodes;
        if contraction.contractions.is_empty() {
            let scalar = self.mp0b_scalar_contraction_f32(layer)?;
            if scalar.num_features != output_row_len {
                return Err(MaceLiteError::UnsupportedRuntime);
            }
            #[cfg(all(feature = "apple-metal", target_os = "macos"))]
            if let Some(cache) = self.mace_scalar_contraction_forward_metal_f32(
                &scalar,
                interaction_out,
                node_attrs,
                out,
                cached_entries,
            )? {
                return Ok(Some(cache));
            }
            return scalar
                .forward_cached_with_entries(interaction_out, node_attrs, out, cached_entries)
                .map(Some);
        }
        if let [component] = contraction.contractions.as_slice() {
            if component.kind == "scalar" {
                let view = contraction_component_view(component);
                let scalar = self.scalar_contraction_from_component_f32(view)?;
                if scalar.num_features == output_row_len {
                    #[cfg(all(feature = "apple-metal", target_os = "macos"))]
                    if let Some(cache) = self.mace_scalar_contraction_forward_metal_f32(
                        &scalar,
                        interaction_out,
                        node_attrs,
                        out,
                        cached_entries,
                    )? {
                        return Ok(Some(cache));
                    }
                    return scalar
                        .forward_cached_with_entries(
                            interaction_out,
                            node_attrs,
                            out,
                            cached_entries,
                        )
                        .map(Some);
                }
            }
        }
        #[cfg(all(feature = "apple-metal", target_os = "macos"))]
        if let [scalar_component, vector_component] = contraction.contractions.as_slice() {
            if scalar_component.kind == "scalar"
                && vector_component.kind == "vector"
                && output_row_len == MP0B_PRODUCT0_ROW_LEN
            {
                let scalar = self.scalar_contraction_from_component_f32(
                    contraction_component_view(scalar_component),
                )?;
                let vector = self.vector_contraction_from_component_f32(
                    contraction_component_view(vector_component),
                )?;
                if self.mace_scalar_vector_contraction_forward_metal_f32(
                    &scalar,
                    &vector,
                    interaction_out,
                    node_attrs,
                    out,
                )? {
                    return Ok(None);
                }
            }
        }
        out.fill(0.0);
        let mut row_offset = 0;
        for component in &contraction.contractions {
            match component.kind.as_str() {
                "scalar" => {
                    let view = contraction_component_view(component);
                    let scalar = self.scalar_contraction_from_component_f32(view)?;
                    let component_len = scalar.num_features;
                    let mut component_out = vec![0.0_f32; num_nodes * component_len];
                    scalar.forward(interaction_out, node_attrs, &mut component_out)?;
                    copy_component_rows_to_product_f32(
                        &component_out,
                        component_len,
                        row_offset,
                        output_row_len,
                        out,
                    )?;
                    row_offset += component_len;
                }
                "vector" => {
                    let view = contraction_component_view(component);
                    let vector = self.vector_contraction_from_component_f32(view)?;
                    let component_len = vector.num_features * vector.num_equivariance;
                    #[cfg(all(feature = "apple-metal", target_os = "macos"))]
                    let vector_metal_done = self.mace_vector_contraction_forward_metal_f32(
                        &vector,
                        interaction_out,
                        node_attrs,
                        row_offset,
                        output_row_len,
                        out,
                    )?;
                    #[cfg(not(all(feature = "apple-metal", target_os = "macos")))]
                    let vector_metal_done = false;
                    if !vector_metal_done {
                        let mut component_out = vec![0.0_f32; num_nodes * component_len];
                        vector.forward(interaction_out, node_attrs, &mut component_out)?;
                        copy_component_rows_to_product_f32(
                            &component_out,
                            component_len,
                            row_offset,
                            output_row_len,
                            out,
                        )?;
                    }
                    row_offset += component_len;
                }
                _ => return Err(MaceLiteError::UnsupportedRuntime),
            }
        }
        if row_offset != output_row_len {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        Ok(None)
    }

    #[cfg(all(feature = "apple-metal", target_os = "macos"))]
    #[allow(clippy::too_many_arguments)]
    fn mace_scalar_vector_contraction_forward_metal_f32(
        &self,
        scalar: &MaceScalarSymmetricContractionF32<'_>,
        vector: &MaceVectorSymmetricContractionF32<'_>,
        interaction_out: &[f32],
        node_attrs: &[f32],
        out: &mut [f32],
    ) -> Result<bool, MaceLiteError> {
        if !metal::mace_metal_enabled()
            || !matches!(
                self.active_runtime_plan_kind(),
                Some(MaceRuntimePlanKind::Oam | MaceRuntimePlanKind::Osaka24)
            )
            || scalar.num_elements != MP0B_NUM_ELEMENTS
            || scalar.num_features != MP0B_NUM_FEATURES
            || scalar.num_ell != MP0B_SH_DIM
            || scalar.u1_params != 1
            || scalar.u2_params != 4
            || scalar.u3_params != 23
            || vector.num_elements != MP0B_NUM_ELEMENTS
            || vector.num_features != MP0B_NUM_FEATURES
            || vector.num_equivariance != 3
            || vector.num_ell != MP0B_SH_DIM
            || vector.u1_params != 1
            || vector.u2_params != 6
            || vector.u3_params != 51
        {
            return Ok(false);
        }
        let num_nodes = interaction_out.len() / (MP0B_NUM_FEATURES * MP0B_SH_DIM);
        if num_nodes < MACE_SCALAR_VECTOR_CONTRACTION_FORWARD_METAL_MIN_NODES
            || interaction_out.len() != num_nodes * MP0B_HIDDEN_ROW_LEN
            || node_attrs.len() != num_nodes * MP0B_NUM_ELEMENTS
            || out.len() != num_nodes * MP0B_PRODUCT0_ROW_LEN
        {
            return Ok(false);
        }
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            MP0B_NUM_ELEMENTS,
            "mace_scalar_vector_contraction_forward_metal node_attrs",
        )?;
        let type_ids = active_elements
            .into_iter()
            .map(|element| u32::try_from(element).map_err(|_| MaceLiteError::UnsupportedRuntime))
            .collect::<Result<Vec<_>, _>>()?;
        let scalar_u1_entries = scalar.u1_nonzero_entries();
        let scalar_u2_entries = scalar.u2_nonzero_entries();
        let scalar_u3_entries = scalar.u3_nonzero_entries();
        let vector_u1_entries = vector.u1_nonzero_entries_by_equiv();
        let vector_u2_entries = vector.u2_nonzero_entries_by_equiv();
        let vector_u3_entries = vector.u3_nonzero_entries_by_equiv();
        metal::mp0b_product0_contraction_forward_f32(
            &type_ids,
            interaction_out,
            scalar.weights_u1,
            scalar.weights_u2,
            scalar.weights_u3,
            scalar_u1_entries.as_ref(),
            scalar_u2_entries.as_ref(),
            scalar_u3_entries.as_ref(),
            vector.weights_u1,
            vector.weights_u2,
            vector.weights_u3,
            vector_u1_entries.as_ref(),
            vector_u2_entries.as_ref(),
            vector_u3_entries.as_ref(),
            out,
        )
        .map_err(MaceLiteError::Metal)?;
        Ok(true)
    }

    #[cfg(all(feature = "apple-metal", target_os = "macos"))]
    #[allow(clippy::too_many_arguments)]
    fn mace_vector_contraction_forward_metal_f32(
        &self,
        vector: &MaceVectorSymmetricContractionF32<'_>,
        interaction_out: &[f32],
        node_attrs: &[f32],
        output_offset: usize,
        output_stride: usize,
        out: &mut [f32],
    ) -> Result<bool, MaceLiteError> {
        if !metal::mace_metal_enabled()
            || !matches!(
                self.active_runtime_plan_kind(),
                Some(MaceRuntimePlanKind::Oam | MaceRuntimePlanKind::Osaka24)
            )
            || vector.num_features != MP0B_NUM_FEATURES
            || vector.num_ell != MP0B_SH_DIM
        {
            return Ok(false);
        }
        let num_nodes = interaction_out.len() / (vector.num_features * vector.num_ell);
        let component_len = vector.num_features * vector.num_equivariance;
        if num_nodes < MACE_SCALAR_VECTOR_CONTRACTION_FORWARD_METAL_MIN_NODES
            || interaction_out.len() != num_nodes * vector.num_features * vector.num_ell
            || node_attrs.len() != num_nodes * vector.num_elements
            || out.len() != num_nodes * output_stride
            || output_offset + component_len > output_stride
        {
            return Ok(false);
        }
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            vector.num_elements,
            "mace_vector_contraction_forward_metal node_attrs",
        )?;
        let type_ids = active_elements
            .into_iter()
            .map(|element| u32::try_from(element).map_err(|_| MaceLiteError::UnsupportedRuntime))
            .collect::<Result<Vec<_>, _>>()?;
        let u1_entries = vector.u1_nonzero_entries_by_equiv();
        let u2_entries = vector.u2_nonzero_entries_by_equiv();
        let u3_entries = vector.u3_nonzero_entries_by_equiv();
        metal::mace_vector_contraction_forward_f32(
            &type_ids,
            interaction_out,
            vector.weights_u1,
            vector.weights_u2,
            vector.weights_u3,
            u1_entries.as_ref(),
            u2_entries.as_ref(),
            u3_entries.as_ref(),
            vector.num_elements,
            vector.num_features,
            vector.num_equivariance,
            vector.num_ell,
            vector.u1_params,
            vector.u2_params,
            vector.u3_params,
            output_stride,
            output_offset,
            out,
        )
        .map_err(MaceLiteError::Metal)?;
        Ok(true)
    }

    #[cfg(all(feature = "apple-metal", target_os = "macos"))]
    #[allow(clippy::too_many_arguments)]
    fn mace_scalar_contraction_forward_metal_f32(
        &self,
        scalar: &MaceScalarSymmetricContractionF32<'_>,
        interaction_out: &[f32],
        node_attrs: &[f32],
        out: &mut [f32],
        cached_entries: Option<&ScalarContractionEntriesF32>,
    ) -> Result<Option<ScalarContractionCacheF32>, MaceLiteError> {
        if !metal::mace_metal_enabled()
            || !matches!(
                self.active_runtime_plan_kind(),
                Some(
                    MaceRuntimePlanKind::Osaka24
                        | MaceRuntimePlanKind::Osaka26
                        | MaceRuntimePlanKind::Oam
                )
            )
            || scalar.num_features != MP0B_NUM_FEATURES
            || scalar.num_ell != MP0B_SH_DIM
        {
            return Ok(None);
        }
        let num_nodes = interaction_out.len() / (scalar.num_features * scalar.num_ell);
        if num_nodes < MACE_SCALAR_CONTRACTION_FORWARD_METAL_MIN_NODES {
            return Ok(None);
        }
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            scalar.num_elements,
            "mace_scalar_contraction_forward_metal node_attrs",
        )?;
        let type_ids = active_elements
            .iter()
            .map(|&element| u32::try_from(element).map_err(|_| MaceLiteError::UnsupportedRuntime))
            .collect::<Result<Vec<_>, _>>()?;
        let entries = cached_entries
            .cloned()
            .unwrap_or_else(|| scalar.scalar_entries());
        let interaction_out_metal = metal::mace_scalar_contraction_forward_with_input_cache_f32(
            &type_ids,
            interaction_out,
            None,
            scalar.weights_u1,
            scalar.weights_u2,
            scalar.weights_u3,
            scalar.num_elements,
            scalar.num_features,
            scalar.num_ell,
            scalar.u1_params,
            scalar.u2_params,
            scalar.u3_params,
            &entries.u1,
            &entries.u2,
            &entries.u3,
            scalar.num_features,
            0,
            out,
        )
        .map_err(MaceLiteError::Metal)?;
        Ok(Some(ScalarContractionCacheF32 {
            active_elements,
            u1_entries: entries.u1,
            u2_entries: entries.u2,
            u3_entries: entries.u3,
            #[cfg(all(feature = "apple-metal", target_os = "macos"))]
            interaction_out_metal: Some(interaction_out_metal),
            #[cfg(feature = "parallel")]
            element_to_dense: Vec::new(),
            #[cfg(feature = "parallel")]
            weighted_entries: None,
        }))
    }

    #[cfg(all(feature = "apple-metal", target_os = "macos"))]
    #[allow(clippy::too_many_arguments)]
    fn mace_scalar_contraction_vjp_metal_f32(
        &self,
        scalar: &MaceScalarSymmetricContractionF32<'_>,
        interaction_out: &[f32],
        node_attrs: &[f32],
        grad_out: &[f32],
        grad_interaction_out: &mut [f32],
        scalar_cache: Option<&ScalarContractionCacheF32>,
        scalar_vjp_metal_cache: Option<&MaceScalarVjpMetalLayerCache>,
    ) -> Result<bool, MaceLiteError> {
        if !metal::mace_metal_enabled()
            || !matches!(
                self.active_runtime_plan_kind(),
                Some(
                    MaceRuntimePlanKind::Osaka24
                        | MaceRuntimePlanKind::Osaka26
                        | MaceRuntimePlanKind::Oam
                )
            )
            || scalar.num_features != MP0B_NUM_FEATURES
            || scalar.num_ell != MP0B_SH_DIM
        {
            return Ok(false);
        }
        let num_nodes = interaction_out.len() / (scalar.num_features * scalar.num_ell);
        if num_nodes < MACE_SCALAR_CONTRACTION_VJP_METAL_MIN_NODES {
            return Ok(false);
        }
        let mp0b_product0_shape = scalar.num_elements == MP0B_NUM_ELEMENTS
            && scalar.num_features == MP0B_NUM_FEATURES
            && scalar.num_ell == MP0B_SH_DIM
            && scalar.u1_params == 1
            && scalar.u2_params == 4
            && scalar.u3_params == 23;
        let interaction_out_metal =
            scalar_cache.and_then(|cache| cache.interaction_out_metal.as_ref());
        if mp0b_product0_shape {
            if let Some(MaceScalarVjpMetalLayerCache::Mp0bProduct0(cache)) = scalar_vjp_metal_cache
            {
                metal::mp0b_product0_scalar_contraction_vjp_with_input_cache_f32(
                    cache,
                    interaction_out,
                    interaction_out_metal,
                    grad_out,
                    grad_interaction_out,
                )
                .map_err(MaceLiteError::Metal)?;
                return Ok(true);
            }
        } else if let Some(MaceScalarVjpMetalLayerCache::Generic(cache)) = scalar_vjp_metal_cache {
            metal::mace_scalar_contraction_vjp_with_input_cache_f32(
                cache,
                interaction_out,
                interaction_out_metal,
                grad_out,
                grad_interaction_out,
            )
            .map_err(MaceLiteError::Metal)?;
            return Ok(true);
        }
        let active_elements: Cow<'_, [usize]> = if let Some(cache) = scalar_cache {
            Cow::Borrowed(cache.active_elements.as_slice())
        } else {
            Cow::Owned(active_unit_one_hot_elements_f32(
                node_attrs,
                num_nodes,
                scalar.num_elements,
                "mace_scalar_contraction_vjp_metal node_attrs",
            )?)
        };
        let type_ids = active_elements
            .iter()
            .map(|&element| u32::try_from(element).map_err(|_| MaceLiteError::UnsupportedRuntime))
            .collect::<Result<Vec<_>, _>>()?;
        let u1_entries: Cow<'_, [ScalarU1EntryF32]> = if let Some(cache) = scalar_cache {
            Cow::Borrowed(cache.u1_entries.as_slice())
        } else {
            scalar.u1_nonzero_entries()
        };
        let u2_entries: Cow<'_, [ScalarU2EntryF32]> = if let Some(cache) = scalar_cache {
            Cow::Borrowed(cache.u2_entries.as_slice())
        } else {
            scalar.u2_nonzero_entries()
        };
        let u3_entries: Cow<'_, [ScalarU3EntryF32]> = if let Some(cache) = scalar_cache {
            Cow::Borrowed(cache.u3_entries.as_slice())
        } else {
            scalar.u3_nonzero_entries()
        };
        if mp0b_product0_shape {
            metal::mp0b_product0_scalar_contraction_vjp_f32(
                &type_ids,
                interaction_out,
                grad_out,
                scalar.weights_u1,
                scalar.weights_u2,
                scalar.weights_u3,
                u1_entries.as_ref(),
                u2_entries.as_ref(),
                u3_entries.as_ref(),
                grad_interaction_out,
            )
            .map_err(MaceLiteError::Metal)?;
            return Ok(true);
        }
        metal::mace_scalar_contraction_vjp_f32(
            &type_ids,
            interaction_out,
            grad_out,
            scalar.weights_u1,
            scalar.weights_u2,
            scalar.weights_u3,
            scalar.num_elements,
            scalar.num_features,
            scalar.num_ell,
            scalar.u1_params,
            scalar.u2_params,
            scalar.u3_params,
            u1_entries.as_ref(),
            u2_entries.as_ref(),
            u3_entries.as_ref(),
            grad_interaction_out,
        )
        .map_err(MaceLiteError::Metal)?;
        Ok(true)
    }

