fn validate_symmetric_contraction_tensor_shapes(
    num_elements: usize,
    records: SymmetricContractionShapeRecords<'_>,
) -> Result<ScalarContractionShape<'_>, MaceLiteError> {
    if records.u1.shape.len() != 2 {
        return Err(MaceLiteError::StateTensorShape {
            name: records.u1_name.to_owned(),
            actual: records.u1.shape.clone(),
            expected: vec![0, 0],
        });
    }
    let num_ell = records.u1.shape[0];
    let u1_params = records.u1.shape[1];
    if num_ell == 0 || u1_params == 0 {
        return Err(invalid_model(format!(
            "symmetric-contraction tensor {:?} must have nonzero dimensions",
            records.u1_name
        )));
    }
    if records.u2.shape.len() != 3
        || records.u2.shape[0] != num_ell
        || records.u2.shape[1] != num_ell
    {
        return Err(MaceLiteError::StateTensorShape {
            name: records.u2_name.to_owned(),
            actual: records.u2.shape.clone(),
            expected: vec![num_ell, num_ell, 0],
        });
    }
    let u2_params = records.u2.shape[2];
    if u2_params == 0 {
        return Err(invalid_model(format!(
            "symmetric-contraction tensor {:?} must have nonzero parameter dimension",
            records.u2_name
        )));
    }
    let expected_prefix = [num_ell, num_ell, num_ell];
    if records.u3.shape.len() != 4 || records.u3.shape[..3] != expected_prefix {
        return Err(MaceLiteError::StateTensorShape {
            name: records.u3_name.to_owned(),
            actual: records.u3.shape.clone(),
            expected: vec![num_ell, num_ell, num_ell, 0],
        });
    }
    let u3_params = records.u3.shape[3];
    if u3_params == 0 {
        return Err(invalid_model(format!(
            "symmetric-contraction tensor {:?} must have nonzero parameter dimension",
            records.u3_name
        )));
    }
    if records.weights_u2.shape.len() != 3
        || records.weights_u2.shape[0] != num_elements
        || records.weights_u2.shape[1] != u2_params
    {
        return Err(MaceLiteError::StateTensorShape {
            name: records.weights_u2_name.to_owned(),
            actual: records.weights_u2.shape.clone(),
            expected: vec![num_elements, u2_params, 0],
        });
    }
    let num_features = records.weights_u2.shape[2];
    if num_features == 0 {
        return Err(invalid_model(format!(
            "symmetric-contraction tensor {:?} must have nonzero feature dimension",
            records.weights_u2_name
        )));
    }
    if records.weights_u1.shape != [num_elements, u1_params, num_features] {
        return Err(MaceLiteError::StateTensorShape {
            name: records.weights_u1_name.to_owned(),
            actual: records.weights_u1.shape.clone(),
            expected: vec![num_elements, u1_params, num_features],
        });
    }
    if records.weights_u3.shape != [num_elements, u3_params, num_features] {
        return Err(MaceLiteError::StateTensorShape {
            name: records.weights_u3_name.to_owned(),
            actual: records.weights_u3.shape.clone(),
            expected: vec![num_elements, u3_params, num_features],
        });
    }
    Ok(ScalarContractionShape {
        num_features,
        num_ell,
        u1_params,
        u2_params,
        u3_params,
        u1: records.u1,
        u2: records.u2,
        u3: records.u3,
        weights_u2: records.weights_u2,
        weights_u1: records.weights_u1,
        weights_u3: records.weights_u3,
    })
}

