#[derive(Clone, Copy, Debug)]
struct MaceScalarSymmetricContractionF32<'a> {
    num_elements: usize,
    num_features: usize,
    num_ell: usize,
    u1_params: usize,
    u2_params: usize,
    u3_params: usize,
    u1: &'a [f32],
    u2: &'a [f32],
    u3: &'a [f32],
    weights_u2: &'a [f32],
    weights_u1: &'a [f32],
    weights_u3: &'a [f32],
    entries: Option<&'a ScalarContractionEntriesF32>,
}

#[derive(Clone, Copy, Debug)]
struct MaceVectorSymmetricContractionF32<'a> {
    num_elements: usize,
    num_features: usize,
    num_equivariance: usize,
    num_ell: usize,
    u1_params: usize,
    u2_params: usize,
    u3_params: usize,
    u1: &'a [f32],
    u2: &'a [f32],
    u3: &'a [f32],
    weights_u2: &'a [f32],
    weights_u1: &'a [f32],
    weights_u3: &'a [f32],
    entries: Option<&'a VectorContractionEntriesF32>,
}

#[derive(Clone, Copy, Debug)]
struct ScalarU1EntryF32 {
    ell: usize,
    param: usize,
    value: f32,
}

#[derive(Clone, Copy, Debug)]
struct ScalarU2EntryF32 {
    left: usize,
    right: usize,
    param: usize,
    value: f32,
}

#[derive(Clone, Copy, Debug)]
struct ScalarU3EntryF32 {
    left: usize,
    right: usize,
    inner: usize,
    param: usize,
    value: f32,
}

#[derive(Clone, Debug)]
struct ScalarContractionEntriesF32 {
    u1: Vec<ScalarU1EntryF32>,
    u2: Vec<ScalarU2EntryF32>,
    u3: Vec<ScalarU3EntryF32>,
}

impl ScalarContractionEntriesF32 {
    fn from_shape(shape: ScalarContractionShapeF32<'_>) -> Self {
        Self {
            u1: scalar_u1_nonzero_entries_f32(shape.num_ell, shape.u1_params, &shape.u1.values),
            u2: scalar_u2_nonzero_entries_f32(shape.num_ell, shape.u2_params, &shape.u2.values),
            u3: scalar_u3_nonzero_entries_f32(shape.num_ell, shape.u3_params, &shape.u3.values),
        }
    }
}

fn scalar_u1_nonzero_entries_f32(
    num_ell: usize,
    u1_params: usize,
    u1: &[f32],
) -> Vec<ScalarU1EntryF32> {
    let mut entries = Vec::new();
    for ell in 0..num_ell {
        for param in 0..u1_params {
            let value = u1[ell * u1_params + param];
            if value != 0.0 {
                entries.push(ScalarU1EntryF32 { ell, param, value });
            }
        }
    }
    entries
}

fn scalar_u2_nonzero_entries_f32(
    num_ell: usize,
    u2_params: usize,
    u2: &[f32],
) -> Vec<ScalarU2EntryF32> {
    let mut entries = Vec::new();
    for left in 0..num_ell {
        for right in 0..num_ell {
            for param in 0..u2_params {
                let value = u2[((left * num_ell + right) * u2_params) + param];
                if value != 0.0 {
                    entries.push(ScalarU2EntryF32 {
                        left,
                        right,
                        param,
                        value,
                    });
                }
            }
        }
    }
    entries
}

fn scalar_u3_nonzero_entries_f32(
    num_ell: usize,
    u3_params: usize,
    u3: &[f32],
) -> Vec<ScalarU3EntryF32> {
    let mut entries = Vec::new();
    for left in 0..num_ell {
        for right in 0..num_ell {
            for inner in 0..num_ell {
                for param in 0..u3_params {
                    let value =
                        u3[(((left * num_ell + right) * num_ell + inner) * u3_params) + param];
                    if value != 0.0 {
                        let (left, right, inner) = sorted_triple(left, right, inner);
                        entries.push(ScalarU3EntryF32 {
                            left,
                            right,
                            inner,
                            param,
                            value,
                        });
                    }
                }
            }
        }
    }
    combine_scalar_u3_entries_f32(entries)
}

#[derive(Clone, Copy, Debug)]
struct VectorU1EntryF32 {
    ell: usize,
    param: usize,
    value: f32,
}

#[derive(Clone, Copy, Debug)]
struct VectorU2EntryF32 {
    left: usize,
    right: usize,
    param: usize,
    value: f32,
}

#[derive(Clone, Copy, Debug)]
struct VectorU3EntryF32 {
    left: usize,
    right: usize,
    inner: usize,
    param: usize,
    value: f32,
}

#[derive(Clone, Debug)]
struct VectorContractionEntriesF32 {
    u1: Vec<Vec<VectorU1EntryF32>>,
    u2: Vec<Vec<VectorU2EntryF32>>,
    u3: Vec<Vec<VectorU3EntryF32>>,
}

impl VectorContractionEntriesF32 {
    fn from_shape(shape: VectorContractionShapeF32<'_>) -> Self {
        Self {
            u1: vector_u1_nonzero_entries_f32(
                shape.num_equivariance,
                shape.num_ell,
                shape.u1_params,
                &shape.u1.values,
            ),
            u2: vector_u2_nonzero_entries_f32(
                shape.num_equivariance,
                shape.num_ell,
                shape.u2_params,
                &shape.u2.values,
            ),
            u3: vector_u3_nonzero_entries_f32(
                shape.num_equivariance,
                shape.num_ell,
                shape.u3_params,
                &shape.u3.values,
            ),
        }
    }
}

fn vector_u1_nonzero_entries_f32(
    num_equivariance: usize,
    num_ell: usize,
    u1_params: usize,
    u1: &[f32],
) -> Vec<Vec<VectorU1EntryF32>> {
    let mut entries = vec![Vec::new(); num_equivariance];
    for (equiv, equiv_entries) in entries.iter_mut().enumerate() {
        for ell in 0..num_ell {
            for param in 0..u1_params {
                let value = u1[((equiv * num_ell + ell) * u1_params) + param];
                if value != 0.0 {
                    equiv_entries.push(VectorU1EntryF32 { ell, param, value });
                }
            }
        }
    }
    entries
}

fn vector_u2_nonzero_entries_f32(
    num_equivariance: usize,
    num_ell: usize,
    u2_params: usize,
    u2: &[f32],
) -> Vec<Vec<VectorU2EntryF32>> {
    let mut entries = vec![Vec::new(); num_equivariance];
    for (equiv, equiv_entries) in entries.iter_mut().enumerate() {
        for left in 0..num_ell {
            for right in 0..num_ell {
                for param in 0..u2_params {
                    let value =
                        u2[(((equiv * num_ell + left) * num_ell + right) * u2_params) + param];
                    if value != 0.0 {
                        equiv_entries.push(VectorU2EntryF32 {
                            left,
                            right,
                            param,
                            value,
                        });
                    }
                }
            }
        }
    }
    entries
}

fn vector_u3_nonzero_entries_f32(
    num_equivariance: usize,
    num_ell: usize,
    u3_params: usize,
    u3: &[f32],
) -> Vec<Vec<VectorU3EntryF32>> {
    let mut entries = vec![Vec::new(); num_equivariance];
    for (equiv, equiv_entries) in entries.iter_mut().enumerate() {
        for left in 0..num_ell {
            for right in 0..num_ell {
                for inner in 0..num_ell {
                    for param in 0..u3_params {
                        let value = u3[((((equiv * num_ell + left) * num_ell + right) * num_ell
                            + inner)
                            * u3_params)
                            + param];
                        if value != 0.0 {
                            let (left, right, inner) = sorted_triple(left, right, inner);
                            equiv_entries.push(VectorU3EntryF32 {
                                left,
                                right,
                                inner,
                                param,
                                value,
                            });
                        }
                    }
                }
            }
        }
        *equiv_entries = combine_vector_u3_entries_f32(std::mem::take(equiv_entries));
    }
    entries
}

