#[derive(Clone, Debug)]
struct Mp0bResidualSkipCacheF32 {
    groups: Vec<Vec<usize>>,
    active_types: Vec<usize>,
    max_group_len: usize,
    packed_weights: Vec<f32>,
    mask_is_identity: bool,
}

#[cfg(feature = "parallel")]
impl ScalarWeightedEntriesFlatF32 {
    #[inline(always)]
    fn slices(&self, dense_element: usize, feature: usize) -> (&[f32], &[f32], &[f32]) {
        let row = dense_element * self.num_features + feature;
        let u1_base = row * self.u1_len;
        let u2_base = row * self.u2_len;
        let u3_base = row * self.u3_len;
        (
            &self.u1[u1_base..u1_base + self.u1_len],
            &self.u2[u2_base..u2_base + self.u2_len],
            &self.u3[u3_base..u3_base + self.u3_len],
        )
    }
}

#[cfg(feature = "parallel")]
#[derive(Clone, Debug)]
struct VectorWeightedEntriesF32 {
    u1: Vec<Vec<f32>>,
    u2: Vec<Vec<f32>>,
    u3: Vec<Vec<f32>>,
}

impl<'a> MaceScalarSymmetricContractionF32<'a> {
    fn forward(&self, x: &[f32], node_attrs: &[f32], out: &mut [f32]) -> Result<(), MaceLiteError> {
        let num_nodes = self.check_runtime_shapes(
            x,
            node_attrs,
            out.len(),
            "mace_symmetric_contraction_f32_forward out",
        )?;
        out.fill(0.0);
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            self.num_elements,
            "mace_symmetric_contraction_f32 node_attrs",
        )?;
        let u1_entries = self.u1_nonzero_entries();
        let u2_entries = self.u2_nonzero_entries();
        let u3_entries = self.u3_nonzero_entries();
        if self.num_ell == 16 {
            #[cfg(feature = "parallel")]
            if rayon::current_num_threads() > 1 && num_nodes >= 32 {
                #[cfg(target_arch = "aarch64")]
                if mace_f32_neon_enabled() {
                    let node_x_len = self.num_features * self.num_ell;
                    out.par_chunks_mut(self.num_features)
                        .enumerate()
                        .with_min_len(mace_contraction_node_min_len())
                        .for_each(|(node, out_row)| {
                            mace_scalar_contraction_forward_node_neon_f32_safe(
                                self,
                                &x[node * node_x_len..(node + 1) * node_x_len],
                                active_elements[node],
                                out_row,
                                &u1_entries,
                                &u2_entries,
                                &u3_entries,
                            );
                        });
                    return Ok(());
                }
                #[cfg(target_arch = "x86_64")]
                if mace_f32_avx2_fma_enabled() {
                    let node_x_len = self.num_features * self.num_ell;
                    out.par_chunks_mut(self.num_features)
                        .enumerate()
                        .with_min_len(mace_contraction_node_min_len())
                        .for_each(|(node, out_row)| {
                            mace_scalar_contraction_forward_node_avx2_f32_safe(
                                self,
                                &x[node * node_x_len..(node + 1) * node_x_len],
                                active_elements[node],
                                out_row,
                                &u1_entries,
                                &u2_entries,
                                &u3_entries,
                            );
                        });
                    return Ok(());
                }
            }
            #[cfg(target_arch = "aarch64")]
            if mace_f32_neon_enabled() {
                let node_x_len = self.num_features * self.num_ell;
                for (node, out_row) in out.chunks_mut(self.num_features).enumerate() {
                    mace_scalar_contraction_forward_node_neon_f32_safe(
                        self,
                        &x[node * node_x_len..(node + 1) * node_x_len],
                        active_elements[node],
                        out_row,
                        &u1_entries,
                        &u2_entries,
                        &u3_entries,
                    );
                }
                return Ok(());
            }
            #[cfg(target_arch = "x86_64")]
            if mace_f32_avx2_fma_enabled() {
                let node_x_len = self.num_features * self.num_ell;
                for (node, out_row) in out.chunks_mut(self.num_features).enumerate() {
                    mace_scalar_contraction_forward_node_avx2_f32_safe(
                        self,
                        &x[node * node_x_len..(node + 1) * node_x_len],
                        active_elements[node],
                        out_row,
                        &u1_entries,
                        &u2_entries,
                        &u3_entries,
                    );
                }
                return Ok(());
            }
        }
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && num_nodes >= 32 {
            let (active_element_list, element_to_dense) =
                active_element_dense_map(&active_elements, self.num_elements);
            let weighted_entries = self.weighted_entries_by_active_element_feature(
                &active_element_list,
                &u1_entries,
                &u2_entries,
                &u3_entries,
            );
            let nodes_per_chunk = 1;
            out.par_chunks_mut(self.num_features * nodes_per_chunk)
                .enumerate()
                .for_each(|(chunk_index, out_chunk)| {
                    let node_start = chunk_index * nodes_per_chunk;
                    let chunk_nodes = out_chunk.len() / self.num_features;
                    for local_node in 0..chunk_nodes {
                        let node = node_start + local_node;
                        let out_row = &mut out_chunk
                            [local_node * self.num_features..(local_node + 1) * self.num_features];
                        let dense_element = element_to_dense[active_elements[node]];
                        debug_assert_ne!(dense_element, usize::MAX);
                        for (feature, output) in out_row.iter_mut().enumerate() {
                            let (weighted_u1, weighted_u2, weighted_u3) =
                                weighted_entries.slices(dense_element, feature);
                            *output = self.forward_node_feature_with_weighted_entries(
                                x,
                                node,
                                feature,
                                &u1_entries,
                                weighted_u1,
                                &u2_entries,
                                weighted_u2,
                                &u3_entries,
                                weighted_u3,
                            );
                        }
                    }
                });
            return Ok(());
        }

        let active_node_groups = nodes_by_element(&active_elements, self.num_elements);
        let mut w1 = vec![0.0; self.u1_params];
        let mut w2 = vec![0.0; self.u2_params];
        let mut w3 = vec![0.0; self.u3_params];
        let mut weighted_u1 = vec![0.0; u1_entries.len()];
        let mut weighted_u2 = vec![0.0; u2_entries.len()];
        let mut weighted_u3 = vec![0.0; u3_entries.len()];
        for feature in 0..self.num_features {
            for (element, nodes) in active_node_groups.iter().enumerate() {
                if nodes.is_empty() {
                    continue;
                }
                self.feature_weights_for_element_into(element, feature, &mut w1, &mut w2, &mut w3);
                weight_scalar_entries_f32(
                    &w1,
                    &w2,
                    &w3,
                    &u1_entries,
                    &u2_entries,
                    &u3_entries,
                    &mut weighted_u1,
                    &mut weighted_u2,
                    &mut weighted_u3,
                );
                for &node in nodes {
                    out[node * self.num_features + feature] = self
                        .forward_node_feature_with_weighted_entries(
                            x,
                            node,
                            feature,
                            &u1_entries,
                            &weighted_u1,
                            &u2_entries,
                            &weighted_u2,
                            &u3_entries,
                            &weighted_u3,
                        );
                }
            }
        }
        Ok(())
    }

    #[allow(dead_code)]
    fn forward_cached_with_entries(
        &self,
        x: &[f32],
        node_attrs: &[f32],
        out: &mut [f32],
        cached_entries: Option<&ScalarContractionEntriesF32>,
    ) -> Result<ScalarContractionCacheF32, MaceLiteError> {
        let num_nodes = self.check_runtime_shapes(
            x,
            node_attrs,
            out.len(),
            "mace_symmetric_contraction_f32_forward out",
        )?;
        out.fill(0.0);
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            self.num_elements,
            "mace_symmetric_contraction_f32 node_attrs",
        )?;
        let entries = cached_entries
            .cloned()
            .unwrap_or_else(|| self.scalar_entries());
        let u1_entries = entries.u1;
        let u2_entries = entries.u2;
        let u3_entries = entries.u3;
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && num_nodes >= 32 {
            let (active_element_list, element_to_dense) =
                active_element_dense_map(&active_elements, self.num_elements);
            let weighted_entries = self.weighted_entries_by_active_element_feature(
                &active_element_list,
                &u1_entries,
                &u2_entries,
                &u3_entries,
            );
            let nodes_per_chunk = 1;
            out.par_chunks_mut(self.num_features * nodes_per_chunk)
                .enumerate()
                .for_each(|(chunk_index, out_chunk)| {
                    let node_start = chunk_index * nodes_per_chunk;
                    let chunk_nodes = out_chunk.len() / self.num_features;
                    for local_node in 0..chunk_nodes {
                        let node = node_start + local_node;
                        let out_row = &mut out_chunk
                            [local_node * self.num_features..(local_node + 1) * self.num_features];
                        let dense_element = element_to_dense[active_elements[node]];
                        debug_assert_ne!(dense_element, usize::MAX);
                        for (feature, output) in out_row.iter_mut().enumerate() {
                            let (weighted_u1, weighted_u2, weighted_u3) =
                                weighted_entries.slices(dense_element, feature);
                            *output = self.forward_node_feature_with_weighted_entries(
                                x,
                                node,
                                feature,
                                &u1_entries,
                                weighted_u1,
                                &u2_entries,
                                weighted_u2,
                                &u3_entries,
                                weighted_u3,
                            );
                        }
                    }
                });
            return Ok(ScalarContractionCacheF32 {
                active_elements,
                u1_entries,
                u2_entries,
                u3_entries,
                #[cfg(all(feature = "apple-metal", target_os = "macos"))]
                interaction_out_metal: None,
                element_to_dense,
                weighted_entries: Some(weighted_entries),
            });
        }

        let active_node_groups = nodes_by_element(&active_elements, self.num_elements);
        let mut w1 = vec![0.0; self.u1_params];
        let mut w2 = vec![0.0; self.u2_params];
        let mut w3 = vec![0.0; self.u3_params];
        let mut weighted_u1 = vec![0.0; u1_entries.len()];
        let mut weighted_u2 = vec![0.0; u2_entries.len()];
        let mut weighted_u3 = vec![0.0; u3_entries.len()];
        for feature in 0..self.num_features {
            for (element, nodes) in active_node_groups.iter().enumerate() {
                if nodes.is_empty() {
                    continue;
                }
                self.feature_weights_for_element_into(element, feature, &mut w1, &mut w2, &mut w3);
                weight_scalar_entries_f32(
                    &w1,
                    &w2,
                    &w3,
                    &u1_entries,
                    &u2_entries,
                    &u3_entries,
                    &mut weighted_u1,
                    &mut weighted_u2,
                    &mut weighted_u3,
                );
                for &node in nodes {
                    out[node * self.num_features + feature] = self
                        .forward_node_feature_with_weighted_entries(
                            x,
                            node,
                            feature,
                            &u1_entries,
                            &weighted_u1,
                            &u2_entries,
                            &weighted_u2,
                            &u3_entries,
                            &weighted_u3,
                        );
                }
            }
        }
        Ok(ScalarContractionCacheF32 {
            active_elements,
            u1_entries,
            u2_entries,
            u3_entries,
            #[cfg(all(feature = "apple-metal", target_os = "macos"))]
            interaction_out_metal: None,
            #[cfg(feature = "parallel")]
            element_to_dense: Vec::new(),
            #[cfg(feature = "parallel")]
            weighted_entries: None,
        })
    }

    #[allow(dead_code)]
    fn scalar_entries(&self) -> ScalarContractionEntriesF32 {
        ScalarContractionEntriesF32 {
            u1: self.u1_nonzero_entries().into_owned(),
            u2: self.u2_nonzero_entries().into_owned(),
            u3: self.u3_nonzero_entries().into_owned(),
        }
    }

    fn vjp_x(
        &self,
        x: &[f32],
        node_attrs: &[f32],
        grad_out: &[f32],
        grad_x: &mut [f32],
    ) -> Result<(), MaceLiteError> {
        let num_nodes = self.check_runtime_shapes(
            x,
            node_attrs,
            grad_out.len(),
            "mace_symmetric_contraction_f32_vjp_x grad_out",
        )?;
        check_len(
            "mace_symmetric_contraction_f32_vjp_x grad_x",
            x.len(),
            grad_x.len(),
        )?;
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            self.num_elements,
            "mace_symmetric_contraction_f32 node_attrs",
        )?;
        let u1_entries = self.u1_nonzero_entries();
        let u2_entries = self.u2_nonzero_entries();
        let u3_entries = self.u3_nonzero_entries();
        if self.num_ell == 16 {
            #[cfg(feature = "parallel")]
            if rayon::current_num_threads() > 1 && num_nodes >= 32 {
                #[cfg(target_arch = "aarch64")]
                if mace_f32_neon_enabled() {
                    let node_x_len = self.num_features * self.num_ell;
                    grad_x
                        .par_chunks_mut(node_x_len)
                        .enumerate()
                        .with_min_len(mace_contraction_node_min_len())
                        .for_each(|(node, grad_x_node)| {
                            mace_scalar_contraction_vjp_node_neon_f32_safe(
                                self,
                                &x[node * node_x_len..(node + 1) * node_x_len],
                                &grad_out[node * self.num_features..(node + 1) * self.num_features],
                                active_elements[node],
                                grad_x_node,
                                &u1_entries,
                                &u2_entries,
                                &u3_entries,
                            );
                        });
                    return Ok(());
                }
                #[cfg(target_arch = "x86_64")]
                if mace_f32_avx2_fma_enabled() {
                    let node_x_len = self.num_features * self.num_ell;
                    grad_x
                        .par_chunks_mut(node_x_len)
                        .enumerate()
                        .with_min_len(mace_contraction_node_min_len())
                        .for_each(|(node, grad_x_node)| {
                            mace_scalar_contraction_vjp_node_avx2_f32_safe(
                                self,
                                &x[node * node_x_len..(node + 1) * node_x_len],
                                &grad_out[node * self.num_features..(node + 1) * self.num_features],
                                active_elements[node],
                                grad_x_node,
                                &u1_entries,
                                &u2_entries,
                                &u3_entries,
                            );
                        });
                    return Ok(());
                }
            }
            #[cfg(target_arch = "aarch64")]
            if mace_f32_neon_enabled() {
                let node_x_len = self.num_features * self.num_ell;
                for (node, grad_x_node) in grad_x.chunks_mut(node_x_len).enumerate() {
                    mace_scalar_contraction_vjp_node_neon_f32_safe(
                        self,
                        &x[node * node_x_len..(node + 1) * node_x_len],
                        &grad_out[node * self.num_features..(node + 1) * self.num_features],
                        active_elements[node],
                        grad_x_node,
                        &u1_entries,
                        &u2_entries,
                        &u3_entries,
                    );
                }
                return Ok(());
            }
            #[cfg(target_arch = "x86_64")]
            if mace_f32_avx2_fma_enabled() {
                let node_x_len = self.num_features * self.num_ell;
                for (node, grad_x_node) in grad_x.chunks_mut(node_x_len).enumerate() {
                    mace_scalar_contraction_vjp_node_avx2_f32_safe(
                        self,
                        &x[node * node_x_len..(node + 1) * node_x_len],
                        &grad_out[node * self.num_features..(node + 1) * self.num_features],
                        active_elements[node],
                        grad_x_node,
                        &u1_entries,
                        &u2_entries,
                        &u3_entries,
                    );
                }
                return Ok(());
            }
        }
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && num_nodes >= 32 {
            let (active_element_list, element_to_dense) =
                active_element_dense_map(&active_elements, self.num_elements);
            let weighted_entries = self.weighted_entries_by_active_element_feature(
                &active_element_list,
                &u1_entries,
                &u2_entries,
                &u3_entries,
            );
            let node_x_len = self.num_features * self.num_ell;
            let nodes_per_chunk = 1;
            grad_x
                .par_chunks_mut(node_x_len * nodes_per_chunk)
                .enumerate()
                .for_each(|(chunk_index, grad_x_chunk)| {
                    let node_start = chunk_index * nodes_per_chunk;
                    let chunk_nodes = grad_x_chunk.len() / node_x_len;
                    for local_node in 0..chunk_nodes {
                        let node = node_start + local_node;
                        let grad_x_node = &mut grad_x_chunk
                            [local_node * node_x_len..(local_node + 1) * node_x_len];
                        let dense_element = element_to_dense[active_elements[node]];
                        debug_assert_ne!(dense_element, usize::MAX);
                        if self.num_ell == 16 {
                            let mut grad_values = [0.0_f32; 16];
                            for feature in 0..self.num_features {
                                let (weighted_u1, weighted_u2, weighted_u3) =
                                    weighted_entries.slices(dense_element, feature);
                                let x_base = self.x_index(node, feature, 0);
                                accumulate_scalar_contraction_weighted_grad_ell16_f32(
                                    grad_out[node * self.num_features + feature],
                                    &x[x_base..x_base + 16],
                                    &u1_entries,
                                    weighted_u1,
                                    &u2_entries,
                                    weighted_u2,
                                    &u3_entries,
                                    weighted_u3,
                                    &mut grad_values,
                                );
                                let local_base = feature * 16;
                                add_ell16_grad_to_slice_f32(
                                    &mut grad_x_node[local_base..local_base + 16],
                                    &grad_values,
                                );
                            }
                        } else {
                            let mut grad_values = vec![0.0; self.num_ell];
                            for feature in 0..self.num_features {
                                let (weighted_u1, weighted_u2, weighted_u3) =
                                    weighted_entries.slices(dense_element, feature);
                                let x_base = self.x_index(node, feature, 0);
                                let local_base = feature * self.num_ell;
                                accumulate_scalar_contraction_weighted_grad_f32(
                                    grad_out[node * self.num_features + feature],
                                    &x[x_base..x_base + self.num_ell],
                                    &u1_entries,
                                    weighted_u1,
                                    &u2_entries,
                                    weighted_u2,
                                    &u3_entries,
                                    weighted_u3,
                                    &mut grad_values,
                                );
                                for (target, value) in grad_x_node
                                    [local_base..local_base + self.num_ell]
                                    .iter_mut()
                                    .zip(&grad_values)
                                {
                                    *target += *value;
                                }
                            }
                        }
                    }
                });
            return Ok(());
        }

        let active_node_groups = nodes_by_element(&active_elements, self.num_elements);
        let mut w1 = vec![0.0; self.u1_params];
        let mut w2 = vec![0.0; self.u2_params];
        let mut w3 = vec![0.0; self.u3_params];
        let mut weighted_u1 = vec![0.0; u1_entries.len()];
        let mut weighted_u2 = vec![0.0; u2_entries.len()];
        let mut weighted_u3 = vec![0.0; u3_entries.len()];
        if self.num_ell == 16 {
            let mut grad_values = [0.0_f32; 16];
            for feature in 0..self.num_features {
                for (element, nodes) in active_node_groups.iter().enumerate() {
                    if nodes.is_empty() {
                        continue;
                    }
                    self.feature_weights_for_element_into(
                        element, feature, &mut w1, &mut w2, &mut w3,
                    );
                    weight_scalar_entries_f32(
                        &w1,
                        &w2,
                        &w3,
                        &u1_entries,
                        &u2_entries,
                        &u3_entries,
                        &mut weighted_u1,
                        &mut weighted_u2,
                        &mut weighted_u3,
                    );
                    for &node in nodes {
                        let x_base = self.x_index(node, feature, 0);
                        accumulate_scalar_contraction_weighted_grad_ell16_f32(
                            grad_out[node * self.num_features + feature],
                            &x[x_base..x_base + 16],
                            &u1_entries,
                            &weighted_u1,
                            &u2_entries,
                            &weighted_u2,
                            &u3_entries,
                            &weighted_u3,
                            &mut grad_values,
                        );
                        add_ell16_grad_to_slice_f32(&mut grad_x[x_base..x_base + 16], &grad_values);
                    }
                }
            }
            return Ok(());
        }
        let mut grad_values = vec![0.0; self.num_ell];
        for feature in 0..self.num_features {
            for (element, nodes) in active_node_groups.iter().enumerate() {
                if nodes.is_empty() {
                    continue;
                }
                self.feature_weights_for_element_into(element, feature, &mut w1, &mut w2, &mut w3);
                weight_scalar_entries_f32(
                    &w1,
                    &w2,
                    &w3,
                    &u1_entries,
                    &u2_entries,
                    &u3_entries,
                    &mut weighted_u1,
                    &mut weighted_u2,
                    &mut weighted_u3,
                );
                for &node in nodes {
                    let x_base = self.x_index(node, feature, 0);
                    accumulate_scalar_contraction_weighted_grad_f32(
                        grad_out[node * self.num_features + feature],
                        &x[x_base..x_base + self.num_ell],
                        &u1_entries,
                        &weighted_u1,
                        &u2_entries,
                        &weighted_u2,
                        &u3_entries,
                        &weighted_u3,
                        &mut grad_values,
                    );
                    for (target, value) in grad_x[x_base..x_base + self.num_ell]
                        .iter_mut()
                        .zip(&grad_values)
                    {
                        *target += *value;
                    }
                }
            }
        }
        Ok(())
    }

    fn vjp_x_active_elements_fast(
        &self,
        x: &[f32],
        active_elements: &[usize],
        grad_out: &[f32],
        grad_x: &mut [f32],
    ) -> Result<bool, MaceLiteError> {
        let per_node_x = self.num_features * self.num_ell;
        if !x.len().is_multiple_of(per_node_x) {
            return Err(shape_mismatch(
                "mace_symmetric_contraction_f32 x",
                per_node_x,
                x.len(),
            ));
        }
        let num_nodes = x.len() / per_node_x;
        check_len(
            "mace_symmetric_contraction_f32 active_elements",
            num_nodes,
            active_elements.len(),
        )?;
        if active_elements
            .iter()
            .any(|&element| element >= self.num_elements)
        {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        check_len(
            "mace_symmetric_contraction_f32_vjp_x grad_out",
            num_nodes * self.num_features,
            grad_out.len(),
        )?;
        check_len(
            "mace_symmetric_contraction_f32_vjp_x grad_x",
            x.len(),
            grad_x.len(),
        )?;
        if self.num_ell != 16 {
            return Ok(false);
        }
        let u1_entries = self.u1_nonzero_entries();
        let u2_entries = self.u2_nonzero_entries();
        let u3_entries = self.u3_nonzero_entries();
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && num_nodes >= 32 {
            #[cfg(target_arch = "aarch64")]
            if mace_f32_neon_enabled() {
                let node_x_len = self.num_features * self.num_ell;
                grad_x
                    .par_chunks_mut(node_x_len)
                    .enumerate()
                    .with_min_len(mace_contraction_node_min_len())
                    .for_each(|(node, grad_x_node)| {
                        mace_scalar_contraction_vjp_node_neon_f32_safe(
                            self,
                            &x[node * node_x_len..(node + 1) * node_x_len],
                            &grad_out[node * self.num_features..(node + 1) * self.num_features],
                            active_elements[node],
                            grad_x_node,
                            &u1_entries,
                            &u2_entries,
                            &u3_entries,
                        );
                    });
                return Ok(true);
            }
            #[cfg(target_arch = "x86_64")]
            if mace_f32_avx2_fma_enabled() {
                let node_x_len = self.num_features * self.num_ell;
                grad_x
                    .par_chunks_mut(node_x_len)
                    .enumerate()
                    .with_min_len(mace_contraction_node_min_len())
                    .for_each(|(node, grad_x_node)| {
                        mace_scalar_contraction_vjp_node_avx2_f32_safe(
                            self,
                            &x[node * node_x_len..(node + 1) * node_x_len],
                            &grad_out[node * self.num_features..(node + 1) * self.num_features],
                            active_elements[node],
                            grad_x_node,
                            &u1_entries,
                            &u2_entries,
                            &u3_entries,
                        );
                    });
                return Ok(true);
            }
        }
        #[cfg(target_arch = "aarch64")]
        if mace_f32_neon_enabled() {
            let node_x_len = self.num_features * self.num_ell;
            for (node, grad_x_node) in grad_x.chunks_mut(node_x_len).enumerate() {
                mace_scalar_contraction_vjp_node_neon_f32_safe(
                    self,
                    &x[node * node_x_len..(node + 1) * node_x_len],
                    &grad_out[node * self.num_features..(node + 1) * self.num_features],
                    active_elements[node],
                    grad_x_node,
                    &u1_entries,
                    &u2_entries,
                    &u3_entries,
                );
            }
            return Ok(true);
        }
        #[cfg(target_arch = "x86_64")]
        if mace_f32_avx2_fma_enabled() {
            let node_x_len = self.num_features * self.num_ell;
            for (node, grad_x_node) in grad_x.chunks_mut(node_x_len).enumerate() {
                mace_scalar_contraction_vjp_node_avx2_f32_safe(
                    self,
                    &x[node * node_x_len..(node + 1) * node_x_len],
                    &grad_out[node * self.num_features..(node + 1) * self.num_features],
                    active_elements[node],
                    grad_x_node,
                    &u1_entries,
                    &u2_entries,
                    &u3_entries,
                );
            }
            return Ok(true);
        }
        Ok(false)
    }

    #[allow(dead_code)]
    fn vjp_x_cached(
        &self,
        x: &[f32],
        grad_out: &[f32],
        grad_x: &mut [f32],
        cache: &ScalarContractionCacheF32,
    ) -> Result<(), MaceLiteError> {
        let per_node_x = self.num_features * self.num_ell;
        if !x.len().is_multiple_of(per_node_x) {
            return Err(shape_mismatch(
                "mace_symmetric_contraction_f32 x",
                per_node_x,
                x.len(),
            ));
        }
        let num_nodes = x.len() / per_node_x;
        check_len(
            "mace_symmetric_contraction_f32_vjp_x grad_out",
            num_nodes * self.num_features,
            grad_out.len(),
        )?;
        check_len(
            "mace_symmetric_contraction_f32_vjp_x grad_x",
            x.len(),
            grad_x.len(),
        )?;
        check_len(
            "mace_symmetric_contraction_f32 active_elements",
            num_nodes,
            cache.active_elements.len(),
        )?;
        let u1_entries = &cache.u1_entries;
        let u2_entries = &cache.u2_entries;
        let u3_entries = &cache.u3_entries;
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && num_nodes >= 32 {
            if let Some(weighted_entries) = &cache.weighted_entries {
                let node_x_len = self.num_features * self.num_ell;
                let nodes_per_chunk = 1;
                grad_x
                    .par_chunks_mut(node_x_len * nodes_per_chunk)
                    .enumerate()
                    .for_each(|(chunk_index, grad_x_chunk)| {
                        let node_start = chunk_index * nodes_per_chunk;
                        let chunk_nodes = grad_x_chunk.len() / node_x_len;
                        for local_node in 0..chunk_nodes {
                            let node = node_start + local_node;
                            let grad_x_node = &mut grad_x_chunk
                                [local_node * node_x_len..(local_node + 1) * node_x_len];
                            let dense_element = cache.element_to_dense[cache.active_elements[node]];
                            debug_assert_ne!(dense_element, usize::MAX);
                            if self.num_ell == 16 {
                                let mut grad_values = [0.0_f32; 16];
                                for feature in 0..self.num_features {
                                    let (weighted_u1, weighted_u2, weighted_u3) =
                                        weighted_entries.slices(dense_element, feature);
                                    let x_base = self.x_index(node, feature, 0);
                                    accumulate_scalar_contraction_weighted_grad_ell16_f32(
                                        grad_out[node * self.num_features + feature],
                                        &x[x_base..x_base + 16],
                                        u1_entries,
                                        weighted_u1,
                                        u2_entries,
                                        weighted_u2,
                                        u3_entries,
                                        weighted_u3,
                                        &mut grad_values,
                                    );
                                    let local_base = feature * 16;
                                    add_ell16_grad_to_slice_f32(
                                        &mut grad_x_node[local_base..local_base + 16],
                                        &grad_values,
                                    );
                                }
                            } else {
                                let mut grad_values = vec![0.0; self.num_ell];
                                for feature in 0..self.num_features {
                                    let (weighted_u1, weighted_u2, weighted_u3) =
                                        weighted_entries.slices(dense_element, feature);
                                    let x_base = self.x_index(node, feature, 0);
                                    let local_base = feature * self.num_ell;
                                    accumulate_scalar_contraction_weighted_grad_f32(
                                        grad_out[node * self.num_features + feature],
                                        &x[x_base..x_base + self.num_ell],
                                        u1_entries,
                                        weighted_u1,
                                        u2_entries,
                                        weighted_u2,
                                        u3_entries,
                                        weighted_u3,
                                        &mut grad_values,
                                    );
                                    for (target, value) in grad_x_node
                                        [local_base..local_base + self.num_ell]
                                        .iter_mut()
                                        .zip(&grad_values)
                                    {
                                        *target += *value;
                                    }
                                }
                            }
                        }
                    });
                return Ok(());
            }
        }

        let active_node_groups = nodes_by_element(&cache.active_elements, self.num_elements);
        let mut w1 = vec![0.0; self.u1_params];
        let mut w2 = vec![0.0; self.u2_params];
        let mut w3 = vec![0.0; self.u3_params];
        let mut weighted_u1 = vec![0.0; u1_entries.len()];
        let mut weighted_u2 = vec![0.0; u2_entries.len()];
        let mut weighted_u3 = vec![0.0; u3_entries.len()];
        if self.num_ell == 16 {
            let mut grad_values = [0.0_f32; 16];
            for feature in 0..self.num_features {
                for (element, nodes) in active_node_groups.iter().enumerate() {
                    if nodes.is_empty() {
                        continue;
                    }
                    self.feature_weights_for_element_into(
                        element, feature, &mut w1, &mut w2, &mut w3,
                    );
                    weight_scalar_entries_f32(
                        &w1,
                        &w2,
                        &w3,
                        u1_entries,
                        u2_entries,
                        u3_entries,
                        &mut weighted_u1,
                        &mut weighted_u2,
                        &mut weighted_u3,
                    );
                    for &node in nodes {
                        let x_base = self.x_index(node, feature, 0);
                        accumulate_scalar_contraction_weighted_grad_ell16_f32(
                            grad_out[node * self.num_features + feature],
                            &x[x_base..x_base + 16],
                            u1_entries,
                            &weighted_u1,
                            u2_entries,
                            &weighted_u2,
                            u3_entries,
                            &weighted_u3,
                            &mut grad_values,
                        );
                        add_ell16_grad_to_slice_f32(&mut grad_x[x_base..x_base + 16], &grad_values);
                    }
                }
            }
            return Ok(());
        }
        let mut grad_values = vec![0.0; self.num_ell];
        for feature in 0..self.num_features {
            for (element, nodes) in active_node_groups.iter().enumerate() {
                if nodes.is_empty() {
                    continue;
                }
                self.feature_weights_for_element_into(element, feature, &mut w1, &mut w2, &mut w3);
                weight_scalar_entries_f32(
                    &w1,
                    &w2,
                    &w3,
                    u1_entries,
                    u2_entries,
                    u3_entries,
                    &mut weighted_u1,
                    &mut weighted_u2,
                    &mut weighted_u3,
                );
                for &node in nodes {
                    let x_base = self.x_index(node, feature, 0);
                    accumulate_scalar_contraction_weighted_grad_f32(
                        grad_out[node * self.num_features + feature],
                        &x[x_base..x_base + self.num_ell],
                        u1_entries,
                        &weighted_u1,
                        u2_entries,
                        &weighted_u2,
                        u3_entries,
                        &weighted_u3,
                        &mut grad_values,
                    );
                    for (target, value) in grad_x[x_base..x_base + self.num_ell]
                        .iter_mut()
                        .zip(&grad_values)
                    {
                        *target += *value;
                    }
                }
            }
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    #[inline(always)]
    fn forward_node_feature_with_weighted_entries(
        &self,
        x: &[f32],
        node: usize,
        feature: usize,
        u1_entries: &[ScalarU1EntryF32],
        weighted_u1: &[f32],
        u2_entries: &[ScalarU2EntryF32],
        weighted_u2: &[f32],
        u3_entries: &[ScalarU3EntryF32],
        weighted_u3: &[f32],
    ) -> f32 {
        let x_base = self.x_index(node, feature, 0);
        let x_row = &x[x_base..x_base + self.num_ell];
        let mut output = 0.0;
        for (entry, &weighted_value) in u1_entries.iter().zip(weighted_u1) {
            output += weighted_value * x_row[entry.ell];
        }
        for (entry, &weighted_value) in u2_entries.iter().zip(weighted_u2) {
            output += weighted_value * x_row[entry.left] * x_row[entry.right];
        }
        for (entry, &weighted_value) in u3_entries.iter().zip(weighted_u3) {
            output += weighted_value * x_row[entry.left] * x_row[entry.right] * x_row[entry.inner];
        }
        output
    }

    fn u1_nonzero_entries(&self) -> Cow<'_, [ScalarU1EntryF32]> {
        if let Some(entries) = self.entries {
            return Cow::Borrowed(&entries.u1);
        }
        Cow::Owned(scalar_u1_nonzero_entries_f32(
            self.num_ell,
            self.u1_params,
            self.u1,
        ))
    }

    fn u2_nonzero_entries(&self) -> Cow<'_, [ScalarU2EntryF32]> {
        if let Some(entries) = self.entries {
            return Cow::Borrowed(&entries.u2);
        }
        Cow::Owned(scalar_u2_nonzero_entries_f32(
            self.num_ell,
            self.u2_params,
            self.u2,
        ))
    }

    fn u3_nonzero_entries(&self) -> Cow<'_, [ScalarU3EntryF32]> {
        if let Some(entries) = self.entries {
            return Cow::Borrowed(&entries.u3);
        }
        Cow::Owned(scalar_u3_nonzero_entries_f32(
            self.num_ell,
            self.u3_params,
            self.u3,
        ))
    }

    #[cfg(feature = "parallel")]
    fn weighted_entries_by_active_element_feature(
        &self,
        active_element_list: &[usize],
        u1_entries: &[ScalarU1EntryF32],
        u2_entries: &[ScalarU2EntryF32],
        u3_entries: &[ScalarU3EntryF32],
    ) -> ScalarWeightedEntriesFlatF32 {
        let rows = active_element_list.len().saturating_mul(self.num_features);
        let mut entries = ScalarWeightedEntriesFlatF32 {
            u1: Vec::with_capacity(rows.saturating_mul(u1_entries.len())),
            u2: Vec::with_capacity(rows.saturating_mul(u2_entries.len())),
            u3: Vec::with_capacity(rows.saturating_mul(u3_entries.len())),
            u1_len: u1_entries.len(),
            u2_len: u2_entries.len(),
            u3_len: u3_entries.len(),
            num_features: self.num_features,
        };
        let mut w1 = vec![0.0; self.u1_params];
        let mut w2 = vec![0.0; self.u2_params];
        let mut w3 = vec![0.0; self.u3_params];
        let mut weighted_u1 = vec![0.0; u1_entries.len()];
        let mut weighted_u2 = vec![0.0; u2_entries.len()];
        let mut weighted_u3 = vec![0.0; u3_entries.len()];
        for &element in active_element_list {
            for feature in 0..self.num_features {
                self.feature_weights_for_element_into(element, feature, &mut w1, &mut w2, &mut w3);
                weight_scalar_entries_f32(
                    &w1,
                    &w2,
                    &w3,
                    u1_entries,
                    u2_entries,
                    u3_entries,
                    &mut weighted_u1,
                    &mut weighted_u2,
                    &mut weighted_u3,
                );
                entries.u1.extend_from_slice(&weighted_u1);
                entries.u2.extend_from_slice(&weighted_u2);
                entries.u3.extend_from_slice(&weighted_u3);
            }
        }
        entries
    }

    #[inline(always)]
    fn feature_weights_for_element_into(
        &self,
        element: usize,
        feature: usize,
        w1: &mut [f32],
        w2: &mut [f32],
        w3: &mut [f32],
    ) {
        for (param, value) in w1.iter_mut().enumerate() {
            *value = self.weights_u1[self.weight_index(element, param, feature, self.u1_params)];
        }
        for (param, value) in w2.iter_mut().enumerate() {
            *value = self.weights_u2[self.weight_index(element, param, feature, self.u2_params)];
        }
        for (param, value) in w3.iter_mut().enumerate() {
            *value = self.weights_u3[self.weight_index(element, param, feature, self.u3_params)];
        }
    }

    fn check_runtime_shapes(
        &self,
        x: &[f32],
        node_attrs: &[f32],
        out_len: usize,
        out_op: &'static str,
    ) -> Result<usize, MaceLiteError> {
        let per_node_x = self.num_features * self.num_ell;
        if !x.len().is_multiple_of(per_node_x) {
            return Err(shape_mismatch(
                "mace_symmetric_contraction_f32 x",
                per_node_x,
                x.len(),
            ));
        }
        let num_nodes = x.len() / per_node_x;
        check_len(
            "mace_symmetric_contraction_f32 node_attrs",
            num_nodes * self.num_elements,
            node_attrs.len(),
        )?;
        check_len(out_op, num_nodes * self.num_features, out_len)?;
        Ok(num_nodes)
    }

    #[inline(always)]
    fn x_index(&self, node: usize, feature: usize, ell: usize) -> usize {
        (node * self.num_features + feature) * self.num_ell + ell
    }

    #[inline(always)]
    fn weight_index(&self, element: usize, param: usize, feature: usize, params: usize) -> usize {
        (element * params + param) * self.num_features + feature
    }
}

impl<'a> MaceVectorSymmetricContractionF32<'a> {
    fn forward(&self, x: &[f32], node_attrs: &[f32], out: &mut [f32]) -> Result<(), MaceLiteError> {
        let num_nodes = self.check_runtime_shapes(
            x,
            node_attrs,
            out.len(),
            "mace_vector_symmetric_contraction_f32_forward out",
        )?;
        out.fill(0.0);
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            self.num_elements,
            "mace_vector_symmetric_contraction_f32 node_attrs",
        )?;
        let u1_entries = self.u1_nonzero_entries_by_equiv();
        let u2_entries = self.u2_nonzero_entries_by_equiv();
        let u3_entries = self.u3_nonzero_entries_by_equiv();
        if self.num_ell == 16 {
            #[cfg(feature = "parallel")]
            if rayon::current_num_threads() > 1 && num_nodes >= 32 {
                #[cfg(target_arch = "aarch64")]
                if mace_f32_neon_enabled() {
                    let node_x_len = self.num_features * self.num_ell;
                    let out_row_len = self.num_features * self.num_equivariance;
                    out.par_chunks_mut(out_row_len)
                        .enumerate()
                        .with_min_len(mace_contraction_node_min_len())
                        .for_each(|(node, out_row)| {
                            mace_vector_contraction_forward_node_neon_f32_safe(
                                self,
                                &x[node * node_x_len..(node + 1) * node_x_len],
                                active_elements[node],
                                out_row,
                                &u1_entries,
                                &u2_entries,
                                &u3_entries,
                            );
                        });
                    return Ok(());
                }
                #[cfg(target_arch = "x86_64")]
                if mace_f32_avx2_fma_enabled() {
                    let node_x_len = self.num_features * self.num_ell;
                    let out_row_len = self.num_features * self.num_equivariance;
                    out.par_chunks_mut(out_row_len)
                        .enumerate()
                        .with_min_len(mace_contraction_node_min_len())
                        .for_each(|(node, out_row)| {
                            mace_vector_contraction_forward_node_avx2_f32_safe(
                                self,
                                &x[node * node_x_len..(node + 1) * node_x_len],
                                active_elements[node],
                                out_row,
                                &u1_entries,
                                &u2_entries,
                                &u3_entries,
                            );
                        });
                    return Ok(());
                }
            }
            #[cfg(target_arch = "aarch64")]
            if mace_f32_neon_enabled() {
                let node_x_len = self.num_features * self.num_ell;
                let out_row_len = self.num_features * self.num_equivariance;
                for (node, out_row) in out.chunks_mut(out_row_len).enumerate() {
                    mace_vector_contraction_forward_node_neon_f32_safe(
                        self,
                        &x[node * node_x_len..(node + 1) * node_x_len],
                        active_elements[node],
                        out_row,
                        &u1_entries,
                        &u2_entries,
                        &u3_entries,
                    );
                }
                return Ok(());
            }
            #[cfg(target_arch = "x86_64")]
            if mace_f32_avx2_fma_enabled() {
                let node_x_len = self.num_features * self.num_ell;
                let out_row_len = self.num_features * self.num_equivariance;
                for (node, out_row) in out.chunks_mut(out_row_len).enumerate() {
                    mace_vector_contraction_forward_node_avx2_f32_safe(
                        self,
                        &x[node * node_x_len..(node + 1) * node_x_len],
                        active_elements[node],
                        out_row,
                        &u1_entries,
                        &u2_entries,
                        &u3_entries,
                    );
                }
                return Ok(());
            }
        }
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && num_nodes >= 32 {
            let (active_element_list, element_to_dense) =
                active_element_dense_map(&active_elements, self.num_elements);
            let weighted_entries = self.weighted_entries_by_active_element_feature(
                &active_element_list,
                &u1_entries,
                &u2_entries,
                &u3_entries,
            );
            let out_row_len = self.num_features * self.num_equivariance;
            out.par_chunks_mut(out_row_len)
                .enumerate()
                .with_min_len(mace_contraction_node_min_len())
                .for_each(|(node, out_row)| {
                    let dense_element = element_to_dense[active_elements[node]];
                    debug_assert_ne!(dense_element, usize::MAX);
                    for feature in 0..self.num_features {
                        let weighted =
                            &weighted_entries[dense_element * self.num_features + feature];
                        self.forward_node_feature_with_weighted_entries_into_row(
                            x,
                            out_row,
                            node,
                            feature,
                            &u1_entries,
                            &weighted.u1,
                            &u2_entries,
                            &weighted.u2,
                            &u3_entries,
                            &weighted.u3,
                        );
                    }
                });
            return Ok(());
        }

        let active_node_groups = nodes_by_element(&active_elements, self.num_elements);
        let mut w1 = vec![0.0; self.u1_params];
        let mut w2 = vec![0.0; self.u2_params];
        let mut w3 = vec![0.0; self.u3_params];
        let mut weighted_u1 = u1_entries
            .iter()
            .map(|entries| vec![0.0; entries.len()])
            .collect::<Vec<_>>();
        let mut weighted_u2 = u2_entries
            .iter()
            .map(|entries| vec![0.0; entries.len()])
            .collect::<Vec<_>>();
        let mut weighted_u3 = u3_entries
            .iter()
            .map(|entries| vec![0.0; entries.len()])
            .collect::<Vec<_>>();
        for feature in 0..self.num_features {
            for (element, nodes) in active_node_groups.iter().enumerate() {
                if nodes.is_empty() {
                    continue;
                }
                self.feature_weights_for_element_into(element, feature, &mut w1, &mut w2, &mut w3);
                weight_vector_entries_f32(
                    &w1,
                    &w2,
                    &w3,
                    &u1_entries,
                    &u2_entries,
                    &u3_entries,
                    &mut weighted_u1,
                    &mut weighted_u2,
                    &mut weighted_u3,
                );
                for &node in nodes {
                    self.forward_node_feature_with_weighted_entries(
                        x,
                        out,
                        node,
                        feature,
                        &u1_entries,
                        &weighted_u1,
                        &u2_entries,
                        &weighted_u2,
                        &u3_entries,
                        &weighted_u3,
                    );
                }
            }
        }
        Ok(())
    }

    fn vjp_x(
        &self,
        x: &[f32],
        node_attrs: &[f32],
        grad_out: &[f32],
        grad_x: &mut [f32],
    ) -> Result<(), MaceLiteError> {
        let num_nodes = self.check_runtime_shapes(
            x,
            node_attrs,
            grad_out.len(),
            "mace_vector_symmetric_contraction_f32_vjp_x grad_out",
        )?;
        check_len(
            "mace_vector_symmetric_contraction_f32_vjp_x grad_x",
            x.len(),
            grad_x.len(),
        )?;
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            self.num_elements,
            "mace_vector_symmetric_contraction_f32 node_attrs",
        )?;
        let u1_entries = self.u1_nonzero_entries_by_equiv();
        let u2_entries = self.u2_nonzero_entries_by_equiv();
        let u3_entries = self.u3_nonzero_entries_by_equiv();
        if self.num_ell == 16 {
            #[cfg(feature = "parallel")]
            if rayon::current_num_threads() > 1 && num_nodes >= 32 {
                #[cfg(target_arch = "aarch64")]
                if mace_f32_neon_enabled() {
                    let node_x_len = self.num_features * self.num_ell;
                    let out_row_len = self.num_features * self.num_equivariance;
                    grad_x
                        .par_chunks_mut(node_x_len)
                        .enumerate()
                        .with_min_len(mace_contraction_node_min_len())
                        .for_each(|(node, grad_x_node)| {
                            mace_vector_contraction_vjp_node_neon_f32_safe(
                                self,
                                &x[node * node_x_len..(node + 1) * node_x_len],
                                &grad_out[node * out_row_len..(node + 1) * out_row_len],
                                active_elements[node],
                                grad_x_node,
                                &u1_entries,
                                &u2_entries,
                                &u3_entries,
                            );
                        });
                    return Ok(());
                }
                #[cfg(target_arch = "x86_64")]
                if mace_f32_avx2_fma_enabled() {
                    let node_x_len = self.num_features * self.num_ell;
                    let out_row_len = self.num_features * self.num_equivariance;
                    grad_x
                        .par_chunks_mut(node_x_len)
                        .enumerate()
                        .with_min_len(mace_contraction_node_min_len())
                        .for_each(|(node, grad_x_node)| {
                            mace_vector_contraction_vjp_node_avx2_f32_safe(
                                self,
                                &x[node * node_x_len..(node + 1) * node_x_len],
                                &grad_out[node * out_row_len..(node + 1) * out_row_len],
                                active_elements[node],
                                grad_x_node,
                                &u1_entries,
                                &u2_entries,
                                &u3_entries,
                            );
                        });
                    return Ok(());
                }
            }
            #[cfg(target_arch = "aarch64")]
            if mace_f32_neon_enabled() {
                let node_x_len = self.num_features * self.num_ell;
                let out_row_len = self.num_features * self.num_equivariance;
                for (node, grad_x_node) in grad_x.chunks_mut(node_x_len).enumerate() {
                    mace_vector_contraction_vjp_node_neon_f32_safe(
                        self,
                        &x[node * node_x_len..(node + 1) * node_x_len],
                        &grad_out[node * out_row_len..(node + 1) * out_row_len],
                        active_elements[node],
                        grad_x_node,
                        &u1_entries,
                        &u2_entries,
                        &u3_entries,
                    );
                }
                return Ok(());
            }
            #[cfg(target_arch = "x86_64")]
            if mace_f32_avx2_fma_enabled() {
                let node_x_len = self.num_features * self.num_ell;
                let out_row_len = self.num_features * self.num_equivariance;
                for (node, grad_x_node) in grad_x.chunks_mut(node_x_len).enumerate() {
                    mace_vector_contraction_vjp_node_avx2_f32_safe(
                        self,
                        &x[node * node_x_len..(node + 1) * node_x_len],
                        &grad_out[node * out_row_len..(node + 1) * out_row_len],
                        active_elements[node],
                        grad_x_node,
                        &u1_entries,
                        &u2_entries,
                        &u3_entries,
                    );
                }
                return Ok(());
            }
        }
        #[cfg(feature = "parallel")]
        if rayon::current_num_threads() > 1 && num_nodes >= 32 {
            let (active_element_list, element_to_dense) =
                active_element_dense_map(&active_elements, self.num_elements);
            let weighted_entries = self.weighted_entries_by_active_element_feature(
                &active_element_list,
                &u1_entries,
                &u2_entries,
                &u3_entries,
            );
            let node_x_len = self.num_features * self.num_ell;
            grad_x
                .par_chunks_mut(node_x_len)
                .enumerate()
                .with_min_len(mace_contraction_node_min_len())
                .for_each(|(node, grad_x_node)| {
                    let dense_element = element_to_dense[active_elements[node]];
                    debug_assert_ne!(dense_element, usize::MAX);
                    if self.num_ell == 16 {
                        let mut grad_values = [0.0_f32; 16];
                        for feature in 0..self.num_features {
                            let weighted =
                                &weighted_entries[dense_element * self.num_features + feature];
                            let x_base = self.x_index(node, feature, 0);
                            let out_base = self.out_index(node, feature, 0);
                            accumulate_vector_contraction_weighted_grad_ell16_f32(
                                &grad_out[out_base..out_base + self.num_equivariance],
                                &x[x_base..x_base + 16],
                                &u1_entries,
                                &weighted.u1,
                                &u2_entries,
                                &weighted.u2,
                                &u3_entries,
                                &weighted.u3,
                                &mut grad_values,
                            );
                            let local_base = feature * 16;
                            add_ell16_grad_to_slice_f32(
                                &mut grad_x_node[local_base..local_base + 16],
                                &grad_values,
                            );
                        }
                    } else {
                        let mut grad_values = vec![0.0; self.num_ell];
                        for feature in 0..self.num_features {
                            let weighted =
                                &weighted_entries[dense_element * self.num_features + feature];
                            let x_base = self.x_index(node, feature, 0);
                            let out_base = self.out_index(node, feature, 0);
                            accumulate_vector_contraction_weighted_grad_f32(
                                &grad_out[out_base..out_base + self.num_equivariance],
                                &x[x_base..x_base + self.num_ell],
                                &u1_entries,
                                &weighted.u1,
                                &u2_entries,
                                &weighted.u2,
                                &u3_entries,
                                &weighted.u3,
                                &mut grad_values,
                            );
                            let local_base = feature * self.num_ell;
                            for (target, value) in grad_x_node
                                [local_base..local_base + self.num_ell]
                                .iter_mut()
                                .zip(&grad_values)
                            {
                                *target += *value;
                            }
                        }
                    }
                });
            return Ok(());
        }

        let active_node_groups = nodes_by_element(&active_elements, self.num_elements);
        let mut w1 = vec![0.0; self.u1_params];
        let mut w2 = vec![0.0; self.u2_params];
        let mut w3 = vec![0.0; self.u3_params];
        let mut weighted_u1 = u1_entries
            .iter()
            .map(|entries| vec![0.0; entries.len()])
            .collect::<Vec<_>>();
        let mut weighted_u2 = u2_entries
            .iter()
            .map(|entries| vec![0.0; entries.len()])
            .collect::<Vec<_>>();
        let mut weighted_u3 = u3_entries
            .iter()
            .map(|entries| vec![0.0; entries.len()])
            .collect::<Vec<_>>();
        if self.num_ell == 16 {
            let mut grad_values = [0.0_f32; 16];
            for feature in 0..self.num_features {
                for (element, nodes) in active_node_groups.iter().enumerate() {
                    if nodes.is_empty() {
                        continue;
                    }
                    self.feature_weights_for_element_into(
                        element, feature, &mut w1, &mut w2, &mut w3,
                    );
                    weight_vector_entries_f32(
                        &w1,
                        &w2,
                        &w3,
                        &u1_entries,
                        &u2_entries,
                        &u3_entries,
                        &mut weighted_u1,
                        &mut weighted_u2,
                        &mut weighted_u3,
                    );
                    for &node in nodes {
                        let x_base = self.x_index(node, feature, 0);
                        let out_base = self.out_index(node, feature, 0);
                        accumulate_vector_contraction_weighted_grad_ell16_f32(
                            &grad_out[out_base..out_base + self.num_equivariance],
                            &x[x_base..x_base + 16],
                            &u1_entries,
                            &weighted_u1,
                            &u2_entries,
                            &weighted_u2,
                            &u3_entries,
                            &weighted_u3,
                            &mut grad_values,
                        );
                        add_ell16_grad_to_slice_f32(&mut grad_x[x_base..x_base + 16], &grad_values);
                    }
                }
            }
            return Ok(());
        }
        let mut grad_values = vec![0.0; self.num_ell];
        for feature in 0..self.num_features {
            for (element, nodes) in active_node_groups.iter().enumerate() {
                if nodes.is_empty() {
                    continue;
                }
                self.feature_weights_for_element_into(element, feature, &mut w1, &mut w2, &mut w3);
                weight_vector_entries_f32(
                    &w1,
                    &w2,
                    &w3,
                    &u1_entries,
                    &u2_entries,
                    &u3_entries,
                    &mut weighted_u1,
                    &mut weighted_u2,
                    &mut weighted_u3,
                );
                for &node in nodes {
                    let x_base = self.x_index(node, feature, 0);
                    let out_base = self.out_index(node, feature, 0);
                    accumulate_vector_contraction_weighted_grad_f32(
                        &grad_out[out_base..out_base + self.num_equivariance],
                        &x[x_base..x_base + self.num_ell],
                        &u1_entries,
                        &weighted_u1,
                        &u2_entries,
                        &weighted_u2,
                        &u3_entries,
                        &weighted_u3,
                        &mut grad_values,
                    );
                    for (target, value) in grad_x[x_base..x_base + self.num_ell]
                        .iter_mut()
                        .zip(&grad_values)
                    {
                        *target += *value;
                    }
                }
            }
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    #[inline(always)]
    fn forward_node_feature_with_weighted_entries(
        &self,
        x: &[f32],
        out: &mut [f32],
        node: usize,
        feature: usize,
        u1_entries: &[Vec<VectorU1EntryF32>],
        weighted_u1: &[Vec<f32>],
        u2_entries: &[Vec<VectorU2EntryF32>],
        weighted_u2: &[Vec<f32>],
        u3_entries: &[Vec<VectorU3EntryF32>],
        weighted_u3: &[Vec<f32>],
    ) {
        let output_row_len = self.num_features * self.num_equivariance;
        let out_row = &mut out[node * output_row_len..(node + 1) * output_row_len];
        self.forward_node_feature_with_weighted_entries_into_row(
            x,
            out_row,
            node,
            feature,
            u1_entries,
            weighted_u1,
            u2_entries,
            weighted_u2,
            u3_entries,
            weighted_u3,
        );
    }

    #[allow(clippy::too_many_arguments)]
    #[inline(always)]
    fn forward_node_feature_with_weighted_entries_into_row(
        &self,
        x: &[f32],
        out_row: &mut [f32],
        node: usize,
        feature: usize,
        u1_entries: &[Vec<VectorU1EntryF32>],
        weighted_u1: &[Vec<f32>],
        u2_entries: &[Vec<VectorU2EntryF32>],
        weighted_u2: &[Vec<f32>],
        u3_entries: &[Vec<VectorU3EntryF32>],
        weighted_u3: &[Vec<f32>],
    ) {
        let x_base = self.x_index(node, feature, 0);
        let x_row = &x[x_base..x_base + self.num_ell];
        for equiv in 0..self.num_equivariance {
            let mut output = 0.0;
            for (entry, &weighted_value) in u1_entries[equiv].iter().zip(&weighted_u1[equiv]) {
                output += weighted_value * x_row[entry.ell];
            }
            for (entry, &weighted_value) in u2_entries[equiv].iter().zip(&weighted_u2[equiv]) {
                output += weighted_value * x_row[entry.left] * x_row[entry.right];
            }
            for (entry, &weighted_value) in u3_entries[equiv].iter().zip(&weighted_u3[equiv]) {
                output +=
                    weighted_value * x_row[entry.left] * x_row[entry.right] * x_row[entry.inner];
            }
            out_row[feature * self.num_equivariance + equiv] = output;
        }
    }

    fn u1_nonzero_entries_by_equiv(&self) -> Cow<'_, [Vec<VectorU1EntryF32>]> {
        if let Some(entries) = self.entries {
            return Cow::Borrowed(&entries.u1);
        }
        Cow::Owned(vector_u1_nonzero_entries_f32(
            self.num_equivariance,
            self.num_ell,
            self.u1_params,
            self.u1,
        ))
    }

    fn u2_nonzero_entries_by_equiv(&self) -> Cow<'_, [Vec<VectorU2EntryF32>]> {
        if let Some(entries) = self.entries {
            return Cow::Borrowed(&entries.u2);
        }
        Cow::Owned(vector_u2_nonzero_entries_f32(
            self.num_equivariance,
            self.num_ell,
            self.u2_params,
            self.u2,
        ))
    }

    fn u3_nonzero_entries_by_equiv(&self) -> Cow<'_, [Vec<VectorU3EntryF32>]> {
        if let Some(entries) = self.entries {
            return Cow::Borrowed(&entries.u3);
        }
        Cow::Owned(vector_u3_nonzero_entries_f32(
            self.num_equivariance,
            self.num_ell,
            self.u3_params,
            self.u3,
        ))
    }

    #[cfg(feature = "parallel")]
    fn weighted_entries_by_active_element_feature(
        &self,
        active_element_list: &[usize],
        u1_entries: &[Vec<VectorU1EntryF32>],
        u2_entries: &[Vec<VectorU2EntryF32>],
        u3_entries: &[Vec<VectorU3EntryF32>],
    ) -> Vec<VectorWeightedEntriesF32> {
        let mut entries =
            Vec::with_capacity(active_element_list.len().saturating_mul(self.num_features));
        let mut w1 = vec![0.0; self.u1_params];
        let mut w2 = vec![0.0; self.u2_params];
        let mut w3 = vec![0.0; self.u3_params];
        let mut weighted_u1 = u1_entries
            .iter()
            .map(|entries| vec![0.0; entries.len()])
            .collect::<Vec<_>>();
        let mut weighted_u2 = u2_entries
            .iter()
            .map(|entries| vec![0.0; entries.len()])
            .collect::<Vec<_>>();
        let mut weighted_u3 = u3_entries
            .iter()
            .map(|entries| vec![0.0; entries.len()])
            .collect::<Vec<_>>();
        for &element in active_element_list {
            for feature in 0..self.num_features {
                self.feature_weights_for_element_into(element, feature, &mut w1, &mut w2, &mut w3);
                weight_vector_entries_f32(
                    &w1,
                    &w2,
                    &w3,
                    u1_entries,
                    u2_entries,
                    u3_entries,
                    &mut weighted_u1,
                    &mut weighted_u2,
                    &mut weighted_u3,
                );
                entries.push(VectorWeightedEntriesF32 {
                    u1: weighted_u1.clone(),
                    u2: weighted_u2.clone(),
                    u3: weighted_u3.clone(),
                });
            }
        }
        entries
    }

    #[inline(always)]
    fn feature_weights_for_element_into(
        &self,
        element: usize,
        feature: usize,
        w1: &mut [f32],
        w2: &mut [f32],
        w3: &mut [f32],
    ) {
        for (param, value) in w1.iter_mut().enumerate() {
            *value = self.weights_u1[self.weight_index(element, param, feature, self.u1_params)];
        }
        for (param, value) in w2.iter_mut().enumerate() {
            *value = self.weights_u2[self.weight_index(element, param, feature, self.u2_params)];
        }
        for (param, value) in w3.iter_mut().enumerate() {
            *value = self.weights_u3[self.weight_index(element, param, feature, self.u3_params)];
        }
    }

    fn check_runtime_shapes(
        &self,
        x: &[f32],
        node_attrs: &[f32],
        out_len: usize,
        out_op: &'static str,
    ) -> Result<usize, MaceLiteError> {
        let per_node_x = self.num_features * self.num_ell;
        if !x.len().is_multiple_of(per_node_x) {
            return Err(shape_mismatch(
                "mace_vector_symmetric_contraction_f32 x",
                per_node_x,
                x.len(),
            ));
        }
        let num_nodes = x.len() / per_node_x;
        check_len(
            "mace_vector_symmetric_contraction_f32 node_attrs",
            num_nodes * self.num_elements,
            node_attrs.len(),
        )?;
        check_len(
            out_op,
            num_nodes * self.num_features * self.num_equivariance,
            out_len,
        )?;
        Ok(num_nodes)
    }

    #[inline(always)]
    fn x_index(&self, node: usize, feature: usize, ell: usize) -> usize {
        (node * self.num_features + feature) * self.num_ell + ell
    }

    #[inline(always)]
    fn out_index(&self, node: usize, feature: usize, equiv: usize) -> usize {
        (node * self.num_features + feature) * self.num_equivariance + equiv
    }

    #[inline(always)]
    fn weight_index(&self, element: usize, param: usize, feature: usize, params: usize) -> usize {
        (element * params + param) * self.num_features + feature
    }
}

fn mp0b_product0_contraction_forward_cpu_f32(
    scalar: &MaceScalarSymmetricContractionF32<'_>,
    vector: &MaceVectorSymmetricContractionF32<'_>,
    x: &[f32],
    node_attrs: &[f32],
    cached_active_elements: Option<&[usize]>,
    out: &mut [f32],
) -> Result<(), MaceLiteError> {
    let per_node_x = MP0B_NUM_FEATURES * MP0B_SH_DIM;
    if !x.len().is_multiple_of(per_node_x) {
        return Err(shape_mismatch(
            "mace_mp0b_product0_contraction_f32 x",
            per_node_x,
            x.len(),
        ));
    }
    let num_nodes = x.len() / per_node_x;
    check_len(
        "mace_mp0b_product0_contraction_f32 node_attrs",
        num_nodes * MP0B_NUM_ELEMENTS,
        node_attrs.len(),
    )?;
    check_len(
        "mace_mp0b_product0_contraction_f32 out",
        num_nodes * MP0B_PRODUCT0_ROW_LEN,
        out.len(),
    )?;
    if scalar.num_elements != MP0B_NUM_ELEMENTS
        || scalar.num_features != MP0B_NUM_FEATURES
        || scalar.num_ell != MP0B_SH_DIM
        || vector.num_elements != MP0B_NUM_ELEMENTS
        || vector.num_features != MP0B_NUM_FEATURES
        || vector.num_equivariance != 3
        || vector.num_ell != MP0B_SH_DIM
    {
        let mut scalar_symmetric = vec![0.0_f32; num_nodes * scalar.num_features];
        let vector_len = vector.num_features * vector.num_equivariance;
        let mut vector_symmetric = vec![0.0_f32; num_nodes * vector_len];
        scalar.forward(x, node_attrs, &mut scalar_symmetric)?;
        vector.forward(x, node_attrs, &mut vector_symmetric)?;
        for node in 0..num_nodes {
            let product_base = node * MP0B_PRODUCT0_ROW_LEN;
            let scalar_base = node * scalar.num_features;
            let vector_base = node * vector_len;
            out[product_base..product_base + scalar.num_features]
                .copy_from_slice(&scalar_symmetric[scalar_base..scalar_base + scalar.num_features]);
            out[product_base + scalar.num_features
                ..product_base + scalar.num_features + vector_len]
                .copy_from_slice(&vector_symmetric[vector_base..vector_base + vector_len]);
        }
        return Ok(());
    }

    let active_elements = if let Some(active_elements) = cached_active_elements {
        check_len(
            "mace_mp0b_product0_contraction_f32 active_elements",
            num_nodes,
            active_elements.len(),
        )?;
        if active_elements
            .iter()
            .any(|&element| element >= MP0B_NUM_ELEMENTS)
        {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        Cow::Borrowed(active_elements)
    } else {
        Cow::Owned(active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            MP0B_NUM_ELEMENTS,
            "mace_mp0b_product0_contraction_f32 node_attrs",
        )?)
    };
    let scalar_u1_entries = scalar.u1_nonzero_entries();
    let scalar_u2_entries = scalar.u2_nonzero_entries();
    let scalar_u3_entries = scalar.u3_nonzero_entries();
    let vector_u1_entries = vector.u1_nonzero_entries_by_equiv();
    let vector_u2_entries = vector.u2_nonzero_entries_by_equiv();
    let vector_u3_entries = vector.u3_nonzero_entries_by_equiv();

    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && num_nodes >= 32 {
        #[cfg(target_arch = "aarch64")]
        if mace_f32_neon_enabled() {
            out.par_chunks_mut(MP0B_PRODUCT0_ROW_LEN)
                .enumerate()
                .with_min_len(mace_contraction_node_min_len())
                .for_each(|(node, out_row)| {
                    let x_node = &x[node * per_node_x..(node + 1) * per_node_x];
                    let element = active_elements[node];
                    mace_scalar_contraction_forward_node_neon_f32_safe(
                        scalar,
                        x_node,
                        element,
                        &mut out_row[..MP0B_NUM_FEATURES],
                        &scalar_u1_entries,
                        &scalar_u2_entries,
                        &scalar_u3_entries,
                    );
                    mace_vector_contraction_forward_node_neon_f32_safe(
                        vector,
                        x_node,
                        element,
                        &mut out_row[MP0B_NUM_FEATURES..],
                        &vector_u1_entries,
                        &vector_u2_entries,
                        &vector_u3_entries,
                    );
                });
            return Ok(());
        }
        #[cfg(target_arch = "x86_64")]
        if mace_f32_avx2_fma_enabled() {
            out.par_chunks_mut(MP0B_PRODUCT0_ROW_LEN)
                .enumerate()
                .with_min_len(mace_contraction_node_min_len())
                .for_each(|(node, out_row)| {
                    let x_node = &x[node * per_node_x..(node + 1) * per_node_x];
                    let element = active_elements[node];
                    mace_scalar_contraction_forward_node_avx2_f32_safe(
                        scalar,
                        x_node,
                        element,
                        &mut out_row[..MP0B_NUM_FEATURES],
                        &scalar_u1_entries,
                        &scalar_u2_entries,
                        &scalar_u3_entries,
                    );
                    mace_vector_contraction_forward_node_avx2_f32_safe(
                        vector,
                        x_node,
                        element,
                        &mut out_row[MP0B_NUM_FEATURES..],
                        &vector_u1_entries,
                        &vector_u2_entries,
                        &vector_u3_entries,
                    );
                });
            return Ok(());
        }
    }

    #[cfg(target_arch = "aarch64")]
    if mace_f32_neon_enabled() {
        for (node, out_row) in out.chunks_mut(MP0B_PRODUCT0_ROW_LEN).enumerate() {
            let x_node = &x[node * per_node_x..(node + 1) * per_node_x];
            let element = active_elements[node];
            mace_scalar_contraction_forward_node_neon_f32_safe(
                scalar,
                x_node,
                element,
                &mut out_row[..MP0B_NUM_FEATURES],
                &scalar_u1_entries,
                &scalar_u2_entries,
                &scalar_u3_entries,
            );
            mace_vector_contraction_forward_node_neon_f32_safe(
                vector,
                x_node,
                element,
                &mut out_row[MP0B_NUM_FEATURES..],
                &vector_u1_entries,
                &vector_u2_entries,
                &vector_u3_entries,
            );
        }
        return Ok(());
    }
    #[cfg(target_arch = "x86_64")]
    if mace_f32_avx2_fma_enabled() {
        for (node, out_row) in out.chunks_mut(MP0B_PRODUCT0_ROW_LEN).enumerate() {
            let x_node = &x[node * per_node_x..(node + 1) * per_node_x];
            let element = active_elements[node];
            mace_scalar_contraction_forward_node_avx2_f32_safe(
                scalar,
                x_node,
                element,
                &mut out_row[..MP0B_NUM_FEATURES],
                &scalar_u1_entries,
                &scalar_u2_entries,
                &scalar_u3_entries,
            );
            mace_vector_contraction_forward_node_avx2_f32_safe(
                vector,
                x_node,
                element,
                &mut out_row[MP0B_NUM_FEATURES..],
                &vector_u1_entries,
                &vector_u2_entries,
                &vector_u3_entries,
            );
        }
        return Ok(());
    }

    let mut scalar_symmetric = vec![0.0_f32; num_nodes * MP0B_NUM_FEATURES];
    let vector_len = MP0B_NUM_FEATURES * 3;
    let mut vector_symmetric = vec![0.0_f32; num_nodes * vector_len];
    scalar.forward(x, node_attrs, &mut scalar_symmetric)?;
    vector.forward(x, node_attrs, &mut vector_symmetric)?;
    for node in 0..num_nodes {
        let product_base = node * MP0B_PRODUCT0_ROW_LEN;
        let scalar_base = node * MP0B_NUM_FEATURES;
        let vector_base = node * vector_len;
        out[product_base..product_base + MP0B_NUM_FEATURES]
            .copy_from_slice(&scalar_symmetric[scalar_base..scalar_base + MP0B_NUM_FEATURES]);
        out[product_base + MP0B_NUM_FEATURES..product_base + MP0B_NUM_FEATURES + vector_len]
            .copy_from_slice(&vector_symmetric[vector_base..vector_base + vector_len]);
    }
    Ok(())
}

