#[cfg(target_arch = "aarch64")]
#[allow(clippy::too_many_arguments, unsafe_code)]
unsafe fn mace_scalar_contraction_vjp_node_neon_f32(
    contraction: &MaceScalarSymmetricContractionF32<'_>,
    x_node: &[f32],
    grad_out_row: &[f32],
    element: usize,
    grad_x_node: &mut [f32],
    u1_entries: &[ScalarU1EntryF32],
    u2_entries: &[ScalarU2EntryF32],
    u3_entries: &[ScalarU3EntryF32],
) {
    use std::arch::aarch64::*;

    #[inline(always)]
    unsafe fn load4_feature(ptr: *const f32) -> float32x4_t {
        let mut out = vdupq_n_f32(0.0);
        out = vsetq_lane_f32(*ptr, out, 0);
        out = vsetq_lane_f32(*ptr.add(16), out, 1);
        out = vsetq_lane_f32(*ptr.add(32), out, 2);
        vsetq_lane_f32(*ptr.add(48), out, 3)
    }

    #[inline(always)]
    unsafe fn add_store4_feature(ptr: *mut f32, value: float32x4_t) {
        *ptr += vgetq_lane_f32(value, 0);
        *ptr.add(16) += vgetq_lane_f32(value, 1);
        *ptr.add(32) += vgetq_lane_f32(value, 2);
        *ptr.add(48) += vgetq_lane_f32(value, 3);
    }

    let num_features = contraction.num_features;
    let u1_element_base = element * contraction.u1_params;
    let u2_element_base = element * contraction.u2_params;
    let u3_element_base = element * contraction.u3_params;
    let mut feature = 0;
    while feature + 4 <= num_features {
        let bar = vld1q_f32(grad_out_row.as_ptr().add(feature));
        let mut x_by_ell = [vdupq_n_f32(0.0); 16];
        for (ell, value) in x_by_ell.iter_mut().enumerate() {
            *value = load4_feature(x_node.as_ptr().add(feature * 16 + ell));
        }
        let mut grad = [vdupq_n_f32(0.0); 16];
        for entry in u1_entries {
            let weight = vld1q_f32(
                contraction
                    .weights_u1
                    .as_ptr()
                    .add((u1_element_base + entry.param) * num_features + feature),
            );
            let derivative = vmulq_f32(vmulq_f32(bar, weight), vdupq_n_f32(entry.value));
            grad[entry.ell] = vaddq_f32(grad[entry.ell], derivative);
        }
        for entry in u2_entries {
            let weight = vld1q_f32(
                contraction
                    .weights_u2
                    .as_ptr()
                    .add((u2_element_base + entry.param) * num_features + feature),
            );
            let derivative = vmulq_f32(vmulq_f32(bar, weight), vdupq_n_f32(entry.value));
            let left = x_by_ell[entry.left];
            let right = x_by_ell[entry.right];
            grad[entry.left] = vfmaq_f32(grad[entry.left], derivative, right);
            grad[entry.right] = vfmaq_f32(grad[entry.right], derivative, left);
        }
        for entry in u3_entries {
            let weight = vld1q_f32(
                contraction
                    .weights_u3
                    .as_ptr()
                    .add((u3_element_base + entry.param) * num_features + feature),
            );
            let derivative = vmulq_f32(vmulq_f32(bar, weight), vdupq_n_f32(entry.value));
            let left = x_by_ell[entry.left];
            let right = x_by_ell[entry.right];
            let inner = x_by_ell[entry.inner];
            if entry.left == entry.right {
                if entry.right == entry.inner {
                    grad[entry.left] = vfmaq_f32(
                        grad[entry.left],
                        vmulq_f32(vdupq_n_f32(3.0), derivative),
                        vmulq_f32(left, left),
                    );
                } else {
                    grad[entry.left] = vfmaq_f32(
                        grad[entry.left],
                        vmulq_f32(vdupq_n_f32(2.0), derivative),
                        vmulq_f32(left, inner),
                    );
                    grad[entry.inner] =
                        vfmaq_f32(grad[entry.inner], derivative, vmulq_f32(left, left));
                }
            } else if entry.right == entry.inner {
                grad[entry.left] = vfmaq_f32(grad[entry.left], derivative, vmulq_f32(right, right));
                grad[entry.right] = vfmaq_f32(
                    grad[entry.right],
                    vmulq_f32(vdupq_n_f32(2.0), derivative),
                    vmulq_f32(left, right),
                );
            } else {
                grad[entry.left] = vfmaq_f32(grad[entry.left], derivative, vmulq_f32(right, inner));
                grad[entry.right] =
                    vfmaq_f32(grad[entry.right], derivative, vmulq_f32(left, inner));
                grad[entry.inner] =
                    vfmaq_f32(grad[entry.inner], derivative, vmulq_f32(left, right));
            }
        }
        for (ell, value) in grad.iter().enumerate() {
            add_store4_feature(grad_x_node.as_mut_ptr().add(feature * 16 + ell), *value);
        }
        feature += 4;
    }
    while feature < num_features {
        mace_scalar_contraction_vjp_feature_scalar_f32(
            contraction,
            x_node,
            grad_out_row[feature],
            element,
            feature,
            grad_x_node,
            u1_entries,
            u2_entries,
            u3_entries,
        );
        feature += 1;
    }
}

