#[cfg(target_arch = "aarch64")]
#[allow(clippy::too_many_arguments, unsafe_code)]
unsafe fn mace_vector_contraction_forward_node_neon_f32(
    contraction: &MaceVectorSymmetricContractionF32<'_>,
    x_node: &[f32],
    element: usize,
    out_row: &mut [f32],
    u1_entries: &[Vec<VectorU1EntryF32>],
    u2_entries: &[Vec<VectorU2EntryF32>],
    u3_entries: &[Vec<VectorU3EntryF32>],
) {
    use std::arch::aarch64::*;

    #[inline(always)]
    unsafe fn load4_feature(ptr: *const f32) -> float32x4_t {
        let mut out = vdupq_n_f32(0.0);
        out = vsetq_lane_f32(*ptr, out, 0);
        out = vsetq_lane_f32(*ptr.add(16), out, 1);
        out = vsetq_lane_f32(*ptr.add(32), out, 2);
        vsetq_lane_f32(*ptr.add(48), out, 3)
    }

    #[inline(always)]
    unsafe fn store4_strided(ptr: *mut f32, stride: usize, value: float32x4_t) {
        *ptr = vgetq_lane_f32(value, 0);
        *ptr.add(stride) = vgetq_lane_f32(value, 1);
        *ptr.add(2 * stride) = vgetq_lane_f32(value, 2);
        *ptr.add(3 * stride) = vgetq_lane_f32(value, 3);
    }

    let num_features = contraction.num_features;
    let num_equiv = contraction.num_equivariance;
    let mut feature = 0;
    while feature + 4 <= num_features {
        let mut x_by_ell = [vdupq_n_f32(0.0); 16];
        for (ell, value) in x_by_ell.iter_mut().enumerate() {
            *value = load4_feature(x_node.as_ptr().add(feature * 16 + ell));
        }
        for equiv in 0..num_equiv {
            let mut acc = vdupq_n_f32(0.0);
            for entry in &u1_entries[equiv] {
                let weight = vld1q_f32(contraction.weights_u1.as_ptr().add(
                    contraction.weight_index(element, entry.param, feature, contraction.u1_params),
                ));
                let x = x_by_ell[entry.ell];
                acc = vfmaq_f32(acc, vmulq_f32(weight, vdupq_n_f32(entry.value)), x);
            }
            for entry in &u2_entries[equiv] {
                let weight = vld1q_f32(contraction.weights_u2.as_ptr().add(
                    contraction.weight_index(element, entry.param, feature, contraction.u2_params),
                ));
                let left = x_by_ell[entry.left];
                let right = x_by_ell[entry.right];
                acc = vfmaq_f32(
                    acc,
                    vmulq_f32(weight, vdupq_n_f32(entry.value)),
                    vmulq_f32(left, right),
                );
            }
            for entry in &u3_entries[equiv] {
                let weight = vld1q_f32(contraction.weights_u3.as_ptr().add(
                    contraction.weight_index(element, entry.param, feature, contraction.u3_params),
                ));
                let left = x_by_ell[entry.left];
                let right = x_by_ell[entry.right];
                let inner = x_by_ell[entry.inner];
                acc = vfmaq_f32(
                    acc,
                    vmulq_f32(weight, vdupq_n_f32(entry.value)),
                    vmulq_f32(vmulq_f32(left, right), inner),
                );
            }
            store4_strided(
                out_row.as_mut_ptr().add(feature * num_equiv + equiv),
                num_equiv,
                acc,
            );
        }
        feature += 4;
    }
    while feature < num_features {
        for equiv in 0..num_equiv {
            out_row[feature * num_equiv + equiv] =
                mace_vector_contraction_forward_feature_scalar_f32(
                    contraction,
                    x_node,
                    element,
                    feature,
                    equiv,
                    u1_entries,
                    u2_entries,
                    u3_entries,
                );
        }
        feature += 1;
    }
}

