#[cfg(target_arch = "x86_64")]
#[target_feature(enable = "avx2")]
#[target_feature(enable = "fma")]
#[allow(clippy::too_many_arguments, unsafe_code)]
unsafe fn mace_scalar_contraction_vjp_node_avx2_f32(
    contraction: &MaceScalarSymmetricContractionF32<'_>,
    x_node: &[f32],
    grad_out_row: &[f32],
    element: usize,
    grad_x_node: &mut [f32],
    u1_entries: &[ScalarU1EntryF32],
    u2_entries: &[ScalarU2EntryF32],
    u3_entries: &[ScalarU3EntryF32],
) {
    use std::arch::x86_64::*;

    #[inline(always)]
    unsafe fn load8_feature(ptr: *const f32) -> __m256 {
        _mm256_set_ps(
            *ptr.add(112),
            *ptr.add(96),
            *ptr.add(80),
            *ptr.add(64),
            *ptr.add(48),
            *ptr.add(32),
            *ptr.add(16),
            *ptr,
        )
    }

    #[inline(always)]
    unsafe fn add_store8_feature(ptr: *mut f32, value: __m256) {
        let mut lanes = [0.0_f32; 8];
        _mm256_storeu_ps(lanes.as_mut_ptr(), value);
        for (lane, value) in lanes.iter().enumerate() {
            *ptr.add(lane * 16) += *value;
        }
    }

    let num_features = contraction.num_features;
    let mut feature = 0;
    while feature + 8 <= num_features {
        let bar = _mm256_loadu_ps(grad_out_row.as_ptr().add(feature));
        let mut x_by_ell = [_mm256_setzero_ps(); 16];
        for (ell, value) in x_by_ell.iter_mut().enumerate() {
            *value = load8_feature(x_node.as_ptr().add(feature * 16 + ell));
        }
        let mut grad = [_mm256_setzero_ps(); 16];
        for entry in u1_entries {
            let weight = _mm256_loadu_ps(contraction.weights_u1.as_ptr().add(
                contraction.weight_index(element, entry.param, feature, contraction.u1_params),
            ));
            let derivative = _mm256_mul_ps(_mm256_mul_ps(bar, weight), _mm256_set1_ps(entry.value));
            grad[entry.ell] = _mm256_add_ps(grad[entry.ell], derivative);
        }
        for entry in u2_entries {
            let weight = _mm256_loadu_ps(contraction.weights_u2.as_ptr().add(
                contraction.weight_index(element, entry.param, feature, contraction.u2_params),
            ));
            let derivative = _mm256_mul_ps(_mm256_mul_ps(bar, weight), _mm256_set1_ps(entry.value));
            let left = x_by_ell[entry.left];
            let right = x_by_ell[entry.right];
            grad[entry.left] = _mm256_fmadd_ps(derivative, right, grad[entry.left]);
            grad[entry.right] = _mm256_fmadd_ps(derivative, left, grad[entry.right]);
        }
        for entry in u3_entries {
            let weight = _mm256_loadu_ps(contraction.weights_u3.as_ptr().add(
                contraction.weight_index(element, entry.param, feature, contraction.u3_params),
            ));
            let derivative = _mm256_mul_ps(_mm256_mul_ps(bar, weight), _mm256_set1_ps(entry.value));
            let left = x_by_ell[entry.left];
            let right = x_by_ell[entry.right];
            let inner = x_by_ell[entry.inner];
            if entry.left == entry.right {
                if entry.right == entry.inner {
                    grad[entry.left] = _mm256_fmadd_ps(
                        _mm256_mul_ps(_mm256_set1_ps(3.0), derivative),
                        _mm256_mul_ps(left, left),
                        grad[entry.left],
                    );
                } else {
                    grad[entry.left] = _mm256_fmadd_ps(
                        _mm256_mul_ps(_mm256_set1_ps(2.0), derivative),
                        _mm256_mul_ps(left, inner),
                        grad[entry.left],
                    );
                    grad[entry.inner] =
                        _mm256_fmadd_ps(derivative, _mm256_mul_ps(left, left), grad[entry.inner]);
                }
            } else if entry.right == entry.inner {
                grad[entry.left] =
                    _mm256_fmadd_ps(derivative, _mm256_mul_ps(right, right), grad[entry.left]);
                grad[entry.right] = _mm256_fmadd_ps(
                    _mm256_mul_ps(_mm256_set1_ps(2.0), derivative),
                    _mm256_mul_ps(left, right),
                    grad[entry.right],
                );
            } else {
                grad[entry.left] =
                    _mm256_fmadd_ps(derivative, _mm256_mul_ps(right, inner), grad[entry.left]);
                grad[entry.right] =
                    _mm256_fmadd_ps(derivative, _mm256_mul_ps(left, inner), grad[entry.right]);
                grad[entry.inner] =
                    _mm256_fmadd_ps(derivative, _mm256_mul_ps(left, right), grad[entry.inner]);
            }
        }
        for (ell, value) in grad.iter().enumerate() {
            add_store8_feature(grad_x_node.as_mut_ptr().add(feature * 16 + ell), *value);
        }
        feature += 8;
    }
    while feature < num_features {
        mace_scalar_contraction_vjp_feature_scalar_f32(
            contraction,
            x_node,
            grad_out_row[feature],
            element,
            feature,
            grad_x_node,
            u1_entries,
            u2_entries,
            u3_entries,
        );
        feature += 1;
    }
}

