#[allow(clippy::too_many_arguments)]
fn mace_scalar_contraction_forward_feature_scalar_f32(
    contraction: &MaceScalarSymmetricContractionF32<'_>,
    x_node: &[f32],
    element: usize,
    feature: usize,
    u1_entries: &[ScalarU1EntryF32],
    u2_entries: &[ScalarU2EntryF32],
    u3_entries: &[ScalarU3EntryF32],
) -> f32 {
    let x_row = &x_node[feature * 16..feature * 16 + 16];
    let mut output = 0.0_f32;
    for entry in u1_entries {
        let weight = contraction.weights_u1
            [contraction.weight_index(element, entry.param, feature, contraction.u1_params)];
        output += entry.value * weight * x_row[entry.ell];
    }
    for entry in u2_entries {
        let weight = contraction.weights_u2
            [contraction.weight_index(element, entry.param, feature, contraction.u2_params)];
        output += entry.value * weight * x_row[entry.left] * x_row[entry.right];
    }
    for entry in u3_entries {
        let weight = contraction.weights_u3
            [contraction.weight_index(element, entry.param, feature, contraction.u3_params)];
        output +=
            entry.value * weight * x_row[entry.left] * x_row[entry.right] * x_row[entry.inner];
    }
    output
}

#[allow(clippy::too_many_arguments)]
fn mace_scalar_contraction_vjp_feature_scalar_f32(
    contraction: &MaceScalarSymmetricContractionF32<'_>,
    x_node: &[f32],
    bar_output: f32,
    element: usize,
    feature: usize,
    grad_x_node: &mut [f32],
    u1_entries: &[ScalarU1EntryF32],
    u2_entries: &[ScalarU2EntryF32],
    u3_entries: &[ScalarU3EntryF32],
) {
    if bar_output == 0.0 {
        return;
    }
    let x_row = &x_node[feature * 16..feature * 16 + 16];
    let grad_row = &mut grad_x_node[feature * 16..feature * 16 + 16];
    for entry in u1_entries {
        let weight = contraction.weights_u1
            [contraction.weight_index(element, entry.param, feature, contraction.u1_params)];
        grad_row[entry.ell] += bar_output * entry.value * weight;
    }
    for entry in u2_entries {
        let derivative = bar_output
            * entry.value
            * contraction.weights_u2
                [contraction.weight_index(element, entry.param, feature, contraction.u2_params)];
        grad_row[entry.left] += derivative * x_row[entry.right];
        grad_row[entry.right] += derivative * x_row[entry.left];
    }
    for entry in u3_entries {
        let derivative = bar_output
            * entry.value
            * contraction.weights_u3
                [contraction.weight_index(element, entry.param, feature, contraction.u3_params)];
        let x_left = x_row[entry.left];
        let x_right = x_row[entry.right];
        let x_inner = x_row[entry.inner];
        if entry.left == entry.right {
            if entry.right == entry.inner {
                grad_row[entry.left] += 3.0 * derivative * x_left * x_left;
            } else {
                grad_row[entry.left] += 2.0 * derivative * x_left * x_inner;
                grad_row[entry.inner] += derivative * x_left * x_left;
            }
        } else if entry.right == entry.inner {
            grad_row[entry.left] += derivative * x_right * x_right;
            grad_row[entry.right] += 2.0 * derivative * x_left * x_right;
        } else {
            grad_row[entry.left] += derivative * x_right * x_inner;
            grad_row[entry.right] += derivative * x_left * x_inner;
            grad_row[entry.inner] += derivative * x_left * x_right;
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn mace_vector_contraction_forward_feature_scalar_f32(
    contraction: &MaceVectorSymmetricContractionF32<'_>,
    x_node: &[f32],
    element: usize,
    feature: usize,
    equiv: usize,
    u1_entries: &[Vec<VectorU1EntryF32>],
    u2_entries: &[Vec<VectorU2EntryF32>],
    u3_entries: &[Vec<VectorU3EntryF32>],
) -> f32 {
    let x_row = &x_node[feature * 16..feature * 16 + 16];
    let mut output = 0.0_f32;
    for entry in &u1_entries[equiv] {
        let weight = contraction.weights_u1
            [contraction.weight_index(element, entry.param, feature, contraction.u1_params)];
        output += entry.value * weight * x_row[entry.ell];
    }
    for entry in &u2_entries[equiv] {
        let weight = contraction.weights_u2
            [contraction.weight_index(element, entry.param, feature, contraction.u2_params)];
        output += entry.value * weight * x_row[entry.left] * x_row[entry.right];
    }
    for entry in &u3_entries[equiv] {
        let weight = contraction.weights_u3
            [contraction.weight_index(element, entry.param, feature, contraction.u3_params)];
        output +=
            entry.value * weight * x_row[entry.left] * x_row[entry.right] * x_row[entry.inner];
    }
    output
}

#[allow(clippy::too_many_arguments)]
fn mace_vector_contraction_vjp_feature_scalar_f32(
    contraction: &MaceVectorSymmetricContractionF32<'_>,
    x_node: &[f32],
    grad_out_row: &[f32],
    element: usize,
    feature: usize,
    grad_x_node: &mut [f32],
    u1_entries: &[Vec<VectorU1EntryF32>],
    u2_entries: &[Vec<VectorU2EntryF32>],
    u3_entries: &[Vec<VectorU3EntryF32>],
) {
    let x_row = &x_node[feature * 16..feature * 16 + 16];
    let grad_row = &mut grad_x_node[feature * 16..feature * 16 + 16];
    for equiv in 0..contraction.num_equivariance {
        let bar_output = grad_out_row[feature * contraction.num_equivariance + equiv];
        if bar_output == 0.0 {
            continue;
        }
        for entry in &u1_entries[equiv] {
            let weight = contraction.weights_u1
                [contraction.weight_index(element, entry.param, feature, contraction.u1_params)];
            grad_row[entry.ell] += bar_output * entry.value * weight;
        }
        for entry in &u2_entries[equiv] {
            let derivative = bar_output
                * entry.value
                * contraction.weights_u2[contraction.weight_index(
                    element,
                    entry.param,
                    feature,
                    contraction.u2_params,
                )];
            grad_row[entry.left] += derivative * x_row[entry.right];
            grad_row[entry.right] += derivative * x_row[entry.left];
        }
        for entry in &u3_entries[equiv] {
            let derivative = bar_output
                * entry.value
                * contraction.weights_u3[contraction.weight_index(
                    element,
                    entry.param,
                    feature,
                    contraction.u3_params,
                )];
            let x_left = x_row[entry.left];
            let x_right = x_row[entry.right];
            let x_inner = x_row[entry.inner];
            if entry.left == entry.right {
                if entry.right == entry.inner {
                    grad_row[entry.left] += 3.0 * derivative * x_left * x_left;
                } else {
                    grad_row[entry.left] += 2.0 * derivative * x_left * x_inner;
                    grad_row[entry.inner] += derivative * x_left * x_left;
                }
            } else if entry.right == entry.inner {
                grad_row[entry.left] += derivative * x_right * x_right;
                grad_row[entry.right] += 2.0 * derivative * x_left * x_right;
            } else {
                grad_row[entry.left] += derivative * x_right * x_inner;
                grad_row[entry.right] += derivative * x_left * x_inner;
                grad_row[entry.inner] += derivative * x_left * x_right;
            }
        }
    }
}

fn is_density_interaction(interaction: &str) -> bool {
    interaction == "RealAgnosticDensityInteractionBlock"
        || interaction == "RealAgnosticDensityResidualInteractionBlock"
}

fn is_residual_interaction(interaction: &str) -> bool {
    interaction == "RealAgnosticResidualInteractionBlock"
        || interaction == "RealAgnosticDensityResidualInteractionBlock"
}

fn is_message_selector_interaction(interaction: &str) -> bool {
    interaction == "RealAgnosticInteractionBlock"
        || interaction == "RealAgnosticDensityInteractionBlock"
}

fn copy_component_rows_to_product(
    component: &[f64],
    component_row_len: usize,
    row_offset: usize,
    output_row_len: usize,
    out: &mut [f64],
) -> Result<(), MaceLiteError> {
    if component_row_len == 0
        || row_offset + component_row_len > output_row_len
        || !component.len().is_multiple_of(component_row_len)
        || out.len() != component.len() / component_row_len * output_row_len
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    for (component_row, out_row) in component
        .chunks(component_row_len)
        .zip(out.chunks_mut(output_row_len))
    {
        out_row[row_offset..row_offset + component_row_len].copy_from_slice(component_row);
    }
    Ok(())
}

