impl Mp0bPreparedCache {
    fn matches_f64(
        &self,
        num_nodes: usize,
        num_edges: usize,
        sh_dim: usize,
        bessel: usize,
    ) -> bool {
        self.pair_node_energy.len() == num_nodes
            && self.active_elements.len() == num_nodes
            && self.edge_attrs_f64.len() == num_edges * sh_dim
            && self.edge_feats_f64.len() == num_edges * bessel
            && self.radial_cache.bessel_basis.len() == num_edges * bessel
            && self.radial_cache.radial_distance.len() == num_edges
            && self.radial_cache.radial_distance_derivative.len() == num_edges
    }

    fn matches_f32(
        &self,
        num_nodes: usize,
        num_edges: usize,
        sh_dim: usize,
        bessel: usize,
    ) -> bool {
        self.pair_node_energy.len() == num_nodes
            && self.active_elements.len() == num_nodes
            && self.edge_attrs_f32.len() == num_edges * sh_dim
            && self.edge_feats_f32.len() == num_edges * bessel
            && self.radial_cache.bessel_basis.len() == num_edges * bessel
            && self.radial_cache.radial_distance.len() == num_edges
            && self.radial_cache.radial_distance_derivative.len() == num_edges
    }
}

