type MaceLiteOutputTensors = (Vec<Vec3>, Option<Mat3>, Option<Mat3>);

impl MaceLiteVjp {
    fn into_output_tensors(
        self,
        structure: &Structure,
        options: &PredictionOptions,
        cutoff: f64,
        symmetrize_virial: bool,
    ) -> Result<MaceLiteOutputTensors, MaceLiteError> {
        let stress_displacement_gradient = symmetric_part(self.displacement_gradient);
        let stress = if options.compute_stress {
            let cell = mace_reference_stress_cell(structure, cutoff)?;
            Some(stress_from_displacement_gradient(
                stress_displacement_gradient,
                &cell,
            )?)
        } else {
            None
        };
        let virial = if options.compute_virial {
            let displacement_gradient = if symmetrize_virial {
                stress_displacement_gradient
            } else {
                self.displacement_gradient
            };
            Some(virial_from_displacement_gradient(displacement_gradient))
        } else {
            None
        };
        Ok((self.forces, stress, virial))
    }
}

#[must_use]
fn symmetric_part(matrix: Mat3) -> Mat3 {
    let mut out = matrix;
    for row in 0..3 {
        for col in 0..row {
            let value = 0.5 * (matrix[row][col] + matrix[col][row]);
            out[row][col] = value;
            out[col][row] = value;
        }
    }
    out
}

