struct MaceProvenanceSpec {
    source_family: String,
    selected_model: String,
    artifact: MaceArtifactProvenanceSpec,
    reference: MaceReferenceProvenanceSpec,
    state_dict_format: String,
    upstream_state_tensor_count: usize,
    runtime_state_tensor_count: usize,
    archival_only_state_tensor_count: usize,
    upstream_state_dict_inventory: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct MaceArtifactProvenanceSpec {
    filename: String,
    url: String,
    sha256: String,
    size_bytes: usize,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct MaceReferenceProvenanceSpec {
    name: String,
    repository: String,
    commit: String,
    package_version: String,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct RadialSpec {
    #[serde(rename = "type")]
    kind: String,
    num_bessel: usize,
    polynomial_cutoff_p: usize,
    r_max: f64,
    #[serde(default)]
    distance_transform: Option<String>,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct PairRepulsionSpec {
    #[serde(rename = "type")]
    kind: String,
    polynomial_cutoff_p: usize,
}

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct LayerSpec {
    interaction: String,
    avg_num_neighbors_norm: f64,
    product: ProductSpec,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct ProductSpec {
    correlation: usize,
    symmetric_contraction: SymmetricContractionSpec,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct SymmetricContractionSpec {
    irreps_in: String,
    irreps_out: String,
    num_elements: usize,
    irrep_normalization: String,
    path_normalization: String,
    use_reduced_cg: bool,
    #[serde(default)]
    u_tensors: Vec<String>,
    #[serde(default)]
    weight_tensors: Vec<String>,
    #[serde(default)]
    contractions: Vec<SymmetricContractionComponentSpec>,
}

#[derive(Clone, Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct SymmetricContractionComponentSpec {
    kind: String,
    #[serde(default)]
    num_equivariance: Option<usize>,
    u_tensors: Vec<String>,
    weight_tensors: Vec<String>,
}

#[allow(dead_code)]
#[derive(Clone, Copy, Debug)]
struct ContractionComponentView<'a> {
    u_tensors: &'a [String],
    weight_tensors: &'a [String],
    num_equivariance: Option<usize>,
}

impl SymmetricContractionSpec {
    fn scalar_component(
        &self,
        layer: usize,
    ) -> Result<ContractionComponentView<'_>, MaceLiteError> {
        if self.contractions.is_empty() {
            return Ok(ContractionComponentView {
                u_tensors: &self.u_tensors,
                weight_tensors: &self.weight_tensors,
                num_equivariance: None,
            });
        }
        self.contractions
            .iter()
            .find(|component| component.kind == "scalar")
            .map(|component| ContractionComponentView {
                u_tensors: &component.u_tensors,
                weight_tensors: &component.weight_tensors,
                num_equivariance: component.num_equivariance,
            })
            .ok_or_else(|| {
                invalid_model(format!(
                    "layer {layer} symmetric_contraction has no scalar contraction"
                ))
            })
    }

    fn vector_component(
        &self,
        layer: usize,
    ) -> Result<ContractionComponentView<'_>, MaceLiteError> {
        self.contractions
            .iter()
            .find(|component| component.kind == "vector")
            .map(|component| ContractionComponentView {
                u_tensors: &component.u_tensors,
                weight_tensors: &component.weight_tensors,
                num_equivariance: component.num_equivariance,
            })
            .ok_or_else(|| {
                invalid_model(format!(
                    "layer {layer} symmetric_contraction has no vector contraction"
                ))
            })
    }
}

fn contraction_component_view(
    component: &SymmetricContractionComponentSpec,
) -> ContractionComponentView<'_> {
    ContractionComponentView {
        u_tensors: &component.u_tensors,
        weight_tensors: &component.weight_tensors,
        num_equivariance: component.num_equivariance,
    }
}

fn contraction_entry_cache_key(component: ContractionComponentView<'_>) -> String {
    component.u_tensors.join("\u{1f}")
}

