#[inline(always)]
fn accumulate_vector_contraction_weighted_grad_f32(
    grad_out_row: &[f32],
    x_row: &[f32],
    u1_entries: &[Vec<VectorU1EntryF32>],
    weighted_u1: &[Vec<f32>],
    u2_entries: &[Vec<VectorU2EntryF32>],
    weighted_u2: &[Vec<f32>],
    u3_entries: &[Vec<VectorU3EntryF32>],
    weighted_u3: &[Vec<f32>],
    grad_values: &mut [f32],
) {
    grad_values.fill(0.0);
    for (equiv, &bar_output) in grad_out_row.iter().enumerate() {
        if bar_output == 0.0 {
            continue;
        }
        for (entry, &weighted_value) in u1_entries[equiv].iter().zip(&weighted_u1[equiv]) {
            debug_assert!(entry.ell < 16);
            // SAFETY: this helper is only called from the validated
            // num_ell == 16 vector contraction path. Entries are constructed
            // by iterating that 16-wide U tensor.
            unsafe {
                *grad_values.get_unchecked_mut(entry.ell) += bar_output * weighted_value;
            }
        }
        for (entry, &weighted_value) in u2_entries[equiv].iter().zip(&weighted_u2[equiv]) {
            let derivative = bar_output * weighted_value;
            debug_assert!(entry.left < 16 && entry.right < 16);
            // SAFETY: see the U-entry invariant documented above.
            unsafe {
                let x_left = *x_row.get_unchecked(entry.left);
                let x_right = *x_row.get_unchecked(entry.right);
                *grad_values.get_unchecked_mut(entry.left) += derivative * x_right;
                *grad_values.get_unchecked_mut(entry.right) += derivative * x_left;
            }
        }
        for (entry, &weighted_value) in u3_entries[equiv].iter().zip(&weighted_u3[equiv]) {
            let derivative = bar_output * weighted_value;
            debug_assert!(entry.left < 16 && entry.right < 16 && entry.inner < 16);
            // SAFETY: see the U-entry invariant documented above.
            unsafe {
                let x_left = *x_row.get_unchecked(entry.left);
                let x_right = *x_row.get_unchecked(entry.right);
                let x_inner = *x_row.get_unchecked(entry.inner);
                if entry.left == entry.right {
                    if entry.right == entry.inner {
                        *grad_values.get_unchecked_mut(entry.left) +=
                            3.0 * derivative * x_left * x_left;
                    } else {
                        *grad_values.get_unchecked_mut(entry.left) +=
                            2.0 * derivative * x_left * x_inner;
                        *grad_values.get_unchecked_mut(entry.inner) += derivative * x_left * x_left;
                    }
                } else if entry.right == entry.inner {
                    *grad_values.get_unchecked_mut(entry.left) += derivative * x_right * x_right;
                    *grad_values.get_unchecked_mut(entry.right) +=
                        2.0 * derivative * x_left * x_right;
                } else {
                    *grad_values.get_unchecked_mut(entry.left) += derivative * x_right * x_inner;
                    *grad_values.get_unchecked_mut(entry.right) += derivative * x_left * x_inner;
                    *grad_values.get_unchecked_mut(entry.inner) += derivative * x_left * x_right;
                }
            }
        }
    }
}

