#[inline(always)]
fn add_ell16_grad_to_slice_f32(target: &mut [f32], values: &[f32; 16]) {
    debug_assert_eq!(target.len(), 16);
    for (target, &value) in target.iter_mut().zip(values) {
        *target += value;
    }
}

#[derive(Clone, Copy)]
struct Mp0bMaskedLinearSpec {
    input_row_len: usize,
    in_features: usize,
    out_features: usize,
    path_weight: f64,
}

fn mp0b_masked_linear(
    input: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    spec: Mp0bMaskedLinearSpec,
    out: &mut [f64],
) {
    debug_assert_eq!(weight.len(), spec.in_features * spec.out_features);
    debug_assert_eq!(output_mask.len(), spec.out_features);
    debug_assert_eq!(input.len() % spec.input_row_len, 0);
    let rows = input.len() / spec.input_row_len;
    debug_assert_eq!(out.len(), rows * spec.out_features);
    for row in 0..rows {
        let input_row = &input[row * spec.input_row_len..(row + 1) * spec.input_row_len];
        let out_row = &mut out[row * spec.out_features..(row + 1) * spec.out_features];
        for out_feature in 0..spec.out_features {
            let mut value = 0.0;
            for (in_feature, &input_value) in input_row.iter().enumerate().take(spec.in_features) {
                value += input_value * weight[in_feature * spec.out_features + out_feature];
            }
            out_row[out_feature] = value * spec.path_weight * output_mask[out_feature];
        }
    }
}

fn masked_linear_f32_input_f64_output(
    input: &[f32],
    weight: &[f64],
    output_mask: &[f64],
    spec: Mp0bMaskedLinearSpec,
    out: &mut [f64],
) {
    debug_assert_eq!(weight.len(), spec.in_features * spec.out_features);
    debug_assert_eq!(output_mask.len(), spec.out_features);
    debug_assert_eq!(input.len() % spec.input_row_len, 0);
    let rows = input.len() / spec.input_row_len;
    debug_assert_eq!(out.len(), rows * spec.out_features);
    for row in 0..rows {
        let input_row = &input[row * spec.input_row_len..(row + 1) * spec.input_row_len];
        let out_row = &mut out[row * spec.out_features..(row + 1) * spec.out_features];
        for out_feature in 0..spec.out_features {
            let mut value = 0.0;
            for (in_feature, &input_value) in input_row.iter().enumerate().take(spec.in_features) {
                value +=
                    f64::from(input_value) * weight[in_feature * spec.out_features + out_feature];
            }
            out_row[out_feature] = value * spec.path_weight * output_mask[out_feature];
        }
    }
}

fn osaka_node_embedding(
    type_ids: &[usize],
    weight: &[f64],
    output_mask: &[f64],
    spec: Mp0bMaskedLinearSpec,
    out: &mut [f64],
) -> Result<(), MaceLiteError> {
    if spec.input_row_len != spec.in_features
        || weight.len() != spec.in_features * spec.out_features
        || output_mask.len() != spec.out_features
        || out.len() != type_ids.len() * spec.out_features
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    for (row, &type_id) in type_ids.iter().enumerate() {
        if type_id >= spec.in_features {
            return Err(MaceLiteError::UnsupportedRuntime);
        }
        let weight_row = &weight[type_id * spec.out_features..(type_id + 1) * spec.out_features];
        let out_row = &mut out[row * spec.out_features..(row + 1) * spec.out_features];
        for (target, (&value, &mask)) in out_row.iter_mut().zip(weight_row.iter().zip(output_mask))
        {
            *target = value * spec.path_weight * mask;
        }
    }
    Ok(())
}

fn mp0b_masked_linear_vjp_input(
    weight: &[f64],
    output_mask: &[f64],
    spec: Mp0bMaskedLinearSpec,
    bar_out: &[f64],
    bar_input: &mut [f64],
) {
    debug_assert_eq!(weight.len(), spec.in_features * spec.out_features);
    debug_assert_eq!(output_mask.len(), spec.out_features);
    debug_assert_eq!(bar_input.len() % spec.input_row_len, 0);
    let rows = bar_input.len() / spec.input_row_len;
    debug_assert_eq!(bar_out.len(), rows * spec.out_features);
    for row in 0..rows {
        let input_offset = row * spec.input_row_len;
        let out_offset = row * spec.out_features;
        for out_feature in 0..spec.out_features {
            let bar =
                bar_out[out_offset + out_feature] * spec.path_weight * output_mask[out_feature];
            for in_feature in 0..spec.in_features {
                bar_input[input_offset + in_feature] +=
                    bar * weight[in_feature * spec.out_features + out_feature];
            }
        }
    }
}

fn mp0b_masked_linear_f32(
    input: &[f32],
    weight: &[f32],
    output_mask: &[f32],
    spec: Mp0bMaskedLinearSpec,
    out: &mut [f32],
) {
    debug_assert_eq!(weight.len(), spec.in_features * spec.out_features);
    debug_assert_eq!(output_mask.len(), spec.out_features);
    debug_assert_eq!(input.len() % spec.input_row_len, 0);
    let rows = input.len() / spec.input_row_len;
    debug_assert_eq!(out.len(), rows * spec.out_features);
    let path_weight = spec.path_weight as f32;
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if rows >= 512
        && spec.input_row_len == spec.in_features
        && spec.out_features >= 8
        && output_mask.iter().all(|&mask| mask == 1.0)
    {
        blas_backend::dense_forward_f32(input, rows, spec.in_features, weight, out, path_weight);
        return;
    }
    for row in 0..rows {
        let input_row = &input[row * spec.input_row_len..(row + 1) * spec.input_row_len];
        let out_row = &mut out[row * spec.out_features..(row + 1) * spec.out_features];
        for out_feature in 0..spec.out_features {
            let mut value = 0.0_f32;
            for (in_feature, &input_value) in input_row.iter().enumerate().take(spec.in_features) {
                value += input_value * weight[in_feature * spec.out_features + out_feature];
            }
            out_row[out_feature] = value * path_weight * output_mask[out_feature];
        }
    }
}

