#[derive(Clone, Copy, Debug)]
struct EquivariantLinearGroup {
    in_features: usize,
    out_features: usize,
    dim: usize,
}

fn component_dims_from_row_len(
    row_len: usize,
    num_features: usize,
) -> Result<Vec<usize>, MaceLiteError> {
    if num_features == 0 || !row_len.is_multiple_of(num_features) {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    match row_len / num_features {
        1 => Ok(vec![1]),
        4 => Ok(vec![1, 3]),
        9 => Ok(vec![1, 3, 5]),
        16 => Ok(vec![1, 3, 5, 7]),
        _ => Err(MaceLiteError::UnsupportedRuntime),
    }
}

fn product_linear_groups(
    row_len: usize,
    num_features: usize,
) -> Result<Vec<EquivariantLinearGroup>, MaceLiteError> {
    Ok(component_dims_from_row_len(row_len, num_features)?
        .into_iter()
        .map(|dim| EquivariantLinearGroup {
            in_features: num_features,
            out_features: num_features,
            dim,
        })
        .collect())
}

fn grouped_input_to_hidden_linear_groups(
    input_irreps: &Irreps,
    output_features: usize,
) -> Vec<EquivariantLinearGroup> {
    let mut groups: Vec<EquivariantLinearGroup> = Vec::new();
    for term in input_irreps.terms() {
        let dim = term.irrep.dim();
        if let Some(last) = groups.last_mut() {
            if last.dim == dim {
                last.in_features += term.mul;
                continue;
            }
        }
        groups.push(EquivariantLinearGroup {
            in_features: term.mul,
            out_features: output_features,
            dim,
        });
    }
    groups
}

fn mp0b_layer1_hidden_irreps_are_compatible(irreps: &Irreps) -> bool {
    const INPUT_DIMS: [usize; 10] = [1, 1, 3, 3, 3, 5, 5, 5, 7, 7];
    irreps.terms().len() == INPUT_DIMS.len()
        && irreps
            .terms()
            .iter()
            .zip(INPUT_DIMS)
            .all(|(term, dim)| term.mul == MP0B_NUM_FEATURES && term.irrep.dim() == dim)
}

fn mp0b_layer1_hidden_linear_weight_scaled_for_groups_f32(
    weight: &[f32],
    groups: &[EquivariantLinearGroup],
) -> Option<Vec<f32>> {
    const GROUP_DIMS: [usize; 4] = [1, 3, 5, 7];
    const GROUP_BLOCKS: [usize; 4] = [2, 3, 3, 2];
    let expected_len = GROUP_BLOCKS
        .iter()
        .map(|blocks| blocks * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES)
        .sum::<usize>();
    if groups.len() != GROUP_DIMS.len() || weight.len() != expected_len {
        return None;
    }
    let mut scaled = Vec::with_capacity(weight.len());
    let mut weight_offset = 0;
    for (index, group) in groups.iter().enumerate() {
        let expected_in_features = GROUP_BLOCKS[index] * MP0B_NUM_FEATURES;
        if group.dim != GROUP_DIMS[index]
            || group.in_features != expected_in_features
            || group.out_features != MP0B_NUM_FEATURES
        {
            return None;
        }
        let group_len = group.in_features * group.out_features;
        let scale = 1.0_f32 / (group.in_features as f32).sqrt();
        scaled.extend(
            weight[weight_offset..weight_offset + group_len]
                .iter()
                .map(|&value| value * scale),
        );
        weight_offset += group_len;
    }
    Some(scaled)
}

/// Minimum row count for dispatching to the BLAS backend.
///
/// libxsmm JIT kernels are fast at any size, so we dispatch unconditionally.
/// MKL/Accelerate have higher call overhead and only win beyond ~16 rows.
#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
#[inline(always)]
const fn blas_dispatch_threshold() -> usize {
    #[cfg(all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64"))]
    {
        1
    }
    #[cfg(not(all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")))]
    {
        16
    }
}

fn equivariant_linear_weight_len(groups: &[EquivariantLinearGroup]) -> usize {
    groups
        .iter()
        .map(|group| group.in_features * group.out_features)
        .sum()
}

fn mace_equivariant_linear(
    input: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    groups: &[EquivariantLinearGroup],
    out: &mut [f64],
) -> Result<(), MaceLiteError> {
    let input_row_len = groups
        .iter()
        .map(|group| group.in_features * group.dim)
        .sum::<usize>();
    let output_row_len = groups
        .iter()
        .map(|group| group.out_features * group.dim)
        .sum::<usize>();
    let weight_len = groups
        .iter()
        .map(|group| group.in_features * group.out_features)
        .sum::<usize>();
    if input_row_len == 0
        || !input.len().is_multiple_of(input_row_len)
        || output_mask.len() != output_row_len
        || out.len() != input.len() / input_row_len * output_row_len
        || weight.len() != weight_len
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let rows = input.len() / input_row_len;
    // Note: the MP0B-specific shortcut paths (`mp0b_scalar_product_linear` and
    // `mp0b_scalar_vector_product_linear`) were removed because those functions
    // now assume their weight argument has already been pre-scaled by
    // `prescale_mp0b_blas_weights`. Generic `mace_equivariant_linear` callers
    // (OSAKA-family runtime plans) pass raw weights and rely on the per-group
    // `path_weight` applied by the generic path below.
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if rows >= blas_dispatch_threshold() {
        mace_equivariant_linear_blas(
            input,
            weight,
            output_mask,
            groups,
            rows,
            input_row_len,
            output_row_len,
            out,
        );
        return Ok(());
    }
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1
        && rayon::current_thread_index().is_none()
        && rows >= 16
        && input_row_len * output_row_len >= 1024
    {
        out.par_chunks_mut(output_row_len)
            .enumerate()
            .for_each(|(row, out_row)| {
                let input_row = &input[row * input_row_len..(row + 1) * input_row_len];
                let mut input_group_offset = 0usize;
                let mut output_group_offset = 0usize;
                let mut weight_offset = 0usize;
                for group in groups {
                    let path_weight = 1.0 / (group.in_features as f64).sqrt();
                    for out_feature in 0..group.out_features {
                        for component in 0..group.dim {
                            let mut value = 0.0;
                            for in_feature in 0..group.in_features {
                                let input_index =
                                    input_group_offset + in_feature * group.dim + component;
                                let weight_index =
                                    weight_offset + in_feature * group.out_features + out_feature;
                                value += input_row[input_index] * weight[weight_index];
                            }
                            let output_index =
                                output_group_offset + out_feature * group.dim + component;
                            out_row[output_index] = value * path_weight * output_mask[output_index];
                        }
                    }
                    input_group_offset += group.in_features * group.dim;
                    output_group_offset += group.out_features * group.dim;
                    weight_offset += group.in_features * group.out_features;
                }
            });
        return Ok(());
    }
    let mut input_group_offset = 0;
    let mut output_group_offset = 0;
    let mut weight_offset = 0;
    for group in groups {
        let path_weight = 1.0 / (group.in_features as f64).sqrt();
        for row in 0..rows {
            let input_row = &input[row * input_row_len..(row + 1) * input_row_len];
            let out_row = &mut out[row * output_row_len..(row + 1) * output_row_len];
            for out_feature in 0..group.out_features {
                for component in 0..group.dim {
                    let mut value = 0.0;
                    for in_feature in 0..group.in_features {
                        let input_index = input_group_offset + in_feature * group.dim + component;
                        let weight_index =
                            weight_offset + in_feature * group.out_features + out_feature;
                        value += input_row[input_index] * weight[weight_index];
                    }
                    let output_index = output_group_offset + out_feature * group.dim + component;
                    out_row[output_index] = value * path_weight * output_mask[output_index];
                }
            }
        }
        input_group_offset += group.in_features * group.dim;
        output_group_offset += group.out_features * group.dim;
        weight_offset += group.in_features * group.out_features;
    }
    Ok(())
}

fn mace_equivariant_linear_vjp_input(
    weight: &[f64],
    output_mask: &[f64],
    groups: &[EquivariantLinearGroup],
    bar_out: &[f64],
    bar_input: &mut [f64],
) -> Result<(), MaceLiteError> {
    let input_row_len = groups
        .iter()
        .map(|group| group.in_features * group.dim)
        .sum::<usize>();
    let output_row_len = groups
        .iter()
        .map(|group| group.out_features * group.dim)
        .sum::<usize>();
    let weight_len = groups
        .iter()
        .map(|group| group.in_features * group.out_features)
        .sum::<usize>();
    if input_row_len == 0
        || !bar_input.len().is_multiple_of(input_row_len)
        || output_mask.len() != output_row_len
        || bar_out.len() != bar_input.len() / input_row_len * output_row_len
        || weight.len() != weight_len
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let rows = bar_input.len() / input_row_len;
    // MP0B-specific shortcut paths removed: the MP0B VJP helpers assume the
    // weight has been pre-scaled by `prescale_mp0b_blas_weights`, which is not
    // true for the OSAKA generic-path callers that drive this function.
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if rows >= blas_dispatch_threshold() {
        mace_equivariant_linear_vjp_input_blas(
            weight,
            output_mask,
            groups,
            rows,
            input_row_len,
            output_row_len,
            bar_out,
            bar_input,
        );
        return Ok(());
    }
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1
        && rayon::current_thread_index().is_none()
        && rows >= 16
        && input_row_len * output_row_len >= 1024
    {
        bar_input
            .par_chunks_mut(input_row_len)
            .enumerate()
            .for_each(|(row, bar_input_row)| {
                let bar_out_row = &bar_out[row * output_row_len..(row + 1) * output_row_len];
                let mut input_group_offset = 0usize;
                let mut output_group_offset = 0usize;
                let mut weight_offset = 0usize;
                for group in groups {
                    let path_weight = 1.0 / (group.in_features as f64).sqrt();
                    for out_feature in 0..group.out_features {
                        for component in 0..group.dim {
                            let output_index =
                                output_group_offset + out_feature * group.dim + component;
                            let bar =
                                bar_out_row[output_index] * path_weight * output_mask[output_index];
                            for in_feature in 0..group.in_features {
                                let input_index =
                                    input_group_offset + in_feature * group.dim + component;
                                let weight_index =
                                    weight_offset + in_feature * group.out_features + out_feature;
                                bar_input_row[input_index] += bar * weight[weight_index];
                            }
                        }
                    }
                    input_group_offset += group.in_features * group.dim;
                    output_group_offset += group.out_features * group.dim;
                    weight_offset += group.in_features * group.out_features;
                }
            });
        return Ok(());
    }
    let mut input_group_offset = 0;
    let mut output_group_offset = 0;
    let mut weight_offset = 0;
    for group in groups {
        let path_weight = 1.0 / (group.in_features as f64).sqrt();
        for row in 0..rows {
            let bar_out_row = &bar_out[row * output_row_len..(row + 1) * output_row_len];
            let bar_input_row = &mut bar_input[row * input_row_len..(row + 1) * input_row_len];
            for out_feature in 0..group.out_features {
                for component in 0..group.dim {
                    let output_index = output_group_offset + out_feature * group.dim + component;
                    let bar = bar_out_row[output_index] * path_weight * output_mask[output_index];
                    for in_feature in 0..group.in_features {
                        let input_index = input_group_offset + in_feature * group.dim + component;
                        let weight_index =
                            weight_offset + in_feature * group.out_features + out_feature;
                        bar_input_row[input_index] += bar * weight[weight_index];
                    }
                }
            }
        }
        input_group_offset += group.in_features * group.dim;
        output_group_offset += group.out_features * group.dim;
        weight_offset += group.in_features * group.out_features;
    }
    Ok(())
}

fn mace_equivariant_linear_f32(
    input: &[f32],
    weight: &[f32],
    output_mask: &[f32],
    groups: &[EquivariantLinearGroup],
    out: &mut [f32],
) -> Result<(), MaceLiteError> {
    let input_row_len = groups
        .iter()
        .map(|group| group.in_features * group.dim)
        .sum::<usize>();
    let output_row_len = groups
        .iter()
        .map(|group| group.out_features * group.dim)
        .sum::<usize>();
    let weight_len = groups
        .iter()
        .map(|group| group.in_features * group.out_features)
        .sum::<usize>();
    if input_row_len == 0
        || !input.len().is_multiple_of(input_row_len)
        || output_mask.len() != output_row_len
        || out.len() != input.len() / input_row_len * output_row_len
        || weight.len() != weight_len
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let rows = input.len() / input_row_len;
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if rows >= 16
        && groups.len() == 1
        && groups[0].dim == 1
        && output_mask.iter().all(|&mask| mask == 1.0)
    {
        let group = groups[0];
        let path_weight = 1.0_f32 / (group.in_features as f32).sqrt();
        blas_backend::dense_forward_f32(input, rows, group.in_features, weight, out, path_weight);
        return Ok(());
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if rows >= 16 {
        mace_equivariant_linear_blas_f32(
            input,
            weight,
            output_mask,
            groups,
            rows,
            input_row_len,
            output_row_len,
            out,
        );
        return Ok(());
    }
    let mut input_group_offset = 0;
    let mut output_group_offset = 0;
    let mut weight_offset = 0;
    for group in groups {
        let path_weight = 1.0_f32 / (group.in_features as f32).sqrt();
        for row in 0..rows {
            let input_row = &input[row * input_row_len..(row + 1) * input_row_len];
            let out_row = &mut out[row * output_row_len..(row + 1) * output_row_len];
            for out_feature in 0..group.out_features {
                for component in 0..group.dim {
                    let mut value = 0.0_f32;
                    for in_feature in 0..group.in_features {
                        let input_index = input_group_offset + in_feature * group.dim + component;
                        let weight_index =
                            weight_offset + in_feature * group.out_features + out_feature;
                        value += input_row[input_index] * weight[weight_index];
                    }
                    let output_index = output_group_offset + out_feature * group.dim + component;
                    out_row[output_index] = value * path_weight * output_mask[output_index];
                }
            }
        }
        input_group_offset += group.in_features * group.dim;
        output_group_offset += group.out_features * group.dim;
        weight_offset += group.in_features * group.out_features;
    }
    Ok(())
}

fn mace_equivariant_linear_vjp_input_f32(
    weight: &[f32],
    output_mask: &[f32],
    groups: &[EquivariantLinearGroup],
    bar_out: &[f32],
    bar_input: &mut [f32],
) -> Result<(), MaceLiteError> {
    let input_row_len = groups
        .iter()
        .map(|group| group.in_features * group.dim)
        .sum::<usize>();
    let output_row_len = groups
        .iter()
        .map(|group| group.out_features * group.dim)
        .sum::<usize>();
    let weight_len = groups
        .iter()
        .map(|group| group.in_features * group.out_features)
        .sum::<usize>();
    if input_row_len == 0
        || !bar_input.len().is_multiple_of(input_row_len)
        || output_mask.len() != output_row_len
        || bar_out.len() != bar_input.len() / input_row_len * output_row_len
        || weight.len() != weight_len
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let rows = bar_input.len() / input_row_len;
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if rows >= 16
        && groups.len() == 1
        && groups[0].dim == 1
        && output_mask.iter().all(|&mask| mask == 1.0)
    {
        let group = groups[0];
        let path_weight = 1.0_f32 / (group.in_features as f32).sqrt();
        blas_backend::dense_vjp_input_f32(
            rows,
            group.in_features,
            weight,
            bar_out,
            bar_input,
            path_weight,
        );
        return Ok(());
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if rows >= 16 {
        mace_equivariant_linear_vjp_input_blas_f32(
            weight,
            output_mask,
            groups,
            rows,
            input_row_len,
            output_row_len,
            bar_out,
            bar_input,
        );
        return Ok(());
    }
    let mut input_group_offset = 0;
    let mut output_group_offset = 0;
    let mut weight_offset = 0;
    for group in groups {
        let path_weight = 1.0_f32 / (group.in_features as f32).sqrt();
        for row in 0..rows {
            let bar_out_row = &bar_out[row * output_row_len..(row + 1) * output_row_len];
            let bar_input_row = &mut bar_input[row * input_row_len..(row + 1) * input_row_len];
            for out_feature in 0..group.out_features {
                for component in 0..group.dim {
                    let output_index = output_group_offset + out_feature * group.dim + component;
                    let bar = bar_out_row[output_index] * path_weight * output_mask[output_index];
                    for in_feature in 0..group.in_features {
                        let input_index = input_group_offset + in_feature * group.dim + component;
                        let weight_index =
                            weight_offset + in_feature * group.out_features + out_feature;
                        bar_input_row[input_index] += bar * weight[weight_index];
                    }
                }
            }
        }
        input_group_offset += group.in_features * group.dim;
        output_group_offset += group.out_features * group.dim;
        weight_offset += group.in_features * group.out_features;
    }
    Ok(())
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
#[allow(clippy::too_many_arguments)]
fn mace_equivariant_linear_blas_f32(
    input: &[f32],
    weight: &[f32],
    output_mask: &[f32],
    groups: &[EquivariantLinearGroup],
    rows: usize,
    input_row_len: usize,
    output_row_len: usize,
    out: &mut [f32],
) {
    let max_in_features = groups
        .iter()
        .map(|group| group.in_features)
        .max()
        .unwrap_or(0);
    let max_out_features = groups
        .iter()
        .map(|group| group.out_features)
        .max()
        .unwrap_or(0);
    let mut packed_input = vec![0.0_f32; rows * max_in_features];
    let mut packed_out = vec![0.0_f32; rows * max_out_features];
    let mut input_group_offset = 0;
    let mut output_group_offset = 0;
    let mut weight_offset = 0;
    for group in groups {
        let path_weight = 1.0_f32 / (group.in_features as f32).sqrt();
        let weight_slice =
            &weight[weight_offset..weight_offset + group.in_features * group.out_features];
        for component in 0..group.dim {
            for row in 0..rows {
                let input_row = &input[row * input_row_len..(row + 1) * input_row_len];
                let packed_row = &mut packed_input
                    [row * max_in_features..row * max_in_features + group.in_features];
                for feature in 0..group.in_features {
                    packed_row[feature] =
                        input_row[input_group_offset + feature * group.dim + component];
                }
            }
            let packed_input_view = &packed_input[..rows * max_in_features];
            let packed_out_view = &mut packed_out[..rows * max_out_features];
            blas_backend::dense_forward_strided_f32(
                packed_input_view,
                rows,
                group.in_features,
                max_in_features,
                weight_slice,
                packed_out_view,
                group.out_features,
                max_out_features,
                path_weight,
                0.0,
            );
            for row in 0..rows {
                let out_row = &mut out[row * output_row_len..(row + 1) * output_row_len];
                let packed_row = &packed_out
                    [row * max_out_features..row * max_out_features + group.out_features];
                for (feature, &value) in packed_row.iter().enumerate() {
                    let output_index = output_group_offset + feature * group.dim + component;
                    out_row[output_index] = value * output_mask[output_index];
                }
            }
        }
        input_group_offset += group.in_features * group.dim;
        output_group_offset += group.out_features * group.dim;
        weight_offset += group.in_features * group.out_features;
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
#[allow(clippy::too_many_arguments)]
fn mace_equivariant_linear_vjp_input_blas_f32(
    weight: &[f32],
    output_mask: &[f32],
    groups: &[EquivariantLinearGroup],
    rows: usize,
    input_row_len: usize,
    output_row_len: usize,
    bar_out: &[f32],
    bar_input: &mut [f32],
) {
    let max_in_features = groups
        .iter()
        .map(|group| group.in_features)
        .max()
        .unwrap_or(0);
    let max_out_features = groups
        .iter()
        .map(|group| group.out_features)
        .max()
        .unwrap_or(0);
    let mut packed_bar_out = vec![0.0_f32; rows * max_out_features];
    let mut packed_bar_input = vec![0.0_f32; rows * max_in_features];
    let mut input_group_offset = 0;
    let mut output_group_offset = 0;
    let mut weight_offset = 0;
    for group in groups {
        let path_weight = 1.0_f32 / (group.in_features as f32).sqrt();
        let weight_slice =
            &weight[weight_offset..weight_offset + group.in_features * group.out_features];
        for component in 0..group.dim {
            for row in 0..rows {
                let bar_out_row = &bar_out[row * output_row_len..(row + 1) * output_row_len];
                let packed_row = &mut packed_bar_out
                    [row * max_out_features..row * max_out_features + group.out_features];
                for (feature, value) in packed_row.iter_mut().enumerate().take(group.out_features) {
                    let output_index = output_group_offset + feature * group.dim + component;
                    *value = bar_out_row[output_index] * output_mask[output_index];
                }
            }
            packed_bar_input.fill(0.0);
            blas_backend::dense_vjp_input_strided_f32(
                rows,
                group.in_features,
                weight_slice,
                group.out_features,
                &packed_bar_out[..rows * max_out_features],
                max_out_features,
                &mut packed_bar_input[..rows * max_in_features],
                max_in_features,
                path_weight,
                0.0,
            );
            for row in 0..rows {
                let bar_input_row = &mut bar_input[row * input_row_len..(row + 1) * input_row_len];
                let packed_row = &packed_bar_input
                    [row * max_in_features..row * max_in_features + group.in_features];
                for (feature, &value) in packed_row.iter().enumerate() {
                    let input_index = input_group_offset + feature * group.dim + component;
                    // Accumulate (`+=`), matching the scalar fallback in
                    // `mace_equivariant_linear_vjp_input_f32` and the
                    // single-group BLAS fast path (which uses GEMM beta = 1.0).
                    // Several callers pass a `bar_input` that already holds
                    // gradient contributions from sibling paths (e.g. the layer
                    // `linear_up` VJP accumulates onto the readout/skip gradient
                    // already present in the product-output gradient buffer).
                    // Overwriting here clobbered those contributions whenever a
                    // group has `dim > 1` (l_max > 0), which is what made the
                    // osaka24 medium forces diverge from FP64.
                    bar_input_row[input_index] += value;
                }
            }
        }
        input_group_offset += group.in_features * group.dim;
        output_group_offset += group.out_features * group.dim;
        weight_offset += group.in_features * group.out_features;
    }
}

