#[derive(Debug)]
struct OsakaFeatureMajorLinearComponentF32 {
    input_group_offset: usize,
    component_offset: usize,
    component_dim: usize,
    component: usize,
    features: usize,
    values: Vec<f32>,
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
fn osaka_hidden_linear_groups_are_feature_major_compatible(
    groups: &[EquivariantLinearGroup],
) -> bool {
    groups
        .iter()
        .map(|group| group.out_features * group.dim)
        .sum::<usize>()
        == MP0B_HIDDEN_ROW_LEN
        && groups
            .iter()
            .all(|group| group.out_features == MP0B_NUM_FEATURES)
        && groups.iter().map(|group| group.dim).sum::<usize>() == MP0B_SH_DIM
}

