                    &bar_out[row * MP0B_HIDDEN_ROW_LEN..(row + 1) * MP0B_HIDDEN_ROW_LEN];
                let packed_row = &mut packed_bar_out_view
                    [row * group.out_features..(row + 1) * group.out_features];
