#[allow(clippy::too_many_arguments)]
fn osaka_hidden_linear_avg_to_feature_major_parallel_blas_f32(
    input: &[f32],
    avg_num_neighbors: f32,
    weight: &[f32],
    groups: &[EquivariantLinearGroup],
    out: &mut [f32],
) -> Result<(), MaceLiteError> {
    let input_row_len = groups
        .iter()
        .map(|group| group.in_features * group.dim)
        .sum::<usize>();
    if input_row_len == 0
        || !input.len().is_multiple_of(input_row_len)
        || out.len() != input.len() / input_row_len * MP0B_HIDDEN_ROW_LEN
        || weight.len() != equivariant_linear_weight_len(groups)
        || !avg_num_neighbors.is_finite()
        || avg_num_neighbors <= 0.0
        || !osaka_hidden_linear_groups_are_feature_major_compatible(groups)
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let rows = input.len() / input_row_len;
    let mut task_specs = Vec::new();
    let mut input_group_offset = 0;
    let mut component_offset = 0;
    let mut weight_offset = 0;
    for &group in groups {
        for component in 0..group.dim {
            task_specs.push((
                group,
                input_group_offset,
                component_offset,
                component,
                weight_offset,
            ));
        }
        input_group_offset += group.in_features * group.dim;
        component_offset += group.dim;
        weight_offset += group.in_features * group.out_features;
    }

    let components = task_specs
        .into_par_iter()
        .map(
            |(group, input_group_offset, component_offset, component, weight_offset)| {
                let mut packed_input = vec![0.0_f32; rows * group.in_features];
                for row in 0..rows {
                    let input_row = &input[row * input_row_len..(row + 1) * input_row_len];
                    let packed_row =
                        &mut packed_input[row * group.in_features..(row + 1) * group.in_features];
                    for (feature, value) in packed_row.iter_mut().enumerate() {
                        *value = input_row[input_group_offset + feature * group.dim + component];
                    }
                }
                let mut values = vec![0.0_f32; rows * group.out_features];
                let path_weight = 1.0_f32 / (group.in_features as f32).sqrt() / avg_num_neighbors;
                blas_backend::dense_forward_f32(
                    &packed_input,
                    rows,
                    group.in_features,
                    &weight[weight_offset..weight_offset + group.in_features * group.out_features],
                    &mut values,
                    path_weight,
                );
                OsakaFeatureMajorLinearComponentF32 {
                    input_group_offset,
                    component_offset,
                    component_dim: group.dim,
                    component,
                    features: group.out_features,
                    values,
                }
            },
        )
        .collect::<Vec<_>>();

    if rows >= 1024 {
        out.par_chunks_mut(MP0B_HIDDEN_ROW_LEN)
            .enumerate()
            .for_each(|(row, out_row)| {
                for component_result in &components {
                    let packed_row = &component_result.values
                        [row * component_result.features..(row + 1) * component_result.features];
                    for (feature, &value) in packed_row.iter().enumerate() {
                        out_row[feature * MP0B_SH_DIM
                            + component_result.component_offset
                            + component_result.component] = value;
                    }
                }
            });
    } else {
        for component_result in components {
            for row in 0..rows {
                let out_row = &mut out[row * MP0B_HIDDEN_ROW_LEN..(row + 1) * MP0B_HIDDEN_ROW_LEN];
                let packed_row = &component_result.values
                    [row * component_result.features..(row + 1) * component_result.features];
                for (feature, &value) in packed_row.iter().enumerate() {
                    out_row[feature * MP0B_SH_DIM
                        + component_result.component_offset
                        + component_result.component] = value;
                }
            }
        }
    }
    Ok(())
}

#[cfg(all(
    feature = "parallel",
    any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    )
))]
#[allow(clippy::too_many_arguments)]
fn osaka_hidden_linear_avg_from_feature_major_vjp_input_parallel_blas_f32(
    avg_num_neighbors: f32,
    weight: &[f32],
    groups: &[EquivariantLinearGroup],
    bar_out: &[f32],
    bar_input: &mut [f32],
) -> Result<(), MaceLiteError> {
    let input_row_len = groups
        .iter()
        .map(|group| group.in_features * group.dim)
        .sum::<usize>();
    if input_row_len == 0
        || !bar_input.len().is_multiple_of(input_row_len)
        || bar_out.len() != bar_input.len() / input_row_len * MP0B_HIDDEN_ROW_LEN
        || weight.len() != equivariant_linear_weight_len(groups)
        || !avg_num_neighbors.is_finite()
        || avg_num_neighbors <= 0.0
        || !osaka_hidden_linear_groups_are_feature_major_compatible(groups)
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let rows = bar_input.len() / input_row_len;
    let mut task_specs = Vec::new();
    let mut input_group_offset = 0;
    let mut component_offset = 0;
    let mut weight_offset = 0;
    for &group in groups {
        for component in 0..group.dim {
            task_specs.push((
                group,
                input_group_offset,
                component_offset,
                component,
                weight_offset,
            ));
        }
        input_group_offset += group.in_features * group.dim;
        component_offset += group.dim;
        weight_offset += group.in_features * group.out_features;
    }

    let components = task_specs
        .into_par_iter()
        .map(
            |(group, input_group_offset, component_offset, component, weight_offset)| {
                let mut packed_bar_out = vec![0.0_f32; rows * group.out_features];
                for row in 0..rows {
                    let bar_out_row =
                        &bar_out[row * MP0B_HIDDEN_ROW_LEN..(row + 1) * MP0B_HIDDEN_ROW_LEN];
                    let packed_row = &mut packed_bar_out
                        [row * group.out_features..(row + 1) * group.out_features];
                    for (feature, value) in packed_row.iter_mut().enumerate() {
                        *value = bar_out_row[feature * MP0B_SH_DIM + component_offset + component];
                    }
                }
                let mut values = vec![0.0_f32; rows * group.in_features];
                let path_weight = 1.0_f32 / (group.in_features as f32).sqrt() / avg_num_neighbors;
                blas_backend::dense_vjp_input_f32(
                    rows,
                    group.in_features,
                    &weight[weight_offset..weight_offset + group.in_features * group.out_features],
                    &packed_bar_out,
                    &mut values,
                    path_weight,
                );
                OsakaFeatureMajorLinearComponentF32 {
                    input_group_offset,
                    component_offset,
                    component_dim: group.dim,
                    component,
                    features: group.in_features,
                    values,
                }
            },
        )
        .collect::<Vec<_>>();

    if rows >= 1024 {
        bar_input
            .par_chunks_mut(input_row_len)
            .enumerate()
            .for_each(|(row, bar_input_row)| {
                for component_result in &components {
                    let packed_row = &component_result.values
                        [row * component_result.features..(row + 1) * component_result.features];
                    for (feature, &value) in packed_row.iter().enumerate() {
                        bar_input_row[component_result.input_group_offset
                            + feature * component_result.component_dim
                            + component_result.component] = value;
                    }
                }
            });
    } else {
        for component_result in components {
            for row in 0..rows {
                let bar_input_row = &mut bar_input[row * input_row_len..(row + 1) * input_row_len];
                let packed_row = &component_result.values
                    [row * component_result.features..(row + 1) * component_result.features];
                for (feature, &value) in packed_row.iter().enumerate() {
                    bar_input_row[component_result.input_group_offset
                        + feature * component_result.component_dim
                        + component_result.component] = value;
                }
            }
        }
    }
    Ok(())
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
#[allow(clippy::too_many_arguments)]
fn mace_equivariant_linear_blas(
    input: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    groups: &[EquivariantLinearGroup],
    rows: usize,
    input_row_len: usize,
    output_row_len: usize,
    out: &mut [f64],
) {
    let max_in_features = groups
        .iter()
        .map(|group| group.in_features)
        .max()
        .unwrap_or(0);
    let max_out_features = groups
        .iter()
        .map(|group| group.out_features)
        .max()
        .unwrap_or(0);
    let mut packed_input = vec![0.0; rows * max_in_features];
    let mut packed_out = vec![0.0; rows * max_out_features];
    let mut input_group_offset = 0;
    let mut output_group_offset = 0;
    let mut weight_offset = 0;
    for group in groups {
        let path_weight = 1.0 / (group.in_features as f64).sqrt();
        let weight_slice =
            &weight[weight_offset..weight_offset + group.in_features * group.out_features];
        for component in 0..group.dim {
            for row in 0..rows {
                let input_row = &input[row * input_row_len..(row + 1) * input_row_len];
                let packed_row = &mut packed_input
                    [row * max_in_features..row * max_in_features + group.in_features];
                for feature in 0..group.in_features {
                    packed_row[feature] =
                        input_row[input_group_offset + feature * group.dim + component];
                }
            }
            let packed_input_view = &packed_input[..rows * max_in_features];
            let packed_out_view = &mut packed_out[..rows * max_out_features];
            blas_backend::dense_forward_strided(
                packed_input_view,
                rows,
                group.in_features,
                max_in_features,
                weight_slice,
                packed_out_view,
                group.out_features,
                max_out_features,
                path_weight,
                0.0,
            );
            for row in 0..rows {
                let out_row = &mut out[row * output_row_len..(row + 1) * output_row_len];
                let packed_row = &packed_out
                    [row * max_out_features..row * max_out_features + group.out_features];
                for (feature, &value) in packed_row.iter().enumerate() {
                    let output_index = output_group_offset + feature * group.dim + component;
                    out_row[output_index] = value * output_mask[output_index];
                }
            }
        }
        input_group_offset += group.in_features * group.dim;
        output_group_offset += group.out_features * group.dim;
        weight_offset += group.in_features * group.out_features;
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
#[allow(clippy::too_many_arguments)]
fn mace_equivariant_linear_vjp_input_blas(
    weight: &[f64],
    output_mask: &[f64],
    groups: &[EquivariantLinearGroup],
    rows: usize,
    input_row_len: usize,
    output_row_len: usize,
    bar_out: &[f64],
    bar_input: &mut [f64],
) {
    let max_in_features = groups
        .iter()
        .map(|group| group.in_features)
        .max()
        .unwrap_or(0);
    let max_out_features = groups
        .iter()
        .map(|group| group.out_features)
        .max()
        .unwrap_or(0);
    let mut packed_bar_out = vec![0.0; rows * max_out_features];
    let mut packed_bar_input = vec![0.0; rows * max_in_features];
    let mut input_group_offset = 0;
    let mut output_group_offset = 0;
    let mut weight_offset = 0;
    for group in groups {
        let path_weight = 1.0 / (group.in_features as f64).sqrt();
        let weight_slice =
            &weight[weight_offset..weight_offset + group.in_features * group.out_features];
        for component in 0..group.dim {
            for row in 0..rows {
                let bar_out_row = &bar_out[row * output_row_len..(row + 1) * output_row_len];
                let packed_row = &mut packed_bar_out
                    [row * max_out_features..row * max_out_features + group.out_features];
                for (feature, value) in packed_row.iter_mut().enumerate().take(group.out_features) {
                    let output_index = output_group_offset + feature * group.dim + component;
                    *value = bar_out_row[output_index] * output_mask[output_index];
                }
            }
            packed_bar_input.fill(0.0);
            blas_backend::dense_vjp_input_strided(
                rows,
                group.in_features,
                weight_slice,
                group.out_features,
                &packed_bar_out[..rows * max_out_features],
                max_out_features,
                &mut packed_bar_input[..rows * max_in_features],
                max_in_features,
                path_weight,
                0.0,
            );
            for row in 0..rows {
                let bar_input_row = &mut bar_input[row * input_row_len..(row + 1) * input_row_len];
                let packed_row = &packed_bar_input
                    [row * max_in_features..row * max_in_features + group.in_features];
                for (feature, &value) in packed_row.iter().enumerate() {
                    let input_index = input_group_offset + feature * group.dim + component;
                    // Accumulate (`+=`), matching the scalar fallback in
                    // `mace_equivariant_linear_vjp_input`. The FP64 osaka VJP for
                    // the wide (l_max = 3) `linear_up` falls through to this
                    // generic BLAS helper, and its `bar_input` already holds the
                    // readout/skip gradient that must be summed in. Overwriting
                    // here made the FP64 reference itself wrong for the osaka24
                    // large variant (it silently dropped that contribution),
                    // which is why the FP32 parity test only surfaced once the
                    // FP32 side was fixed to accumulate.
                    bar_input_row[input_index] += value;
                }
            }
        }
        input_group_offset += group.in_features * group.dim;
        output_group_offset += group.out_features * group.dim;
        weight_offset += group.in_features * group.out_features;
    }
}

// Consumes weights that have been pre-scaled by `1 / sqrt(MP0B_NUM_FEATURES)`
// in `prescale_mp0b_blas_weights`, so the GEMM call uses `alpha = 1.0` and the
// masked-linear fallback uses `path_weight = 1.0`.
fn mp0b_scalar_product_linear(
    input: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    path_weight: f64,
    out: &mut [f64],
) {
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if output_mask.iter().all(|&mask| mask == 1.0)
        && input.len().is_multiple_of(MP0B_NUM_FEATURES)
        && input.len() / MP0B_NUM_FEATURES >= blas_dispatch_threshold()
    {
        blas_backend::dense_forward(
            input,
            input.len() / MP0B_NUM_FEATURES,
            MP0B_NUM_FEATURES,
            weight,
            out,
            path_weight,
        );
        return;
    }
    mp0b_masked_linear(
        input,
        weight,
        output_mask,
        Mp0bMaskedLinearSpec {
            input_row_len: MP0B_NUM_FEATURES,
            in_features: MP0B_NUM_FEATURES,
            out_features: MP0B_NUM_FEATURES,
            path_weight,
        },
        out,
    );
}

fn mp0b_scalar_product_linear_vjp_input(
    weight: &[f64],
    output_mask: &[f64],
    bar_out: &[f64],
    path_weight: f64,
    bar_input: &mut [f64],
) {
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if output_mask.iter().all(|&mask| mask == 1.0)
        && bar_input.len().is_multiple_of(MP0B_NUM_FEATURES)
        && bar_input.len() / MP0B_NUM_FEATURES >= blas_dispatch_threshold()
    {
        blas_backend::dense_vjp_input(
            bar_input.len() / MP0B_NUM_FEATURES,
            MP0B_NUM_FEATURES,
            weight,
            bar_out,
            bar_input,
            path_weight,
        );
        return;
    }
    mp0b_masked_linear_vjp_input(
        weight,
        output_mask,
        Mp0bMaskedLinearSpec {
            input_row_len: MP0B_NUM_FEATURES,
            in_features: MP0B_NUM_FEATURES,
            out_features: MP0B_NUM_FEATURES,
            path_weight,
        },
        bar_out,
        bar_input,
    );
}

// Consumes weights that have been pre-scaled by `1 / sqrt(MP0B_NUM_FEATURES)`
// in `prescale_mp0b_blas_weights`. Both the BLAS dispatch and the manual loop
// skip the per-element path-weight multiply.
fn mp0b_scalar_product_linear_f32(
    input: &[f32],
    weight: &[f32],
    output_mask: &[f32],
    out: &mut [f32],
) {
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if output_mask.iter().all(|&mask| mask == 1.0)
        && input.len().is_multiple_of(MP0B_NUM_FEATURES)
        && input.len() / MP0B_NUM_FEATURES >= 16
    {
        blas_backend::dense_forward_f32(
            input,
            input.len() / MP0B_NUM_FEATURES,
            MP0B_NUM_FEATURES,
            weight,
            out,
            1.0,
        );
        return;
    }
    mp0b_masked_linear_f32(
        input,
        weight,
        output_mask,
        Mp0bMaskedLinearSpec {
            input_row_len: MP0B_NUM_FEATURES,
            in_features: MP0B_NUM_FEATURES,
            out_features: MP0B_NUM_FEATURES,
            path_weight: 1.0,
        },
        out,
    );
}

