fn mp0b_scalar_vector_product_linear(
    input: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    path_weight: f64,
    out: &mut [f64],
) {
    let vector_equivariance = 3;
    let scalar_len = MP0B_NUM_FEATURES;
    let vector_len = MP0B_NUM_FEATURES * vector_equivariance;
    let row_len = scalar_len + vector_len;
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    debug_assert_eq!(weight.len(), block_weights * 2);
    debug_assert_eq!(output_mask.len(), row_len);
    debug_assert_eq!(input.len() % row_len, 0);
    debug_assert_eq!(input.len(), out.len());
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if output_mask.iter().all(|&mask| mask == 1.0)
        && input.len() / row_len >= blas_dispatch_threshold()
    {
        mp0b_scalar_vector_product_linear_blas(
            input,
            weight,
            out,
            input.len() / row_len,
            path_weight,
        );
        return;
    }
    for (input_row, out_row) in input.chunks(row_len).zip(out.chunks_mut(row_len)) {
        for out_feature in 0..MP0B_NUM_FEATURES {
            let mut value = 0.0;
            for in_feature in 0..MP0B_NUM_FEATURES {
                value +=
                    input_row[in_feature] * weight[in_feature * MP0B_NUM_FEATURES + out_feature];
            }
            out_row[out_feature] = value * path_weight * output_mask[out_feature];
        }
        for out_feature in 0..MP0B_NUM_FEATURES {
            for m in 0..vector_equivariance {
                let out_index = scalar_len + out_feature * vector_equivariance + m;
                let mut value = 0.0;
                for in_feature in 0..MP0B_NUM_FEATURES {
                    let in_index = scalar_len + in_feature * vector_equivariance + m;
                    let weight_index = block_weights + in_feature * MP0B_NUM_FEATURES + out_feature;
                    value += input_row[in_index] * weight[weight_index];
                }
                out_row[out_index] = value * path_weight * output_mask[out_index];
            }
        }
    }
}

// Consumes weights pre-scaled by `1 / sqrt(MP0B_NUM_FEATURES)`.
fn mp0b_scalar_vector_product_linear_vjp_input(
    weight: &[f64],
    output_mask: &[f64],
    bar_out: &[f64],
    path_weight: f64,
    bar_input: &mut [f64],
) {
    let vector_equivariance = 3;
    let scalar_len = MP0B_NUM_FEATURES;
    let vector_len = MP0B_NUM_FEATURES * vector_equivariance;
    let row_len = scalar_len + vector_len;
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    debug_assert_eq!(weight.len(), block_weights * 2);
    debug_assert_eq!(output_mask.len(), row_len);
    debug_assert_eq!(bar_out.len(), bar_input.len());
    debug_assert_eq!(bar_input.len() % row_len, 0);
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if output_mask.iter().all(|&mask| mask == 1.0)
        && bar_input.len() / row_len >= blas_dispatch_threshold()
    {
        mp0b_scalar_vector_product_linear_vjp_input_blas(
            weight,
            bar_out,
            bar_input,
            bar_input.len() / row_len,
            path_weight,
        );
        return;
    }
    for (bar_out_row, bar_input_row) in bar_out.chunks(row_len).zip(bar_input.chunks_mut(row_len)) {
        for out_feature in 0..MP0B_NUM_FEATURES {
            let bar = bar_out_row[out_feature] * path_weight * output_mask[out_feature];
            for in_feature in 0..MP0B_NUM_FEATURES {
                bar_input_row[in_feature] +=
                    bar * weight[in_feature * MP0B_NUM_FEATURES + out_feature];
            }
        }
        for out_feature in 0..MP0B_NUM_FEATURES {
            for m in 0..vector_equivariance {
                let out_index = scalar_len + out_feature * vector_equivariance + m;
                let bar = bar_out_row[out_index] * path_weight * output_mask[out_index];
                for in_feature in 0..MP0B_NUM_FEATURES {
                    let in_index = scalar_len + in_feature * vector_equivariance + m;
                    let weight_index = block_weights + in_feature * MP0B_NUM_FEATURES + out_feature;
                    bar_input_row[in_index] += bar * weight[weight_index];
                }
            }
        }
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
fn mp0b_scalar_vector_product_linear_blas(
    input: &[f64],
    weight: &[f64],
    out: &mut [f64],
    rows: usize,
    path_weight: f64,
) {
    let scalar_len = MP0B_NUM_FEATURES;
    let vector_equivariance = 3;
    let row_len = scalar_len * (1 + vector_equivariance);
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    blas_backend::dense_forward_strided(
        input,
        rows,
        MP0B_NUM_FEATURES,
        row_len,
        &weight[..block_weights],
        out,
        MP0B_NUM_FEATURES,
        row_len,
        path_weight,
        0.0,
    );

    let mut vector_input = vec![0.0; rows * MP0B_NUM_FEATURES];
    let mut vector_out = vec![0.0; rows * MP0B_NUM_FEATURES];
    for m in 0..vector_equivariance {
        for row in 0..rows {
            let input_row = &input[row * row_len..(row + 1) * row_len];
            let vector_input_row =
                &mut vector_input[row * MP0B_NUM_FEATURES..(row + 1) * MP0B_NUM_FEATURES];
            for feature in 0..MP0B_NUM_FEATURES {
                vector_input_row[feature] =
                    input_row[scalar_len + feature * vector_equivariance + m];
            }
        }
        blas_backend::dense_forward(
            &vector_input,
            rows,
            MP0B_NUM_FEATURES,
            &weight[block_weights..],
            &mut vector_out,
            path_weight,
        );
        for row in 0..rows {
            let out_row = &mut out[row * row_len..(row + 1) * row_len];
            let vector_out_row =
                &vector_out[row * MP0B_NUM_FEATURES..(row + 1) * MP0B_NUM_FEATURES];
            for feature in 0..MP0B_NUM_FEATURES {
                out_row[scalar_len + feature * vector_equivariance + m] = vector_out_row[feature];
            }
        }
    }
}

