fn mp0b_scalar_vector_product_linear_f32(
    input: &[f32],
    weight: &[f32],
    output_mask: &[f32],
    out: &mut [f32],
) {
    let vector_equivariance = 3;
    let scalar_len = MP0B_NUM_FEATURES;
    let vector_len = MP0B_NUM_FEATURES * vector_equivariance;
    let row_len = scalar_len + vector_len;
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    debug_assert_eq!(weight.len(), block_weights * 2);
    debug_assert_eq!(output_mask.len(), row_len);
    debug_assert_eq!(input.len() % row_len, 0);
    debug_assert_eq!(input.len(), out.len());
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if output_mask.iter().all(|&mask| mask == 1.0) && input.len() / row_len >= 16 {
        mp0b_scalar_vector_product_linear_blas_f32(input, weight, out, input.len() / row_len, 1.0);
        return;
    }
    for (input_row, out_row) in input.chunks(row_len).zip(out.chunks_mut(row_len)) {
        for out_feature in 0..MP0B_NUM_FEATURES {
            let mut value = 0.0_f32;
            for in_feature in 0..MP0B_NUM_FEATURES {
                value +=
                    input_row[in_feature] * weight[in_feature * MP0B_NUM_FEATURES + out_feature];
            }
            out_row[out_feature] = value * output_mask[out_feature];
        }
        for out_feature in 0..MP0B_NUM_FEATURES {
            for m in 0..vector_equivariance {
                let out_index = scalar_len + out_feature * vector_equivariance + m;
                let mut value = 0.0_f32;
                for in_feature in 0..MP0B_NUM_FEATURES {
                    let in_index = scalar_len + in_feature * vector_equivariance + m;
                    let weight_index = block_weights + in_feature * MP0B_NUM_FEATURES + out_feature;
                    value += input_row[in_index] * weight[weight_index];
                }
                out_row[out_index] = value * output_mask[out_index];
            }
        }
    }
}

