fn mp0b_scalar_residual_skip(
    input: &[f64],
    node_attrs: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    out: &mut [f64],
) {
    let input_row_len = MP0B_PRODUCT0_ROW_LEN;
    let path_weight = 1.0 / ((MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS) as f64).sqrt();
    debug_assert_eq!(
        weight.len(),
        MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES
    );
    debug_assert_eq!(output_mask.len(), MP0B_NUM_FEATURES);
    debug_assert_eq!(input.len() % input_row_len, 0);
    let num_nodes = input.len() / input_row_len;
    debug_assert_eq!(node_attrs.len(), num_nodes * MP0B_NUM_ELEMENTS);
    debug_assert_eq!(out.len(), num_nodes * MP0B_NUM_FEATURES);
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if num_nodes >= blas_dispatch_threshold()
        && mp0b_scalar_residual_skip_blas(input, node_attrs, weight, output_mask, out, num_nodes)
    {
        return;
    }
    for node in 0..num_nodes {
        let input_row = &input[node * input_row_len..(node + 1) * input_row_len];
        let attr_row = &node_attrs[node * MP0B_NUM_ELEMENTS..(node + 1) * MP0B_NUM_ELEMENTS];
        let out_row = &mut out[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
        let active_type = active_one_hot_type(attr_row);
        for out_feature in 0..MP0B_NUM_FEATURES {
            let mut value = 0.0;
            for (in_feature, &input_value) in input_row.iter().enumerate().take(MP0B_NUM_FEATURES) {
                if let Some((type_id, attr)) = active_type {
                    let weight_index = (in_feature * MP0B_NUM_ELEMENTS + type_id)
                        * MP0B_NUM_FEATURES
                        + out_feature;
                    value += input_value * attr * weight[weight_index];
                } else {
                    for (type_id, &attr) in attr_row.iter().enumerate() {
                        if attr != 0.0 {
                            let weight_index = (in_feature * MP0B_NUM_ELEMENTS + type_id)
                                * MP0B_NUM_FEATURES
                                + out_feature;
                            value += input_value * attr * weight[weight_index];
                        }
                    }
                }
            }
            out_row[out_feature] = value * path_weight * output_mask[out_feature];
        }
    }
}

fn mp0b_scalar_residual_skip_vjp_input(
    node_attrs: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    bar_out: &[f64],
    bar_input: &mut [f64],
) {
    let input_row_len = MP0B_PRODUCT0_ROW_LEN;
    let path_weight = 1.0 / ((MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS) as f64).sqrt();
    debug_assert_eq!(
        weight.len(),
        MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES
    );
    debug_assert_eq!(output_mask.len(), MP0B_NUM_FEATURES);
    debug_assert_eq!(bar_input.len() % input_row_len, 0);
    let num_nodes = bar_input.len() / input_row_len;
    debug_assert_eq!(node_attrs.len(), num_nodes * MP0B_NUM_ELEMENTS);
    debug_assert_eq!(bar_out.len(), num_nodes * MP0B_NUM_FEATURES);
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if num_nodes >= blas_dispatch_threshold()
        && mp0b_scalar_residual_skip_vjp_input_blas(
            node_attrs,
            weight,
            output_mask,
            bar_out,
            bar_input,
            num_nodes,
        )
    {
        return;
    }
    for node in 0..num_nodes {
        let attr_row = &node_attrs[node * MP0B_NUM_ELEMENTS..(node + 1) * MP0B_NUM_ELEMENTS];
        let bar_out_row = &bar_out[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
        let bar_input_row = &mut bar_input[node * input_row_len..(node + 1) * input_row_len];
        let active_type = active_one_hot_type(attr_row);
        for out_feature in 0..MP0B_NUM_FEATURES {
            let bar = bar_out_row[out_feature] * path_weight * output_mask[out_feature];
            for (in_feature, bar_input_value) in
                bar_input_row.iter_mut().enumerate().take(MP0B_NUM_FEATURES)
            {
                if let Some((type_id, attr)) = active_type {
                    let weight_index = (in_feature * MP0B_NUM_ELEMENTS + type_id)
                        * MP0B_NUM_FEATURES
                        + out_feature;
                    *bar_input_value += bar * attr * weight[weight_index];
                } else {
                    for (type_id, &attr) in attr_row.iter().enumerate() {
                        if attr != 0.0 {
                            let weight_index = (in_feature * MP0B_NUM_ELEMENTS + type_id)
                                * MP0B_NUM_FEATURES
                                + out_feature;
                            *bar_input_value += bar * attr * weight[weight_index];
                        }
                    }
                }
            }
        }
    }
}

