fn mp0b_hidden_message_selector(
    input: &[f64],
    node_attrs: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    out: &mut [f64],
) {
    let block_dims = [1, 3, 5, 7];
    let path_weights = [
        1.0 / ((MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS) as f64).sqrt(),
        0.016_227_837_090_296_83,
        0.020_950_047_598_562_217,
        0.024_788_430_610_565_716,
    ];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES;
    debug_assert_eq!(weight.len(), block_weights * block_dims.len());
    debug_assert_eq!(output_mask.len(), MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(input.len() % MP0B_HIDDEN_ROW_LEN, 0);
    debug_assert_eq!(input.len(), out.len());
    let num_nodes = input.len() / MP0B_HIDDEN_ROW_LEN;
    debug_assert_eq!(node_attrs.len(), num_nodes * MP0B_NUM_ELEMENTS);
    let mask_is_identity = output_mask.iter().all(|&mask| mask == 1.0);
    #[cfg(all(
        feature = "parallel",
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ))]
    if rayon::current_num_threads() > 1
        && mace_openblas_threads_is_one()
        && num_nodes >= 512
        && mp0b_hidden_message_selector_parallel_openblas(
            input,
            node_attrs,
            weight,
            output_mask,
            mask_is_identity,
            out,
            num_nodes,
        )
    {
        return;
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if num_nodes >= blas_dispatch_threshold()
        && mp0b_hidden_message_selector_blas(
            input,
            node_attrs,
            weight,
            output_mask,
            mask_is_identity,
            out,
            num_nodes,
        )
    {
        return;
    }
    let mut accum = [0.0; MP0B_NUM_FEATURES];
    for node in 0..num_nodes {
        let input_row = &input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let attr_row = &node_attrs[node * MP0B_NUM_ELEMENTS..(node + 1) * MP0B_NUM_ELEMENTS];
        let out_row = &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let active_type = active_one_hot_type(attr_row);
        let mut block_offset = 0;
        for (block, &component_dim) in block_dims.iter().enumerate() {
            let block_scale = path_weights[block] / (component_dim as f64).sqrt();
            let weight_offset = block * block_weights;
            for component in 0..component_dim {
                accum.fill(0.0);
                if let Some((type_id, attr)) = active_type {
                    for in_feature in 0..MP0B_NUM_FEATURES {
                        let input_value =
                            input_row[block_offset + in_feature * component_dim + component];
                        if input_value == 0.0 {
                            continue;
                        }
                        let weight_row_offset = weight_offset
                            + (in_feature * MP0B_NUM_ELEMENTS + type_id) * MP0B_NUM_FEATURES;
                        let weight_row =
                            &weight[weight_row_offset..weight_row_offset + MP0B_NUM_FEATURES];
                        let scale = input_value * attr;
                        for (value, &weight_value) in accum.iter_mut().zip(weight_row) {
                            *value += scale * weight_value;
                        }
                    }
                } else {
                    for in_feature in 0..MP0B_NUM_FEATURES {
                        let input_value =
                            input_row[block_offset + in_feature * component_dim + component];
                        if input_value == 0.0 {
                            continue;
                        }
                        for (type_id, &attr) in attr_row.iter().enumerate() {
                            if attr == 0.0 {
                                continue;
                            }
                            let weight_row_offset = weight_offset
                                + (in_feature * MP0B_NUM_ELEMENTS + type_id) * MP0B_NUM_FEATURES;
                            let weight_row =
                                &weight[weight_row_offset..weight_row_offset + MP0B_NUM_FEATURES];
                            let scale = input_value * attr;
                            for (value, &weight_value) in accum.iter_mut().zip(weight_row) {
                                *value += scale * weight_value;
                            }
                        }
                    }
                }
                for (out_feature, &value) in accum.iter().enumerate() {
                    let out_index = block_offset + out_feature * component_dim + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[out_index]
                    };
                    out_row[out_index] = value * block_scale * mask;
                }
            }
            block_offset += MP0B_NUM_FEATURES * component_dim;
        }
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
fn mp0b_hidden_message_selector_blas(
    input: &[f64],
    node_attrs: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    mask_is_identity: bool,
    out: &mut [f64],
    num_nodes: usize,
) -> bool {
    let Ok(active_elements) = active_unit_one_hot_elements(
        node_attrs,
        num_nodes,
        MP0B_NUM_ELEMENTS,
        "mace_mp0b_hidden_message_selector node_attrs",
    ) else {
        return false;
    };
    let groups = nodes_by_element(&active_elements, MP0B_NUM_ELEMENTS);
    let max_group_len = groups.iter().map(Vec::len).max().unwrap_or(0);
    if max_group_len == 0 {
        out.fill(0.0);
        return true;
    }

    let block_dims = [1, 3, 5, 7];
    let path_weights = [
        1.0 / ((MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS) as f64).sqrt(),
        0.016_227_837_090_296_83,
        0.020_950_047_598_562_217,
        0.024_788_430_610_565_716,
    ];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES;
    let mut packed_weight = vec![0.0; MP0B_NUM_FEATURES * MP0B_NUM_FEATURES];
    let mut component_input = vec![0.0; max_group_len * MP0B_NUM_FEATURES];
    let mut component_out = vec![0.0; max_group_len * MP0B_NUM_FEATURES];
    out.fill(0.0);
    let mut block_offset = 0;
    for (block, &component_dim) in block_dims.iter().enumerate() {
        let block_scale = path_weights[block] / (component_dim as f64).sqrt();
        let weight_offset = block * block_weights;
        for (type_id, nodes) in groups.iter().enumerate() {
            if nodes.is_empty() {
                continue;
            }
            pack_hidden_selector_weight(weight, weight_offset, type_id, &mut packed_weight);
            let rows = nodes.len();
            let component_input = &mut component_input[..rows * MP0B_NUM_FEATURES];
            let component_out = &mut component_out[..rows * MP0B_NUM_FEATURES];
            for component in 0..component_dim {
                for (row, &node) in nodes.iter().enumerate() {
                    let input_row =
                        &input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                    let component_input_row = &mut component_input
                        [row * MP0B_NUM_FEATURES..(row + 1) * MP0B_NUM_FEATURES];
                    for feature in 0..MP0B_NUM_FEATURES {
                        component_input_row[feature] =
                            input_row[block_offset + feature * component_dim + component];
                    }
                }
                blas_backend::dense_forward(
                    component_input,
                    rows,
                    MP0B_NUM_FEATURES,
                    &packed_weight,
                    component_out,
                    block_scale,
                );
                for (row, &node) in nodes.iter().enumerate() {
                    let out_row =
                        &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                    let component_out_row =
                        &component_out[row * MP0B_NUM_FEATURES..(row + 1) * MP0B_NUM_FEATURES];
                    for (feature, &component_value) in component_out_row.iter().enumerate() {
                        let out_index = block_offset + feature * component_dim + component;
                        let mask = if mask_is_identity {
                            1.0
                        } else {
                            output_mask[out_index]
                        };
                        out_row[out_index] = component_value * mask;
                    }
                }
            }
        }
        block_offset += MP0B_NUM_FEATURES * component_dim;
    }
    true
}

#[cfg(all(
    feature = "parallel",
    feature = "openblas",
    target_os = "linux",
    any(target_arch = "x86_64", target_arch = "aarch64")
))]
struct SelectorComponentF64 {
    block_offset: usize,
    component_dim: usize,
    component: usize,
    nodes: Vec<usize>,
    values: Vec<f64>,
}

#[cfg(all(
    feature = "parallel",
    feature = "openblas",
    target_os = "linux",
    any(target_arch = "x86_64", target_arch = "aarch64")
))]
#[allow(clippy::too_many_arguments)]
fn mp0b_hidden_message_selector_parallel_openblas(
    input: &[f64],
    node_attrs: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    mask_is_identity: bool,
    out: &mut [f64],
    num_nodes: usize,
) -> bool {
    let Ok(active_elements) = active_unit_one_hot_elements(
        node_attrs,
        num_nodes,
        MP0B_NUM_ELEMENTS,
        "mace_mp0b_hidden_message_selector_parallel node_attrs",
    ) else {
        return false;
    };
    let groups = nodes_by_element(&active_elements, MP0B_NUM_ELEMENTS);
    let block_dims = [1, 3, 5, 7];
    let path_weights = [
        1.0 / ((MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS) as f64).sqrt(),
        0.016_227_837_090_296_83,
        0.020_950_047_598_562_217,
        0.024_788_430_610_565_716,
    ];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES;
    let mut task_specs = Vec::new();
    let mut block_offset = 0;
    for (block, &component_dim) in block_dims.iter().enumerate() {
        for (type_id, nodes) in groups.iter().enumerate() {
            if nodes.is_empty() {
                continue;
            }
            for component in 0..component_dim {
                task_specs.push((type_id, block, block_offset, component_dim, component));
            }
        }
        block_offset += MP0B_NUM_FEATURES * component_dim;
    }

    let components = task_specs
        .into_par_iter()
        .map(|(type_id, block, block_offset, component_dim, component)| {
            let nodes = &groups[type_id];
            let rows = nodes.len();
            let block_scale = path_weights[block] / (component_dim as f64).sqrt();
            let weight_offset = block * block_weights;
            let mut packed_weight = vec![0.0; MP0B_NUM_FEATURES * MP0B_NUM_FEATURES];
            pack_hidden_selector_weight(weight, weight_offset, type_id, &mut packed_weight);
            let mut component_input = vec![0.0; rows * MP0B_NUM_FEATURES];
            for (row, &node) in nodes.iter().enumerate() {
                let input_row =
                    &input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                let component_input_row =
                    &mut component_input[row * MP0B_NUM_FEATURES..(row + 1) * MP0B_NUM_FEATURES];
                for feature in 0..MP0B_NUM_FEATURES {
                    component_input_row[feature] =
                        input_row[block_offset + feature * component_dim + component];
                }
            }
            let mut values = vec![0.0; rows * MP0B_NUM_FEATURES];
            blas_backend::dense_forward(
                &component_input,
                rows,
                MP0B_NUM_FEATURES,
                &packed_weight,
                &mut values,
                block_scale,
            );
            SelectorComponentF64 {
                block_offset,
                component_dim,
                component,
                nodes: nodes.clone(),
                values,
            }
        })
        .collect::<Vec<_>>();

    out.fill(0.0);
    for component_result in components {
        for (row, &node) in component_result.nodes.iter().enumerate() {
            let out_row = &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
            let component_row =
                &component_result.values[row * MP0B_NUM_FEATURES..(row + 1) * MP0B_NUM_FEATURES];
            for (feature, &component_value) in component_row.iter().enumerate() {
                let out_index = component_result.block_offset
                    + feature * component_result.component_dim
                    + component_result.component;
                let mask = if mask_is_identity {
                    1.0
                } else {
                    output_mask[out_index]
                };
                out_row[out_index] = component_value * mask;
            }
        }
    }
    true
}

fn mp0b_hidden_message_selector_vjp_input_from_feature_major(
    node_attrs: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    bar_out_feature_major: &[f64],
    bar_input: &mut [f64],
) {
    let block_dims = [1, 3, 5, 7];
    let path_weights = [
        1.0 / ((MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS) as f64).sqrt(),
        0.016_227_837_090_296_83,
        0.020_950_047_598_562_217,
        0.024_788_430_610_565_716,
    ];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES;
    debug_assert_eq!(weight.len(), block_weights * block_dims.len());
    debug_assert_eq!(output_mask.len(), MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(bar_input.len() % MP0B_HIDDEN_ROW_LEN, 0);
    debug_assert_eq!(bar_out_feature_major.len(), bar_input.len());
    let num_nodes = bar_input.len() / MP0B_HIDDEN_ROW_LEN;
    debug_assert_eq!(node_attrs.len(), num_nodes * MP0B_NUM_ELEMENTS);
    let mask_is_identity = output_mask.iter().all(|&mask| mask == 1.0);
    #[cfg(all(
        feature = "parallel",
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ))]
    if rayon::current_num_threads() > 1
        && mace_openblas_threads_is_one()
        && num_nodes >= 512
        && mp0b_hidden_message_selector_vjp_input_from_feature_major_parallel_openblas(
            node_attrs,
            weight,
            output_mask,
            mask_is_identity,
            bar_out_feature_major,
            bar_input,
            num_nodes,
        )
    {
        return;
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if num_nodes >= blas_dispatch_threshold()
        && mp0b_hidden_message_selector_vjp_input_from_feature_major_blas(
            node_attrs,
            weight,
            output_mask,
            mask_is_identity,
            bar_out_feature_major,
            bar_input,
            num_nodes,
        )
    {
        return;
    }
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1
        && rayon::current_thread_index().is_none()
        && num_nodes >= 16
    {
        bar_input
            .par_chunks_mut(MP0B_HIDDEN_ROW_LEN)
            .enumerate()
            .for_each(|(node, bar_input_row)| {
                let attr_row =
                    &node_attrs[node * MP0B_NUM_ELEMENTS..(node + 1) * MP0B_NUM_ELEMENTS];
                let bar_out_row = &bar_out_feature_major
                    [node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                let active_type = active_one_hot_type(attr_row);
                let mut bar_values = [0.0; MP0B_NUM_FEATURES];
                let mut block_offset = 0;
                let mut component_offset = 0;
                for (block, &component_dim) in block_dims.iter().enumerate() {
                    let block_scale = path_weights[block] / (component_dim as f64).sqrt();
                    let weight_offset = block * block_weights;
                    for component in 0..component_dim {
                        for (out_feature, bar_value) in bar_values.iter_mut().enumerate() {
                            let hidden_index =
                                block_offset + out_feature * component_dim + component;
                            let feature_major_index =
                                out_feature * MP0B_SH_DIM + component_offset + component;
                            let mask = if mask_is_identity {
                                1.0
                            } else {
                                output_mask[hidden_index]
                            };
                            *bar_value = bar_out_row[feature_major_index] * block_scale * mask;
                        }
                        if let Some((type_id, attr)) = active_type {
                            for in_feature in 0..MP0B_NUM_FEATURES {
                                let weight_row_offset = weight_offset
                                    + (in_feature * MP0B_NUM_ELEMENTS + type_id)
                                        * MP0B_NUM_FEATURES;
                                let weight_row = &weight
                                    [weight_row_offset..weight_row_offset + MP0B_NUM_FEATURES];
                                let mut value = 0.0;
                                for (&bar_value, &weight_value) in bar_values.iter().zip(weight_row)
                                {
                                    value += bar_value * weight_value;
                                }
                                let input_index =
                                    block_offset + in_feature * component_dim + component;
                                bar_input_row[input_index] += attr * value;
                            }
                        } else {
                            for in_feature in 0..MP0B_NUM_FEATURES {
                                let mut value = 0.0;
                                for (type_id, &attr) in attr_row.iter().enumerate() {
                                    if attr == 0.0 {
                                        continue;
                                    }
                                    let weight_row_offset = weight_offset
                                        + (in_feature * MP0B_NUM_ELEMENTS + type_id)
                                            * MP0B_NUM_FEATURES;
                                    let weight_row = &weight
                                        [weight_row_offset..weight_row_offset + MP0B_NUM_FEATURES];
                                    for (&bar_value, &weight_value) in
                                        bar_values.iter().zip(weight_row)
                                    {
                                        value += attr * bar_value * weight_value;
                                    }
                                }
                                let input_index =
                                    block_offset + in_feature * component_dim + component;
                                bar_input_row[input_index] += value;
                            }
                        }
                    }
                    block_offset += MP0B_NUM_FEATURES * component_dim;
                    component_offset += component_dim;
                }
            });
        return;
    }
    let mut bar_values = [0.0; MP0B_NUM_FEATURES];
    for node in 0..num_nodes {
        let attr_row = &node_attrs[node * MP0B_NUM_ELEMENTS..(node + 1) * MP0B_NUM_ELEMENTS];
        let bar_out_row =
            &bar_out_feature_major[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let bar_input_row =
            &mut bar_input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let active_type = active_one_hot_type(attr_row);
        let mut block_offset = 0;
        let mut component_offset = 0;
        for (block, &component_dim) in block_dims.iter().enumerate() {
            let block_scale = path_weights[block] / (component_dim as f64).sqrt();
            let weight_offset = block * block_weights;
            for component in 0..component_dim {
                for (out_feature, bar_value) in bar_values.iter_mut().enumerate() {
                    let hidden_index = block_offset + out_feature * component_dim + component;
                    let feature_major_index =
                        out_feature * MP0B_SH_DIM + component_offset + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[hidden_index]
                    };
                    *bar_value = bar_out_row[feature_major_index] * block_scale * mask;
                }
                if let Some((type_id, attr)) = active_type {
                    for in_feature in 0..MP0B_NUM_FEATURES {
                        let weight_row_offset = weight_offset
                            + (in_feature * MP0B_NUM_ELEMENTS + type_id) * MP0B_NUM_FEATURES;
                        let weight_row =
                            &weight[weight_row_offset..weight_row_offset + MP0B_NUM_FEATURES];
                        let mut value = 0.0;
                        for (&bar_value, &weight_value) in bar_values.iter().zip(weight_row) {
                            value += bar_value * weight_value;
                        }
                        let input_index = block_offset + in_feature * component_dim + component;
                        bar_input_row[input_index] += attr * value;
                    }
                } else {
                    for in_feature in 0..MP0B_NUM_FEATURES {
                        let mut value = 0.0;
                        for (type_id, &attr) in attr_row.iter().enumerate() {
                            if attr == 0.0 {
                                continue;
                            }
                            let weight_row_offset = weight_offset
                                + (in_feature * MP0B_NUM_ELEMENTS + type_id) * MP0B_NUM_FEATURES;
                            let weight_row =
                                &weight[weight_row_offset..weight_row_offset + MP0B_NUM_FEATURES];
                            for (&bar_value, &weight_value) in bar_values.iter().zip(weight_row) {
                                value += attr * bar_value * weight_value;
                            }
                        }
                        let input_index = block_offset + in_feature * component_dim + component;
                        bar_input_row[input_index] += value;
                    }
                }
            }
            block_offset += MP0B_NUM_FEATURES * component_dim;
            component_offset += component_dim;
        }
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
#[allow(clippy::too_many_arguments)]
fn mp0b_hidden_message_selector_vjp_input_from_feature_major_blas(
    node_attrs: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    mask_is_identity: bool,
    bar_out_feature_major: &[f64],
    bar_input: &mut [f64],
    num_nodes: usize,
) -> bool {
    let Ok(active_elements) = active_unit_one_hot_elements(
        node_attrs,
        num_nodes,
        MP0B_NUM_ELEMENTS,
        "mace_mp0b_hidden_message_selector_vjp node_attrs",
    ) else {
        return false;
    };
    let groups = nodes_by_element(&active_elements, MP0B_NUM_ELEMENTS);
    let max_group_len = groups.iter().map(Vec::len).max().unwrap_or(0);
    if max_group_len == 0 {
        return true;
    }

    let block_dims = [1, 3, 5, 7];
    let path_weights = [
        1.0 / ((MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS) as f64).sqrt(),
        0.016_227_837_090_296_83,
        0.020_950_047_598_562_217,
        0.024_788_430_610_565_716,
    ];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES;
    let mut packed_weight = vec![0.0; MP0B_NUM_FEATURES * MP0B_NUM_FEATURES];
    let mut component_bar_out = vec![0.0; max_group_len * MP0B_NUM_FEATURES];
    let mut component_bar_input = vec![0.0; max_group_len * MP0B_NUM_FEATURES];
    let mut block_offset = 0;
    let mut component_offset = 0;
    for (block, &component_dim) in block_dims.iter().enumerate() {
        let block_scale = path_weights[block] / (component_dim as f64).sqrt();
        let weight_offset = block * block_weights;
        for (type_id, nodes) in groups.iter().enumerate() {
            if nodes.is_empty() {
                continue;
            }
            pack_hidden_selector_weight(weight, weight_offset, type_id, &mut packed_weight);
            let rows = nodes.len();
            let component_bar_out = &mut component_bar_out[..rows * MP0B_NUM_FEATURES];
            let component_bar_input = &mut component_bar_input[..rows * MP0B_NUM_FEATURES];
            for component in 0..component_dim {
                for (row, &node) in nodes.iter().enumerate() {
                    let bar_out_row = &bar_out_feature_major
                        [node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                    let component_bar_out_row = &mut component_bar_out
                        [row * MP0B_NUM_FEATURES..(row + 1) * MP0B_NUM_FEATURES];
                    for (feature, component_bar_value) in
                        component_bar_out_row.iter_mut().enumerate()
                    {
                        let hidden_index = block_offset + feature * component_dim + component;
                        let feature_major_index =
                            feature * MP0B_SH_DIM + component_offset + component;
                        let mask = if mask_is_identity {
                            1.0
                        } else {
                            output_mask[hidden_index]
                        };
                        *component_bar_value =
                            bar_out_row[feature_major_index] * block_scale * mask;
                    }
                }
                component_bar_input.fill(0.0);
                blas_backend::dense_vjp_input(
                    rows,
                    MP0B_NUM_FEATURES,
                    &packed_weight,
                    component_bar_out,
                    component_bar_input,
                    1.0,
                );
                for (row, &node) in nodes.iter().enumerate() {
                    let bar_input_row = &mut bar_input
                        [node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                    let component_bar_input_row = &component_bar_input
                        [row * MP0B_NUM_FEATURES..(row + 1) * MP0B_NUM_FEATURES];
                    for feature in 0..MP0B_NUM_FEATURES {
                        bar_input_row[block_offset + feature * component_dim + component] +=
                            component_bar_input_row[feature];
                    }
                }
            }
        }
        block_offset += MP0B_NUM_FEATURES * component_dim;
        component_offset += component_dim;
    }
    true
}

fn mp0b_hidden_message_selector_f32(
    input: &[f32],
    node_attrs: &[f32],
    weight: &[f32],
    output_mask: &[f32],
    out: &mut [f32],
) {
    let block_dims = [1, 3, 5, 7];
    let path_weights = [
        1.0 / ((MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS) as f32).sqrt(),
        0.016_227_837_f32,
        0.020_950_048_f32,
        0.024_788_43_f32,
    ];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES;
    debug_assert_eq!(weight.len(), block_weights * block_dims.len());
    debug_assert_eq!(output_mask.len(), MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(input.len() % MP0B_HIDDEN_ROW_LEN, 0);
    debug_assert_eq!(input.len(), out.len());
    let num_nodes = input.len() / MP0B_HIDDEN_ROW_LEN;
    debug_assert_eq!(node_attrs.len(), num_nodes * MP0B_NUM_ELEMENTS);
    let mask_is_identity = output_mask.iter().all(|&mask| mask == 1.0);
    #[cfg(all(
        feature = "parallel",
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ))]
    if rayon::current_num_threads() > 1
        && mace_openblas_threads_is_one()
        && num_nodes >= 512
        && mp0b_hidden_message_selector_parallel_openblas_f32(
            input,
            node_attrs,
            weight,
            output_mask,
            mask_is_identity,
            out,
            num_nodes,
        )
    {
        return;
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if num_nodes >= 16
        && mp0b_hidden_message_selector_blas_f32(
            input,
            node_attrs,
            weight,
            output_mask,
            mask_is_identity,
            out,
            num_nodes,
        )
    {
        return;
    }
    let mut accum = [0.0_f32; MP0B_NUM_FEATURES];
    for node in 0..num_nodes {
        let input_row = &input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let attr_row = &node_attrs[node * MP0B_NUM_ELEMENTS..(node + 1) * MP0B_NUM_ELEMENTS];
        let out_row = &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let active_type = active_one_hot_type_f32(attr_row);
        let mut block_offset = 0;
        for (block, &component_dim) in block_dims.iter().enumerate() {
            let block_scale = path_weights[block] / (component_dim as f32).sqrt();
            let weight_offset = block * block_weights;
            for component in 0..component_dim {
                accum.fill(0.0);
                if let Some((type_id, attr)) = active_type {
                    for in_feature in 0..MP0B_NUM_FEATURES {
                        let input_value =
                            input_row[block_offset + in_feature * component_dim + component];
                        if input_value == 0.0 {
                            continue;
                        }
                        let weight_row_offset = weight_offset
                            + (in_feature * MP0B_NUM_ELEMENTS + type_id) * MP0B_NUM_FEATURES;
                        let weight_row =
                            &weight[weight_row_offset..weight_row_offset + MP0B_NUM_FEATURES];
                        let scale = input_value * attr;
                        for (value, &weight_value) in accum.iter_mut().zip(weight_row) {
                            *value += scale * weight_value;
                        }
                    }
                } else {
                    for in_feature in 0..MP0B_NUM_FEATURES {
                        let input_value =
                            input_row[block_offset + in_feature * component_dim + component];
                        if input_value == 0.0 {
                            continue;
                        }
                        for (type_id, &attr) in attr_row.iter().enumerate() {
                            if attr == 0.0 {
                                continue;
                            }
                            let weight_row_offset = weight_offset
                                + (in_feature * MP0B_NUM_ELEMENTS + type_id) * MP0B_NUM_FEATURES;
                            let weight_row =
                                &weight[weight_row_offset..weight_row_offset + MP0B_NUM_FEATURES];
                            let scale = input_value * attr;
                            for (value, &weight_value) in accum.iter_mut().zip(weight_row) {
                                *value += scale * weight_value;
                            }
                        }
                    }
                }
                for (out_feature, &value) in accum.iter().enumerate() {
                    let out_index = block_offset + out_feature * component_dim + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[out_index]
                    };
                    out_row[out_index] = value * block_scale * mask;
                }
            }
            block_offset += MP0B_NUM_FEATURES * component_dim;
        }
    }
}

