#[allow(dead_code)]
fn large_hidden_linear_avg(
    input: &[f64],
    avg_num_neighbors: f64,
    weight: &[f64],
    output_mask: &[f64],
    out: &mut [f64],
) {
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if output_mask.iter().all(|&mask| mask == 1.0)
        && input.len().is_multiple_of(MP0B_HIDDEN_ROW_LEN)
        && input.len() / MP0B_HIDDEN_ROW_LEN >= blas_dispatch_threshold()
    {
        large_hidden_linear_avg_blas(
            input,
            avg_num_neighbors,
            weight,
            out,
            input.len() / MP0B_HIDDEN_ROW_LEN,
        );
        return;
    }
    let block_dims = [1, 3, 5, 7];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
    debug_assert_eq!(weight.len(), block_weights * block_dims.len());
    debug_assert_eq!(output_mask.len(), MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(input.len() % MP0B_HIDDEN_ROW_LEN, 0);
    debug_assert_eq!(input.len(), out.len());
    debug_assert!(avg_num_neighbors.is_finite() && avg_num_neighbors > 0.0);
    let num_nodes = input.len() / MP0B_HIDDEN_ROW_LEN;
    let mask_is_identity = output_mask.iter().all(|&mask| mask == 1.0);
    for node in 0..num_nodes {
        let input_row = &input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let out_row = &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let mut block_offset = 0;
        let mut accum = [0.0; MP0B_NUM_FEATURES];
        for (block, &component_dim) in block_dims.iter().enumerate() {
            let weight_offset = block * block_weights;
            for component in 0..component_dim {
                accum.fill(0.0);
                for in_feature in 0..MP0B_NUM_FEATURES {
                    let input_index = block_offset + in_feature * component_dim + component;
                    let input_value = input_row[input_index];
                    if input_value == 0.0 {
                        continue;
                    }
                    let scale = input_value * path_weight;
                    let weight_row = &weight[weight_offset + in_feature * MP0B_NUM_FEATURES
                        ..weight_offset + (in_feature + 1) * MP0B_NUM_FEATURES];
                    for (value, &weight_value) in accum.iter_mut().zip(weight_row) {
                        *value += scale * weight_value;
                    }
                }
                for (out_feature, &value) in accum.iter().enumerate() {
                    let out_index = block_offset + out_feature * component_dim + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[out_index]
                    };
                    out_row[out_index] = value * mask / avg_num_neighbors;
                }
            }
            block_offset += MP0B_NUM_FEATURES * component_dim;
        }
    }
}

#[allow(dead_code)]
fn large_hidden_linear_avg_vjp_input(
    avg_num_neighbors: f64,
    weight: &[f64],
    output_mask: &[f64],
    bar_out: &[f64],
    bar_input: &mut [f64],
) {
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if output_mask.iter().all(|&mask| mask == 1.0)
        && bar_input.len().is_multiple_of(MP0B_HIDDEN_ROW_LEN)
        && bar_input.len() / MP0B_HIDDEN_ROW_LEN >= blas_dispatch_threshold()
    {
        large_hidden_linear_avg_vjp_input_blas(
            avg_num_neighbors,
            weight,
            bar_out,
            bar_input,
            bar_input.len() / MP0B_HIDDEN_ROW_LEN,
        );
        return;
    }
    let block_dims = [1, 3, 5, 7];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
    debug_assert_eq!(weight.len(), block_weights * block_dims.len());
    debug_assert_eq!(output_mask.len(), MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(bar_input.len() % MP0B_HIDDEN_ROW_LEN, 0);
    debug_assert_eq!(bar_out.len(), bar_input.len());
    debug_assert!(avg_num_neighbors.is_finite() && avg_num_neighbors > 0.0);
    let num_nodes = bar_input.len() / MP0B_HIDDEN_ROW_LEN;
    let mask_is_identity = output_mask.iter().all(|&mask| mask == 1.0);
    let mut bar_values = [0.0; MP0B_NUM_FEATURES];
    for node in 0..num_nodes {
        let bar_out_row = &bar_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        if bar_out_row.iter().all(|value| *value == 0.0) {
            continue;
        }
        let bar_input_row =
            &mut bar_input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let mut block_offset = 0;
        for (block, &component_dim) in block_dims.iter().enumerate() {
            let weight_offset = block * block_weights;
            for component in 0..component_dim {
                for (out_feature, bar_value) in bar_values.iter_mut().enumerate() {
                    let out_index = block_offset + out_feature * component_dim + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[out_index]
                    };
                    *bar_value = bar_out_row[out_index] * path_weight * mask / avg_num_neighbors;
                }
                if bar_values.iter().all(|value| *value == 0.0) {
                    continue;
                }
                let active_bar_count = bar_values.iter().filter(|value| **value != 0.0).count();
                if active_bar_count * 4 <= MP0B_NUM_FEATURES {
                    for (out_feature, &bar_value) in bar_values.iter().enumerate() {
                        if bar_value == 0.0 {
                            continue;
                        }
                        for in_feature in 0..MP0B_NUM_FEATURES {
                            let input_index = block_offset + in_feature * component_dim + component;
                            bar_input_row[input_index] += bar_value
                                * weight
                                    [weight_offset + in_feature * MP0B_NUM_FEATURES + out_feature];
                        }
                    }
                } else {
                    for in_feature in 0..MP0B_NUM_FEATURES {
                        let weight_row = &weight[weight_offset + in_feature * MP0B_NUM_FEATURES
                            ..weight_offset + (in_feature + 1) * MP0B_NUM_FEATURES];
                        let mut value = 0.0;
                        for (&bar_value, &weight_value) in bar_values.iter().zip(weight_row) {
                            value += bar_value * weight_value;
                        }
                        let input_index = block_offset + in_feature * component_dim + component;
                        bar_input_row[input_index] += value;
                    }
                }
            }
            block_offset += MP0B_NUM_FEATURES * component_dim;
        }
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
fn large_hidden_linear_avg_blas(
    input: &[f64],
    avg_num_neighbors: f64,
    weight: &[f64],
    out: &mut [f64],
    rows: usize,
) {
    let block_dims = [1, 3, 5, 7];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let alpha = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt() / avg_num_neighbors;
    debug_assert_eq!(weight.len(), block_weights * block_dims.len());
    debug_assert_eq!(input.len(), rows * MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(out.len(), input.len());
    debug_assert!(avg_num_neighbors.is_finite() && avg_num_neighbors > 0.0);

    let mut packed_input = vec![0.0; rows * MP0B_NUM_FEATURES];
    let mut packed_out = vec![0.0; rows * MP0B_NUM_FEATURES];
    let mut block_offset = 0;
    for (block, &component_dim) in block_dims.iter().enumerate() {
        let weight_slice = &weight[block * block_weights..(block + 1) * block_weights];
        for component in 0..component_dim {
            for row in 0..rows {
                let input_row = &input[row * MP0B_HIDDEN_ROW_LEN..(row + 1) * MP0B_HIDDEN_ROW_LEN];
                let packed_row =
                    &mut packed_input[row * MP0B_NUM_FEATURES..(row + 1) * MP0B_NUM_FEATURES];
                for feature in 0..MP0B_NUM_FEATURES {
                    packed_row[feature] =
                        input_row[block_offset + feature * component_dim + component];
                }
            }
            blas_backend::dense_forward(
                &packed_input,
                rows,
                MP0B_NUM_FEATURES,
                weight_slice,
                &mut packed_out,
                alpha,
            );
            for row in 0..rows {
                let out_row = &mut out[row * MP0B_HIDDEN_ROW_LEN..(row + 1) * MP0B_HIDDEN_ROW_LEN];
                let packed_row =
                    &packed_out[row * MP0B_NUM_FEATURES..(row + 1) * MP0B_NUM_FEATURES];
                for (feature, &value) in packed_row.iter().enumerate() {
                    out_row[block_offset + feature * component_dim + component] = value;
                }
            }
        }
        block_offset += MP0B_NUM_FEATURES * component_dim;
    }
}

