#[cfg(all(
    feature = "openblas",
    target_os = "linux",
    any(target_arch = "x86_64", target_arch = "aarch64")
))]
fn large_hidden_linear_avg_vjp_input_openblas_notrans_f32(
    avg_num_neighbors: f32,
    weight: &[f32],
    bar_out: &[f32],
    bar_input: &mut [f32],
    rows: usize,
) {
    let trace_timings = mace_trace_timings_enabled();
    let total_start = trace_timings.then(Instant::now);
    let block_dims = [1, 3, 5, 7];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let alpha = 1.0_f32 / (MP0B_NUM_FEATURES as f32).sqrt() / avg_num_neighbors;
    let max_component_dim = block_dims.iter().copied().max().unwrap_or(1);
    let mut packed_bar_out = vec![0.0_f32; rows * max_component_dim * MP0B_NUM_FEATURES];
    let mut packed_bar_input = vec![0.0_f32; rows * max_component_dim * MP0B_NUM_FEATURES];
    let mut transposed_weight = vec![0.0_f32; block_weights];
    let mut block_offset = 0;
    for (block, &component_dim) in block_dims.iter().enumerate() {
        let block_start = trace_timings.then(Instant::now);
        let weight_slice = &weight[block * block_weights..(block + 1) * block_weights];
        for input_feature in 0..MP0B_NUM_FEATURES {
            for output_feature in 0..MP0B_NUM_FEATURES {
                transposed_weight[output_feature * MP0B_NUM_FEATURES + input_feature] =
                    weight_slice[input_feature * MP0B_NUM_FEATURES + output_feature];
            }
        }
        let transpose_ms = block_start.map(mace_trace_elapsed_ms);
        let pack_start = trace_timings.then(Instant::now);
        let packed_rows = rows * component_dim;
        let packed_len = packed_rows * MP0B_NUM_FEATURES;
        let packed_bar_out_block = &mut packed_bar_out[..packed_len];
        for row in 0..rows {
            for component in 0..component_dim {
                let bar_out_row =
                    &bar_out[row * MP0B_HIDDEN_ROW_LEN..(row + 1) * MP0B_HIDDEN_ROW_LEN];
                let packed_row_index = row * component_dim + component;
                let packed_row = &mut packed_bar_out_block[packed_row_index * MP0B_NUM_FEATURES
                    ..(packed_row_index + 1) * MP0B_NUM_FEATURES];
                for feature in 0..MP0B_NUM_FEATURES {
                    packed_row[feature] =
                        bar_out_row[block_offset + feature * component_dim + component];
                }
            }
        }
        let pack_ms = pack_start.map(mace_trace_elapsed_ms);
        let gemm_start = trace_timings.then(Instant::now);
        let packed_bar_input_block = &mut packed_bar_input[..packed_len];
        mace_dense_forward_f32(
            packed_bar_out_block,
            packed_rows,
            MP0B_NUM_FEATURES,
            &transposed_weight,
            packed_bar_input_block,
            alpha,
        );
        let gemm_ms = gemm_start.map(mace_trace_elapsed_ms);
        let unpack_start = trace_timings.then(Instant::now);
        for row in 0..rows {
            for component in 0..component_dim {
                let bar_input_row =
                    &mut bar_input[row * MP0B_HIDDEN_ROW_LEN..(row + 1) * MP0B_HIDDEN_ROW_LEN];
                let packed_row_index = row * component_dim + component;
                let packed_row = &packed_bar_input_block[packed_row_index * MP0B_NUM_FEATURES
                    ..(packed_row_index + 1) * MP0B_NUM_FEATURES];
                for (feature, &value) in packed_row.iter().enumerate() {
                    bar_input_row[block_offset + feature * component_dim + component] += value;
                }
            }
        }
        if let Some(unpack_start) = unpack_start {
            eprintln!(
                "mace_osaka26_f32 hidden_vjp_notrans_block{block}_dim{component_dim}_transpose_ms={:.3} pack_ms={:.3} gemm_ms={:.3} unpack_ms={:.3}",
                transpose_ms.unwrap_or(0.0),
                pack_ms.unwrap_or(0.0),
                gemm_ms.unwrap_or(0.0),
                mace_trace_elapsed_ms(unpack_start)
            );
        }
        block_offset += MP0B_NUM_FEATURES * component_dim;
    }
    if let Some(start) = total_start {
        eprintln!(
            "mace_osaka26_f32 hidden_vjp_notrans_total_ms={:.3}",
            mace_trace_elapsed_ms(start)
        );
    }
}

