fn osaka_scalar_residual_skip_vjp_input(
    node_attrs: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    bar_out: &[f64],
    num_features: usize,
    num_elements: usize,
    bar_input: &mut [f64],
) -> Result<(), MaceLiteError> {
    if num_features == 0
        || num_elements == 0
        || output_mask.len() < num_features
        || weight.len() != num_features * num_elements * num_features
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    if !node_attrs.len().is_multiple_of(num_elements) {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let num_nodes = node_attrs.len() / num_elements;
    if num_nodes == 0
        || !bar_input.len().is_multiple_of(num_nodes)
        || !bar_out.len().is_multiple_of(num_nodes)
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let input_row_len = bar_input.len() / num_nodes;
    let output_row_len = bar_out.len() / num_nodes;
    if input_row_len < num_features || output_row_len != output_mask.len() {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let path_weight = 1.0 / ((num_features * num_elements) as f64).sqrt();
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && num_nodes >= 32 {
        bar_input
            .par_chunks_mut(input_row_len)
            .enumerate()
            .for_each(|(node, bar_input_row)| {
                let attr_row = &node_attrs[node * num_elements..(node + 1) * num_elements];
                let bar_out_row = &bar_out[node * output_row_len..(node + 1) * output_row_len];
                let active_type = active_one_hot_type(attr_row);
                for out_feature in 0..num_features {
                    let bar = bar_out_row[out_feature] * path_weight * output_mask[out_feature];
                    for (in_feature, bar_input_value) in
                        bar_input_row.iter_mut().enumerate().take(num_features)
                    {
                        if let Some((type_id, attr)) = active_type {
                            let weight_index =
                                (in_feature * num_elements + type_id) * num_features + out_feature;
                            *bar_input_value += bar * attr * weight[weight_index];
                        } else {
                            for (type_id, &attr) in attr_row.iter().enumerate() {
                                if attr == 0.0 {
                                    continue;
                                }
                                let weight_index = (in_feature * num_elements + type_id)
                                    * num_features
                                    + out_feature;
                                *bar_input_value += bar * attr * weight[weight_index];
                            }
                        }
                    }
                }
            });
        return Ok(());
    }
    for node in 0..num_nodes {
        let attr_row = &node_attrs[node * num_elements..(node + 1) * num_elements];
        let bar_out_row = &bar_out[node * output_row_len..(node + 1) * output_row_len];
        let bar_input_row = &mut bar_input[node * input_row_len..(node + 1) * input_row_len];
        let active_type = active_one_hot_type(attr_row);
        for out_feature in 0..num_features {
            let bar = bar_out_row[out_feature] * path_weight * output_mask[out_feature];
            for (in_feature, bar_input_value) in
                bar_input_row.iter_mut().enumerate().take(num_features)
            {
                if let Some((type_id, attr)) = active_type {
                    let weight_index =
                        (in_feature * num_elements + type_id) * num_features + out_feature;
                    *bar_input_value += bar * attr * weight[weight_index];
                } else {
                    for (type_id, &attr) in attr_row.iter().enumerate() {
                        if attr == 0.0 {
                            continue;
                        }
                        let weight_index =
                            (in_feature * num_elements + type_id) * num_features + out_feature;
                        *bar_input_value += bar * attr * weight[weight_index];
                    }
                }
            }
        }
    }
    Ok(())
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    )
))]
fn pack_osaka_scalar_skip_type_weight_f32(
    weight: &[f32],
    type_id: usize,
    num_features: usize,
    num_elements: usize,
    packed: &mut [f32],
) {
    debug_assert_eq!(packed.len(), num_features * num_features);
    for in_feature in 0..num_features {
        let source_offset = (in_feature * num_elements + type_id) * num_features;
        let target_offset = in_feature * num_features;
        packed[target_offset..target_offset + num_features]
            .copy_from_slice(&weight[source_offset..source_offset + num_features]);
    }
}

#[cfg(feature = "parallel")]
fn osaka_scalar_residual_skip_node_parallel_f32(
    input: &[f32],
    active_elements: &[usize],
    weight: &[f32],
    output_mask: &[f32],
    config: OsakaScalarSkipConfig,
    out: &mut [f32],
) {
    let input_row_len = config.input_row_len;
    let num_features = config.num_features;
    let num_elements = config.num_elements;
    let output_row_len = output_mask.len();
    let path_weight = 1.0_f32 / ((num_features * num_elements) as f32).sqrt();
    out.par_chunks_mut(output_row_len)
        .zip(input.par_chunks(input_row_len))
        .zip(active_elements.par_iter())
        .for_each(|((out_row, input_row), &type_id)| {
            out_row.fill(0.0);
            for (in_feature, &input_value) in input_row.iter().take(num_features).enumerate() {
                if input_value == 0.0 {
                    continue;
                }
                let weight_offset = (in_feature * num_elements + type_id) * num_features;
                let weight_row = &weight[weight_offset..weight_offset + num_features];
                for (target, &weight_value) in out_row.iter_mut().zip(weight_row) {
                    *target += input_value * weight_value;
                }
            }
            for (target, &mask) in out_row.iter_mut().zip(output_mask) {
                *target *= path_weight * mask;
            }
        });
}

#[cfg(feature = "parallel")]
#[allow(clippy::too_many_arguments)]
fn osaka_scalar_residual_skip_vjp_input_node_parallel_f32(
    active_elements: &[usize],
    weight: &[f32],
    output_mask: &[f32],
    bar_out: &[f32],
    input_row_len: usize,
    output_row_len: usize,
    num_features: usize,
    num_elements: usize,
    bar_input: &mut [f32],
) {
    let path_weight = 1.0_f32 / ((num_features * num_elements) as f32).sqrt();
    bar_input
        .par_chunks_mut(input_row_len)
        .zip(bar_out.par_chunks(output_row_len))
        .zip(active_elements.par_iter())
        .for_each(|((bar_input_row, bar_out_row), &type_id)| {
            for (in_feature, bar_input_value) in
                bar_input_row.iter_mut().enumerate().take(num_features)
            {
                let weight_offset = (in_feature * num_elements + type_id) * num_features;
                let weight_row = &weight[weight_offset..weight_offset + num_features];
                let mut value = 0.0_f32;
                for ((&bar, &mask), &weight_value) in
                    bar_out_row.iter().zip(output_mask).zip(weight_row)
                {
                    value += bar * mask * weight_value;
                }
                *bar_input_value += value * path_weight;
            }
        });
}

#[cfg(all(feature = "parallel", target_arch = "aarch64"))]
#[allow(clippy::too_many_arguments, unsafe_code)]
fn osaka_scalar_residual_skip_vjp_input_node_parallel_neon_f32(
    active_elements: &[usize],
    weight: &[f32],
    bar_out: &[f32],
    input_row_len: usize,
    num_features: usize,
    num_elements: usize,
    bar_input: &mut [f32],
) {
    debug_assert_eq!(num_features, MP0B_NUM_FEATURES);
    let path_weight = 1.0_f32 / ((num_features * num_elements) as f32).sqrt();
    bar_input
        .par_chunks_mut(input_row_len)
        .zip(bar_out.par_chunks(num_features))
        .zip(active_elements.par_iter())
        .for_each(|((bar_input_row, bar_out_row), &type_id)| {
            for (in_feature, bar_input_value) in
                bar_input_row.iter_mut().enumerate().take(MP0B_NUM_FEATURES)
            {
                let weight_offset = (in_feature * num_elements + type_id) * MP0B_NUM_FEATURES;
                let weight_row = &weight[weight_offset..weight_offset + MP0B_NUM_FEATURES];
                // SAFETY: aarch64 guarantees NEON support. Slices are exactly
                // MP0B_NUM_FEATURES long by construction above.
                let value =
                    unsafe { dot_product_128_neon_f32(bar_out_row, weight_row) } * path_weight;
                *bar_input_value += value;
            }
        });
}

#[cfg(all(feature = "parallel", target_arch = "aarch64"))]
#[allow(unsafe_code)]
#[inline(always)]
unsafe fn dot_product_128_neon_f32(lhs: &[f32], rhs: &[f32]) -> f32 {
    use std::arch::aarch64::*;

    debug_assert_eq!(lhs.len(), MP0B_NUM_FEATURES);
    debug_assert_eq!(rhs.len(), MP0B_NUM_FEATURES);
    let mut acc0 = vdupq_n_f32(0.0);
    let mut acc1 = vdupq_n_f32(0.0);
    let mut index = 0;
    while index + 8 <= MP0B_NUM_FEATURES {
        let lhs0 = vld1q_f32(lhs.as_ptr().add(index));
        let rhs0 = vld1q_f32(rhs.as_ptr().add(index));
        let lhs1 = vld1q_f32(lhs.as_ptr().add(index + 4));
        let rhs1 = vld1q_f32(rhs.as_ptr().add(index + 4));
        acc0 = vfmaq_f32(acc0, lhs0, rhs0);
        acc1 = vfmaq_f32(acc1, lhs1, rhs1);
        index += 8;
    }
    vaddvq_f32(vaddq_f32(acc0, acc1))
}

fn osaka_scalar_residual_skip_f32(
    input: &[f32],
    node_attrs: &[f32],
    weight: &[f32],
    output_mask: &[f32],
    config: OsakaScalarSkipConfig,
    out: &mut [f32],
) -> Result<(), MaceLiteError> {
    let input_row_len = config.input_row_len;
    let num_features = config.num_features;
    let num_elements = config.num_elements;
    if num_features == 0
        || num_elements == 0
        || input_row_len < num_features
        || output_mask.len() < num_features
        || !input.len().is_multiple_of(input_row_len)
        || weight.len() != num_features * num_elements * num_features
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let num_nodes = input.len() / input_row_len;
    if node_attrs.len() != num_nodes * num_elements || out.len() != num_nodes * output_mask.len() {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    #[cfg(feature = "parallel")]
    if input_row_len >= num_features && rayon::current_num_threads() > 1 && num_nodes >= 128 {
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            num_elements,
            "osaka_scalar_residual_skip_f32 node_attrs",
        )?;
        osaka_scalar_residual_skip_node_parallel_f32(
            input,
            &active_elements,
            weight,
            output_mask,
            config,
            out,
        );
        return Ok(());
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if input_row_len == num_features && output_mask.len() == num_features && num_nodes >= 512 {
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            num_elements,
            "osaka_scalar_residual_skip_f32 node_attrs",
        )?;
        let active_node_groups = nodes_by_element(&active_elements, num_elements);
        let path_weight = 1.0_f32 / ((num_features * num_elements) as f32).sqrt();
        let mut packed_weight = vec![0.0_f32; num_features * num_features];
        let mut packed_input = Vec::new();
        let mut packed_out = Vec::new();
        out.fill(0.0);
        for (type_id, nodes) in active_node_groups.iter().enumerate() {
            if nodes.is_empty() {
                continue;
            }
            pack_osaka_scalar_skip_type_weight_f32(
                weight,
                type_id,
                num_features,
                num_elements,
                &mut packed_weight,
            );
            packed_input.resize(nodes.len() * num_features, 0.0);
            packed_out.resize(nodes.len() * num_features, 0.0);
            for (row, &node) in nodes.iter().enumerate() {
                packed_input[row * num_features..(row + 1) * num_features].copy_from_slice(
                    &input[node * input_row_len..node * input_row_len + num_features],
                );
            }
            blas_backend::dense_forward_f32(
                &packed_input,
                nodes.len(),
                num_features,
                &packed_weight,
                &mut packed_out,
                path_weight,
            );
            for (row, &node) in nodes.iter().enumerate() {
                let out_row = &mut out[node * output_mask.len()..(node + 1) * output_mask.len()];
                let packed_row = &packed_out[row * num_features..(row + 1) * num_features];
                for (target, (&value, &mask)) in
                    out_row.iter_mut().zip(packed_row.iter().zip(output_mask))
                {
                    *target = value * mask;
                }
            }
        }
        return Ok(());
    }
    out.fill(0.0);
    let path_weight = 1.0_f32 / ((num_features * num_elements) as f32).sqrt();
    for node in 0..num_nodes {
        let input_row = &input[node * input_row_len..(node + 1) * input_row_len];
        let attr_row = &node_attrs[node * num_elements..(node + 1) * num_elements];
        let out_row = &mut out[node * output_mask.len()..(node + 1) * output_mask.len()];
        let active_type = active_one_hot_type_f32(attr_row);
        for out_feature in 0..num_features {
            let mut value = 0.0_f32;
            for (in_feature, &input_value) in input_row.iter().enumerate().take(num_features) {
                if let Some((type_id, attr)) = active_type {
                    let weight_index =
                        (in_feature * num_elements + type_id) * num_features + out_feature;
                    value += input_value * attr * weight[weight_index];
                } else {
                    for (type_id, &attr) in attr_row.iter().enumerate() {
                        if attr == 0.0 {
                            continue;
                        }
                        let weight_index =
                            (in_feature * num_elements + type_id) * num_features + out_feature;
                        value += input_value * attr * weight[weight_index];
                    }
                }
            }
            out_row[out_feature] = value * path_weight * output_mask[out_feature];
        }
    }
    Ok(())
}

fn osaka_scalar_residual_skip_vjp_input_f32(
    node_attrs: &[f32],
    weight: &[f32],
    output_mask: &[f32],
    bar_out: &[f32],
    num_features: usize,
    num_elements: usize,
    bar_input: &mut [f32],
) -> Result<(), MaceLiteError> {
    if num_features == 0
        || num_elements == 0
        || output_mask.len() < num_features
        || weight.len() != num_features * num_elements * num_features
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    if !node_attrs.len().is_multiple_of(num_elements) {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let num_nodes = node_attrs.len() / num_elements;
    if num_nodes == 0
        || !bar_input.len().is_multiple_of(num_nodes)
        || !bar_out.len().is_multiple_of(num_nodes)
    {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    let input_row_len = bar_input.len() / num_nodes;
    let output_row_len = bar_out.len() / num_nodes;
    if input_row_len < num_features || output_row_len != output_mask.len() {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    #[cfg(feature = "parallel")]
    if input_row_len >= num_features && rayon::current_num_threads() > 1 && num_nodes >= 128 {
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            num_elements,
            "osaka_scalar_residual_skip_vjp_input_f32 node_attrs",
        )?;
        #[cfg(target_arch = "aarch64")]
        if num_features == MP0B_NUM_FEATURES
            && output_row_len == MP0B_NUM_FEATURES
            && output_mask.iter().all(|&mask| mask == 1.0)
            && mace_f32_neon_enabled()
        {
            osaka_scalar_residual_skip_vjp_input_node_parallel_neon_f32(
                &active_elements,
                weight,
                bar_out,
                input_row_len,
                num_features,
                num_elements,
                bar_input,
            );
            return Ok(());
        }
        osaka_scalar_residual_skip_vjp_input_node_parallel_f32(
            &active_elements,
            weight,
            output_mask,
            bar_out,
            input_row_len,
            output_row_len,
            num_features,
            num_elements,
            bar_input,
        );
        return Ok(());
    }
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        )
    ))]
    if input_row_len == num_features && output_row_len == num_features && num_nodes >= 512 {
        let active_elements = active_unit_one_hot_elements_f32(
            node_attrs,
            num_nodes,
            num_elements,
            "osaka_scalar_residual_skip_vjp_input_f32 node_attrs",
        )?;
        let active_node_groups = nodes_by_element(&active_elements, num_elements);
        let path_weight = 1.0_f32 / ((num_features * num_elements) as f32).sqrt();
        let mut packed_weight = vec![0.0_f32; num_features * num_features];
        let mut packed_bar_out = Vec::new();
        let mut packed_bar_input = Vec::new();
        for (type_id, nodes) in active_node_groups.iter().enumerate() {
            if nodes.is_empty() {
                continue;
            }
            pack_osaka_scalar_skip_type_weight_f32(
                weight,
                type_id,
                num_features,
                num_elements,
                &mut packed_weight,
            );
            packed_bar_out.resize(nodes.len() * num_features, 0.0);
            packed_bar_input.resize(nodes.len() * num_features, 0.0);
            packed_bar_input.fill(0.0);
            for (row, &node) in nodes.iter().enumerate() {
                let bar_out_row = &bar_out[node * output_row_len..(node + 1) * output_row_len];
                let packed_row = &mut packed_bar_out[row * num_features..(row + 1) * num_features];
                for (target, (&bar, &mask)) in packed_row
                    .iter_mut()
                    .zip(bar_out_row.iter().zip(output_mask))
                {
                    *target = bar * mask;
                }
            }
            blas_backend::dense_vjp_input_f32(
                nodes.len(),
                num_features,
                &packed_weight,
                &packed_bar_out,
                &mut packed_bar_input,
                path_weight,
            );
            for (row, &node) in nodes.iter().enumerate() {
                let bar_input_row =
                    &mut bar_input[node * input_row_len..node * input_row_len + num_features];
                let packed_row = &packed_bar_input[row * num_features..(row + 1) * num_features];
                for (target, &value) in bar_input_row.iter_mut().zip(packed_row) {
                    *target += value;
                }
            }
        }
        return Ok(());
    }
    let path_weight = 1.0_f32 / ((num_features * num_elements) as f32).sqrt();
    for node in 0..num_nodes {
        let attr_row = &node_attrs[node * num_elements..(node + 1) * num_elements];
        let bar_out_row = &bar_out[node * output_row_len..(node + 1) * output_row_len];
        let bar_input_row = &mut bar_input[node * input_row_len..(node + 1) * input_row_len];
        let active_type = active_one_hot_type_f32(attr_row);
        for out_feature in 0..num_features {
            let bar = bar_out_row[out_feature] * path_weight * output_mask[out_feature];
            for (in_feature, bar_input_value) in
                bar_input_row.iter_mut().enumerate().take(num_features)
            {
                if let Some((type_id, attr)) = active_type {
                    let weight_index =
                        (in_feature * num_elements + type_id) * num_features + out_feature;
                    *bar_input_value += bar * attr * weight[weight_index];
                } else {
                    for (type_id, &attr) in attr_row.iter().enumerate() {
                        if attr == 0.0 {
                            continue;
                        }
                        let weight_index =
                            (in_feature * num_elements + type_id) * num_features + out_feature;
                        *bar_input_value += bar * attr * weight[weight_index];
                    }
                }
            }
        }
    }
    Ok(())
}

fn mp0b_layer0_hidden_linear(
    input: &[f64],
    density: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    out: &mut [f64],
) {
    let block_dims = [1, 3, 5, 7];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
    debug_assert_eq!(weight.len(), block_weights * block_dims.len());
    debug_assert_eq!(output_mask.len(), MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(input.len() % MP0B_HIDDEN_ROW_LEN, 0);
    debug_assert_eq!(input.len(), out.len());
    let num_nodes = input.len() / MP0B_HIDDEN_ROW_LEN;
    debug_assert_eq!(density.len(), num_nodes);
    let mask_is_identity = output_mask.iter().all(|&mask| mask == 1.0);
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if num_nodes >= blas_dispatch_threshold() {
        #[cfg(all(
            feature = "parallel",
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ))]
        if rayon::current_num_threads() > 1 && mace_openblas_threads_is_one() && num_nodes >= 64 {
            mp0b_layer0_hidden_linear_parallel_openblas(
                input,
                density,
                weight,
                output_mask,
                mask_is_identity,
                out,
                num_nodes,
            );
            return;
        }
        mp0b_layer0_hidden_linear_blas(
            input,
            density,
            weight,
            output_mask,
            mask_is_identity,
            out,
            num_nodes,
        );
        return;
    }
    for node in 0..num_nodes {
        let input_row = &input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let out_row = &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let density_norm = density[node] + 1.0;
        let mut block_offset = 0;
        let mut accum = [0.0; MP0B_NUM_FEATURES];
        for (block, &component_dim) in block_dims.iter().enumerate() {
            let weight_offset = block * block_weights;
            for component in 0..component_dim {
                accum.fill(0.0);
                for in_feature in 0..MP0B_NUM_FEATURES {
                    let input_index = block_offset + in_feature * component_dim + component;
                    let input_value = input_row[input_index];
                    if input_value == 0.0 {
                        continue;
                    }
                    let scale = input_value * path_weight;
                    let weight_row = &weight[weight_offset + in_feature * MP0B_NUM_FEATURES
                        ..weight_offset + (in_feature + 1) * MP0B_NUM_FEATURES];
                    for (value, &weight_value) in accum.iter_mut().zip(weight_row) {
                        *value += scale * weight_value;
                    }
                }
                for (out_feature, &value) in accum.iter().enumerate() {
                    let out_index = block_offset + out_feature * component_dim + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[out_index]
                    };
                    out_row[out_index] = value * mask / density_norm;
                }
            }
            block_offset += MP0B_NUM_FEATURES * component_dim;
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn mp0b_layer0_hidden_linear_vjp_input_density(
    input: &[f64],
    density: &[f64],
    linear_out: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    bar_out: &[f64],
    bar_input: &mut [f64],
    bar_density: &mut [f64],
) {
    let block_dims = [1, 3, 5, 7];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
    debug_assert_eq!(weight.len(), block_weights * block_dims.len());
    debug_assert_eq!(output_mask.len(), MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(input.len() % MP0B_HIDDEN_ROW_LEN, 0);
    debug_assert_eq!(linear_out.len(), input.len());
    debug_assert_eq!(bar_input.len(), input.len());
    debug_assert_eq!(bar_out.len(), input.len());
    let num_nodes = input.len() / MP0B_HIDDEN_ROW_LEN;
    debug_assert_eq!(density.len(), num_nodes);
    debug_assert_eq!(bar_density.len(), num_nodes);
    let mask_is_identity = output_mask.iter().all(|&mask| mask == 1.0);
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if num_nodes >= blas_dispatch_threshold() {
        #[cfg(all(
            feature = "parallel",
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ))]
        if rayon::current_num_threads() > 1 && mace_openblas_threads_is_one() && num_nodes >= 64 {
            mp0b_layer0_hidden_linear_vjp_input_density_parallel_openblas(
                density,
                linear_out,
                weight,
                output_mask,
                mask_is_identity,
                bar_out,
                bar_input,
                bar_density,
                num_nodes,
            );
            return;
        }
        mp0b_layer0_hidden_linear_vjp_input_density_blas(
            density,
            linear_out,
            weight,
            output_mask,
            mask_is_identity,
            bar_out,
            bar_input,
            bar_density,
            num_nodes,
        );
        return;
    }
    let mut bar_values = [0.0; MP0B_NUM_FEATURES];
    for node in 0..num_nodes {
        let linear_out_row =
            &linear_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let bar_out_row = &bar_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let bar_input_row =
            &mut bar_input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let density_norm = density[node] + 1.0;
        let mut block_offset = 0;
        for (block, &component_dim) in block_dims.iter().enumerate() {
            let weight_offset = block * block_weights;
            for component in 0..component_dim {
                for (out_feature, bar_value) in bar_values.iter_mut().enumerate() {
                    let out_index = block_offset + out_feature * component_dim + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[out_index]
                    };
                    bar_density[node] -=
                        bar_out_row[out_index] * linear_out_row[out_index] / density_norm;
                    *bar_value = bar_out_row[out_index] * path_weight * mask / density_norm;
                }
                for in_feature in 0..MP0B_NUM_FEATURES {
                    let weight_row = &weight[weight_offset + in_feature * MP0B_NUM_FEATURES
                        ..weight_offset + (in_feature + 1) * MP0B_NUM_FEATURES];
                    let mut value = 0.0;
                    for (&bar_value, &weight_value) in bar_values.iter().zip(weight_row) {
                        value += bar_value * weight_value;
                    }
                    let input_index = block_offset + in_feature * component_dim + component;
                    bar_input_row[input_index] += value;
                }
            }
            block_offset += MP0B_NUM_FEATURES * component_dim;
        }
    }
}

#[cfg(all(
    feature = "parallel",
    feature = "openblas",
    target_os = "linux",
    any(target_arch = "x86_64", target_arch = "aarch64")
))]
struct HiddenLinearComponentF64 {
    offset: usize,
    component_dim: usize,
    component: usize,
    values: Vec<f64>,
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
fn mp0b_layer0_hidden_linear_blas(
    input: &[f64],
    density: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    mask_is_identity: bool,
    out: &mut [f64],
    num_nodes: usize,
) {
    let block_dims = [1, 3, 5, 7];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
    out.fill(0.0);
    let mut component_input = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
    let mut component_out = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
    let mut block_offset = 0;
    for (block, &component_dim) in block_dims.iter().enumerate() {
        let weight_offset = block * block_weights;
        for component in 0..component_dim {
            for node in 0..num_nodes {
                let input_row =
                    &input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                let component_input_row =
                    &mut component_input[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                for feature in 0..MP0B_NUM_FEATURES {
                    component_input_row[feature] =
                        input_row[block_offset + feature * component_dim + component];
                }
            }
            blas_backend::dense_forward(
                &component_input,
                num_nodes,
                MP0B_NUM_FEATURES,
                &weight[weight_offset..weight_offset + block_weights],
                &mut component_out,
                path_weight,
            );
            for node in 0..num_nodes {
                let density_norm = density[node] + 1.0;
                let out_row =
                    &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                let component_out_row =
                    &component_out[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                for (feature, &component_value) in component_out_row.iter().enumerate() {
                    let out_index = block_offset + feature * component_dim + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[out_index]
                    };
                    out_row[out_index] = component_value * mask / density_norm;
                }
            }
        }
        block_offset += MP0B_NUM_FEATURES * component_dim;
    }
}

#[cfg(all(
    feature = "parallel",
    feature = "openblas",
    target_os = "linux",
    any(target_arch = "x86_64", target_arch = "aarch64")
))]
fn mp0b_layer0_hidden_linear_parallel_openblas(
    input: &[f64],
    density: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    mask_is_identity: bool,
    out: &mut [f64],
    num_nodes: usize,
) {
    let block_dims = [1, 3, 5, 7];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
    let mut task_specs = Vec::new();
    let mut block_offset = 0;
    for (block, &component_dim) in block_dims.iter().enumerate() {
        for component in 0..component_dim {
            task_specs.push((
                block_offset,
                component_dim,
                component,
                block * block_weights,
            ));
        }
        block_offset += MP0B_NUM_FEATURES * component_dim;
    }

    let components = task_specs
        .into_par_iter()
        .map(|(block_offset, component_dim, component, weight_offset)| {
            let mut component_input = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
            for node in 0..num_nodes {
                let input_row =
                    &input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                let component_input_row =
                    &mut component_input[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                for feature in 0..MP0B_NUM_FEATURES {
                    component_input_row[feature] =
                        input_row[block_offset + feature * component_dim + component];
                }
            }
            let mut values = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
            blas_backend::dense_forward(
                &component_input,
                num_nodes,
                MP0B_NUM_FEATURES,
                &weight[weight_offset..weight_offset + block_weights],
                &mut values,
                path_weight,
            );
            HiddenLinearComponentF64 {
                offset: block_offset,
                component_dim,
                component,
                values,
            }
        })
        .collect::<Vec<_>>();

    out.fill(0.0);
    for component_result in components {
        for node in 0..num_nodes {
            let density_norm = density[node] + 1.0;
            let out_row = &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
            let component_row =
                &component_result.values[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
            for (feature, &value) in component_row.iter().enumerate() {
                let out_index = component_result.offset
                    + feature * component_result.component_dim
                    + component_result.component;
                let mask = if mask_is_identity {
                    1.0
                } else {
                    output_mask[out_index]
                };
                out_row[out_index] = value * mask / density_norm;
            }
        }
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
#[allow(clippy::too_many_arguments)]
fn mp0b_layer0_hidden_linear_vjp_input_density_blas(
    density: &[f64],
    linear_out: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    mask_is_identity: bool,
    bar_out: &[f64],
    bar_input: &mut [f64],
    bar_density: &mut [f64],
    num_nodes: usize,
) {
    let block_dims = [1, 3, 5, 7];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
    for node in 0..num_nodes {
        let density_norm = density[node] + 1.0;
        let linear_out_row =
            &linear_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let bar_out_row = &bar_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        for index in 0..MP0B_HIDDEN_ROW_LEN {
            bar_density[node] -= bar_out_row[index] * linear_out_row[index] / density_norm;
        }
    }

    let mut component_bar_out = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
    let mut component_bar_input = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
    let mut block_offset = 0;
    for (block, &component_dim) in block_dims.iter().enumerate() {
        let weight_offset = block * block_weights;
        for component in 0..component_dim {
            for node in 0..num_nodes {
                let density_norm = density[node] + 1.0;
                let bar_out_row =
                    &bar_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                let component_bar_out_row = &mut component_bar_out
                    [node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                for (feature, component_bar_value) in component_bar_out_row.iter_mut().enumerate() {
                    let out_index = block_offset + feature * component_dim + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[out_index]
                    };
                    *component_bar_value =
                        bar_out_row[out_index] * path_weight * mask / density_norm;
                }
            }
            component_bar_input.fill(0.0);
            blas_backend::dense_vjp_input(
                num_nodes,
                MP0B_NUM_FEATURES,
                &weight[weight_offset..weight_offset + block_weights],
                &component_bar_out,
                &mut component_bar_input,
                1.0,
            );
            for node in 0..num_nodes {
                let bar_input_row =
                    &mut bar_input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                let component_bar_input_row =
                    &component_bar_input[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                for feature in 0..MP0B_NUM_FEATURES {
                    bar_input_row[block_offset + feature * component_dim + component] +=
                        component_bar_input_row[feature];
                }
            }
        }
        block_offset += MP0B_NUM_FEATURES * component_dim;
    }
}

#[cfg(all(
    feature = "parallel",
    feature = "openblas",
    target_os = "linux",
    any(target_arch = "x86_64", target_arch = "aarch64")
))]
#[allow(clippy::too_many_arguments)]
fn mp0b_layer0_hidden_linear_vjp_input_density_parallel_openblas(
    density: &[f64],
    linear_out: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    mask_is_identity: bool,
    bar_out: &[f64],
    bar_input: &mut [f64],
    bar_density: &mut [f64],
    num_nodes: usize,
) {
    let block_dims = [1, 3, 5, 7];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let path_weight = 1.0 / (MP0B_NUM_FEATURES as f64).sqrt();
    bar_density
        .par_iter_mut()
        .enumerate()
        .for_each(|(node, bar_density_value)| {
            let density_norm = density[node] + 1.0;
            let linear_out_row =
                &linear_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
            let bar_out_row =
                &bar_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
            for index in 0..MP0B_HIDDEN_ROW_LEN {
                *bar_density_value -= bar_out_row[index] * linear_out_row[index] / density_norm;
            }
        });

    let mut task_specs = Vec::new();
    let mut block_offset = 0;
    for (block, &component_dim) in block_dims.iter().enumerate() {
        for component in 0..component_dim {
            task_specs.push((
                block_offset,
                component_dim,
                component,
                block * block_weights,
            ));
        }
        block_offset += MP0B_NUM_FEATURES * component_dim;
    }

    let components = task_specs
        .into_par_iter()
        .map(|(block_offset, component_dim, component, weight_offset)| {
            let mut component_bar_out = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
            for node in 0..num_nodes {
                let density_norm = density[node] + 1.0;
                let bar_out_row =
                    &bar_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                let component_bar_out_row = &mut component_bar_out
                    [node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                for (feature, component_bar_value) in component_bar_out_row.iter_mut().enumerate() {
                    let out_index = block_offset + feature * component_dim + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[out_index]
                    };
                    *component_bar_value =
                        bar_out_row[out_index] * path_weight * mask / density_norm;
                }
            }
            let mut values = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
            blas_backend::dense_vjp_input(
                num_nodes,
                MP0B_NUM_FEATURES,
                &weight[weight_offset..weight_offset + block_weights],
                &component_bar_out,
                &mut values,
                1.0,
            );
            HiddenLinearComponentF64 {
                offset: block_offset,
                component_dim,
                component,
                values,
            }
        })
        .collect::<Vec<_>>();

    for component_result in components {
        for node in 0..num_nodes {
            let bar_input_row =
                &mut bar_input[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
            let component_row =
                &component_result.values[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
            for (feature, &value) in component_row.iter().enumerate() {
                bar_input_row[component_result.offset
                    + feature * component_result.component_dim
                    + component_result.component] += value;
            }
        }
    }
}

// Consumes `interactions.1.linear.weight` after block-wise pre-scaling by
// `MP0B_LAYER1_HIDDEN_PATH_WEIGHTS` in `prescale_mp0b_blas_weights`, so the
// per-block path-weight multiply is absorbed into the weight slice.
fn mp0b_layer1_hidden_linear(
    input: &[f64],
    density: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    out: &mut [f64],
) {
    let input_row_len = 5120;
    let input_block_dims = [1, 1, 3, 3, 3, 5, 5, 5, 7, 7];
    let output_block_dims = [1, 3, 5, 7];
    let output_blocks = [0, 0, 1, 1, 1, 2, 2, 2, 3, 3];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    debug_assert_eq!(weight.len(), block_weights * input_block_dims.len());
    debug_assert_eq!(output_mask.len(), MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(input.len() % input_row_len, 0);
    let num_nodes = input.len() / input_row_len;
    debug_assert_eq!(density.len(), num_nodes);
    debug_assert_eq!(out.len(), num_nodes * MP0B_HIDDEN_ROW_LEN);
    let mask_is_identity = output_mask.iter().all(|&mask| mask == 1.0);
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if mask_is_identity && num_nodes >= blas_dispatch_threshold() {
        #[cfg(all(
            feature = "parallel",
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ))]
        if rayon::current_num_threads() > 1 && mace_openblas_threads_is_one() && num_nodes >= 64 {
            mp0b_layer1_hidden_linear_parallel_openblas(input, density, weight, out, num_nodes);
            return;
        }
        mp0b_layer1_hidden_linear_blas(input, density, weight, out, num_nodes);
        return;
    }
    let mut input_offsets = [0_usize; 10];
    for block in 1..input_block_dims.len() {
        input_offsets[block] =
            input_offsets[block - 1] + MP0B_NUM_FEATURES * input_block_dims[block - 1];
    }
    let mut output_offsets = [0_usize; 4];
    for block in 1..output_block_dims.len() {
        output_offsets[block] =
            output_offsets[block - 1] + MP0B_NUM_FEATURES * output_block_dims[block - 1];
    }
    let mut accum = [0.0; MP0B_NUM_FEATURES];
    for node in 0..num_nodes {
        let input_row = &input[node * input_row_len..(node + 1) * input_row_len];
        let out_row = &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        out_row.fill(0.0);
        for (block, &component_dim) in input_block_dims.iter().enumerate() {
            let input_offset = input_offsets[block];
            let output_block = output_blocks[block];
            let output_offset = output_offsets[output_block];
            let weight_offset = block * block_weights;
            for component in 0..component_dim {
                accum.fill(0.0);
                for in_feature in 0..MP0B_NUM_FEATURES {
                    let input_index = input_offset + in_feature * component_dim + component;
                    let input_value = input_row[input_index];
                    if input_value == 0.0 {
                        continue;
                    }
                    let weight_row = &weight[weight_offset + in_feature * MP0B_NUM_FEATURES
                        ..weight_offset + (in_feature + 1) * MP0B_NUM_FEATURES];
                    for (value, &weight_value) in accum.iter_mut().zip(weight_row) {
                        *value += input_value * weight_value;
                    }
                }
                for (out_feature, &value) in accum.iter().enumerate() {
                    let out_index = output_offset + out_feature * component_dim + component;
                    out_row[out_index] += value;
                }
            }
        }
        let density_norm = density[node] + 1.0;
        if mask_is_identity {
            for value in out_row {
                *value /= density_norm;
            }
        } else {
            for (value, &mask) in out_row.iter_mut().zip(output_mask) {
                *value = *value * mask / density_norm;
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
// VJP counterpart of `mp0b_layer1_hidden_linear`. The weight is pre-scaled by
// block path weights, so the bar accumulation does not multiply by them.
fn mp0b_layer1_hidden_linear_vjp_input_density(
    input: &[f64],
    density: &[f64],
    linear_out: &[f64],
    weight: &[f64],
    output_mask: &[f64],
    bar_out: &[f64],
    bar_input: &mut [f64],
    bar_density: &mut [f64],
) {
    let input_row_len = 5120;
    let input_block_dims = [1, 1, 3, 3, 3, 5, 5, 5, 7, 7];
    let output_block_dims = [1, 3, 5, 7];
    let output_blocks = [0, 0, 1, 1, 1, 2, 2, 2, 3, 3];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    debug_assert_eq!(weight.len(), block_weights * input_block_dims.len());
    debug_assert_eq!(output_mask.len(), MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(input.len() % input_row_len, 0);
    let num_nodes = input.len() / input_row_len;
    debug_assert_eq!(linear_out.len(), num_nodes * MP0B_HIDDEN_ROW_LEN);
    debug_assert_eq!(bar_input.len(), input.len());
    debug_assert_eq!(density.len(), num_nodes);
    debug_assert_eq!(bar_density.len(), num_nodes);
    debug_assert_eq!(bar_out.len(), num_nodes * MP0B_HIDDEN_ROW_LEN);
    let mask_is_identity = output_mask.iter().all(|&mask| mask == 1.0);
    #[cfg(any(
        all(feature = "accelerate-blas", target_os = "macos"),
        all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
        all(
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ),
        all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
    ))]
    if mask_is_identity && num_nodes >= blas_dispatch_threshold() {
        #[cfg(all(
            feature = "parallel",
            feature = "openblas",
            target_os = "linux",
            any(target_arch = "x86_64", target_arch = "aarch64")
        ))]
        if rayon::current_num_threads() > 1 && mace_openblas_threads_is_one() && num_nodes >= 512 {
            mp0b_layer1_hidden_linear_vjp_input_density_parallel_openblas(
                density,
                linear_out,
                weight,
                bar_out,
                bar_input,
                bar_density,
                num_nodes,
            );
            return;
        }
        mp0b_layer1_hidden_linear_vjp_input_density_blas(
            density,
            linear_out,
            weight,
            bar_out,
            bar_input,
            bar_density,
            num_nodes,
        );
        return;
    }
    let mut input_offsets = [0_usize; 10];
    for block in 1..input_block_dims.len() {
        input_offsets[block] =
            input_offsets[block - 1] + MP0B_NUM_FEATURES * input_block_dims[block - 1];
    }
    let mut output_offsets = [0_usize; 4];
    for block in 1..output_block_dims.len() {
        output_offsets[block] =
            output_offsets[block - 1] + MP0B_NUM_FEATURES * output_block_dims[block - 1];
    }
    let mut bar_values = [0.0; MP0B_NUM_FEATURES];
    for node in 0..num_nodes {
        let linear_out_row =
            &linear_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let bar_out_row = &bar_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let bar_input_row = &mut bar_input[node * input_row_len..(node + 1) * input_row_len];

        let density_norm = density[node] + 1.0;
        for index in 0..MP0B_HIDDEN_ROW_LEN {
            bar_density[node] -= bar_out_row[index] * linear_out_row[index] / density_norm;
        }

        for (block, &component_dim) in input_block_dims.iter().enumerate() {
            let input_offset = input_offsets[block];
            let output_block = output_blocks[block];
            let output_offset = output_offsets[output_block];
            let weight_offset = block * block_weights;
            for component in 0..component_dim {
                for (out_feature, bar_value) in bar_values.iter_mut().enumerate() {
                    let out_index = output_offset + out_feature * component_dim + component;
                    let mask = if mask_is_identity {
                        1.0
                    } else {
                        output_mask[out_index]
                    };
                    *bar_value = bar_out_row[out_index] * mask / density_norm;
                }
                for in_feature in 0..MP0B_NUM_FEATURES {
                    let weight_row = &weight[weight_offset + in_feature * MP0B_NUM_FEATURES
                        ..weight_offset + (in_feature + 1) * MP0B_NUM_FEATURES];
                    let mut value = 0.0;
                    for (&bar_value, &weight_value) in bar_values.iter().zip(weight_row) {
                        value += bar_value * weight_value;
                    }
                    let input_index = input_offset + in_feature * component_dim + component;
                    bar_input_row[input_index] = value;
                }
            }
        }
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
fn mp0b_layer1_hidden_linear_blas(
    input: &[f64],
    density: &[f64],
    weight: &[f64],
    out: &mut [f64],
    num_nodes: usize,
) {
    let input_row_len = 5120;
    let input_block_dims = [1, 1, 3, 3, 3, 5, 5, 5, 7, 7];
    let output_block_dims = [1, 3, 5, 7];
    let output_blocks = [0, 0, 1, 1, 1, 2, 2, 2, 3, 3];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let mut input_offsets = [0_usize; 10];
    for block in 1..input_block_dims.len() {
        input_offsets[block] =
            input_offsets[block - 1] + MP0B_NUM_FEATURES * input_block_dims[block - 1];
    }
    let mut output_offsets = [0_usize; 4];
    for block in 1..output_block_dims.len() {
        output_offsets[block] =
            output_offsets[block - 1] + MP0B_NUM_FEATURES * output_block_dims[block - 1];
    }
    out.fill(0.0);
    let mut component_input = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
    let mut component_out = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
    for (block, &component_dim) in input_block_dims.iter().enumerate() {
        let input_offset = input_offsets[block];
        let output_offset = output_offsets[output_blocks[block]];
        let weight_offset = block * block_weights;
        for component in 0..component_dim {
            for node in 0..num_nodes {
                let input_row = &input[node * input_row_len..(node + 1) * input_row_len];
                let component_input_row =
                    &mut component_input[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                for feature in 0..MP0B_NUM_FEATURES {
                    component_input_row[feature] =
                        input_row[input_offset + feature * component_dim + component];
                }
            }
            // Weight slice is pre-scaled by `MP0B_LAYER1_HIDDEN_PATH_WEIGHTS[block]`.
            blas_backend::dense_forward(
                &component_input,
                num_nodes,
                MP0B_NUM_FEATURES,
                &weight[weight_offset..weight_offset + block_weights],
                &mut component_out,
                1.0,
            );
            for node in 0..num_nodes {
                let out_row =
                    &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                let component_out_row =
                    &component_out[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                for feature in 0..MP0B_NUM_FEATURES {
                    out_row[output_offset + feature * component_dim + component] +=
                        component_out_row[feature];
                }
            }
        }
    }
    for node in 0..num_nodes {
        let density_norm = density[node] + 1.0;
        let out_row = &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        for value in out_row {
            *value /= density_norm;
        }
    }
}

#[cfg(all(
    feature = "parallel",
    feature = "openblas",
    target_os = "linux",
    any(target_arch = "x86_64", target_arch = "aarch64")
))]
fn mp0b_layer1_hidden_linear_parallel_openblas(
    input: &[f64],
    density: &[f64],
    weight: &[f64],
    out: &mut [f64],
    num_nodes: usize,
) {
    let input_row_len = 5120;
    let input_block_dims = [1, 1, 3, 3, 3, 5, 5, 5, 7, 7];
    let output_block_dims = [1, 3, 5, 7];
    let output_blocks = [0, 0, 1, 1, 1, 2, 2, 2, 3, 3];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let mut input_offsets = [0_usize; 10];
    for block in 1..input_block_dims.len() {
        input_offsets[block] =
            input_offsets[block - 1] + MP0B_NUM_FEATURES * input_block_dims[block - 1];
    }
    let mut output_offsets = [0_usize; 4];
    for block in 1..output_block_dims.len() {
        output_offsets[block] =
            output_offsets[block - 1] + MP0B_NUM_FEATURES * output_block_dims[block - 1];
    }

    let mut task_specs = Vec::new();
    for (block, &component_dim) in input_block_dims.iter().enumerate() {
        for component in 0..component_dim {
            task_specs.push((
                input_offsets[block],
                output_offsets[output_blocks[block]],
                component_dim,
                component,
                block * block_weights,
            ));
        }
    }
    let components = task_specs
        .into_par_iter()
        .map(
            |(input_offset, output_offset, component_dim, component, weight_offset)| {
                let mut component_input = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
                for node in 0..num_nodes {
                    let input_row = &input[node * input_row_len..(node + 1) * input_row_len];
                    let component_input_row = &mut component_input
                        [node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                    for feature in 0..MP0B_NUM_FEATURES {
                        component_input_row[feature] =
                            input_row[input_offset + feature * component_dim + component];
                    }
                }
                let mut values = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
                blas_backend::dense_forward(
                    &component_input,
                    num_nodes,
                    MP0B_NUM_FEATURES,
                    &weight[weight_offset..weight_offset + block_weights],
                    &mut values,
                    1.0,
                );
                HiddenLinearComponentF64 {
                    offset: output_offset,
                    component_dim,
                    component,
                    values,
                }
            },
        )
        .collect::<Vec<_>>();

    out.fill(0.0);
    for component_result in components {
        for node in 0..num_nodes {
            let out_row = &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
            let component_row =
                &component_result.values[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
            for (feature, &value) in component_row.iter().enumerate() {
                out_row[component_result.offset
                    + feature * component_result.component_dim
                    + component_result.component] += value;
            }
        }
    }
    for node in 0..num_nodes {
        let density_norm = density[node] + 1.0;
        let out_row = &mut out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        for value in out_row {
            *value /= density_norm;
        }
    }
}

#[cfg(any(
    all(feature = "accelerate-blas", target_os = "macos"),
    all(feature = "intel-mkl", target_os = "linux", target_arch = "x86_64"),
    all(
        feature = "openblas",
        target_os = "linux",
        any(target_arch = "x86_64", target_arch = "aarch64")
    ),
    all(feature = "libxsmm", target_os = "linux", target_arch = "x86_64")
))]
#[allow(clippy::too_many_arguments)]
fn mp0b_layer1_hidden_linear_vjp_input_density_blas(
    density: &[f64],
    linear_out: &[f64],
    weight: &[f64],
    bar_out: &[f64],
    bar_input: &mut [f64],
    bar_density: &mut [f64],
    num_nodes: usize,
) {
    let input_row_len = 5120;
    let input_block_dims = [1, 1, 3, 3, 3, 5, 5, 5, 7, 7];
    let output_block_dims = [1, 3, 5, 7];
    let output_blocks = [0, 0, 1, 1, 1, 2, 2, 2, 3, 3];
    let block_weights = MP0B_NUM_FEATURES * MP0B_NUM_FEATURES;
    let mut input_offsets = [0_usize; 10];
    for block in 1..input_block_dims.len() {
        input_offsets[block] =
            input_offsets[block - 1] + MP0B_NUM_FEATURES * input_block_dims[block - 1];
    }
    let mut output_offsets = [0_usize; 4];
    for block in 1..output_block_dims.len() {
        output_offsets[block] =
            output_offsets[block - 1] + MP0B_NUM_FEATURES * output_block_dims[block - 1];
    }
    for node in 0..num_nodes {
        let density_norm = density[node] + 1.0;
        let linear_out_row =
            &linear_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        let bar_out_row = &bar_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
        for index in 0..MP0B_HIDDEN_ROW_LEN {
            bar_density[node] -= bar_out_row[index] * linear_out_row[index] / density_norm;
        }
    }

    let mut component_bar_out = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
    let mut component_bar_input = vec![0.0; num_nodes * MP0B_NUM_FEATURES];
    for (block, &component_dim) in input_block_dims.iter().enumerate() {
        let input_offset = input_offsets[block];
        let output_offset = output_offsets[output_blocks[block]];
        let weight_offset = block * block_weights;
        for component in 0..component_dim {
            for node in 0..num_nodes {
                let density_norm = density[node] + 1.0;
                let bar_out_row =
                    &bar_out[node * MP0B_HIDDEN_ROW_LEN..(node + 1) * MP0B_HIDDEN_ROW_LEN];
                let component_bar_out_row = &mut component_bar_out
                    [node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                // Weight slice is pre-scaled by
                // `MP0B_LAYER1_HIDDEN_PATH_WEIGHTS[block]`; no per-element
                // multiply here.
                for feature in 0..MP0B_NUM_FEATURES {
                    component_bar_out_row[feature] = bar_out_row
                        [output_offset + feature * component_dim + component]
                        / density_norm;
                }
            }
            component_bar_input.fill(0.0);
            blas_backend::dense_vjp_input(
                num_nodes,
                MP0B_NUM_FEATURES,
                &weight[weight_offset..weight_offset + block_weights],
                &component_bar_out,
                &mut component_bar_input,
                1.0,
            );
            for node in 0..num_nodes {
                let bar_input_row =
                    &mut bar_input[node * input_row_len..(node + 1) * input_row_len];
                let component_bar_input_row =
                    &component_bar_input[node * MP0B_NUM_FEATURES..(node + 1) * MP0B_NUM_FEATURES];
                for feature in 0..MP0B_NUM_FEATURES {
                    bar_input_row[input_offset + feature * component_dim + component] +=
                        component_bar_input_row[feature];
                }
            }
        }
    }
}

