fn mp0b_layer1_dynamic_templates(
    plan: &TensorProductPlan,
) -> Option<Vec<Mp0bLayer1DynamicTemplate>> {
    if plan.input2_dim() != MP0B_SH_DIM
        || !plan.weight_numel.is_multiple_of(MP0B_NUM_FEATURES)
        || plan.instructions.len() != plan.weight_numel
    {
        return None;
    }
    let layouts = plan.checked_layouts().ok()?;
    let mut templates = Vec::with_capacity(plan.weight_numel / MP0B_NUM_FEATURES);
    for weight_base in (0..plan.weight_numel).step_by(MP0B_NUM_FEATURES) {
        let first = plan.instructions[weight_base];
        if first.weight_offset != Some(weight_base) {
            return None;
        }
        let first_x = *layouts.in1.get(first.in1_segment)?;
        let first_y = *layouts.in2.get(first.in2_segment)?;
        let first_out = *layouts.out.get(first.out_segment)?;
        if first_x.len == 0 || first_out.len == 0 {
            return None;
        }
        for feature in 0..MP0B_NUM_FEATURES {
            let instruction = plan.instructions[weight_base + feature];
            if instruction.weight_offset != Some(weight_base + feature)
                || instruction.in2_segment != first.in2_segment
                || instruction.cg_offset != first.cg_offset
                || instruction.cg_len != first.cg_len
                || instruction.path_weight != first.path_weight
            {
                return None;
            }
            let x = *layouts.in1.get(instruction.in1_segment)?;
            let out = *layouts.out.get(instruction.out_segment)?;
            if x.len != first_x.len
                || out.len != first_out.len
                || x.start != first_x.start + feature * first_x.len
                || out.start != first_out.start + feature * first_out.len
            {
                return None;
            }
        }
        let cg_entries = plan.cg_entries[first.cg_offset..first.cg_offset + first.cg_len]
            .iter()
            .map(|cg| Mp0bLayer1Cg {
                i_m: cg.i_m,
                j_m: cg.j_m,
                k_m: cg.k_m,
                scale: first.path_weight * cg.value,
            })
            .collect();
        templates.push(Mp0bLayer1DynamicTemplate {
            template: Mp0bLayer1TpTemplate {
                x_base: first_x.start,
                x_dim: first_x.len,
                y_base: first_y.start,
                out_base: first_out.start,
                out_dim: first_out.len,
                weight_base,
            },
            cg_entries,
        });
    }
    Some(templates)
}

fn tp_forward_accumulate_with_layouts_unchecked(
    plan: &TensorProductPlan,
    layouts: &TensorProductLayouts,
    x: &[f64],
    y: &[f64],
    w_edge: Option<&[f64]>,
    out_values: &mut [f64],
) {
    for instruction in &plan.instructions {
        let in1 = layouts.in1[instruction.in1_segment];
        let in2 = layouts.in2[instruction.in2_segment];
        let out = layouts.out[instruction.out_segment];
        let weight = instruction
            .weight_offset
            .and_then(|offset| w_edge.map(|weights| weights[offset]))
            .unwrap_or(1.0);
        let scale = instruction.path_weight * weight;
        let cg_start = instruction.cg_offset;
        let cg_end = cg_start + instruction.cg_len;
        for cg in &plan.cg_entries[cg_start..cg_end] {
            out_values[out.start + cg.k_m] +=
                scale * cg.value * x[in1.start + cg.i_m] * y[in2.start + cg.j_m];
        }
    }
}

