#[derive(Clone, Copy)]
struct ConvTpFeaturePathF32 {
    in1_start: usize,
    in1_stride: usize,
    in2_start: usize,
    out_start: usize,
    out_stride: usize,
    weight_offset: usize,
    cg_offset: usize,
    cg_len: usize,
    path_weight: f32,
}

fn conv_tp_feature_paths_f32(
    plan: &TensorProductPlan,
    layouts: &TensorProductLayouts,
    feature_dim: usize,
) -> Option<Vec<ConvTpFeaturePathF32>> {
    if feature_dim == 0
        || !plan.weight_numel.is_multiple_of(feature_dim)
        || plan.instructions.len() != plan.weight_numel
    {
        return None;
    }
    let mut paths = Vec::with_capacity(plan.weight_numel / feature_dim);
    for chunk in plan.instructions.chunks_exact(feature_dim) {
        let first = chunk[0];
        let in1_base_segment = first.in1_segment;
        let out_base_segment = first.out_segment;
        let weight_offset = first.weight_offset?;
        let in1_start = layouts.in1[in1_base_segment].start;
        let out_start = layouts.out[out_base_segment].start;
        let in1_stride = if feature_dim > 1 {
            layouts.in1[in1_base_segment + 1]
                .start
                .checked_sub(in1_start)?
        } else {
            layouts.in1[in1_base_segment].len
        };
        let out_stride = if feature_dim > 1 {
            layouts.out[out_base_segment + 1]
                .start
                .checked_sub(out_start)?
        } else {
            layouts.out[out_base_segment].len
        };
        for (feature, instruction) in chunk.iter().enumerate() {
            if instruction.in1_segment != in1_base_segment + feature
                || instruction.out_segment != out_base_segment + feature
                || instruction.in2_segment != first.in2_segment
                || instruction.cg_offset != first.cg_offset
                || instruction.cg_len != first.cg_len
                || instruction.weight_offset != Some(weight_offset + feature)
                || instruction.path_weight != first.path_weight
            {
                return None;
            }
        }
        paths.push(ConvTpFeaturePathF32 {
            in1_start,
            in1_stride,
            in2_start: layouts.in2[first.in2_segment].start,
            out_start,
            out_stride,
            weight_offset,
            cg_offset: first.cg_offset,
            cg_len: first.cg_len,
            path_weight: first.path_weight as f32,
        });
    }
    Some(paths)
}

#[allow(clippy::too_many_arguments)]
fn conv_tp_feature_path_forward_f32(
    plan: &TensorProductPlan,
    paths: &[ConvTpFeaturePathF32],
    x: &[f32],
    y: &[f32],
    w: &[f32],
    feature_dim: usize,
    out_values: &mut [f32],
) {
    for path in paths {
        let cg_end = path.cg_offset + path.cg_len;
        for cg in &plan.cg_entries[path.cg_offset..cg_end] {
            let coeff = path.path_weight * cg.value as f32 * y[path.in2_start + cg.j_m];
            for feature in 0..feature_dim {
                out_values[path.out_start + feature * path.out_stride + cg.k_m] += coeff
                    * w[path.weight_offset + feature]
                    * x[path.in1_start + feature * path.in1_stride + cg.i_m];
            }
        }
    }
}

#[allow(clippy::too_many_arguments)]
fn conv_tp_feature_path_vjp_f32(
    plan: &TensorProductPlan,
    paths: &[ConvTpFeaturePathF32],
    x: &[f32],
    y: &[f32],
    w: &[f32],
    grad_out: &[f32],
    feature_dim: usize,
    grad_x: &mut [f32],
    grad_y: &mut [f32],
    grad_w: &mut [f32],
) {
    for path in paths {
        let cg_end = path.cg_offset + path.cg_len;
        for cg in &plan.cg_entries[path.cg_offset..cg_end] {
            let y_index = path.in2_start + cg.j_m;
            let base = path.path_weight * cg.value as f32;
            let y_value = y[y_index];
            for feature in 0..feature_dim {
                let x_index = path.in1_start + feature * path.in1_stride + cg.i_m;
                let out_index = path.out_start + feature * path.out_stride + cg.k_m;
                let weight_index = path.weight_offset + feature;
                let bar_out = grad_out[out_index];
                let scale_bar = base * bar_out;
                grad_x[x_index] += scale_bar * w[weight_index] * y_value;
                grad_y[y_index] += scale_bar * w[weight_index] * x[x_index];
                grad_w[weight_index] += base * x[x_index] * y_value * bar_out;
            }
        }
    }
}

fn mp0b_apply_conv_tp(
    input: Mp0bConvTpInput<'_>,
    scatter_message: &mut [f64],
) -> Result<(), MaceLiteError> {
    let num_edges = input.senders.len();
    let input1_dim = input.plan.input1_dim();
    let input2_dim = input.plan.input2_dim();
    let output_dim = input.plan.output_dim();
    let weight_numel = input.plan.weight_numel;
    debug_assert_eq!(input.receivers.len(), num_edges);
    debug_assert_eq!(input.edge_attrs.len(), num_edges * input2_dim);
    debug_assert_eq!(input.tp_weights.len(), num_edges * weight_numel);
    debug_assert_eq!(input.output_mask.len(), output_dim);
    debug_assert_eq!(input.linear_up.len() % input1_dim, 0);
    let num_nodes = input.linear_up.len() / input1_dim;
    debug_assert_eq!(scatter_message.len(), num_nodes * output_dim);
    let mask_is_identity = input.output_mask.iter().all(|&mask| mask == 1.0);
    if mask_is_identity
        && input1_dim == MP0B_NUM_FEATURES
        && input2_dim == MP0B_SH_DIM
        && output_dim == MP0B_HIDDEN_ROW_LEN
        && weight_numel == 4 * MP0B_NUM_FEATURES
    {
        mp0b_apply_conv_tp_layer0_scalar_fast(input, scatter_message);
        return Ok(());
    }
    if mask_is_identity
        && input2_dim == MP0B_SH_DIM
        && input1_dim.is_multiple_of(MP0B_NUM_FEATURES)
        && output_dim.is_multiple_of(MP0B_NUM_FEATURES)
        && weight_numel.is_multiple_of(MP0B_NUM_FEATURES)
        && mp0b_layer1_dynamic_templates(input.plan).is_some()
    {
        mp0b_apply_conv_tp_layer1_scalar_vector_fast(input, scatter_message);
        return Ok(());
    }
    let layouts = input.plan.checked_layouts()?;
    scatter_message.fill(0.0);
    let mut message = vec![0.0; output_dim];
    for edge in 0..num_edges {
        let sender = input.senders[edge];
        let receiver = input.receivers[edge];
        let x = &input.linear_up[sender * input1_dim..(sender + 1) * input1_dim];
        let y = &input.edge_attrs[edge * input2_dim..(edge + 1) * input2_dim];
        let w = &input.tp_weights[edge * weight_numel..(edge + 1) * weight_numel];
        message.fill(0.0);
        tp_forward_accumulate_with_layouts_unchecked(
            input.plan,
            &layouts,
            x,
            y,
            Some(w),
            &mut message,
        );
        let scatter = &mut scatter_message[receiver * output_dim..(receiver + 1) * output_dim];
        if mask_is_identity {
            for (target, &value) in scatter.iter_mut().zip(message.iter()) {
                *target += value;
            }
        } else {
            for ((target, &value), &mask) in scatter
                .iter_mut()
                .zip(message.iter())
                .zip(input.output_mask)
            {
                *target += value * mask;
            }
        }
    }
    Ok(())
}

fn mp0b_apply_conv_tp_layer0_scalar_fast(input: Mp0bConvTpInput<'_>, scatter_message: &mut [f64]) {
    let num_edges = input.senders.len();
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && num_edges >= 512 {
        mp0b_apply_conv_tp_layer0_scalar_fast_parallel(&input, scatter_message);
        return;
    }
    scatter_message.fill(0.0);
    for edge in 0..num_edges {
        let sender = input.senders[edge];
        let receiver = input.receivers[edge];
        let x = &input.linear_up[sender * MP0B_NUM_FEATURES..(sender + 1) * MP0B_NUM_FEATURES];
        let y = &input.edge_attrs[edge * MP0B_SH_DIM..(edge + 1) * MP0B_SH_DIM];
        let w =
            &input.tp_weights[edge * (4 * MP0B_NUM_FEATURES)..(edge + 1) * (4 * MP0B_NUM_FEATURES)];
        let scatter = &mut scatter_message
            [receiver * MP0B_HIDDEN_ROW_LEN..(receiver + 1) * MP0B_HIDDEN_ROW_LEN];
        for feature in 0..MP0B_NUM_FEATURES {
            let x_value = x[feature];
            scatter[feature] += x_value * w[feature] * y[0];

            let weight_l1 = x_value * w[MP0B_NUM_FEATURES + feature];
            let out_l1 = MP0B_NUM_FEATURES + feature * 3;
            scatter[out_l1] += weight_l1 * y[1];
            scatter[out_l1 + 1] += weight_l1 * y[2];
            scatter[out_l1 + 2] += weight_l1 * y[3];

            let weight_l2 = x_value * w[2 * MP0B_NUM_FEATURES + feature];
            let out_l2 = MP0B_NUM_FEATURES + 3 * MP0B_NUM_FEATURES + feature * 5;
            scatter[out_l2] += weight_l2 * y[4];
            scatter[out_l2 + 1] += weight_l2 * y[5];
            scatter[out_l2 + 2] += weight_l2 * y[6];
            scatter[out_l2 + 3] += weight_l2 * y[7];
            scatter[out_l2 + 4] += weight_l2 * y[8];

            let weight_l3 = x_value * w[3 * MP0B_NUM_FEATURES + feature];
            let out_l3 =
                MP0B_NUM_FEATURES + 3 * MP0B_NUM_FEATURES + 5 * MP0B_NUM_FEATURES + feature * 7;
            scatter[out_l3] += weight_l3 * y[9];
            scatter[out_l3 + 1] += weight_l3 * y[10];
            scatter[out_l3 + 2] += weight_l3 * y[11];
            scatter[out_l3 + 3] += weight_l3 * y[12];
            scatter[out_l3 + 4] += weight_l3 * y[13];
            scatter[out_l3 + 5] += weight_l3 * y[14];
            scatter[out_l3 + 6] += weight_l3 * y[15];
        }
    }
}

#[cfg(target_arch = "aarch64")]
#[allow(dead_code, unsafe_code)]
fn mp0b_apply_conv_tp_layer0_scalar_edge_neon_f64_safe(
    x: &[f64],
    y: &[f64],
    w: &[f64],
    scatter: &mut [f64],
) {
    // SAFETY: aarch64 guarantees NEON support. The caller passes fixed
    // MACE layer0 rows sized exactly as the scalar kernel expects.
    unsafe { mp0b_apply_conv_tp_layer0_scalar_edge_neon_f64(x, y, w, scatter) }
}

#[cfg(target_arch = "aarch64")]
#[allow(dead_code, unsafe_code)]
unsafe fn mp0b_apply_conv_tp_layer0_scalar_edge_neon_f64(
    x: &[f64],
    y: &[f64],
    w: &[f64],
    scatter: &mut [f64],
) {
    use std::arch::aarch64::*;

    #[inline(always)]
    unsafe fn add_store2_strided(ptr: *mut f64, stride: usize, value: float64x2_t) {
        if stride == 1 {
            let current = vld1q_f64(ptr);
            vst1q_f64(ptr, vaddq_f64(current, value));
        } else {
            *ptr += vgetq_lane_f64(value, 0);
            *ptr.add(stride) += vgetq_lane_f64(value, 1);
        }
    }

    let mut feature = 0;
    while feature + 2 <= MP0B_NUM_FEATURES {
        let x_v = vld1q_f64(x.as_ptr().add(feature));

        let w0 = vld1q_f64(w.as_ptr().add(feature));
        add_store2_strided(
            scatter.as_mut_ptr().add(feature),
            1,
            vmulq_f64(vmulq_f64(x_v, w0), vdupq_n_f64(y[0])),
        );

        let w1 = vld1q_f64(w.as_ptr().add(MP0B_NUM_FEATURES + feature));
        let weight_l1 = vmulq_f64(x_v, w1);
        let out_l1 = MP0B_NUM_FEATURES + feature * 3;
        add_store2_strided(
            scatter.as_mut_ptr().add(out_l1),
            3,
            vmulq_f64(weight_l1, vdupq_n_f64(y[1])),
        );
        add_store2_strided(
            scatter.as_mut_ptr().add(out_l1 + 1),
            3,
            vmulq_f64(weight_l1, vdupq_n_f64(y[2])),
        );
        add_store2_strided(
            scatter.as_mut_ptr().add(out_l1 + 2),
            3,
            vmulq_f64(weight_l1, vdupq_n_f64(y[3])),
        );

        let w2 = vld1q_f64(w.as_ptr().add(2 * MP0B_NUM_FEATURES + feature));
        let weight_l2 = vmulq_f64(x_v, w2);
        let out_l2 = MP0B_NUM_FEATURES + 3 * MP0B_NUM_FEATURES + feature * 5;
        for offset in 0..5 {
            add_store2_strided(
                scatter.as_mut_ptr().add(out_l2 + offset),
                5,
                vmulq_f64(weight_l2, vdupq_n_f64(y[4 + offset])),
            );
        }

        let w3 = vld1q_f64(w.as_ptr().add(3 * MP0B_NUM_FEATURES + feature));
        let weight_l3 = vmulq_f64(x_v, w3);
        let out_l3 =
            MP0B_NUM_FEATURES + 3 * MP0B_NUM_FEATURES + 5 * MP0B_NUM_FEATURES + feature * 7;
        for offset in 0..7 {
            add_store2_strided(
                scatter.as_mut_ptr().add(out_l3 + offset),
                7,
                vmulq_f64(weight_l3, vdupq_n_f64(y[9 + offset])),
            );
        }

        feature += 2;
    }
}

#[cfg(all(feature = "parallel", target_arch = "x86_64"))]
#[allow(unsafe_code)]
#[inline]
fn mp0b_apply_conv_tp_layer0_scalar_edge_avx512_f64_safe(
    x: &[f64],
    y: &[f64],
    w: &[f64],
    scatter: &mut [f64],
) {
    debug_assert!(mace_f64_avx512_enabled());
    // SAFETY: guarded by runtime AVX512F detection. The caller passes fixed
    // MACE layer0 row slices sized exactly as the scalar kernel expects.
    unsafe { mp0b_apply_conv_tp_layer0_scalar_edge_avx512_f64(x, y, w, scatter) }
}

#[cfg(all(feature = "parallel", target_arch = "x86_64"))]
#[allow(unsafe_code)]
#[target_feature(enable = "avx512f")]
#[inline]
unsafe fn mp0b_apply_conv_tp_layer0_scalar_edge_avx512_f64(
    x: &[f64],
    y: &[f64],
    w: &[f64],
    scatter: &mut [f64],
) {
    use std::arch::x86_64::*;

    #[inline(always)]
    unsafe fn add_store8_strided(ptr: *mut f64, stride: usize, value: __m512d) {
        if stride == 1 {
            let current = _mm512_loadu_pd(ptr);
            _mm512_storeu_pd(ptr, _mm512_add_pd(current, value));
        } else {
            let mut lanes = [0.0_f64; 8];
            _mm512_storeu_pd(lanes.as_mut_ptr(), value);
            for (lane, &lane_value) in lanes.iter().enumerate() {
                *ptr.add(lane * stride) += lane_value;
            }
        }
    }

    let mut feature = 0;
    while feature + 8 <= MP0B_NUM_FEATURES {
        let x_v = _mm512_loadu_pd(x.as_ptr().add(feature));

        let w0_v = _mm512_loadu_pd(w.as_ptr().add(feature));
        add_store8_strided(
            scatter.as_mut_ptr().add(feature),
            1,
            _mm512_mul_pd(_mm512_mul_pd(x_v, w0_v), _mm512_set1_pd(y[0])),
        );

        let w1_v = _mm512_loadu_pd(w.as_ptr().add(MP0B_NUM_FEATURES + feature));
        let xw1_v = _mm512_mul_pd(x_v, w1_v);
        let out_l1 = MP0B_NUM_FEATURES + feature * 3;
        for component in 0..3 {
            add_store8_strided(
                scatter.as_mut_ptr().add(out_l1 + component),
                3,
                _mm512_mul_pd(xw1_v, _mm512_set1_pd(y[1 + component])),
            );
        }

        let w2_v = _mm512_loadu_pd(w.as_ptr().add(2 * MP0B_NUM_FEATURES + feature));
        let xw2_v = _mm512_mul_pd(x_v, w2_v);
        let out_l2 = MP0B_NUM_FEATURES + 3 * MP0B_NUM_FEATURES + feature * 5;
        for component in 0..5 {
            add_store8_strided(
                scatter.as_mut_ptr().add(out_l2 + component),
                5,
                _mm512_mul_pd(xw2_v, _mm512_set1_pd(y[4 + component])),
            );
        }

        let w3_v = _mm512_loadu_pd(w.as_ptr().add(3 * MP0B_NUM_FEATURES + feature));
        let xw3_v = _mm512_mul_pd(x_v, w3_v);
        let out_l3 =
            MP0B_NUM_FEATURES + 3 * MP0B_NUM_FEATURES + 5 * MP0B_NUM_FEATURES + feature * 7;
        for component in 0..7 {
            add_store8_strided(
                scatter.as_mut_ptr().add(out_l3 + component),
                7,
                _mm512_mul_pd(xw3_v, _mm512_set1_pd(y[9 + component])),
            );
        }

        feature += 8;
    }
}

