#[cfg(all(feature = "parallel", target_arch = "x86_64"))]
#[allow(unsafe_code)]
#[target_feature(enable = "avx2")]
#[inline]
unsafe fn mp0b_apply_conv_tp_layer0_scalar_edge_avx2_f64(
    x: &[f64],
    y: &[f64],
    w: &[f64],
    scatter: &mut [f64],
) {
    use std::arch::x86_64::*;

    #[inline(always)]
    unsafe fn add_store4_strided(ptr: *mut f64, stride: usize, value: __m256d) {
        if stride == 1 {
            let current = _mm256_loadu_pd(ptr);
            _mm256_storeu_pd(ptr, _mm256_add_pd(current, value));
        } else {
            let mut lanes = [0.0_f64; 4];
            _mm256_storeu_pd(lanes.as_mut_ptr(), value);
            for (lane, &lane_value) in lanes.iter().enumerate() {
                *ptr.add(lane * stride) += lane_value;
            }
        }
    }

    let mut feature = 0;
    while feature + 4 <= MP0B_NUM_FEATURES {
        let x_v = _mm256_loadu_pd(x.as_ptr().add(feature));

        let w0_v = _mm256_loadu_pd(w.as_ptr().add(feature));
        add_store4_strided(
            scatter.as_mut_ptr().add(feature),
            1,
            _mm256_mul_pd(_mm256_mul_pd(x_v, w0_v), _mm256_set1_pd(y[0])),
        );

        let w1_v = _mm256_loadu_pd(w.as_ptr().add(MP0B_NUM_FEATURES + feature));
        let xw1_v = _mm256_mul_pd(x_v, w1_v);
        let out_l1 = MP0B_NUM_FEATURES + feature * 3;
        for component in 0..3 {
            add_store4_strided(
                scatter.as_mut_ptr().add(out_l1 + component),
                3,
                _mm256_mul_pd(xw1_v, _mm256_set1_pd(y[1 + component])),
            );
        }

        let w2_v = _mm256_loadu_pd(w.as_ptr().add(2 * MP0B_NUM_FEATURES + feature));
        let xw2_v = _mm256_mul_pd(x_v, w2_v);
        let out_l2 = MP0B_NUM_FEATURES + 3 * MP0B_NUM_FEATURES + feature * 5;
        for component in 0..5 {
            add_store4_strided(
                scatter.as_mut_ptr().add(out_l2 + component),
                5,
                _mm256_mul_pd(xw2_v, _mm256_set1_pd(y[4 + component])),
            );
        }

        let w3_v = _mm256_loadu_pd(w.as_ptr().add(3 * MP0B_NUM_FEATURES + feature));
        let xw3_v = _mm256_mul_pd(x_v, w3_v);
        let out_l3 =
            MP0B_NUM_FEATURES + 3 * MP0B_NUM_FEATURES + 5 * MP0B_NUM_FEATURES + feature * 7;
        for component in 0..7 {
            add_store4_strided(
                scatter.as_mut_ptr().add(out_l3 + component),
                7,
                _mm256_mul_pd(xw3_v, _mm256_set1_pd(y[9 + component])),
            );
        }

        feature += 4;
    }
}

#[cfg(feature = "parallel")]
fn mp0b_apply_conv_tp_layer0_scalar_fast_parallel(
    input: &Mp0bConvTpInput<'_>,
    scatter_message: &mut [f64],
) {
    let num_edges = input.senders.len();
    let num_nodes = input.linear_up.len() / MP0B_NUM_FEATURES;
    let weight_row_len = 4 * MP0B_NUM_FEATURES;
    debug_assert_eq!(scatter_message.len(), num_nodes * MP0B_HIDDEN_ROW_LEN);

    let mut edge_counts_by_receiver = vec![0usize; num_nodes];
    for &receiver in input.receivers {
        edge_counts_by_receiver[receiver] += 1;
    }
    let mut edges_by_receiver = edge_counts_by_receiver
        .iter()
        .map(|&count| Vec::with_capacity(count))
        .collect::<Vec<_>>();
    for edge in 0..num_edges {
        edges_by_receiver[input.receivers[edge]].push(edge);
    }

    scatter_message
        .par_chunks_mut(MP0B_HIDDEN_ROW_LEN)
        .enumerate()
        .with_min_len(2)
        .for_each(|(receiver, scatter)| {
            scatter.fill(0.0);
            for &edge in &edges_by_receiver[receiver] {
                let sender = input.senders[edge];
                let x =
                    &input.linear_up[sender * MP0B_NUM_FEATURES..(sender + 1) * MP0B_NUM_FEATURES];
                let y = &input.edge_attrs[edge * MP0B_SH_DIM..(edge + 1) * MP0B_SH_DIM];
                let w = &input.tp_weights[edge * weight_row_len..(edge + 1) * weight_row_len];
                #[cfg(target_arch = "aarch64")]
                {
                    mp0b_apply_conv_tp_layer0_scalar_edge_neon_f64_safe(x, y, w, scatter);
                    continue;
                }
                #[cfg(target_arch = "x86_64")]
                {
                    if mace_f64_avx512_enabled() {
                        mp0b_apply_conv_tp_layer0_scalar_edge_avx512_f64_safe(x, y, w, scatter);
                        continue;
                    }
                    if mace_f64_avx2_enabled() {
                        mp0b_apply_conv_tp_layer0_scalar_edge_avx2_f64_safe(x, y, w, scatter);
                        continue;
                    }
                }
                #[cfg(not(target_arch = "aarch64"))]
                {
                    for feature in 0..MP0B_NUM_FEATURES {
                        let x_value = x[feature];
                        scatter[feature] += x_value * w[feature] * y[0];

                        let weight_l1 = x_value * w[MP0B_NUM_FEATURES + feature];
                        let out_l1 = MP0B_NUM_FEATURES + feature * 3;
                        scatter[out_l1] += weight_l1 * y[1];
                        scatter[out_l1 + 1] += weight_l1 * y[2];
                        scatter[out_l1 + 2] += weight_l1 * y[3];

                        let weight_l2 = x_value * w[2 * MP0B_NUM_FEATURES + feature];
                        let out_l2 = MP0B_NUM_FEATURES + 3 * MP0B_NUM_FEATURES + feature * 5;
                        scatter[out_l2] += weight_l2 * y[4];
                        scatter[out_l2 + 1] += weight_l2 * y[5];
                        scatter[out_l2 + 2] += weight_l2 * y[6];
                        scatter[out_l2 + 3] += weight_l2 * y[7];
                        scatter[out_l2 + 4] += weight_l2 * y[8];

                        let weight_l3 = x_value * w[3 * MP0B_NUM_FEATURES + feature];
                        let out_l3 = MP0B_NUM_FEATURES
                            + 3 * MP0B_NUM_FEATURES
                            + 5 * MP0B_NUM_FEATURES
                            + feature * 7;
                        scatter[out_l3] += weight_l3 * y[9];
                        scatter[out_l3 + 1] += weight_l3 * y[10];
                        scatter[out_l3 + 2] += weight_l3 * y[11];
                        scatter[out_l3 + 3] += weight_l3 * y[12];
                        scatter[out_l3 + 4] += weight_l3 * y[13];
                        scatter[out_l3 + 5] += weight_l3 * y[14];
                        scatter[out_l3 + 6] += weight_l3 * y[15];
                    }
                }
            }
        });
}

#[allow(clippy::expect_used)]
fn mp0b_apply_conv_tp_layer1_scalar_vector_fast(
    input: Mp0bConvTpInput<'_>,
    scatter_message: &mut [f64],
) {
    let num_edges = input.senders.len();
    let input1_dim = input.plan.input1_dim();
    let output_row_len = input.plan.output_dim();
    let weight_row_len = input.plan.weight_numel;
    #[cfg(feature = "parallel")]
    if rayon::current_num_threads() > 1 && num_edges >= 512 {
        mp0b_apply_conv_tp_layer1_scalar_vector_fast_parallel(&input, scatter_message);
        return;
    }
    scatter_message.fill(0.0);
    let templates = mp0b_layer1_dynamic_templates(input.plan)
        .expect("validated MACE layer1 fast path templates");
    for edge in 0..num_edges {
        let sender = input.senders[edge];
        let receiver = input.receivers[edge];
        let x = &input.linear_up[sender * input1_dim..(sender + 1) * input1_dim];
        let y = &input.edge_attrs[edge * MP0B_SH_DIM..(edge + 1) * MP0B_SH_DIM];
        let w = &input.tp_weights[edge * weight_row_len..(edge + 1) * weight_row_len];
        let scatter =
            &mut scatter_message[receiver * output_row_len..(receiver + 1) * output_row_len];
        for dynamic_template in &templates {
            let template = dynamic_template.template;
            let cg_entries = &dynamic_template.cg_entries;
            for feature in 0..MP0B_NUM_FEATURES {
                let weight = w[template.weight_base + feature];
                let x_base = template.x_base + feature * template.x_dim;
                let out_base = template.out_base + feature * template.out_dim;
                for cg in cg_entries {
                    scatter[out_base + cg.k_m] +=
                        weight * cg.scale * x[x_base + cg.i_m] * y[template.y_base + cg.j_m];
                }
            }
        }
    }
}

#[cfg(target_arch = "aarch64")]
#[allow(dead_code, unsafe_code)]
fn mp0b_apply_conv_tp_layer1_scalar_vector_edge_neon_f64_safe(
    x: &[f64],
    y: &[f64],
    w: &[f64],
    scatter: &mut [f64],
    templates: &[Mp0bLayer1DynamicTemplate],
) {
    // SAFETY: aarch64 guarantees NEON support. The caller passes row slices
    // sized by the same checked MACE-Osaka24 layer1 layout as the scalar path.
    unsafe { mp0b_apply_conv_tp_layer1_scalar_vector_edge_neon_f64(x, y, w, scatter, templates) }
}

#[cfg(target_arch = "aarch64")]
#[allow(dead_code, unsafe_code)]
unsafe fn mp0b_apply_conv_tp_layer1_scalar_vector_edge_neon_f64(
    x: &[f64],
    y: &[f64],
    w: &[f64],
    scatter: &mut [f64],
    templates: &[Mp0bLayer1DynamicTemplate],
) {
    use std::arch::aarch64::*;

    #[inline(always)]
    unsafe fn load2_strided(ptr: *const f64, stride: usize) -> float64x2_t {
        if stride == 1 {
            vld1q_f64(ptr)
        } else {
            let mut out = vdupq_n_f64(0.0);
            out = vsetq_lane_f64(*ptr, out, 0);
            vsetq_lane_f64(*ptr.add(stride), out, 1)
        }
    }

    #[inline(always)]
    unsafe fn add_store2_strided(ptr: *mut f64, stride: usize, value: float64x2_t) {
        if stride == 1 {
            let current = vld1q_f64(ptr);
            vst1q_f64(ptr, vaddq_f64(current, value));
        } else {
            *ptr += vgetq_lane_f64(value, 0);
            *ptr.add(stride) += vgetq_lane_f64(value, 1);
        }
    }

    for dynamic_template in templates {
        let template = dynamic_template.template;
        let cg_entries = &dynamic_template.cg_entries;
        let mut feature = 0;
        while feature + 2 <= MP0B_NUM_FEATURES {
            let weight_v = vld1q_f64(w.as_ptr().add(template.weight_base + feature));
            let x_base = template.x_base + feature * template.x_dim;
            let out_base = template.out_base + feature * template.out_dim;
            for cg in cg_entries {
                let x_v = load2_strided(x.as_ptr().add(x_base + cg.i_m), template.x_dim);
                let scale = vdupq_n_f64(cg.scale * y[template.y_base + cg.j_m]);
                let value = vmulq_f64(vmulq_f64(weight_v, scale), x_v);
                add_store2_strided(
                    scatter.as_mut_ptr().add(out_base + cg.k_m),
                    template.out_dim,
                    value,
                );
            }
            feature += 2;
        }
        while feature < MP0B_NUM_FEATURES {
            let weight = w[template.weight_base + feature];
            let x_base = template.x_base + feature * template.x_dim;
            let out_base = template.out_base + feature * template.out_dim;
            for cg in cg_entries {
                scatter[out_base + cg.k_m] +=
                    weight * cg.scale * x[x_base + cg.i_m] * y[template.y_base + cg.j_m];
            }
            feature += 1;
        }
    }
}

