#[cfg(feature = "parallel")]
#[allow(clippy::expect_used)]
fn mp0b_apply_conv_tp_layer1_scalar_vector_fast_vjp_parallel(
    input: &Mp0bConvTpInput<'_>,
    bar_scatter_message: &[f64],
    edge_chunk_len: usize,
) -> Mp0bConvTpVjp {
    let input1_dim = input.plan.input1_dim();
    let weight_row_len = input.plan.weight_numel;
    let output_row_len = input.plan.output_dim();
    let mut bar_edge_attrs = vec![0.0; input.edge_attrs.len()];
    let mut bar_tp_weights = vec![0.0; input.tp_weights.len()];
    let templates = mp0b_layer1_dynamic_templates(input.plan)
        .expect("validated MACE layer1 fast path templates");

    let chunk_linear_up_updates = bar_edge_attrs
        .par_chunks_mut(edge_chunk_len * MP0B_SH_DIM)
        .zip(bar_tp_weights.par_chunks_mut(edge_chunk_len * weight_row_len))
        .enumerate()
        .map(
            |(chunk_index, (bar_edge_attrs_chunk, bar_tp_weights_chunk))| {
                let edge_start = chunk_index * edge_chunk_len;
                let chunk_edges = bar_edge_attrs_chunk.len() / MP0B_SH_DIM;
                debug_assert_eq!(bar_tp_weights_chunk.len(), chunk_edges * weight_row_len);
                let mut linear_up_updates = Vec::new();
                let mut active_sender = None;
                let mut bar_x_values = vec![0.0; input1_dim];
                for local_edge in 0..chunk_edges {
                    let edge = edge_start + local_edge;
                    let sender = input.senders[edge];
                    let receiver = input.receivers[edge];
                    if active_sender != Some(sender) {
                        mp0b_push_bar_linear_up_update(
                            &mut linear_up_updates,
                            active_sender,
                            &bar_x_values,
                        );
                        bar_x_values.fill(0.0);
                        active_sender = Some(sender);
                    }
                    let x = &input.linear_up[sender * input1_dim..(sender + 1) * input1_dim];
                    let y = &input.edge_attrs[edge * MP0B_SH_DIM..(edge + 1) * MP0B_SH_DIM];
                    let w = &input.tp_weights[edge * weight_row_len..(edge + 1) * weight_row_len];
                    let bar_scatter = &bar_scatter_message
                        [receiver * output_row_len..(receiver + 1) * output_row_len];
                    let bar_w = &mut bar_tp_weights_chunk
                        [local_edge * weight_row_len..(local_edge + 1) * weight_row_len];

                    let mut bar_y = [0.0; MP0B_SH_DIM];
                    #[cfg(target_arch = "aarch64")]
                    {
                        mp0b_apply_conv_tp_layer1_scalar_vector_vjp_edge_neon_f64_safe(
                            x,
                            y,
                            w,
                            bar_scatter,
                            bar_w,
                            &mut bar_x_values,
                            &mut bar_y,
                            &templates,
                        );
                        bar_edge_attrs_chunk
                            [local_edge * MP0B_SH_DIM..(local_edge + 1) * MP0B_SH_DIM]
                            .copy_from_slice(&bar_y);
                        continue;
                    }
                    #[cfg(target_arch = "x86_64")]
                    {
                        if mace_f64_avx512_enabled() {
                            mp0b_apply_conv_tp_layer1_scalar_vector_vjp_edge_avx512_f64_safe(
                                x,
                                y,
                                w,
                                bar_scatter,
                                bar_w,
                                &mut bar_x_values,
                                &mut bar_y,
                                &templates,
                            );
                            bar_edge_attrs_chunk
                                [local_edge * MP0B_SH_DIM..(local_edge + 1) * MP0B_SH_DIM]
                                .copy_from_slice(&bar_y);
                            continue;
                        }
                        if mace_f64_avx2_enabled() {
                            mp0b_apply_conv_tp_layer1_scalar_vector_vjp_edge_avx2_f64_safe(
                                x,
                                y,
                                w,
                                bar_scatter,
                                bar_w,
                                &mut bar_x_values,
                                &mut bar_y,
                                &templates,
                            );
                            bar_edge_attrs_chunk
                                [local_edge * MP0B_SH_DIM..(local_edge + 1) * MP0B_SH_DIM]
                                .copy_from_slice(&bar_y);
                            continue;
                        }
                    }
                    #[cfg(not(target_arch = "aarch64"))]
                    {
                        for dynamic_template in &templates {
                            let template = dynamic_template.template;
                            let cg_entries = &dynamic_template.cg_entries;
                            for feature in 0..MP0B_NUM_FEATURES {
                                let weight_index = template.weight_base + feature;
                                let weight = w[weight_index];
                                let x_base = template.x_base + feature * template.x_dim;
                                let out_base = template.out_base + feature * template.out_dim;
                                let mut bar_weight = 0.0;
                                for cg in cg_entries {
                                    let x_index = x_base + cg.i_m;
                                    let y_index = template.y_base + cg.j_m;
                                    let out_index = out_base + cg.k_m;
                                    let scale = cg.scale;
                                    let bar_out = bar_scatter[out_index];
                                    bar_x_values[x_index] += scale * weight * y[y_index] * bar_out;
                                    bar_y[y_index] += scale * weight * x[x_index] * bar_out;
                                    bar_weight += scale * x[x_index] * y[y_index] * bar_out;
                                }
                                bar_w[weight_index] = bar_weight;
                            }
                        }
                    }
                    #[cfg(not(target_arch = "aarch64"))]
                    bar_edge_attrs_chunk[local_edge * MP0B_SH_DIM..(local_edge + 1) * MP0B_SH_DIM]
                        .copy_from_slice(&bar_y);
                }
                mp0b_push_bar_linear_up_update(
                    &mut linear_up_updates,
                    active_sender,
                    &bar_x_values,
                );
                linear_up_updates
            },
        )
        .collect::<Vec<_>>();

    let mut bar_linear_up = vec![0.0; input.linear_up.len()];
    for linear_up_updates in chunk_linear_up_updates {
        for (sender, values) in linear_up_updates {
            mp0b_flush_bar_linear_up_update(&mut bar_linear_up, input1_dim, Some(sender), &values);
        }
    }

    Mp0bConvTpVjp {
        bar_linear_up,
        bar_edge_attrs,
        bar_tp_weights,
    }
}

