#[allow(unsafe_code)]
unsafe fn mp0b_apply_conv_tp_layer1_scalar_vector_fast_avx2_f32(
    input: Mp0bConvTpInputF32<'_>,
    scatter_message: &mut [f32],
) {
    use std::arch::x86_64::*;

    #[inline(always)]
    unsafe fn load8_strided(ptr: *const f32, stride: usize) -> __m256 {
        if stride == 1 {
            _mm256_loadu_ps(ptr)
        } else {
            _mm256_set_ps(
                *ptr.add(7 * stride),
                *ptr.add(6 * stride),
                *ptr.add(5 * stride),
                *ptr.add(4 * stride),
                *ptr.add(3 * stride),
                *ptr.add(2 * stride),
                *ptr.add(stride),
                *ptr,
            )
        }
    }

    #[inline(always)]
    unsafe fn add_store8_strided(ptr: *mut f32, stride: usize, value: __m256) {
        if stride == 1 {
            let current = _mm256_loadu_ps(ptr);
            _mm256_storeu_ps(ptr, _mm256_add_ps(current, value));
        } else {
            let mut lanes = [0.0_f32; 8];
            _mm256_storeu_ps(lanes.as_mut_ptr(), value);
            for (lane, &lane_value) in lanes.iter().enumerate() {
                *ptr.add(lane * stride) += lane_value;
            }
        }
    }

    let num_edges = input.senders.len();
    let weight_row_len = 10 * MP0B_NUM_FEATURES;
    scatter_message.fill(0.0);
    for edge in 0..num_edges {
        let sender = input.senders[edge];
        let receiver = input.receivers[edge];
        let x =
            &input.linear_up[sender * MP0B_PRODUCT0_ROW_LEN..(sender + 1) * MP0B_PRODUCT0_ROW_LEN];
        let y = &input.edge_attrs[edge * MP0B_SH_DIM..(edge + 1) * MP0B_SH_DIM];
        let w = &input.tp_weights[edge * weight_row_len..(edge + 1) * weight_row_len];
        let scatter = &mut scatter_message[receiver * MP0B_LAYER1_CONV_TP_OUTPUT_ROW_LEN
            ..(receiver + 1) * MP0B_LAYER1_CONV_TP_OUTPUT_ROW_LEN];
        for (template_index, template) in MP0B_LAYER1_TP_TEMPLATES.iter().enumerate() {
            let cg_entries = MP0B_LAYER1_TP_CG_TEMPLATES_F32[template_index];
            let mut feature = 0;
            while feature + 8 <= MP0B_NUM_FEATURES {
                let weight_v = _mm256_loadu_ps(w.as_ptr().add(template.weight_base + feature));
                let x_base = template.x_base + feature * template.x_dim;
                let out_base = template.out_base + feature * template.out_dim;
                for cg in cg_entries {
                    let x_v = load8_strided(x.as_ptr().add(x_base + cg.i_m), template.x_dim);
                    let scale = _mm256_set1_ps(cg.scale * y[template.y_base + cg.j_m]);
                    let value = _mm256_mul_ps(_mm256_mul_ps(weight_v, scale), x_v);
                    add_store8_strided(
                        scatter.as_mut_ptr().add(out_base + cg.k_m),
                        template.out_dim,
                        value,
                    );
                }
                feature += 8;
            }
            while feature < MP0B_NUM_FEATURES {
                let weight = w[template.weight_base + feature];
                let x_base = template.x_base + feature * template.x_dim;
                let out_base = template.out_base + feature * template.out_dim;
                for cg in cg_entries {
                    scatter[out_base + cg.k_m] +=
                        weight * cg.scale * x[x_base + cg.i_m] * y[template.y_base + cg.j_m];
                }
                feature += 1;
            }
        }
    }
}

