#[allow(unsafe_code)]
fn mp0b_apply_conv_tp_layer1_scalar_vector_fast_vjp_neon_f32_safe(
    input: Mp0bConvTpInputF32<'_>,
    bar_scatter_message: &[f32],
) -> Mp0bConvTpVjpF32 {
    // SAFETY: aarch64 guarantees NEON support. The helper only reads and
    // writes within the same slice bounds validated by the scalar kernel.
    unsafe { mp0b_apply_conv_tp_layer1_scalar_vector_fast_vjp_neon_f32(input, bar_scatter_message) }
}

#[cfg(target_arch = "aarch64")]
#[allow(unsafe_code)]
unsafe fn mp0b_apply_conv_tp_layer1_scalar_vector_fast_vjp_neon_f32(
    input: Mp0bConvTpInputF32<'_>,
    bar_scatter_message: &[f32],
) -> Mp0bConvTpVjpF32 {
    use std::arch::aarch64::*;

    #[inline(always)]
    unsafe fn load4_strided(ptr: *const f32, stride: usize) -> float32x4_t {
        if stride == 1 {
            vld1q_f32(ptr)
        } else {
            let mut out = vdupq_n_f32(0.0);
            out = vsetq_lane_f32(*ptr, out, 0);
            out = vsetq_lane_f32(*ptr.add(stride), out, 1);
            out = vsetq_lane_f32(*ptr.add(2 * stride), out, 2);
            vsetq_lane_f32(*ptr.add(3 * stride), out, 3)
        }
    }

    #[inline(always)]
    unsafe fn add_store4_strided(ptr: *mut f32, stride: usize, value: float32x4_t) {
        if stride == 1 {
            let current = vld1q_f32(ptr);
            vst1q_f32(ptr, vaddq_f32(current, value));
        } else {
            *ptr += vgetq_lane_f32(value, 0);
            *ptr.add(stride) += vgetq_lane_f32(value, 1);
            *ptr.add(2 * stride) += vgetq_lane_f32(value, 2);
            *ptr.add(3 * stride) += vgetq_lane_f32(value, 3);
        }
    }

    #[inline(always)]
    unsafe fn horizontal_sum(value: float32x4_t) -> f32 {
        vaddvq_f32(value)
    }

    #[allow(clippy::too_many_arguments)]
    #[inline(always)]
    unsafe fn apply_template<const N: usize>(
        template: Mp0bLayer1TpTemplate,
        cg_entries: &[Mp0bLayer1CgF32; N],
        x: &[f32],
        y: &[f32],
        w: &[f32],
        bar_scatter: &[f32],
        bar_w: &mut [f32],
        bar_x_values: &mut [f32; MP0B_PRODUCT0_ROW_LEN],
        bar_y: &mut [f32; MP0B_SH_DIM],
        bar_y_v: &mut [float32x4_t; MP0B_SH_DIM],
    ) {
        let mut feature = 0;
        while feature + 4 <= MP0B_NUM_FEATURES {
            let weight_index = template.weight_base + feature;
            let weight_v = vld1q_f32(w.as_ptr().add(weight_index));
            let mut bar_weight_v = vdupq_n_f32(0.0);
            let x_base = template.x_base + feature * template.x_dim;
            let out_base = template.out_base + feature * template.out_dim;
            for cg in cg_entries {
                let x_index = x_base + cg.i_m;
                let y_index = template.y_base + cg.j_m;
                let out_index = out_base + cg.k_m;
                let x_v = load4_strided(x.as_ptr().add(x_index), template.x_dim);
                let bar_out_v =
                    load4_strided(bar_scatter.as_ptr().add(out_index), template.out_dim);
                let scale_v = vdupq_n_f32(cg.scale);
                let y_v = vdupq_n_f32(y[y_index]);
                let scaled_bar = vmulq_f32(vmulq_f32(scale_v, weight_v), bar_out_v);
                let bar_x_delta = vmulq_f32(scaled_bar, y_v);
                add_store4_strided(
                    bar_x_values.as_mut_ptr().add(x_index),
                    template.x_dim,
                    bar_x_delta,
                );
                bar_y_v[y_index] = vaddq_f32(bar_y_v[y_index], vmulq_f32(scaled_bar, x_v));
                bar_weight_v = vfmaq_f32(
                    bar_weight_v,
                    vmulq_f32(scale_v, x_v),
                    vmulq_f32(y_v, bar_out_v),
                );
            }
            vst1q_f32(bar_w.as_mut_ptr().add(weight_index), bar_weight_v);
            feature += 4;
        }
        while feature < MP0B_NUM_FEATURES {
            let weight_index = template.weight_base + feature;
            let weight = w[weight_index];
            let x_base = template.x_base + feature * template.x_dim;
            let out_base = template.out_base + feature * template.out_dim;
            let mut bar_weight = 0.0_f32;
            for cg in cg_entries {
                let x_index = x_base + cg.i_m;
                let y_index = template.y_base + cg.j_m;
                let out_index = out_base + cg.k_m;
                let scale = cg.scale;
                let bar_out = bar_scatter[out_index];
                bar_x_values[x_index] += scale * weight * y[y_index] * bar_out;
                bar_y[y_index] += scale * weight * x[x_index] * bar_out;
                bar_weight += scale * x[x_index] * y[y_index] * bar_out;
            }
            bar_w[weight_index] = bar_weight;
            feature += 1;
        }
    }

    let num_edges = input.senders.len();
    let weight_row_len = 10 * MP0B_NUM_FEATURES;
    let mut bar_linear_up = vec![0.0_f32; input.linear_up.len()];
    let mut bar_edge_attrs = vec![0.0_f32; input.edge_attrs.len()];
    let mut bar_tp_weights = vec![0.0_f32; input.tp_weights.len()];
    let mut active_sender = None;
    let mut bar_x_values = [0.0_f32; MP0B_PRODUCT0_ROW_LEN];
    for edge in 0..num_edges {
        let sender = input.senders[edge];
        let receiver = input.receivers[edge];
        if active_sender != Some(sender) {
            mp0b_flush_product0_bar_linear_up_f32(&mut bar_linear_up, active_sender, &bar_x_values);
            bar_x_values.fill(0.0);
            active_sender = Some(sender);
        }
        let x =
            &input.linear_up[sender * MP0B_PRODUCT0_ROW_LEN..(sender + 1) * MP0B_PRODUCT0_ROW_LEN];
        let y = &input.edge_attrs[edge * MP0B_SH_DIM..(edge + 1) * MP0B_SH_DIM];
        let w = &input.tp_weights[edge * weight_row_len..(edge + 1) * weight_row_len];
        let bar_w = &mut bar_tp_weights[edge * weight_row_len..(edge + 1) * weight_row_len];
        let bar_scatter = &bar_scatter_message
            [receiver * 10 * MP0B_PRODUCT0_ROW_LEN..(receiver + 1) * 10 * MP0B_PRODUCT0_ROW_LEN];
        let mut bar_y = [0.0_f32; MP0B_SH_DIM];
        let mut bar_y_v = [vdupq_n_f32(0.0); MP0B_SH_DIM];
        apply_template(
            MP0B_LAYER1_TP_TEMPLATES[0],
            &MP0B_LAYER1_TP_CG0_F32,
            x,
            y,
            w,
            bar_scatter,
            bar_w,
            &mut bar_x_values,
            &mut bar_y,
            &mut bar_y_v,
        );
        apply_template(
            MP0B_LAYER1_TP_TEMPLATES[1],
            &MP0B_LAYER1_TP_CG1_F32,
            x,
            y,
            w,
            bar_scatter,
            bar_w,
            &mut bar_x_values,
            &mut bar_y,
            &mut bar_y_v,
        );
        apply_template(
            MP0B_LAYER1_TP_TEMPLATES[2],
            &MP0B_LAYER1_TP_CG2_F32,
            x,
            y,
            w,
            bar_scatter,
            bar_w,
            &mut bar_x_values,
            &mut bar_y,
            &mut bar_y_v,
        );
        apply_template(
            MP0B_LAYER1_TP_TEMPLATES[3],
            &MP0B_LAYER1_TP_CG3_F32,
            x,
            y,
            w,
            bar_scatter,
            bar_w,
            &mut bar_x_values,
            &mut bar_y,
            &mut bar_y_v,
        );
        apply_template(
            MP0B_LAYER1_TP_TEMPLATES[4],
            &MP0B_LAYER1_TP_CG4_F32,
            x,
            y,
            w,
            bar_scatter,
            bar_w,
            &mut bar_x_values,
            &mut bar_y,
            &mut bar_y_v,
        );
        apply_template(
            MP0B_LAYER1_TP_TEMPLATES[5],
            &MP0B_LAYER1_TP_CG5_F32,
            x,
            y,
            w,
            bar_scatter,
            bar_w,
            &mut bar_x_values,
            &mut bar_y,
            &mut bar_y_v,
        );
        apply_template(
            MP0B_LAYER1_TP_TEMPLATES[6],
            &MP0B_LAYER1_TP_CG6_F32,
            x,
            y,
            w,
            bar_scatter,
            bar_w,
            &mut bar_x_values,
            &mut bar_y,
            &mut bar_y_v,
        );
        apply_template(
            MP0B_LAYER1_TP_TEMPLATES[7],
            &MP0B_LAYER1_TP_CG7_F32,
            x,
            y,
            w,
            bar_scatter,
            bar_w,
            &mut bar_x_values,
            &mut bar_y,
            &mut bar_y_v,
        );
        apply_template(
            MP0B_LAYER1_TP_TEMPLATES[8],
            &MP0B_LAYER1_TP_CG8_F32,
            x,
            y,
            w,
            bar_scatter,
            bar_w,
            &mut bar_x_values,
            &mut bar_y,
            &mut bar_y_v,
        );
        apply_template(
            MP0B_LAYER1_TP_TEMPLATES[9],
            &MP0B_LAYER1_TP_CG9_F32,
            x,
            y,
            w,
            bar_scatter,
            bar_w,
            &mut bar_x_values,
            &mut bar_y,
            &mut bar_y_v,
        );
        for (target, value) in bar_y.iter_mut().zip(bar_y_v) {
            *target += horizontal_sum(value);
        }
        bar_edge_attrs[edge * MP0B_SH_DIM..(edge + 1) * MP0B_SH_DIM].copy_from_slice(&bar_y);
    }
    mp0b_flush_product0_bar_linear_up_f32(&mut bar_linear_up, active_sender, &bar_x_values);
    Mp0bConvTpVjpF32 {
        bar_linear_up,
        bar_edge_attrs,
        bar_tp_weights,
    }
}

