unsafe fn mp0b_apply_conv_tp_layer1_scalar_vector_vjp_edge_avx2_f32(
    x: &[f32],
    y: &[f32],
    w: &[f32],
    bar_scatter: &[f32],
    bar_w: &mut [f32],
    bar_x_values: &mut [f32; MP0B_PRODUCT0_ROW_LEN],
    bar_y: &mut [f32; MP0B_SH_DIM],
) {
    use std::arch::x86_64::*;

    #[inline(always)]
    unsafe fn load8_strided(ptr: *const f32, stride: usize) -> __m256 {
        if stride == 1 {
            _mm256_loadu_ps(ptr)
        } else {
            _mm256_set_ps(
                *ptr.add(7 * stride),
                *ptr.add(6 * stride),
                *ptr.add(5 * stride),
                *ptr.add(4 * stride),
                *ptr.add(3 * stride),
                *ptr.add(2 * stride),
                *ptr.add(stride),
                *ptr,
            )
        }
    }

    #[inline(always)]
    unsafe fn add_store8_strided(ptr: *mut f32, stride: usize, value: __m256) {
        if stride == 1 {
            let current = _mm256_loadu_ps(ptr);
            _mm256_storeu_ps(ptr, _mm256_add_ps(current, value));
        } else {
            let mut lanes = [0.0_f32; 8];
            _mm256_storeu_ps(lanes.as_mut_ptr(), value);
            for (lane, &lane_value) in lanes.iter().enumerate() {
                *ptr.add(lane * stride) += lane_value;
            }
        }
    }

    #[inline(always)]
    unsafe fn horizontal_sum(value: __m256) -> f32 {
        let mut lanes = [0.0_f32; 8];
        _mm256_storeu_ps(lanes.as_mut_ptr(), value);
        lanes.iter().sum()
    }

    #[allow(clippy::too_many_arguments)]
    #[inline(always)]
    unsafe fn apply_template<const N: usize>(
        template: Mp0bLayer1TpTemplate,
        cg_entries: &[Mp0bLayer1CgF32; N],
        x: &[f32],
        y: &[f32],
        w: &[f32],
        bar_scatter: &[f32],
        bar_w: &mut [f32],
        bar_x_values: &mut [f32; MP0B_PRODUCT0_ROW_LEN],
        bar_y: &mut [f32; MP0B_SH_DIM],
        bar_y_v: &mut [__m256; MP0B_SH_DIM],
    ) {
        let mut feature = 0;
        while feature + 8 <= MP0B_NUM_FEATURES {
            let weight_index = template.weight_base + feature;
            let weight_v = _mm256_loadu_ps(w.as_ptr().add(weight_index));
            let mut bar_weight_v = _mm256_setzero_ps();
            let x_base = template.x_base + feature * template.x_dim;
            let out_base = template.out_base + feature * template.out_dim;
            for cg in cg_entries {
                let x_index = x_base + cg.i_m;
                let y_index = template.y_base + cg.j_m;
                let out_index = out_base + cg.k_m;
                let x_v = load8_strided(x.as_ptr().add(x_index), template.x_dim);
                let bar_out_v =
                    load8_strided(bar_scatter.as_ptr().add(out_index), template.out_dim);
                let scale_v = _mm256_set1_ps(cg.scale);
                let y_v = _mm256_set1_ps(y[y_index]);
                let scaled_bar = _mm256_mul_ps(_mm256_mul_ps(scale_v, weight_v), bar_out_v);
                let bar_x_delta = _mm256_mul_ps(scaled_bar, y_v);
                add_store8_strided(
                    bar_x_values.as_mut_ptr().add(x_index),
                    template.x_dim,
                    bar_x_delta,
                );
                bar_y_v[y_index] = _mm256_add_ps(bar_y_v[y_index], _mm256_mul_ps(scaled_bar, x_v));
                bar_weight_v = _mm256_add_ps(
                    bar_weight_v,
                    _mm256_mul_ps(_mm256_mul_ps(scale_v, x_v), _mm256_mul_ps(y_v, bar_out_v)),
                );
            }
            _mm256_storeu_ps(bar_w.as_mut_ptr().add(weight_index), bar_weight_v);
            feature += 8;
        }
        while feature < MP0B_NUM_FEATURES {
            let weight_index = template.weight_base + feature;
            let weight = w[weight_index];
            let x_base = template.x_base + feature * template.x_dim;
            let out_base = template.out_base + feature * template.out_dim;
            let mut bar_weight = 0.0_f32;
            for cg in cg_entries {
                let x_index = x_base + cg.i_m;
                let y_index = template.y_base + cg.j_m;
                let out_index = out_base + cg.k_m;
                let scale = cg.scale;
                let bar_out = bar_scatter[out_index];
                bar_x_values[x_index] += scale * weight * y[y_index] * bar_out;
                bar_y[y_index] += scale * weight * x[x_index] * bar_out;
                bar_weight += scale * x[x_index] * y[y_index] * bar_out;
            }
            bar_w[weight_index] = bar_weight;
            feature += 1;
        }
    }

    let mut bar_y_v = [_mm256_setzero_ps(); MP0B_SH_DIM];
    apply_template(
        MP0B_LAYER1_TP_TEMPLATES[0],
        &MP0B_LAYER1_TP_CG0_F32,
        x,
        y,
        w,
        bar_scatter,
        bar_w,
        bar_x_values,
        bar_y,
        &mut bar_y_v,
    );
    apply_template(
        MP0B_LAYER1_TP_TEMPLATES[1],
        &MP0B_LAYER1_TP_CG1_F32,
        x,
        y,
        w,
        bar_scatter,
        bar_w,
        bar_x_values,
        bar_y,
        &mut bar_y_v,
    );
    apply_template(
        MP0B_LAYER1_TP_TEMPLATES[2],
        &MP0B_LAYER1_TP_CG2_F32,
        x,
        y,
        w,
        bar_scatter,
        bar_w,
        bar_x_values,
        bar_y,
        &mut bar_y_v,
    );
    apply_template(
        MP0B_LAYER1_TP_TEMPLATES[3],
        &MP0B_LAYER1_TP_CG3_F32,
        x,
        y,
        w,
        bar_scatter,
        bar_w,
        bar_x_values,
        bar_y,
        &mut bar_y_v,
    );
    apply_template(
        MP0B_LAYER1_TP_TEMPLATES[4],
        &MP0B_LAYER1_TP_CG4_F32,
        x,
        y,
        w,
        bar_scatter,
        bar_w,
        bar_x_values,
        bar_y,
        &mut bar_y_v,
    );
    apply_template(
        MP0B_LAYER1_TP_TEMPLATES[5],
        &MP0B_LAYER1_TP_CG5_F32,
        x,
        y,
        w,
        bar_scatter,
        bar_w,
        bar_x_values,
        bar_y,
        &mut bar_y_v,
    );
    apply_template(
        MP0B_LAYER1_TP_TEMPLATES[6],
        &MP0B_LAYER1_TP_CG6_F32,
        x,
        y,
        w,
        bar_scatter,
        bar_w,
        bar_x_values,
        bar_y,
        &mut bar_y_v,
    );
    apply_template(
        MP0B_LAYER1_TP_TEMPLATES[7],
        &MP0B_LAYER1_TP_CG7_F32,
        x,
        y,
        w,
        bar_scatter,
        bar_w,
        bar_x_values,
        bar_y,
        &mut bar_y_v,
    );
    apply_template(
        MP0B_LAYER1_TP_TEMPLATES[8],
        &MP0B_LAYER1_TP_CG8_F32,
        x,
        y,
        w,
        bar_scatter,
        bar_w,
        bar_x_values,
        bar_y,
        &mut bar_y_v,
    );
    apply_template(
        MP0B_LAYER1_TP_TEMPLATES[9],
        &MP0B_LAYER1_TP_CG9_F32,
        x,
        y,
        w,
        bar_scatter,
        bar_w,
        bar_x_values,
        bar_y,
        &mut bar_y_v,
    );
    for (target, value) in bar_y.iter_mut().zip(bar_y_v) {
        *target += horizontal_sum(value);
    }
}

