fn validate_osaka_runtime_provenance(
    provenance: Option<&MaceProvenanceSpec>,
    model_state_dict_format: Option<&str>,
    runtime_state_tensor_count: usize,
) -> Result<(), MaceLiteError> {
    let Some(provenance) = provenance else {
        return Err(invalid_model(
            "osaka_runtime_plan requires provenance for pinned MACE-Osaka24 artifact identity",
        ));
    };
    validate_mace_provenance_str(
        "source_family",
        &provenance.source_family,
        OSAKA24_SOURCE_FAMILY,
    )?;
    let pin = osaka24_artifact_pin(&provenance.selected_model).ok_or_else(|| {
        invalid_model(format!(
            "provenance.selected_model must be one of {:?}, {:?}, or {:?}, got {:?}",
            OSAKA24_SMALL_SELECTED_MODEL,
            OSAKA24_MEDIUM_SELECTED_MODEL,
            OSAKA24_LARGE_SELECTED_MODEL,
            provenance.selected_model
        ))
    })?;
    validate_mace_provenance_str(
        "selected_model",
        &provenance.selected_model,
        pin.selected_model,
    )?;
    validate_mace_provenance_str(
        "artifact.filename",
        &provenance.artifact.filename,
        pin.filename,
    )?;
    let expected_url = format!("{}{}", OSAKA24_RELEASE_URL_PREFIX, pin.filename);
    validate_mace_provenance_str("artifact.url", &provenance.artifact.url, &expected_url)?;
    validate_mace_provenance_str("artifact.sha256", &provenance.artifact.sha256, pin.sha256)?;
    validate_mace_provenance_usize(
        "artifact.size_bytes",
        provenance.artifact.size_bytes,
        pin.size_bytes,
    )?;
    validate_mace_provenance_str(
        "reference.name",
        &provenance.reference.name,
        OSAKA26_REFERENCE_NAME,
    )?;
    validate_mace_provenance_str(
        "reference.repository",
        &provenance.reference.repository,
        OSAKA26_REFERENCE_REPOSITORY,
    )?;
    validate_mace_provenance_str(
        "reference.commit",
        &provenance.reference.commit,
        OSAKA26_REFERENCE_COMMIT,
    )?;
    validate_mace_provenance_str(
        "reference.package_version",
        &provenance.reference.package_version,
        OSAKA26_REFERENCE_PACKAGE_VERSION,
    )?;
    validate_mace_provenance_str(
        "state_dict_format",
        &provenance.state_dict_format,
        MANIFEST_F64_STATE_DICT_FORMAT,
    )?;
    if model_state_dict_format != Some(provenance.state_dict_format.as_str()) {
        return Err(invalid_model(format!(
            "provenance.state_dict_format must match model state_dict_format {:?}, got {:?}",
            model_state_dict_format, provenance.state_dict_format
        )));
    }
    validate_mace_provenance_usize(
        "runtime_state_tensor_count vs state_dict.len",
        provenance.runtime_state_tensor_count,
        runtime_state_tensor_count,
    )?;
    if provenance.upstream_state_tensor_count
        != provenance.runtime_state_tensor_count + provenance.archival_only_state_tensor_count
    {
        return Err(invalid_model(format!(
            "provenance upstream/runtime/archival tensor counts must satisfy upstream = runtime + archival, got {} != {} + {}",
            provenance.upstream_state_tensor_count,
            provenance.runtime_state_tensor_count,
            provenance.archival_only_state_tensor_count
        )));
    }
    validate_mace_provenance_str(
        "upstream_state_dict_inventory",
        &provenance.upstream_state_dict_inventory,
        OSAKA26_STATE_DICT_INVENTORY_PATH,
    )?;
    Ok(())
}

