fn validate_mp0b_provenance(
    provenance: Option<&MaceProvenanceSpec>,
    has_mp0b_runtime_plan: bool,
    model_state_dict_format: Option<&str>,
    runtime_state_tensor_count: usize,
) -> Result<(), MaceLiteError> {
    let Some(provenance) = provenance else {
        if has_mp0b_runtime_plan {
            return Err(invalid_model(
                "mp0b_runtime_plan requires provenance for pinned MACE-MP0b artifact identity",
            ));
        }
        return Ok(());
    };
    if !has_mp0b_runtime_plan {
        return Err(invalid_model(
            "provenance is only supported for pinned MACE-MP0b runtime plans",
        ));
    }

    validate_mace_provenance_str(
        "source_family",
        &provenance.source_family,
        MP0B_SOURCE_FAMILY,
    )?;
    validate_mace_provenance_str(
        "selected_model",
        &provenance.selected_model,
        MP0B_SELECTED_MODEL,
    )?;
    validate_mace_provenance_str(
        "artifact.filename",
        &provenance.artifact.filename,
        MP0B_ARTIFACT_FILENAME,
    )?;
    validate_mace_provenance_str("artifact.url", &provenance.artifact.url, MP0B_ARTIFACT_URL)?;
    validate_mace_provenance_str(
        "artifact.sha256",
        &provenance.artifact.sha256,
        MP0B_ARTIFACT_SHA256,
    )?;
    validate_mace_provenance_usize(
        "artifact.size_bytes",
        provenance.artifact.size_bytes,
        MP0B_ARTIFACT_SIZE_BYTES,
    )?;
    validate_mace_provenance_str(
        "reference.name",
        &provenance.reference.name,
        MP0B_REFERENCE_NAME,
    )?;
    validate_mace_provenance_str(
        "reference.repository",
        &provenance.reference.repository,
        MP0B_REFERENCE_REPOSITORY,
    )?;
    validate_mace_provenance_str(
        "reference.commit",
        &provenance.reference.commit,
        MP0B_REFERENCE_COMMIT,
    )?;
    validate_mace_provenance_str(
        "reference.package_version",
        &provenance.reference.package_version,
        MP0B_REFERENCE_PACKAGE_VERSION,
    )?;
    validate_mace_provenance_str(
        "state_dict_format",
        &provenance.state_dict_format,
        MANIFEST_F64_STATE_DICT_FORMAT,
    )?;
    if model_state_dict_format != Some(provenance.state_dict_format.as_str()) {
        return Err(invalid_model(format!(
            "provenance.state_dict_format must match model state_dict_format {:?}, got {:?}",
            model_state_dict_format, provenance.state_dict_format
        )));
    }
    validate_mace_provenance_usize(
        "upstream_state_tensor_count",
        provenance.upstream_state_tensor_count,
        MP0B_UPSTREAM_STATE_TENSOR_COUNT,
    )?;
    validate_mace_provenance_usize(
        "runtime_state_tensor_count",
        provenance.runtime_state_tensor_count,
        MP0B_RUNTIME_STATE_TENSOR_COUNT,
    )?;
    validate_mace_provenance_usize(
        "runtime_state_tensor_count vs state_dict.len",
        provenance.runtime_state_tensor_count,
        runtime_state_tensor_count,
    )?;
    validate_mace_provenance_usize(
        "archival_only_state_tensor_count",
        provenance.archival_only_state_tensor_count,
        MP0B_ARCHIVAL_ONLY_STATE_TENSOR_COUNT,
    )?;
    if provenance.upstream_state_tensor_count
        != provenance.runtime_state_tensor_count + provenance.archival_only_state_tensor_count
    {
        return Err(invalid_model(format!(
            "provenance upstream/runtime/archival tensor counts must satisfy upstream = runtime + archival, got {} != {} + {}",
            provenance.upstream_state_tensor_count,
            provenance.runtime_state_tensor_count,
            provenance.archival_only_state_tensor_count
        )));
    }
    validate_mace_provenance_str(
        "upstream_state_dict_inventory",
        &provenance.upstream_state_dict_inventory,
        MP0B_STATE_DICT_INVENTORY_PATH,
    )?;
    Ok(())
}

#[derive(Clone, Copy)]
struct Mp0bExpectedLayerPlan {
    interaction: &'static str,
    linear_up_input_dim: usize,
    linear_up_output_dim: usize,
    conv_tp_weight_numel: usize,
    conv_tp_output_dim: usize,
    skip_output_dim: usize,
    skip_kind: &'static str,
    product_output_dim: usize,
    product_kind: &'static str,
}

fn expected_mp0b_layer_plan(layer: usize) -> Mp0bExpectedLayerPlan {
    match layer {
        0 => Mp0bExpectedLayerPlan {
            interaction: "RealAgnosticDensityInteractionBlock",
            linear_up_input_dim: MP0B_NUM_FEATURES,
            linear_up_output_dim: MP0B_NUM_FEATURES,
            conv_tp_weight_numel: 512,
            conv_tp_output_dim: MP0B_HIDDEN_ROW_LEN,
            skip_output_dim: MP0B_HIDDEN_ROW_LEN,
            skip_kind: "message_selector",
            product_output_dim: MP0B_PRODUCT0_ROW_LEN,
            product_kind: "scalar_vector",
        },
        1 => Mp0bExpectedLayerPlan {
            interaction: "RealAgnosticDensityResidualInteractionBlock",
            linear_up_input_dim: MP0B_PRODUCT0_ROW_LEN,
            linear_up_output_dim: MP0B_PRODUCT0_ROW_LEN,
            conv_tp_weight_numel: 1280,
            conv_tp_output_dim: 10 * MP0B_PRODUCT0_ROW_LEN,
            skip_output_dim: MP0B_PRODUCT1_ROW_LEN,
            skip_kind: "residual_add",
            product_output_dim: MP0B_PRODUCT1_ROW_LEN,
            product_kind: "scalar",
        },
        _ => unreachable!("MP0b runtime plan validation only calls layers 0 and 1"),
    }
}

#[derive(Clone, Copy)]
struct Mp0bExpectedConvTpPlan {
    irreps_in1: &'static str,
    irreps_in2: &'static str,
    irreps_out: &'static str,
    weight_numel: usize,
    instruction_count: usize,
    cg_count: usize,
}

fn expected_mp0b_conv_tp_plan(layer: usize) -> Mp0bExpectedConvTpPlan {
    match layer {
        0 => Mp0bExpectedConvTpPlan {
            irreps_in1: "128x0e",
            irreps_in2: "1x0e+1x1o+1x2e+1x3o",
            irreps_out: "128x0e+128x1o+128x2e+128x3o",
            weight_numel: 512,
            instruction_count: 512,
            cg_count: 16,
        },
        1 => Mp0bExpectedConvTpPlan {
            irreps_in1: "128x0e+128x1o",
            irreps_in2: "1x0e+1x1o+1x2e+1x3o",
            irreps_out: "128x0e+128x0e+128x1o+128x1o+128x1o+128x2e+128x2e+128x2e+128x3o+128x3o",
            weight_numel: 1280,
            instruction_count: 1280,
            cg_count: 86,
        },
        _ => unreachable!("MP0b runtime plan validation only calls layers 0 and 1"),
    }
}

fn validate_osaka26_conv_tp_plan(
    layer: usize,
    plan: &TensorProductPlan,
) -> Result<(), MaceLiteError> {
    let plan_key = MaceRuntimePlanKind::Osaka26.manifest_key();
    validate_runtime_conv_tp_irreps(plan_key, layer, "irreps_in1", &plan.irreps_in1, "128x0e")?;
    validate_runtime_conv_tp_irreps(
        plan_key,
        layer,
        "irreps_in2",
        &plan.irreps_in2,
        "1x0e+1x1o+1x2e+1x3o",
    )?;
    validate_runtime_conv_tp_irreps(
        plan_key,
        layer,
        "irreps_out",
        &plan.irreps_out,
        "128x0e+128x1o+128x2e+128x3o",
    )?;
    validate_runtime_conv_tp_usize(
        plan_key,
        layer,
        "instruction_count",
        plan.instructions.len(),
        512,
    )?;
    validate_runtime_conv_tp_usize(plan_key, layer, "cg_count", plan.cg_entries.len(), 16)?;
    validate_runtime_conv_tp_usize(plan_key, layer, "weight_numel", plan.weight_numel, 512)?;
    Ok(())
}

fn validate_mp0b_conv_tp_plan(layer: usize, plan: &TensorProductPlan) -> Result<(), MaceLiteError> {
    let expected = expected_mp0b_conv_tp_plan(layer);
    validate_runtime_conv_tp_irreps(
        MaceRuntimePlanKind::Mp0b.manifest_key(),
        layer,
        "irreps_in1",
        &plan.irreps_in1,
        expected.irreps_in1,
    )?;
    validate_runtime_conv_tp_irreps(
        MaceRuntimePlanKind::Mp0b.manifest_key(),
        layer,
        "irreps_in2",
        &plan.irreps_in2,
        expected.irreps_in2,
    )?;
    validate_runtime_conv_tp_irreps(
        MaceRuntimePlanKind::Mp0b.manifest_key(),
        layer,
        "irreps_out",
        &plan.irreps_out,
        expected.irreps_out,
    )?;
    validate_runtime_conv_tp_usize(
        MaceRuntimePlanKind::Mp0b.manifest_key(),
        layer,
        "instruction_count",
        plan.instructions.len(),
        expected.instruction_count,
    )?;
    validate_runtime_conv_tp_usize(
        MaceRuntimePlanKind::Mp0b.manifest_key(),
        layer,
        "cg_count",
        plan.cg_entries.len(),
        expected.cg_count,
    )?;
    validate_runtime_conv_tp_usize(
        MaceRuntimePlanKind::Mp0b.manifest_key(),
        layer,
        "weight_numel",
        plan.weight_numel,
        expected.weight_numel,
    )?;
    Ok(())
}

fn validate_runtime_conv_tp_irreps(
    plan_key: &str,
    layer: usize,
    field: &str,
    actual: &Irreps,
    expected: &str,
) -> Result<(), MaceLiteError> {
    let expected_irreps = expected.parse::<Irreps>()?;
    if actual != &expected_irreps {
        return Err(invalid_model(format!(
            "{plan_key} requires conv_tp_plans[{layer}].{field} to be {expected:?}, got {:?}",
            actual.to_string()
        )));
    }
    Ok(())
}

