fn validate_mp0b_layer_state_shapes(
    state_float_tensors: &HashMap<String, StateFloatTensor>,
    layer: usize,
    plan: &PinnedMaceRuntimeLayerPlanSpec,
) -> Result<(), MaceLiteError> {
    let linear_up_weight_len = match layer {
        0 => MP0B_NUM_FEATURES * MP0B_NUM_FEATURES,
        1 => 2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES,
        _ => unreachable!("MP0b runtime plan validation only calls layers 0 and 1"),
    };
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.linear_up.weight"),
        &[linear_up_weight_len],
    )?;
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.linear_up.output_mask"),
        &[plan.linear_up_output_dim],
    )?;
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.conv_tp.output_mask"),
        &[plan.conv_tp_output_dim],
    )?;
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.conv_tp_weights.layer0.weight"),
        &[plan.density_input_dim, plan.conv_tp_weight_mlp_hidden_dim],
    )?;
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.conv_tp_weights.layer1.weight"),
        &[
            plan.conv_tp_weight_mlp_hidden_dim,
            plan.conv_tp_weight_mlp_hidden_dim,
        ],
    )?;
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.conv_tp_weights.layer2.weight"),
        &[
            plan.conv_tp_weight_mlp_hidden_dim,
            plan.conv_tp_weight_mlp_hidden_dim,
        ],
    )?;
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.conv_tp_weights.layer3.weight"),
        &[
            plan.conv_tp_weight_mlp_hidden_dim,
            plan.conv_tp_weight_numel,
        ],
    )?;
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.density_fn.layer0.weight"),
        &[plan.density_input_dim, plan.density_output_dim],
    )?;

    let linear_weight_len = match layer {
        0 => 4 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES,
        1 => 10 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES,
        _ => unreachable!("MP0b runtime plan validation only calls layers 0 and 1"),
    };
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.linear.weight"),
        &[linear_weight_len],
    )?;
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.linear.output_mask"),
        &[plan.linear_message_output_dim],
    )?;

    let skip_weight_len = match layer {
        0 => 4 * MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES,
        1 => MP0B_NUM_FEATURES * MP0B_NUM_ELEMENTS * MP0B_NUM_FEATURES,
        _ => unreachable!("MP0b runtime plan validation only calls layers 0 and 1"),
    };
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.skip_tp.weight"),
        &[skip_weight_len],
    )?;
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("interactions.{layer}.skip_tp.output_mask"),
        &[plan.skip_output_dim],
    )?;

    let product_weight_len = match layer {
        0 => 2 * MP0B_NUM_FEATURES * MP0B_NUM_FEATURES,
        1 => MP0B_NUM_FEATURES * MP0B_NUM_FEATURES,
        _ => unreachable!("MP0b runtime plan validation only calls layers 0 and 1"),
    };
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("products.{layer}.linear.weight"),
        &[product_weight_len],
    )?;
    validate_pinned_mace_state_shape(
        state_float_tensors,
        &format!("products.{layer}.linear.output_mask"),
        &[plan.product_output_dim],
    )?;
    Ok(())
}

