fn validate_runtime_state_shape(
    plan_key: &str,
    state_float_tensors: &HashMap<String, StateFloatTensor>,
    name: &str,
    expected: &[usize],
) -> Result<(), MaceLiteError> {
    let tensor = state_float_tensors
        .get(name)
        .ok_or_else(|| invalid_model(format!("{plan_key} requires state_dict tensor {name:?}")))?;
    if tensor.shape != expected {
        return Err(MaceLiteError::StateTensorShape {
            name: name.to_owned(),
            actual: tensor.shape.clone(),
            expected: expected.to_vec(),
        });
    }
    Ok(())
}

fn validate_pinned_mace_state_shape_any(
    state_float_tensors: &HashMap<String, StateFloatTensor>,
    name: &str,
    expected_shapes: &[&[usize]],
) -> Result<(), MaceLiteError> {
    validate_runtime_state_shape_any(
        PINNED_MACE_RUNTIME_PLAN_KEY,
        state_float_tensors,
        name,
        expected_shapes,
    )
}

fn validate_runtime_state_shape_any(
    plan_key: &str,
    state_float_tensors: &HashMap<String, StateFloatTensor>,
    name: &str,
    expected_shapes: &[&[usize]],
) -> Result<(), MaceLiteError> {
    let tensor = state_float_tensors
        .get(name)
        .ok_or_else(|| invalid_model(format!("{plan_key} requires state_dict tensor {name:?}")))?;
    if expected_shapes.contains(&tensor.shape.as_slice()) {
        return Ok(());
    }
    Err(MaceLiteError::StateTensorShape {
        name: name.to_owned(),
        actual: tensor.shape.clone(),
        expected: expected_shapes
            .first()
            .map_or_else(Vec::new, |shape| shape.to_vec()),
    })
}

fn osaka_product_kind_for_row_len(
    row_len: usize,
    num_features: usize,
) -> Result<&'static str, MaceLiteError> {
    if num_features == 0 || !row_len.is_multiple_of(num_features) {
        return Err(MaceLiteError::UnsupportedRuntime);
    }
    match row_len / num_features {
        1 => Ok("scalar"),
        4 => Ok("scalar_vector"),
        9 => Ok("scalar_vector_l2"),
        16 => Ok("scalar_vector_l2_l3"),
        _ => Err(MaceLiteError::UnsupportedRuntime),
    }
}

fn validate_referenced_state_tensors(
    layers: &[LayerSpec],
    state_dict_tensor_names: &[String],
) -> Result<(), MaceLiteError> {
    if state_dict_tensor_names.is_empty() {
        return Ok(());
    }
    for (layer_index, layer) in layers.iter().enumerate() {
        let contraction = &layer.product.symmetric_contraction;
        for name in contraction_tensor_names(contraction) {
            if !state_dict_tensor_names
                .iter()
                .any(|candidate| candidate == name)
            {
                return Err(invalid_model(format!(
                    "layer {layer_index} symmetric_contraction references missing state_dict tensor {name:?}"
                )));
            }
        }
    }
    Ok(())
}

fn contraction_tensor_names(contraction: &SymmetricContractionSpec) -> Vec<&String> {
    let mut names = Vec::new();
    names.extend(contraction.u_tensors.iter());
    names.extend(contraction.weight_tensors.iter());
    for component in &contraction.contractions {
        names.extend(component.u_tensors.iter());
        names.extend(component.weight_tensors.iter());
    }
    names
}

fn validate_state_tensor_shape(name: &str, shape: &[usize]) -> Result<(), MaceLiteError> {
    shape_len(shape, name)?;
    Ok(())
}

fn shape_len(shape: &[usize], name: &str) -> Result<usize, MaceLiteError> {
    shape.iter().try_fold(1_usize, |acc, value| {
        acc.checked_mul(*value).ok_or_else(|| {
            invalid_model(format!(
                "state_dict tensor {name:?} shape product overflows"
            ))
        })
    })
}

fn validate_state_tensor_value(
    name: &str,
    dtype: &str,
    shape: &[usize],
    value: &Value,
    depth: usize,
) -> Result<(), MaceLiteError> {
    if depth == shape.len() {
        return validate_state_tensor_scalar(name, dtype, value);
    }

    let Some(items) = value.as_array() else {
        return Err(invalid_model(format!(
            "state_dict tensor {name:?} values rank does not match shape {shape:?}"
        )));
    };
    if items.len() != shape[depth] {
        return Err(invalid_model(format!(
            "state_dict tensor {name:?} values dimension {depth} length {} does not match shape {}",
            items.len(),
            shape[depth]
        )));
    }
    for item in items {
        validate_state_tensor_value(name, dtype, shape, item, depth + 1)?;
    }
    Ok(())
}

fn validate_state_tensor_scalar(
    name: &str,
    dtype: &str,
    value: &Value,
) -> Result<(), MaceLiteError> {
    match dtype {
        "torch.float64" => {
            if value.as_f64().is_some_and(f64::is_finite) {
                Ok(())
            } else {
                Err(invalid_model(format!(
                    "state_dict tensor {name:?} must contain finite float64 values"
                )))
            }
        }
        "torch.int64" => {
            if value.as_i64().is_some() || value.as_u64().is_some() {
                Ok(())
            } else {
                Err(invalid_model(format!(
                    "state_dict tensor {name:?} must contain int64 values"
                )))
            }
        }
        "torch.int32" => {
            let in_range = value
                .as_i64()
                .is_some_and(|number| i32::try_from(number).is_ok())
                || value
                    .as_u64()
                    .is_some_and(|number| i32::try_from(number).is_ok());
            if in_range {
                Ok(())
            } else {
                Err(invalid_model(format!(
                    "state_dict tensor {name:?} must contain int32 values"
                )))
            }
        }
        "torch.bool" => {
            if value.as_bool().is_some() {
                Ok(())
            } else {
                Err(invalid_model(format!(
                    "state_dict tensor {name:?} must contain bool values"
                )))
            }
        }
        other => Err(invalid_model(format!(
            "state_dict tensor {name:?} has unsupported dtype {other:?}"
        ))),
    }
}

fn collect_float_tensor_values(
    name: &str,
    shape: &[usize],
    value: &Value,
    depth: usize,
    values: &mut Vec<f64>,
) -> Result<(), MaceLiteError> {
    if depth == shape.len() {
        let Some(value) = value.as_f64() else {
            return Err(invalid_model(format!(
                "state_dict tensor {name:?} must contain float64 values"
            )));
        };
        values.push(value);
        return Ok(());
    }
    let Some(items) = value.as_array() else {
        return Err(invalid_model(format!(
            "state_dict tensor {name:?} values rank does not match shape {shape:?}"
        )));
    };
    for item in items {
        collect_float_tensor_values(name, shape, item, depth + 1, values)?;
    }
    Ok(())
}

fn invalid_model(message: impl Into<String>) -> MaceLiteError {
    MaceLiteError::InvalidModel(message.into())
}

fn uses_partial_pbc(structure: &Structure) -> bool {
    structure.pbc.iter().any(|enabled| *enabled) && !structure.pbc.iter().all(|enabled| *enabled)
}

fn mace_reference_stress_cell(structure: &Structure, cutoff: f64) -> Result<Cell, MaceLiteError> {
    let cell = *structure
        .cell
        .as_ref()
        .ok_or(MaceLiteError::StressRequiresCell)?;
    if !uses_partial_pbc(structure) {
        return Ok(cell);
    }
    let max_abs_position = structure
        .positions
        .iter()
        .flat_map(|position| position.iter())
        .map(|component| component.abs())
        .fold(0.0, f64::max);
    let nonperiodic_extent = (max_abs_position + 1.0) * 5.0 * cutoff;
    let mut vectors = cell.vectors;
    for (axis, row) in vectors.iter_mut().enumerate() {
        if !structure.pbc[axis] {
            *row = [0.0; 3];
            row[axis] = nonperiodic_extent;
        }
    }
    Ok(Cell::new(vectors))
}
